/**
 * A follow-up typed while the agent was still working. It carries its images
 * alongside its text so nothing is lost between queueing and sending.
 *
 * The `id` is what every other site addresses the message BY. Object identity
 * cannot do it: editing mints a new object, so an identity filter written
 * against the pre-edit object silently matches nothing and the message is sent
 * a second time. An index cannot do it either: the drain shifts the array while
 * a send is in flight, so an index captured at render time addresses a
 * different message by the time the user clicks.
 */
/**
 * The panel's pull-request list for a run that has no folder, or none read yet.
 * Module scope so its identity is stable — a fresh `[]` per render would be a
 * changed prop on every keystroke in the composer.
 */

/**
 * How long the session search waits for typing to stop.
 *
 * The ask is not a filter over rows the renderer already holds — the daemon
 * reads the conversations themselves, and for cursor it spawns a process.
 * Measured at ~900ms for a term matching nothing across a 3,029-session claude
 * profile, so a request per keystroke would queue work the user has already
 * typed past.
 */
const SESSION_SEARCH_DEBOUNCE_MS = 350;

/**
 * How many merged rows the picker shows.
 *
 * TWIN LIMIT: apps/daemon/src/v1/agents/services/cli-sessions.service.ts
 * `SESSION_LIST_LIMIT`, which is per PROFILE. This is the cap on the fold of
 * all of them, and it is the same number deliberately: a picker showing more
 * rows than one profile's worth has stopped being a list somebody scrolls, and
 * the search is what narrows it.
 */
const SESSION_LIST_LIMIT = 400;

/** The start screen's content column — the greeting and the new-run composer. */
const START_COLUMN_WIDTH = '42rem';

/**
 * The new-chat composer's project: chosen by an applied configuration or by
 * hand — either outlives a folder change — else the folder's own.
 */
interface ComposerProject {
  projectId: string | null;
  source: 'config' | 'manual' | 'folder';
}
const FOLDER_PROJECT: ComposerProject = { projectId: null, source: 'folder' };
const NO_PROJECTS: ProjectTargetRef[] = [];
const NO_NOTIFIED_RUNS: ChatRun[] = [];

/**
 * What a new run is told about its project: nothing for the folder's own (the
 * daemon resolves it the same way), else the choice — an explicit none for a
 * cleared chip, and an id the daemon passes over once its project is gone.
 */
function projectFieldOf(project: ComposerProject): {
  projectId?: string | null;
} {
  return project.source === 'folder' ? {} : { projectId: project.projectId };
}

/** The start screen's own padding, and so its smallest gap to the sidebar. */
const START_COLUMN_PAD = '1.5rem';

/**
 * How often the archive sweep re-checks, once a window is set.
 *
 * Six hours rather than daily: the app is routinely left running for days, and
 * a 24-hour timer means a retention window is enforced at whatever time of day
 * the app last started — so a chat can sit a day past the window purely
 * because of when somebody launched it. Rather than hourly, because nothing
 * about this is urgent and each tick is a request plus, on the tick that
 * matters, a real teardown per row.
 */
const ARCHIVE_SWEEP_INTERVAL_MS = 6 * 60 * 60 * 1000;

/**
 * How many pages ONE press of `Load earlier messages` may walk back while the
 * transcript does not grow upward — see `pageOlderUntilVisible`.
 *
 * Bounded because a press is a person waiting: five pages is `HISTORY_PAGE`
 * five times over, which on the run this was measured against reaches the seed
 * message from anywhere in the conversation, while a conversation whose every
 * page folds away entirely is one where paging further answers nothing either.
 */
const OLDER_PAGES_PER_PRESS = 5;

/** The identity of the top entry on screen, or null when there is none. */
function topEntryKey(entries: readonly TranscriptEntry[]): string | null {
  const first = entries[0];
  return first === undefined ? null : transcriptEntryKey(first);
}

/**
 * A run's sidebar label: its custom title when renamed, else the NAME of the
 * team it ran (falling back to the slug once the team is deleted),
 * else the agent driving the 1:1 chat.
 */
/** How long after an archive the notice waits for the stretch the daemon queues for it. */
const ARCHIVE_LESSON_WATCH_MS = 10_000;

/** The archive notice: the stretch queued for the archived thread, and today's spend. */
interface ArchiveLessonNotice {
  segment: LessonSegment;
  todayUsd: number | null;
}

function runLabel(run: ChatRun, teamNames: Map<string, string>): string {
  if (run.title) {
    return run.title;
  }
  if (run.teamId) {
    return teamNames.get(run.teamId) ?? run.teamId;
  }
  return run.agentKind ?? 'chat';
}

/**
 * What a run is parked on. Module scope so its identity is stable — it is an
 * effect dependency of `useRunNotifications`, and a fresh arrow per render
 * would re-run that effect on every keystroke in the composer.
 */
/**
 * A call block's lifecycle in the panel's run vocabulary. A `pending` call has
 * been asked for and is not over, which the panel's rows call `running` —
 * unless it is waiting under the run's active-turn cap, which they call
 * `queued`.
 */
function callThreadStatusOf(
  block: Pick<CallBlockEntry, 'status' | 'queued'>,
): AgentThread['status'] {
  if (block.status !== 'pending') {
    return block.status;
  }
  return block.queued === true ? 'queued' : 'running';
}

/** The ring's figures as an agent card's three context fields. */
function agentContextFields(figures: ContextFigures): {
  contextTokens: number | null;
  contextWindowTokens: number | null;
  contextEstimated: boolean;
} {
  return {
    contextTokens: figures.tokens,
    contextWindowTokens: figures.window,
    contextEstimated: figures.estimated === true,
  };
}

/** A spend as the header's two money props. */
function headerSpendOf(spend: CallSpend): {
  costUsd: number | null;
  estimatedCostUsd: number | null;
} {
  return {
    costUsd: spend.costUsd,
    estimatedCostUsd: spend.estimatedCostUsd ?? null,
  };
}

/**
 * Order two call ids by the number the broker minted them with (`call-2`
 * before `call-10`), which is the order the calls were made in. An id carrying
 * no number sorts after the ones that do, by its text.
 */
function compareCallIds(a: string, b: string): number {
  const number = (id: string): number => {
    const match = /(\d+)$/.exec(id);
    return match === null ? Number.POSITIVE_INFINITY : Number(match[1]);
  };
  return number(a) - number(b) || a.localeCompare(b);
}

function runAwaiting(run: ChatRun): RunAwaiting | null {
  return run.awaiting;
}

/**
 * Where the run's folder stands right now, as a spreadable create-payload
 * fragment — the fixed point the chat's diff view later measures against.
 *
 * Read at creation for the reason `currentRunSettings` is, and kept
 * separate from it because a stamp is a reading of the FOLDER, not a run
 * setting. A TEAM run is stamped too, against the run's own folder: it is
 * the start commit that folder's line totals are measured from, so an
 * unstamped team run would never count its lines.
 *
 * Each field is omitted rather than sent null when there is nothing to say — a
 * plain folder, a checkout with no commits — so an unstamped run is one shape
 * on the wire whatever failed to answer.
 */
async function chatGitStamp(cwd: string): Promise<{
  startSha?: string;
  startDirty?: boolean;
}> {
  const { sha, dirty } = await window.geniro.getGitStamp(cwd);
  return {
    ...(sha === null ? {} : { startSha: sha }),
    ...(dirty === null ? {} : { startDirty: dirty }),
  };
}

/** Draft key for the landing composer, which has no run id of its own. */
const NEW_CHAT_DRAFT = '__new__';

/** Why both composers' Send is held while a paste is still being read. */
const READING_PASTE_TITLE =
  'Reading the pasted image — it can be sent once it is ready';

/** Why both composers' Send is held while a picked file is still uploading. */
const UPLOADING_FILE_TITLE =
  'Uploading the attached file — it can be sent once it is ready';

/**
 * One frozen empty map for "this CLI has no parameter picks", shared by every
 * render.
 *
 * A `?? {}` at the prop would mint a fresh object each time and defeat the
 * settings panel's own memo on exactly the runs that have nothing stored — the
 * common case — so the memo would only ever hit once a parameter was set.
 */
const NO_PARAMETER_VALUES: Record<string, string> = {};

/**
 * One frozen empty list for "this CLI has no recent config directories",
 * shared by every render.
 *
 * A `?? []` at the prop would mint a fresh array each time and defeat the
 * settings panel's memo on exactly the threads that have no recents — the
 * common case — so the memo would only ever hit once a directory was stored.
 */
const EMPTY_RECENT_CONFIG_DIRS: readonly string[] = [];

/**
 * What the archive dialog CALLS the thing it is asking about, and what its
 * confirm button promises.
 *
 * Four readings rather than a noun substituted into one sentence: a team
 * run is stopped as a RUN — every agent still working in it — where a chat's
 * cancel is one turn, and "Archive a running run" is not a sentence. It says
 * `run` and never `team`, on the delete dialog's own rule: the library
 * team is untouched, and naming it here is how a reader comes to think
 * otherwise.
 */
function archiveDialogCopy(run: ChatRun | null): {
  title: string;
  confirmLabel: string;
} {
  const working = run?.status === 'running';
  if (run?.teamId != null) {
    return {
      // NOT "working": `RUN_STATUS_META` reserves that word for `held`, and the
      // header of the very run being archived reads `running` — so the dialog
      // named a different state than the row behind it. "A running run" is not
      // a sentence, which is what "working" was reaching for; this says the
      // same thing without borrowing another status's word.
      title: working ? 'Archive a run in progress' : 'Archive run',
      confirmLabel: working ? 'Stop run & archive' : 'Archive',
    };
  }
  return {
    title: working ? 'Archive a running chat' : 'Archive chat',
    confirmLabel: working ? 'Cancel turn & archive' : 'Archive',
  };
}

/** How long a link's ask to open a call card waits for the card to be drawn. */
const OPEN_CALL_WAIT_MS = 10_000;

/**
 * Where the agents panel is hosted: its own grid column, or a right-edge
 * drawer at phone width.
 *
 * A component rather than a ternary at the call site, because the alternative
 * is writing the panel's ~40 props twice — and two call sites for one panel
 * is how one host comes to be handed a reading the other is not. The drawer
 * arm carries the panel's SURFACE (width, border, background); the drawer
 * itself owns only the backdrop, the fixed positioning and the slide, which
 * is the split `mobile-drawer.tsx` states.
 */
function PanelHost({
  drawer,
  open,
  onClose,
  children,
}: {
  drawer: boolean;
  open: boolean;
  onClose: () => void;
  children: React.ReactNode;
}): React.JSX.Element {
  if (!drawer) {
    return <>{children}</>;
  }
  return (
    <MobileDrawer
      open={open}
      onClose={onClose}
      className="flex w-[88vw] max-w-[380px] flex-col bg-sidebar">
      {children}
    </MobileDrawer>
  );
}

/** A team's trigger as the composer names it: the member the first message goes to. */
interface RunTrigger {
  id: string;
  name: string;
  trigger: string;
  agent: CliKind;
}

function runTriggersOf(team: Team): RunTrigger[] {
  const id = firstMessageMemberOf(team);
  const member = team.members.find((m) => m.id === id);
  return member === undefined
    ? []
    : [
        {
          id: member.id,
          name: member.name,
          trigger: 'first message',
          agent: member.agent,
        },
      ];
}

export function Chats({
  client,
  handle,
  active = true,
  openRunId = null,
  onRunOpened,
  processesRequest = null,
  onProcessesOpened,
  onActiveRunChange,
  onTitleChange,
  onOpenSettings,
  onOpenMemory,
  onOpenKnowledge,
  onOpenTeam,
  onOpenProject,
  onOpenTerminal,
  onFolderChange,
  onPhoneDetailChange,
  onWaitingChange,
  phoneHomeSignal = 0,
  firstLaunchAgent = null,
  onFirstLaunchHandled,
  transcriptPageCap,
  hosted = null,
}: {
  client: DaemonClient;
  handle: DaemonHandle;
  /**
   * Draw ONE conversation the sidebar never lists, inside another surface:
   * the thread alone, with no list, no new-chat composer and nothing that
   * belongs to the whole app (notifications, the archive sweep, global search).
   */
  hosted?: HostedThread | null;
  firstLaunchAgent?: CliKind | null;
  onFirstLaunchHandled?: () => void;
  /** The most one transcript page holds whatever `Settings.historyPageSize` says. */
  transcriptPageCap?: number;
  /**
   * Take the app to a Settings pane. Absent in a harness, which is why every
   * call site is optional-chained rather than asserted.
   *
   * Chats owns no route of its own — the nav rail is `App`'s — and fast actions
   * are edited on ONE screen, so the composer's way to that screen has to be a
   * callback rather than a dialog of its own.
   */
  onOpenSettings?: (section: SettingsSection) => void;
  /**
   * Take the app to Settings → Memory with this entry (`m12`) open — a memory
   * tool row's handle. Absent, the handle is plain text.
   */
  onOpenMemory?: (handle: string) => void;
  /**
   * Take the app to the Knowledge page with this document open — a knowledge
   * tool row's handle. Absent, the row offers no link to it.
   */
  onOpenKnowledge?: (target: KnowledgeOpenTarget) => void;
  /**
   * Take the app to the Teams screen with this library team open — a
   * saved proposal card's "Open team". Absent, the card offers none.
   */
  onOpenTeam?: (slug: string) => void;
  /**
   * Open the Projects screen on one project, or on the gallery for null — where
   * the + menu's "Manage configurations…" leads, since each project keeps its
   * own. Absent, the menu opens the configurations dialog instead.
   */
  onOpenProject?: (projectId: string | null) => void;
  /**
   * A thread another screen has asked to have opened, or null.
   *
   * The task board's cards each hold a run, so "follow what the agent is
   * doing" is a jump from that screen to this one. It arrives as a prop rather
   * than through the notification channel both already listen on, because
   * there is no main-process event behind it — and it is CLEARED by
   * {@link onRunOpened} rather than read once, or a user who navigated away
   * from the thread and came back to Tasks would be sent to it again.
   */
  openRunId?: string | null;
  /** Told once the request above has been honoured, so the caller can drop it. */
  onRunOpened?: () => void;
  /**
   * A thread whose processes popup to open once that thread is the open one —
   * one-shot like {@link openRunId}, and told back through
   * {@link onProcessesOpened}.
   */
  processesRequest?: string | null;
  onProcessesOpened?: () => void;
  /**
   * Which thread is open NOW — announced on every change, including the ones
   * nobody requested (a click in the sidebar, a delete closing the open row).
   *
   * Deliberately NOT `openRunId`, which is the opposite direction and a
   * one-shot besides: it is a REQUEST that {@link onRunOpened} clears the
   * moment it is honoured, and clicking a row in the sidebar never sets it at
   * all. Reading it as "what is open" is wrong almost always, which is what
   * left the address bar naming no thread and the "open in browser" control
   * with nothing to build a link from.
   */
  onActiveRunChange?: (runId: string | null) => void;
  /** False while another view is shown (the tab stays mounted, hidden). */
  active?: boolean;
  /**
   * Report the open thread's name to the shell's title bar.
   *
   * The bar spans the window, ABOVE the columns, so the name of the thing on
   * screen has to travel up to it — this component is the only one that knows
   * it. Null for the landing view, which is not a document.
   */
  onTitleChange?: (title: string | null) => void;
  /**
   * Open a new tab of the shell's terminal panel in a folder. The panel spans
   * the window below every view, so it is `App`'s; absent in a harness, which
   * hides the control that would call it.
   */
  onOpenTerminal?: (cwd: string) => void;
  /** Report the open thread's folder, where a terminal opened from the keyboard starts. */
  onFolderChange?: (cwd: string | null) => void;
  /**
   * Report whether a phone is on a DETAIL page (a thread, or the new-chat
   * composer) rather than the chat list — the shell titles the page by it.
   * Always false at wider widths, where there are no pages.
   */
  onPhoneDetailChange?: (detail: boolean) => void;
  /**
   * Report every unarchived thread's wait, ranked (`waitReadings`) — the
   * title bar's status line, the jump chord and the board's card marks are
   * the shell's, and this component is the one holding the rows they read.
   */
  onWaitingChange?: (readings: readonly WaitReading[]) => void;
  /**
   * Bumped by the shell when the Chats tab is pressed while it is on show —
   * the phone's way back from a detail page to the chat list.
   */
  phoneHomeSignal?: number;
}): React.JSX.Element {
  const apis = useMemo(() => createDaemonApis(handle), [handle]);
  const projectRefs = useProjectRefs(apis, client);
  const projects = projectRefs ?? NO_PROJECTS;
  const {
    chats: chatApi,
    agents: agentsApi,
    teams: teamApi,
    groups: groupApi,
    capabilities: capabilitiesApi,
    handoff: handoffApi,
  } = apis;

  /**
   * Whether the window is phone-width right now.
   *
   * The list, the transcript and (see `showAgentsPanel` below) the agents
   * panel are three fixed-width-or-more columns that only fit side by side
   * on a wide window — at phone width the list and the transcript are pages
   * of their own (`phoneListPage` below) and the panel is a drawer. See
   * `use-narrow-viewport.ts` for why this needs a JS read rather than a
   * `max-*:` class: the grid's own `gridTemplateColumns` further down is an
   * inline style, and an inline style always wins over a class targeting
   * the same property.
   */
  const hostedRef = useRef(hosted);
  hostedRef.current = hosted;
  const isHosted = hosted !== null;
  const hostedWorkingThreads = hosted?.workingThreads ?? [];
  const narrowViewport = useNarrowViewport() && !isHosted;
  /**
   * Whether a phone shows the new-chat COMPOSER page rather than the chat
   * list. A phone has three pages — the list, the composer, an open thread —
   * and the thread is already named by `activeRunId`; this names the other
   * detail page, reached from the list's `+`.
   */
  const [mobileComposeOpen, setMobileComposeOpen] = useState(false);
  /**
   * The agents panel's own phone drawer, on the right edge.
   *
   * Component state rather than `useThreadFlag`: a panel that reopened itself
   * on every thread switch because it was left open in another one is the
   * opposite of what a drawer is for.
   */
  const [mobilePanelOpen, setMobilePanelOpen] = useState(false);
  const [composerText] = useState(createComposerText);
  const setInput = composerText.set;
  /**
   * The unsent message each thread is holding, with its staged images.
   *
   * A draft belongs to the conversation it was written in: typing half a
   * question in one thread, looking something up in another and coming back
   * must find it still there — and must never let it be sent from the thread
   * the user happened to be standing in. Before this there was ONE composer
   * state for every thread, so switching carried the text across and the images
   * with it.
   *
   * A ref, not state: nothing renders from the map itself — the composer reads
   * the live `composerText`/`attachments`, and this is only consulted at the
   * moment of a switch. As state it would re-render every thread row on each
   * keystroke.
   *
   * Keyed by run id, with {@link NEW_CHAT_DRAFT} standing in for the landing
   * card, which is a composer the user can equally leave half-filled.
   */
  const draftsRef = useRef(
    new Map<string, { text: string; images: StagedAttachment[] }>(),
  );
  /**
   * Whose draft the composer on screen is — a run id, or
   * {@link NEW_CHAT_DRAFT}. Written by `swapDraft`, the one place the composer
   * changes hands, and read by a paste still being READ when it lands.
   */
  const composerOwnerRef = useRef<string>(NEW_CHAT_DRAFT);
  // Images pasted into whichever composer is on screen — the landing card and
  // the follow-up card are never mounted at once, so one stage serves both.
  // Routed, because that one stage serves every thread's draft in turn and a
  // read can outlive the switch between two of them.
  const attachments = useAttachments(browserImageCodec, {
    current: () => composerOwnerRef.current,
    elsewhere: (owner, attachment) => {
      const draft = draftsRef.current.get(owner);
      const images = draft?.images ?? [];
      // The cap the live stage enforces, applied where nothing can say so: the
      // draft is off screen, so the surplus image is dropped rather than
      // parked where the daemon would refuse the whole message over it.
      if (images.length >= MAX_ATTACHMENTS) {
        return;
      }
      draftsRef.current.set(owner, {
        text: draft?.text ?? '',
        images: [...images, attachment],
      });
    },
  });
  const attachmentsRef = useRef<StagedAttachment[]>([]);
  attachmentsRef.current = attachments.attachments;
  // The paperclip. Images join the stage above; anything else becomes a path
  // in the text — its own on the Mac, an uploaded copy's on a phone — written
  // into whichever draft it was picked for. See `useFileAttach`.
  const fileAttach = useFileAttach({
    remote: isRemoteRuntime(),
    stageImages: attachments.addFiles,
    resolvePath: (file) => window.geniro.filePath(file),
    upload: async (file) =>
      (
        await chatApi.uploadChatFile(
          {
            uploadChatFileDto: {
              name: file.name,
              data: await readAsBase64(file),
            },
          },
          { signal: AbortSignal.timeout(CHAT_UPLOAD_TIMEOUT_MS) },
        )
      ).path,
    currentOwner: () => composerOwnerRef.current,
    deliver: (owner, paths) => {
      if (owner === composerOwnerRef.current) {
        setInput((text) => appendPaths(text, paths));
        return;
      }
      const draft = draftsRef.current.get(owner);
      draftsRef.current.set(owner, {
        text: appendPaths(draft?.text ?? '', paths),
        images: draft?.images ?? [],
      });
    },
  });
  /**
   * What the composer holds is not yet what the user gave it — a paste still
   * being read, or a picked file still uploading. Both sends refuse while it
   * lasts, and the button says which.
   */
  const attachBusy = attachments.reading || fileAttach.uploading;
  const attachBusyTitle = attachments.reading
    ? READING_PASTE_TITLE
    : UPLOADING_FILE_TITLE;

  // What the composer targets: a bare CLI kind for a single-agent chat, or
  // `team:<slug>` to run a library team.
  const [target, setTarget] = useState<string>(CLI_KINDS[0]!);
  const [teams, setTeams] = useState<TeamSummary[]>([]);
  // The "continue a session" picker. Its agent is its OWN — someone looking for
  // an old cursor thread should not have to change what the composer is
  // pointed at first, and picking one sets the composer from the session
  // anyway.
  const [sessionPickerOpen, setSessionPickerOpen] = useState(false);
  const [sessionAgent, setSessionAgent] = useState<CliKind>(CLI_KINDS[0]!);
  const [sessionListing, setSessionListing] = useState<MergedSessions | null>(
    null,
  );
  /**
   * What is in the search box, and the value the daemon has been asked about.
   *
   * TWO pieces of state and not one, because the search is now a question put
   * to the daemon — it reads the conversations themselves — and one request per
   * keystroke would spawn a cursor process per keystroke. The box stays
   * instant; the ask lands once typing pauses.
   */
  const [sessionQuery, setSessionQuery] = useState('');
  const [sessionQueryAsked, setSessionQueryAsked] = useState('');
  const [sessionsLoading, setSessionsLoading] = useState(false);
  const [sessionsError, setSessionsError] = useState<string | null>(null);
  const [resumingSessionId, setResumingSessionId] = useState<string | null>(
    null,
  );
  // Both from `composer-values.ts`: a team target has no CLI of its own, so
  // which key its model is remembered under is a rule, and an invariant held by
  // two copies is one edit from being false.
  const teamSlug = teamSlugOf(target);
  const agentKind = targetAgentKind(target);
  // Approval mode for the NEXT new chat, narrowed to what its CLI honours.
  const [approvalMode, setApprovalMode] = useState<ChatApprovalMode>('ask');
  /**
   * Per-CLI detection, or null until the probe answers. Null means UNKNOWN and
   * is rendered as "everything is offered" — refusing agents while the probe
   * is still running would flicker a working CLI out of the picker on launch.
   */
  const [cliDetections, setCliDetections] = useState<CliDetection[] | null>(
    null,
  );
  // Per-CLI so switching agents restores that agent's model rather than
  // carrying an alias the other CLI has never heard of.
  const [models, setModels] = useState<Partial<Record<CliKind, string>>>({});
  // Per-CLI for the same reason as models: the levels are one CLI's own
  // vocabulary, and the other CLI has none at all.
  const [efforts, setEfforts] = useState<Partial<Record<CliKind, string>>>({});
  const [contextWindows, setContextWindows] = useState<
    Partial<Record<CliKind, string>>
  >({});
  const [autoCompactPercent, setAutoCompactPercent] = useState<number | null>(
    null,
  );
  // The OTHER model settings, per CLI, as `{parameterId: value}`. Per CLI on
  // the same terms as the two above, and opaque: which ids exist is the MODEL's
  // answer, re-asked whenever it changes.
  const [modelParameters, setModelParameters] = useState<
    Partial<Record<CliKind, Record<string, string>>>
  >({});
  // Machine capabilities — gates the plan option; reading pre-warms the probe.
  // Working directory for the NEXT new chat. Seeded from the last-used folder
  // (persisted in settings); each chat records its own cwd, so this is only the
  // default the picker starts from.
  const [folder, setFolder] = useState<string | null>(null);
  const [composerProject, setComposerProject] =
    useState<ComposerProject>(FOLDER_PROJECT);
  // Recently used folders (persisted), surfaced as composer suggestion chips.
  const [recentFolders, setRecentFolders] = useState<string[]>([]);
  // OPTIONAL config directory (profile / account) for the NEXT new chat — the
  // CLI's own is the normal state,
  // and like the folder above it is remembered only as the picker's default;
  // the run records its own at creation and can never change it afterwards.
  // PER CLI, like `models`/`efforts` beside it: each keeps a different layout
  // in its directory, so a claude profile is not a fact about codex's own.
  const [configDirs, setConfigDirs] = useState<
    Partial<Record<CliKind, string>>
  >({});
  /** This composer's own default — the derived form every read site below uses. */
  const configDir = configDirs[agentKind] ?? null;
  const [recentConfigDirsByAgent, setRecentConfigDirsByAgent] = useState<
    Partial<Record<CliKind, string[]>>
  >({});
  /** This composer's own recents — the derived form every read site below uses. */
  const recentConfigDirs = recentConfigDirsByAgent[agentKind] ?? [];
  /**
   * The user's NAMED agent configurations, kept in Settings → the claude card.
   *
   * Read here only so the config-directory pickers can wear each one's COLOUR
   * as a left border on its row. Nothing in this screen writes them — Settings
   * owns that — so this is a snapshot, re-taken whenever this screen comes
   * back into view (beside the fast actions): a rename made in Settings shows
   * on return, while one made with this screen on display waits for the next
   * visit. Never per render — a colour is recognition, not state a turn
   * depends on, and re-reading settings.json to keep a border current by the
   * frame would cost more than the border is worth.
   */
  const [configProfiles, setConfigProfiles] = useState<ConfigProfile[]>([]);
  /**
   * The user's saved new-chat setups, and the dialog that manages them.
   *
   * A configuration is a bundle of COMPOSER state, so it is owned here rather
   * than in the picker: applying one moves this screen's own chips, and the
   * branch switch it may perform reports through this screen's notice strip.
   * They are editable on the Settings screen as well, which is why the list is
   * re-read whenever this tab becomes visible again.
   */
  const [runConfigs, setRunConfigs] = useState<RunConfig[]>([]);
  const [runConfigPickerOpen, setRunConfigPickerOpen] = useState(false);
  /** Whether the dialog opens on the LIST or straight into a new entry. */
  const [runConfigPickerMode, setRunConfigPickerMode] = useState<
    'list' | 'new'
  >('list');
  /**
   * Why a configuration's branch was not taken. Its own state rather than
   * `error`: it is a partial success — the rest of the configuration applied —
   * and it is reported through the composer's notice strip, in amber.
   */
  const [runConfigBranchNotice, setRunConfigBranchNotice] = useState<
    string | null
  >(null);
  /**
   * The user's fast actions — read here rather than in the bar, because the
   * composer is what a press writes into and this screen already owns that
   * text. Editing them lives in Settings; this side only reads.
   */
  const [fastActions, setFastActions] = useState<FastAction[]>([]);
  /**
   * How many fast actions have been pressed this session. Not a statistic — it
   * is what the caret effect below keys on, since the interesting moment is
   * "another press happened" and two presses of the same action are two of
   * them.
   */
  const [fastActionPresses, setFastActionPresses] = useState(0);
  /** The new-chat textarea, so a pressed action can put the cursor back in it. */
  const newChatInputRef = useRef<HTMLTextAreaElement | null>(null);
  const transcriptEndRef = useRef<HTMLDivElement | null>(null);
  /**
   * Is the reader above the tail? The one piece of scroll position that is
   * STATE rather than a ref, because a control renders from it
   * ({@link JumpToLatest}).
   *
   * Written from the scroll listener, which fires at frame rate — so it is
   * written with the value itself and React bails out of the re-render whenever
   * it has not flipped. Only the transitions cost anything.
   */
  const [aboveTail, setAboveTail] = useState(false);
  /**
   * Whether a turn's tool rows start folded (`Settings.collapseToolSteps`).
   *
   * Re-read whenever this tab becomes VISIBLE rather than once at mount, on the
   * same reasoning as the team library beside it: the switch lives on the
   * Settings screen while this one stays mounted, so a mount-only read would
   * leave the transcript folding by yesterday's answer until the app restarted.
   */
  const [collapseToolSteps, setCollapseToolSteps] = useState(false);
  /**
   * How many transcript items a page brings back (`Settings.historyPageSize`),
   * read when the tab becomes active like the switch above, so a size changed
   * in Settings applies to the next page fetched.
   */
  const [historyPageSize, setHistoryPageSize] = useState<number>(
    DEFAULT_HISTORY_PAGE_SIZE,
  );
  /**
   * Whether the transcript is currently glued to its tail.
   *
   * A ref, not state: it is read inside a `scroll` listener and a
   * `ResizeObserver` callback, both of which fire far more often than a render
   * should, and none of its readers need to re-render when it flips.
   */
  const followingRef = useRef(true);
  /**
   * Whether a finger owns the scroll position — while it does, the tail is not
   * followed (see `createTouchScrollGuard`). Created once: its state is two
   * numbers read from listeners, and nothing re-renders on it.
   */
  const touchGuardRef = useRef(createTouchScrollGuard());
  const upwardIntentRef = useRef(createUpwardScrollIntent());
  /**
   * `loadOlder`, or null when this thread has nothing older to load.
   *
   * A ref because the scroll listener is deliberately keyed on the run alone —
   * re-arming it per streamed token was measured churn — so it cannot close
   * over a value that changes as pages arrive.
   */
  const loadOlderRef = useRef<(() => Promise<boolean>) | null>(null);
  /** Previous `scrollTop`, so a scroll can be told to have moved UP. */
  const lastScrollTopRef = useRef(0);
  // The message queue — see `use-message-queue.ts`. Kept across a reload, a
  // hosted conversation's under its surface's own key.
  const messageQueue = useMessageQueue({
    persist: true,
    scope: hosted?.queueScope ?? null,
  });
  const {
    queues,
    pausedQueues,
    postingIds,
    steerStatus,
    subagentCancelAsk,
    answerCancelAsk,
    enqueue: enqueueMessage,
    hasQueued: hasQueuedMessages,
    resetSteerStatus,
  } = messageQueue;
  // Ref indirection: the stable addItem callback fires the drain on a turn's
  // terminal item, before the turn start the drain sends through exists.
  const drainQueueRef = useRef<(runId: string) => void>(() => {});
  // Set once the transcript rows exist, below; `useChatRun` calls it on a
  // live "not sent" row.
  const onLiveUnsentRef = useRef<
    (runId: string, deliveryIds: string[], rowId: string) => void
  >(() => {});
  /** A turn's ending already reported to the hosting surface, since the turn started. */
  const turnEndReportedRef = useRef(false);
  const onTurnEndRef = useRef<(runId: string) => void>(() => {
    turnEndReportedRef.current = true;
    void hostedRef.current?.onTurnSettled?.();
  });

  /**
   * Park the composer's contents under `from`, and put `to`'s back.
   *
   * One helper for both directions (thread → thread and thread → landing card)
   * so the two cannot drift into saving different things. Called BEFORE the
   * switch commits, since it reads what is still on screen. `null` is the
   * landing card, which has no run id to key its draft by.
   */
  const swapDraft = useLatestCallback(
    (from: string | null, to: string | null): void => {
      const text = composerText.get();
      const images = attachmentsRef.current;
      const fromKey = from ?? NEW_CHAT_DRAFT;
      if (text.length > 0 || images.length > 0) {
        draftsRef.current.set(fromKey, { text, images });
      } else {
        // An emptied composer is not a draft — keeping one would restore text
        // the user had deliberately cleared.
        draftsRef.current.delete(fromKey);
      }
      const incoming = draftsRef.current.get(to ?? NEW_CHAT_DRAFT);
      setInput(incoming?.text ?? '');
      attachments.restore(incoming?.images ?? []);
      composerOwnerRef.current = to ?? NEW_CHAT_DRAFT;
    },
    [attachments],
  );

  /**
   * Put a message that did not go out back where the user wrote it: the
   * composer if its thread is still the one on screen, else that thread's
   * parked draft — which is where a switch made during the send put everything
   * else the user left there.
   *
   * Never over what was written since, the rule every send path follows: text
   * comes back only into an empty box, images only onto an empty stage.
   */
  const restoreUnsent = useLatestCallback(
    (runId: string, text: string, staged: StagedAttachment[]): void => {
      const restored = { text, staged };
      if (composerOwnerRef.current === runId) {
        setInput(
          (current) =>
            restoreIntoEmpty({ text: current, staged: [] }, restored).text,
        );
        if (attachmentsRef.current.length === 0) {
          attachments.restore(staged);
        }
        return;
      }
      const draft = draftsRef.current.get(runId);
      const next = restoreIntoEmpty(
        { text: draft?.text ?? '', staged: draft?.images ?? [] },
        restored,
      );
      draftsRef.current.set(runId, {
        text: next.text,
        images: [...next.staged],
      });
    },
    [attachments],
  );

  const {
    runs,
    setRuns,
    markRunSeen,
    runsLoaded,
    runsRef,
    activeRunId,
    activeRunIdRef,
    items,
    itemsRef,
    anchors,
    callConversations,
    delegateConversations,
    hasOlder,
    loadingOlder,
    loadingHistory,
    loadOlder,
    loadAround,
    loadNewer,
    returnToTail,
    awayFromTail,
    namingRunIds,
    markRenamed,
    liveText,
    reconnectNonce,
    streaming,
    setStreaming,
    error,
    setError,
    activities,
    holding,
    awaitingCalls,
    rootsIdle,
    shellsOut,
    delegatesOut,
    settleSummaries,
    quietSettles,
    settleOwed,
    offScopeRuns,
    agentNotices,
    deadRequestKeys,
    pendingScrollRef,
    sawTerminalRef,
    addItem,
    rememberRunContext,
    refreshRuns,
    hasOlderRuns,
    loadingOlderRuns,
    loadOlderRuns,
    chatScope,
    showScope,
    activityWindow,
    showActivityWindow,
    addRun,
    placeRun,
    dropRun,
    refileChangedRuns,
    activateRun,
    handleActivateRun,
    deactivateRun,
  } = useChatRun({
    client,
    chatApi,
    teamApi,
    historyPageSize,
    pageCap:
      transcriptPageCap ??
      (isHosted && isRemoteRuntime() ? REMOTE_HISTORY_PAGE : undefined),
    swapDraft,
    resetSteerStatus,
    hasQueuedMessages,
    drainQueueRef,
    onLiveUnsentRef,
    onTurnEndRef,
    pinned: hosted === null ? null : { open: hosted.open },
  });

  const [activityPreset, setActivityPreset] = useState<ActivityPreset>('any');

  /**
   * Every turn a hosted conversation starts other than a typed send (a
   * button, an Apply, a Retry) runs the surface's step first and reports the
   * conversation working at once, as a send does; `refuseHostedTurn` takes
   * that back when the daemon refuses the start.
   */
  const startHostedTurn = useLatestCallback(
    async (runId: string | null): Promise<boolean> => {
      const surface = hostedRef.current;
      if (surface === null) {
        return false;
      }
      await surface.onBeforeSend?.();
      if (
        runId === null ||
        runId !== activeRunIdRef.current ||
        streamingRef.current
      ) {
        return false;
      }
      setStreaming(true);
      turnEndReportedRef.current = false;
      return true;
    },
    [setStreaming],
  );
  const refuseHostedTurn = useLatestCallback((): void => {
    turnEndReportedRef.current = true;
    setStreaming(false);
  }, [setStreaming]);

  // A thread opening (a row tapped, a jump from Tasks, the composer's first
  // send creating one) replaces the composer page, so going back from that
  // thread lands on the list rather than on a composer nobody left open.
  useEffect(() => {
    if (activeRunId !== null) {
      setMobileComposeOpen(false);
    }
  }, [activeRunId]);
  /** The phone's chat LIST page — the Chats tab's first page. */
  const phoneListPage =
    narrowViewport && activeRunId === null && !mobileComposeOpen;
  const phoneDetailPage = narrowViewport && !phoneListPage;
  useEffect(() => {
    onPhoneDetailChange?.(phoneDetailPage);
  }, [onPhoneDetailChange, phoneDetailPage]);

  // Null unless there IS something older, so the scroll listener's own guard is
  // "can this thread page at all" rather than a second copy of that question.
  useEffect(() => {
    loadOlderRef.current = hasOlder ? loadOlder : null;
  }, [hasOlder, loadOlder]);
  // The same for reading FORWARD, which only a window from the middle of the
  // conversation can do — at the tail, newer rows arrive live.
  const loadNewerRef = useRef<(() => Promise<boolean>) | null>(null);
  useEffect(() => {
    loadNewerRef.current = awayFromTail ? loadNewer : null;
  }, [awayFromTail, loadNewer]);

  // Live mirror, so a callback that must not be rebuilt on every delta can
  // still ask whether a turn was in flight BEFORE it started one of its own —
  // which is what tells a failed send whether the working state is its to
  // clear. Assigned during render, never from an effect.
  const streamingRef = useRef(false);
  streamingRef.current = streaming;
  const holdingRef = useRef<ReadonlyMap<string, number>>(holding);
  useEffect(() => {
    holdingRef.current = holding;
  }, [holding]);
  /**
   * The team runs whose manager is parked in a wait on its own callees —
   * the second half of "this agent is in a turn and producing nothing", read
   * on the send path beside {@link holdingRef}.
   */
  const awaitingCallsRef = useRef<ReadonlySet<string>>(awaitingCalls);
  useEffect(() => {
    awaitingCallsRef.current = awaitingCalls;
  }, [awaitingCalls]);
  /** Team runs whose Manager has ended its turn — read beside the two above. */
  const rootsIdleRef = useRef<ReadonlySet<string>>(rootsIdle);
  useEffect(() => {
    rootsIdleRef.current = rootsIdle;
  }, [rootsIdle]);
  /**
   * The runs with BACKGROUND work out — sub-agents still out, or a detached
   * command still up. Read on the send path beside the refs above; they park
   * the agent only once its reply is over (see {@link activeRunHeld}).
   */
  const delegatesOutRef = useRef<ReadonlySet<string>>(delegatesOut);
  useEffect(() => {
    delegatesOutRef.current = delegatesOut;
  }, [delegatesOut]);
  const shellsOutRef = useRef<ReadonlySet<string>>(shellsOut);
  useEffect(() => {
    shellsOutRef.current = shellsOut;
  }, [shellsOut]);

  /**
   * What each chat's context ring last read — see {@link useContextReadings}.
   *
   * Declared here, well above its two uses, because one of them is the DELETE
   * path: a reading outliving the thread it describes is the one way a
   * per-run cache could start lying, and the cleanup has to be reachable from
   * where the run is destroyed.
   */
  const {
    remember: rememberContextReading,
    recall: recallContextReading,
    forget: forgetContextReading,
  } = useContextReadings();

  useEffect(() => {
    if (!active) {
      return;
    }
    void window.geniro.getSettings().then((s) => {
      setCollapseToolSteps(s.collapseToolSteps ?? false);
      setHistoryPageSize(s.historyPageSize ?? DEFAULT_HISTORY_PAGE_SIZE);
    });
  }, [active]);

  // The team library is editable on the Teams page while this tab stays
  // mounted (hidden), so refetch it every time the tab becomes visible — a
  // mount-only fetch would leave the target selector stale after a save or
  // delete over there.
  const [teamsLoaded, setTeamsLoaded] = useState(false);
  useEffect(() => {
    if (!active) {
      return;
    }
    void teamApi
      .listTeams()
      .then((list) => {
        setTeams(list);
        setTeamsLoaded(true);
      })
      .catch(() => setTeams([]));
  }, [active, teamApi]);

  // A remembered team target can be gone (deleted/renamed on the Teams
  // page): once the library has ACTUALLY loaded, fall back instead of keeping
  // a dead selection. Gated on teamsLoaded so the initial empty list (or
  // a failed fetch) never clobbers a target the restore just set.
  useEffect(() => {
    if (teamsLoaded && teamSlug && !teams.some((wf) => wf.slug === teamSlug)) {
      setTarget(CLI_KINDS[0]!);
    }
  }, [teamsLoaded, teamSlug, teams]);

  /** Composer target change — remembered as the default for next time. */
  const changeTarget = useLatestCallback((value: string): void => {
    setTarget(value);
    void window.geniro.updateSettings({ lastChatTarget: value });
  }, []);

  /**
   * New-run approval mode — remembered like the target above, so the composer
   * opens on the mode the user actually works in. The per-RUN picker in the
   * open transcript is deliberately not wired here: it patches that one run's
   * setting, and changing an existing run's mode is not a statement about what
   * the next one should start as.
   */
  const changeApprovalMode = useLatestCallback(
    (value: ChatApprovalMode): void => {
      setApprovalMode(value);
      void window.geniro.updateSettings({ lastApprovalMode: value });
    },
    [],
  );

  /** New-run model for one CLI — remembered per CLI, like the mode above. */
  const changeModel = useLatestCallback(
    (kind: CliKind, model: string | null): void => {
      setModels((current) => {
        const next = { ...current };
        if (model === null) {
          // Absent, not empty: "no entry" IS the CLI default, and an empty
          // string would reach `--model` as a blank argument.
          delete next[kind];
        } else {
          next[kind] = model;
        }
        void window.geniro.updateSettings({ lastModels: next });
        return next;
      });
      // A window size belongs to the MODEL that offered it: only some models
      // carry the axis at all, and those that do differ in what they list, so a
      // size remembered from the previous model is one the new one may simply
      // refuse. The daemon already drops it on a patch that changes model
      // (`ChatService`); a NEW run has to be told the same thing here, or it is
      // created carrying a size the model declines — and the chip, reading the
      // new model's list, draws the default while the stored word is still what
      // gets sent.
      setContextWindows((current) => {
        if (current[kind] === undefined) {
          return current;
        }
        const next = { ...current };
        delete next[kind];
        void window.geniro.updateSettings({ lastContextWindows: next });
        return next;
      });
      // The other model settings go the same way, and the case is sharper:
      // WHICH parameter ids exist at all is the model's own answer, so a value
      // kept across a model change names an axis the new model never
      // enumerated — sent on every turn, and for months on a team node.
      setModelParameters((current) => {
        if (current[kind] === undefined) {
          return current;
        }
        const next = { ...current };
        delete next[kind];
        void window.geniro.updateSettings({ lastModelParameters: next });
        return next;
      });
    },
    [],
  );

  /** New-run reasoning effort for one CLI — remembered per CLI, like the model. */
  const changeEffort = useLatestCallback(
    (kind: CliKind, effort: string | null): void => {
      setEfforts((current) => {
        const next = { ...current };
        if (effort === null) {
          // Absent, not empty — "no entry" IS the CLI default (no --effort).
          delete next[kind];
        } else {
          next[kind] = effort;
        }
        void window.geniro.updateSettings({ lastEfforts: next });
        return next;
      });
    },
    [],
  );

  /** New-run auto-compact threshold — one for every CLI, remembered. */
  const changeAutoCompact = useLatestCallback(
    (percent: number | null): void => {
      setAutoCompactPercent(percent);
      void window.geniro.updateSettings({ lastAutoCompactPercent: percent });
    },
    [],
  );

  /**
   * New-run context-window size for one CLI — remembered per CLI, like the
   * effort, and cleared to the model's default the same way.
   *
   * Per CLI even though the sizes belong to the MODEL: a user who works at `1m`
   * wants it on the next chat too, and a size the next model does not offer is
   * drawn as unavailable by the chip rather than sent.
   */
  const changeContextWindow = useLatestCallback(
    (kind: CliKind, contextWindow: string | null): void => {
      setContextWindows((current) => {
        const next = { ...current };
        if (contextWindow === null) {
          // Absent, not empty — "no entry" IS the model's own window.
          delete next[kind];
        } else {
          next[kind] = contextWindow;
        }
        void window.geniro.updateSettings({ lastContextWindows: next });
        return next;
      });
    },
    [],
  );

  /**
   * New-run value for ONE of a model's other settings, remembered per CLI.
   *
   * One parameter at a time rather than the whole map, because that is what a
   * chip press is — the row holds several, each its own control, and replacing
   * the map from one of them would drop the others.
   */
  const changeModelParameter = useLatestCallback(
    (kind: CliKind, parameterId: string, value: string | null): void => {
      setModelParameters((current) => {
        const forKind = { ...(current[kind] ?? {}) };
        if (value === null) {
          // Absent, not empty — "no entry" IS whatever the model is already on.
          delete forKind[parameterId];
        } else {
          forKind[parameterId] = value;
        }
        const next = { ...current };
        if (Object.keys(forKind).length === 0) {
          delete next[kind];
        } else {
          next[kind] = forKind;
        }
        void window.geniro.updateSettings({ lastModelParameters: next });
        return next;
      });
    },
    [],
  );

  // Sidebar labels show the team's NAME, not its slug.
  const teamNames = useMemo(
    () => new Map(teams.map((wf) => [wf.slug, wf.name])),
    [teams],
  );

  // Relative "last activity" labels drift as time passes — re-render the list
  // once a minute while the tab is visible so "3m" doesn't freeze forever.
  const [, bumpClock] = useReducer((n: number) => n + 1, 0);
  useEffect(() => {
    if (!active) {
      return;
    }
    const id = window.setInterval(bumpClock, 60_000);
    return () => window.clearInterval(id);
  }, [active]);

  // Stable id-keyed rename commit so the memoized ChatListItem rows do not
  // re-render on every keystroke (fresh per-row closures would defeat the
  // memo equality). Its activate sibling lives below activateRun. The row owns
  // the edit state and its busy/error display; this only performs the write,
  // and REJECTS on failure so the row can keep the typed name on screen.
  const handleRenameRun = useLatestCallback(
    async (runId: string, title: string): Promise<void> => {
      const updated = await chatApi.renameRun({
        runId,
        renameRunDto: { title },
      });
      // BEFORE the state write, so a naming announce that lands between the two
      // cannot put the generated title back over the name just typed. The
      // daemon already refuses to rename a run the user has renamed; this
      // covers the other order, where its write had already won.
      markRenamed(runId);
      // Patch only the title — a concurrent WS item may have fresher
      // status/preview in state than this response's snapshot.
      setRuns((prev) =>
        prev.map((run) =>
          run.id === updated.id ? { ...run, title: updated.title } : run,
        ),
      );
    },
    [chatApi, markRenamed],
  );

  // Rejects on failure so the notes field can keep its text and say so. Patches
  // only `notes`, for the reason the rename above patches only `title`.
  // Per run, the newest write sent: a slower, older reply landing after a newer
  // one must not put the older text back on the row.
  const notesWriteSeq = useRef(new Map<string, number>());
  const handleSetRunNotes = useLatestCallback(
    async (runId: string, notes: string): Promise<void> => {
      const seq = (notesWriteSeq.current.get(runId) ?? 0) + 1;
      notesWriteSeq.current.set(runId, seq);
      const updated = await chatApi.setRunNotes({
        runId,
        setRunNotesDto: { notes },
      });
      if (notesWriteSeq.current.get(runId) !== seq) {
        return;
      }
      setRuns((prev) =>
        prev.map((run) =>
          run.id === updated.id ? { ...run, notes: updated.notes } : run,
        ),
      );
    },
    [chatApi],
  );

  /**
   * The sidebar's groups, in the order they are drawn.
   *
   * Held here rather than fetched by each header because every group-level
   * answer the daemon gives is a whole-list one — a move swaps two rows, a
   * delete releases runs into the loose section — so one array is the only
   * shape in which the sidebar can be right about all of them at once.
   */
  const [groups, setGroups] = useState<RunGroupDto[]>([]);
  /**
   * A group just created that should open with its name selected, so naming it
   * is typing rather than a second trip through the menu. The header reports
   * back when it has taken the focus and this clears — otherwise a later
   * re-mount would drop the row into edit mode again, out of nowhere.
   */
  const [namingGroupId, setNamingGroupId] = useState<string | null>(null);
  /**
   * The sections the user asked to see in FULL, keyed the way the list keys
   * them (`'loose'` for the ungrouped run).
   *
   * Per-session and deliberately not persisted like a group's `collapsed`: the
   * fold's job is to keep a long section from burying its neighbours, and the
   * answer to "which threads matter" is the working set at the moment someone
   * is looking. A relaunch is exactly when that should be re-asked.
   */
  const [expandedSections, setExpandedSections] = useState<ReadonlySet<string>>(
    () => new Set<string>(),
  );

  /**
   * What the pointer is currently carrying, or null.
   *
   * ONE piece of state for both drags the sidebar supports, because a drop
   * target has to know which it is being offered: a group dragged onto a header
   * REORDERS, a chat dragged onto the same header FILES ITSELF into it, and the
   * two must not be told apart by guessing from an id.
   */
  const [drag, setDrag] = useState<{
    kind: 'group' | 'run';
    id: string;
  } | null>(null);
  /**
   * The section a dragged CHAT would land in — a group id, or null for the
   * loose list. `undefined` is "none", which is a third state and not the same
   * as null: null is a real destination.
   */
  const [dropSectionId, setDropSectionId] = useState<string | null | undefined>(
    undefined,
  );

  /**
   * Read by the drag handlers, which must stay referentially stable: they are
   * passed to memoized rows and headers, and a fresh identity per render would
   * rebuild every one of them on every `dragover` — several times a second,
   * mid-drag.
   */
  const groupsRef = useRef<RunGroupDto[]>([]);
  groupsRef.current = groups;
  const handleSetRunGroupRef = useRef<
    (runId: string, groupId: string | null) => void
  >(() => undefined);
  const dragRef = useRef<{ kind: 'group' | 'run'; id: string } | null>(null);
  dragRef.current = drag;

  const refreshGroups = useLatestCallback((): void => {
    void groupApi
      .listRunGroups()
      .then(setGroups)
      .catch((err: unknown) => setError(String(err)));
  }, [groupApi]);

  /**
   * Reordering happens LIVE, in `groups`, as the cursor passes over each
   * header — the list rearranges under the pointer rather than jumping when the
   * button comes up, which is the difference between a drag that feels
   * connected to the mouse and one that feels like a form submission. The
   * daemon is told once, at the end (`handleDragEnd`), because the intermediate
   * arrangements are not decisions.
   */
  const handleGroupDragStart = useLatestCallback(
    (groupId: string): void => setDrag({ kind: 'group', id: groupId }),
    [],
  );

  const handleRunDragStart = useLatestCallback(
    (runId: string): void => setDrag({ kind: 'run', id: runId }),
    [],
  );

  /**
   * The pointer is over a group's header.
   *
   * Two gestures land here and they do different things: a GROUP being dragged
   * rearranges the list under the cursor, a CHAT lights the header up as the
   * place it would land.
   */
  const handleGroupDragOver = useLatestCallback((overGroupId: string): void => {
    const dragging = dragRef.current;
    if (dragging === null) {
      return;
    }
    if (dragging.kind === 'run') {
      setDropSectionId(overGroupId);
      return;
    }
    setGroups((prev) => {
      if (dragging.id === overGroupId) {
        return prev;
      }
      const from = prev.findIndex((group) => group.id === dragging.id);
      const to = prev.findIndex((group) => group.id === overGroupId);
      if (from === -1 || to === -1) {
        return prev;
      }
      const next = [...prev];
      next.splice(to, 0, next.splice(from, 1)[0]!);
      // Positions are restated so nothing downstream re-sorts the array back
      // into the order it had a moment ago — `runGroupSections` sorts by
      // `position`, and leaving them stale would undo the drag on every
      // render.
      return next.map((group, position) => ({ ...group, position }));
    });
  }, []);

  /** The pointer is over a SECTION — a chat row, or the loose list's label. */
  const handleSectionDragOver = useLatestCallback(
    (groupId: string | null): void => {
      if (dragRef.current?.kind === 'run') {
        setDropSectionId(groupId);
      }
    },
    [],
  );

  /**
   * The scope whose band a live reorder has actually MOVED, and `undefined`
   * while none has.
   *
   * `null` is a real value here — the loose list is a scope — which is why the
   * idle state is `undefined` rather than null. A ref rather than state
   * because nothing renders from it: it exists so `dragend` can tell a drag
   * that rearranged something from one that merely passed over rows, and a
   * drop that changes nothing writes nothing.
   */
  const pinnedReorderRef = useRef<string | null | undefined>(undefined);

  /**
   * The pointer is over a chat ROW.
   *
   * It rearranges the PINNED band under the cursor, and does nothing at all
   * anywhere else — which is the whole of "only relative to other pinned
   * threads". Three separate refusals, and each names a different way the
   * gesture could leave the band: the carried row is not pinned, the row under
   * it is not, or the two are in different groups. A pinned run dragged over
   * another group's rows therefore reorders nothing, and the section's own
   * drop handler still re-files it, which is the move that was already there.
   *
   * Live, like the group headers' reorder and for its reason: the daemon is
   * told once at `dragend`, because the arrangements the cursor passes through
   * are not decisions.
   */
  const handleRunDragOver = useLatestCallback((overRunId: string): void => {
    const dragging = dragRef.current;
    if (dragging?.kind !== 'run' || dragging.id === overRunId) {
      return;
    }
    const rows = runsRef.current;
    const moved = rows.find((row) => row.id === dragging.id);
    const over = rows.find((row) => row.id === overRunId);
    if (
      moved === undefined ||
      over === undefined ||
      moved.pinnedPosition === null ||
      over.pinnedPosition === null ||
      moved.groupId !== over.groupId
    ) {
      return;
    }
    const band = rows
      .filter(
        (row) => row.groupId === moved.groupId && row.pinnedPosition !== null,
      )
      .sort((a, b) => (a.pinnedPosition ?? 0) - (b.pinnedPosition ?? 0));
    const from = band.findIndex((row) => row.id === moved.id);
    const to = band.findIndex((row) => row.id === over.id);
    if (from === -1 || to === -1 || from === to) {
      return;
    }
    const next = [...band];
    next.splice(to, 0, next.splice(from, 1)[0]!);
    const seated = new Map(next.map((row, position) => [row.id, position]));
    pinnedReorderRef.current = moved.groupId;
    // Positions are RESTATED rather than left stale, for the reason the group
    // reorder restates its own: `splitPinnedRuns` sorts the band by this
    // column, so an unwritten position would re-sort the list back into the
    // order it had a moment ago and undo the drag on every render.
    setRuns((prev) =>
      prev.map((row) => {
        const position = seated.get(row.id);
        return position === undefined
          ? row
          : { ...row, pinnedPosition: position };
      }),
    );
  }, []);

  /** A chat was dropped into a section. A drop in its own section is a no-op. */
  const handleDropInSection = useLatestCallback(
    (groupId: string | null): void => {
      const dragging = dragRef.current;
      // A GROUP drop is `dragend`'s to finish, so it must leave the drag standing.
      // Every section accepts the drop (its `dragover` prevents the default for
      // either gesture), and `drop` fires BEFORE `dragend`: clearing here
      // re-rendered `dragRef` to null in between, `handleDragEnd` then read no
      // group, and the arrangement the list had just been dragged into was never
      // saved — the next rename, recolour or fold answered with the daemon's old
      // positions and the rows jumped back.
      if (dragging?.kind !== 'run') {
        return;
      }
      setDropSectionId(undefined);
      setDrag(null);
      const run = runsRef.current.find((r) => r.id === dragging.id);
      if (run === undefined || run.groupId === groupId) {
        return;
      }
      handleSetRunGroupRef.current(dragging.id, groupId);
    },
    [],
  );

  const handleDragEnd = useLatestCallback((): void => {
    const dragging = dragRef.current;
    setDrag(null);
    setDropSectionId(undefined);
    const reordered = pinnedReorderRef.current;
    pinnedReorderRef.current = undefined;
    if (reordered !== undefined) {
      // Only when the band actually MOVED — a pinned row picked up and put
      // back writes nothing. The whole arrangement goes out, not a
      // displacement, so replaying it lands on the same rows.
      void chatApi
        .reorderPinnedRuns({
          reorderPinnedDto: {
            groupId: reordered,
            ids: runsRef.current
              .filter(
                (row) =>
                  row.groupId === reordered && row.pinnedPosition !== null,
              )
              .sort((a, b) => (a.pinnedPosition ?? 0) - (b.pinnedPosition ?? 0))
              .map((row) => row.id),
          },
        })
        .then((band) => {
          const seated = new Map(
            band.map((row) => [row.id, row.pinnedPosition]),
          );
          setRuns((prev) =>
            prev.map((row) =>
              seated.has(row.id)
                ? { ...row, pinnedPosition: seated.get(row.id) ?? null }
                : row,
            ),
          );
        })
        .catch((err: unknown) => setError(String(err)));
      return;
    }
    if (dragging?.kind !== 'group') {
      return;
    }
    void groupApi
      // The whole arrangement, not a displacement: the daemon renumbers from
      // this list, so replaying it lands on the same rows.
      .reorderRunGroups({
        reorderRunGroupsDto: { ids: groupsRef.current.map((g) => g.id) },
      })
      .then(setGroups)
      .catch((err: unknown) => setError(String(err)));
  }, [groupApi, chatApi]);

  const handleToggleGroup = useLatestCallback(
    (groupId: string, collapsed: boolean): void => {
      // Optimistic: folding is the one group action a user does repeatedly, and
      // waiting a round trip to see a chevron move reads as a dropped click.
      // The write is a fire-and-forget PATCH — a failure leaves the fold state
      // to be corrected by the next list fetch rather than snapping the row
      // back under a finger that is already moving away.
      setGroups((prev) =>
        prev.map((group) =>
          group.id === groupId ? { ...group, collapsed } : group,
        ),
      );
      void groupApi
        .updateRunGroup({ groupId, updateRunGroupDto: { collapsed } })
        .catch((err: unknown) => setError(String(err)));
    },
    [groupApi],
  );

  /** Rejects on failure, so the header keeps the typed name and shows why. */
  const handleRenameGroup = useLatestCallback(
    async (groupId: string, name: string): Promise<void> => {
      const updated = await groupApi.updateRunGroup({
        groupId,
        updateRunGroupDto: { name },
      });
      setGroups((prev) =>
        prev.map((group) => (group.id === groupId ? updated : group)),
      );
    },
    [groupApi],
  );

  const handleGroupCommand = useLatestCallback(
    (groupId: string, command: GroupCommand): void => {
      const fail = (err: unknown): void => setError(String(err));
      if (command.kind === 'color') {
        void groupApi
          .updateRunGroup({
            groupId,
            updateRunGroupDto: { color: command.color },
          })
          .then((updated) =>
            setGroups((prev) =>
              prev.map((group) => (group.id === groupId ? updated : group)),
            ),
          )
          .catch(fail);
        return;
      }
      if (command.kind === 'auto-folder') {
        void window.geniro
          .pickProjectFolder()
          .then((chosen) =>
            chosen === null
              ? undefined
              : groupApi
                  .updateRunGroup({
                    groupId,
                    updateRunGroupDto: { autoCwd: chosen },
                  })
                  .then((updated) =>
                    setGroups((prev) =>
                      prev.map((group) =>
                        group.id === groupId ? updated : group,
                      ),
                    ),
                  ),
          )
          .catch(fail);
        return;
      }
      if (command.kind === 'auto-team') {
        void groupApi
          .updateRunGroup({
            groupId,
            updateRunGroupDto: { autoTeamId: command.slug },
          })
          .then((updated) =>
            setGroups((prev) =>
              prev.map((group) => (group.id === groupId ? updated : group)),
            ),
          )
          .catch(fail);
        return;
      }
      if (command.kind === 'auto-clear') {
        void groupApi
          .updateRunGroup({ groupId, updateRunGroupDto: { autoCwd: null } })
          .then((updated) =>
            setGroups((prev) =>
              prev.map((group) => (group.id === groupId ? updated : group)),
            ),
          )
          .catch(fail);
        return;
      }
      // Delete ASKS first. Nothing is destroyed — the chats are released, not
      // removed — but "delete" is a word a user reads as final, so the dialog
      // is where the difference gets stated instead of being squeezed into a
      // menu row's hint.
      setDeletingGroup(groupsRef.current.find((g) => g.id === groupId) ?? null);
      setDeleteGroupError(null);
    },
    [groupApi],
  );

  /** The group queued for deletion (null = no confirm open). */
  const [deletingGroup, setDeletingGroup] = useState<RunGroupDto | null>(null);
  const [deleteGroupBusy, setDeleteGroupBusy] = useState(false);
  const [deleteGroupError, setDeleteGroupError] = useState<string | null>(null);

  const confirmDeleteGroup = useLatestCallback(async (): Promise<void> => {
    const group = deletingGroup;
    if (group === null) {
      return;
    }
    setDeleteGroupBusy(true);
    setDeleteGroupError(null);
    try {
      await groupApi.deleteRunGroup({ groupId: group.id });
      setGroups((prev) => prev.filter((row) => row.id !== group.id));
      setRuns((prev) =>
        prev.map((run) =>
          run.groupId === group.id ? { ...run, groupId: null } : run,
        ),
      );
      setDeletingGroup(null);
    } catch (err) {
      // Kept open carrying the reason, like every other confirm here: closing
      // would report a delete that did not happen.
      setDeleteGroupError(String(err));
    } finally {
      setDeleteGroupBusy(false);
    }
  }, [deletingGroup, groupApi]);

  const handleSetRunGroup = useLatestCallback(
    (runId: string, groupId: string | null): void => {
      void chatApi
        // On the RUN's route — and so on the CHATS client: the run is what
        // changed, so the run is the answer and the sidebar replaces the row it
        // already holds.
        .setRunGroup({ runId, setRunGroupDto: { groupId } })
        .then((updated) =>
          setRuns((prev) =>
            prev.map((run) =>
              run.id === updated.id
                ? { ...run, groupId: updated.groupId }
                : run,
            ),
          ),
        )
        .catch((err: unknown) => setError(String(err)));
    },
    [chatApi],
  );

  const handleSetRunPinned = useLatestCallback(
    (runId: string, pinned: boolean): void => {
      void chatApi
        .setRunPinned({ runId, setRunPinnedDto: { pinned } })
        .then((affected) => {
          // The reply is the whole SCOPE the write re-seated, not the pressed
          // row, so every position this client holds for that band is
          // replaced at once. Deriving the others here instead would be the
          // daemon's own renumbering written a second time, in a place that
          // cannot see the rows a stale list is missing.
          const seated = new Map(
            affected.map((run) => [run.id, run.pinnedPosition]),
          );
          setRuns((prev) =>
            prev.map((run) =>
              seated.has(run.id)
                ? { ...run, pinnedPosition: seated.get(run.id) ?? null }
                : run,
            ),
          );
        })
        .catch((err: unknown) => setError(String(err)));
    },
    [chatApi],
  );

  // Stable and id-keyed like its pin sibling, so the memoized rows keep their
  // equality. Patches only the colour: the reply is a snapshot, and a WS item
  // may already have fresher status in state.
  const handleSetRunColor = useLatestCallback(
    (runId: string, color: RunGroupColor | null): void => {
      void chatApi
        .setRunColor({ runId, setRunColorDto: { color } })
        .then((updated) => {
          setRuns((prev) =>
            prev.map((run) =>
              run.id === updated.id ? { ...run, color: updated.color } : run,
            ),
          );
        })
        .catch((err: unknown) => setError(String(err)));
    },
    [chatApi],
  );

  // Read by the drop handler above, which is declared first because the drag
  // handlers belong together — a ref keeps the order from mattering.
  handleSetRunGroupRef.current = handleSetRunGroup;

  /**
   * Make a group.
   *
   * The name is a placeholder the header immediately opens for editing —
   * there is no text-prompt dialog in this app, and adding one to name a
   * folder would be a modal for a two-word answer. Chats are dragged in
   * afterwards; nothing files itself here.
   */
  const handleNewGroup = useLatestCallback((): void => {
    void groupApi
      .createRunGroup({ createRunGroupDto: { name: 'New group' } })
      .then((created) => {
        setGroups((prev) => [...prev, created]);
        setNamingGroupId(created.id);
      })
      .catch((err: unknown) => setError(String(err)));
  }, [groupApi]);

  /** Stable, so the memoized headers do not re-render on every keystroke. */
  const clearNamingGroup = useLatestCallback(() => setNamingGroupId(null), []);

  /**
   * Write one thread to a file — the whole transcript with every tool call, the
   * settings its turns ran under, its per-node state and its spend.
   *
   * The DOCUMENT is the daemon's (`exportChat`), deliberately: a chat's history
   * is paged behind a cursor, so a file built from `items` on screen would be
   * whatever the user had scrolled through, and nothing in it would say so.
   * This side only names the file and hands the bytes to main.
   *
   * NOT gated behind a confirm, and SILENT on success: it creates a file and
   * changes nothing, the save dialog is itself the decision point, and the user
   * chose where the file went — a strip afterwards saying so would report back
   * the one fact they just supplied. Only a failure has anything to say.
   */
  const handleExportRun = useLatestCallback(
    (runId: string): void => {
      const run = runsRef.current.find((r) => r.id === runId);
      if (!run) {
        return;
      }
      setError(null);
      void (async () => {
        try {
          const doc = await chatApi.exportChat({ runId });
          await window.geniro.saveChatExport({
            suggestedName: chatExportBaseName(runLabel(run, teamNames)),
            // Indented rather than compact: this file exists to be read and
            // pasted into a bug report, and two spaces is the difference
            // between a diffable document and one very long line.
            json: JSON.stringify(doc, null, 2),
            // Rendered up front rather than after the pick, because the format
            // is chosen inside a native panel main owns — see
            // `main/save-chat-export.ts`. Both are strings over a document
            // already in memory.
            markdown: chatToMarkdown(doc),
          });
        } catch (err) {
          setError(String(err));
        }
      })();
    },
    [chatApi, teamNames],
  );

  /** The user's verdicts on a card's member assessments, for `MemberVerdictsContext`. */
  const readMemberVerdicts = useLatestCallback<MemberVerdicts['read']>(
    (chatRunId, cardSeq) =>
      apis.stats.readCardAssessmentVerdicts({ chatRunId, cardSeq }),
    [apis],
  );
  const setMemberVerdict = useLatestCallback<MemberVerdicts['set']>(
    (request) =>
      apis.stats.setMemberAssessmentVerdict({
        memberAssessmentVerdictDto: request,
      }),
    [apis],
  );
  const memberVerdicts = useMemo<MemberVerdicts>(
    () => ({ read: readMemberVerdicts, set: setMemberVerdict }),
    [readMemberVerdicts, setMemberVerdict],
  );

  /**
   * Put back the worktree a chat outlived — see `task-worktree.ts`. Every send
   * path goes through `startTurn`, Retry and Apply through their own calls, so
   * those are the three places that use it.
   */
  const restoreWorktree = useLatestCallback(
    (run: WorktreeRun) => restoreRunWorktree(apis, run),
    [apis],
  );

  /** A recommendations card's Apply, for `RecommendationsApplyContext`. */
  const applyRecommendations = useLatestCallback<RecommendationsApplier>(
    async (runId, cardSeq, ids) => {
      const raised = await startHostedTurn(runId);
      const clientMessageId = randomId();
      try {
        await sendRestoringWorktree(
          () =>
            chatApi.applyRecommendations({
              runId,
              applyRecommendationsDto: { cardSeq, ids, clientMessageId },
            }),
          runsRef.current.find((run) => run.id === runId) ?? null,
          restoreWorktree,
        );
      } catch (err) {
        if (raised) {
          refuseHostedTurn();
        }
        throw err;
      }
    },
    [chatApi, startHostedTurn, refuseHostedTurn, restoreWorktree],
  );

  /** An analysis chat's header chip: the thread it reads, one press away. */
  const analysisSourceOf = useLatestCallback(
    (run: ChatRun): { label: string; onOpen: () => void } | null => {
      if (isHosted) {
        return null;
      }
      const teamSlug = run.analysisTeamSlug;
      if (teamSlug != null) {
        return {
          label: `team ${teamNames.get(teamSlug) ?? teamSlug}`,
          onOpen: () => onOpenTeam?.(teamSlug),
        };
      }
      const sourceId = run.analysisSourceRunId;
      if (sourceId == null) {
        return null;
      }
      const source = runsRef.current.find((r) => r.id === sourceId);
      return {
        label: source ? runLabel(source, teamNames) : 'the analysed thread',
        onOpen: () => void activateRun(sourceId),
      };
    },
    [activateRun, teamNames, onOpenTeam],
  );

  /** The thread the Analyze thread dialog is open for (null = closed). */
  const [analyzingRun, setAnalyzingRun] = useState<ChatRun | null>(null);
  /** The thread whose analysis popup is open (null = closed). */
  const [analysisOf, setAnalysisOf] = useState<ChatRun | null>(null);
  /**
   * Bumped when an analysis starts and when its popup closes: a new analysis
   * is a new conversation for the popup, and the Analyze button re-reads.
   */
  const [analysisGeneration, setAnalysisGeneration] = useState(0);
  /**
   * Analyze on a thread: its analysis's popup when it has one, else the setup
   * dialog. The analysis is never on the sidebar — the popup is where it is.
   */
  const handleAnalyzeRun = useLatestCallback(
    (runId: string): void => {
      const run = runsRef.current.find((r) => r.id === runId);
      if (!run) {
        return;
      }
      void chatApi
        .getThreadAnalysis({ runId })
        .then(({ analysis }) => {
          if (analysis == null) {
            setAnalyzingRun(run);
          } else {
            setAnalysisOf(run);
          }
        })
        .catch((err: unknown) => setError(describeDaemonError(err)));
    },
    [chatApi, setError],
  );

  // Moved by each "Reflect now" the user starts, so the panel's button
  // re-reads the thread's lessons state and shows the reflection working.
  const [lessonsGeneration, setLessonsGeneration] = useState(0);
  const handleReflectRun = useLatestCallback(
    (runId: string): void => {
      setError(null);
      void apis.lessons
        .reflectLessons({ runId, reflectLessonsDto: {} })
        .then(() => setLessonsGeneration((generation) => generation + 1))
        .catch((err: unknown) => setError(describeDaemonError(err)));
    },
    [apis, setError],
  );
  const readLessonsMark = useLatestCallback(
    (runId: string): Promise<ThreadLessonsMark> =>
      apis.lessons.getThreadLessonsState({ runId }).then(lessonsMarkOf),
    [apis],
  );

  // The run queued for deletion (null = no confirm open). Deleting is
  // IRREVERSIBLE — rows, attachments and PTY sessions all go — so it is the
  // one row action that asks first.
  const [deleting, setDeleting] = useState<ChatRun | null>(null);
  const [deleteBusy, setDeleteBusy] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);
  const [extractLessonsOnDelete, setExtractLessonsOnDelete] = useState(false);
  const [deleteLessons, setDeleteLessons] =
    useState<ThreadLessonEstimateDto | null>(null);
  const handleDeleteRun = useLatestCallback((runId: string): void => {
    const run = runsRef.current.find((r) => r.id === runId);
    if (run) {
      setDeleteError(null);
      setExtractLessonsOnDelete(false);
      setDeleteLessons(null);
      setDeleting(run);
    }
  }, []);

  const deletingId = deleting?.id ?? null;
  useEffect(() => {
    if (deletingId === null) {
      return;
    }
    let live = true;
    apis.lessons
      .estimateLessons({ runId: deletingId })
      .then((answer) => {
        if (live) {
          setDeleteLessons(answer);
        }
      })
      .catch(() => {
        if (live) {
          setDeleteLessons(null);
        }
      });
    return () => {
      live = false;
    };
  }, [apis, deletingId]);

  const [archiveLessons, setArchiveLessons] =
    useState<ArchiveLessonNotice | null>(null);
  const stopArchiveLessonWatch = useRef<(() => void) | null>(null);
  useEffect(() => () => stopArchiveLessonWatch.current?.(), []);
  const archiveLessonModel = useModelDisplayName(
    agentsApi,
    archiveLessons?.segment.estimate.agentKind ?? null,
    archiveLessons?.segment.estimate.model ?? null,
  );
  const archiveLessonDetail =
    archiveLessons === null
      ? null
      : archiveNoticeDetail(
          archiveLessons.segment,
          archiveLessons.todayUsd,
          archiveLessonModel,
        );
  const deleteLessonModel = useModelDisplayName(
    agentsApi,
    deleteLessons?.estimate.agentKind ?? null,
    deleteLessons?.estimate.model ?? null,
  );

  // The chat queued for archiving — ONLY ever a running one (see the dialog).
  const [archiving, setArchiving] = useState<ChatRun | null>(null);
  const [archiveBusy, setArchiveBusy] = useState(false);
  const [archiveError, setArchiveError] = useState<string | null>(null);

  // The selected team's trigger for the composer's trigger chip — the
  // member the first message goes to. It also records that member's agent
  // KIND: the run prompt is delivered to exactly that member, so the `/`
  // skill autocomplete resolves through it.
  const [triggers, setTriggers] = useState<
    { id: string; name: string; trigger: string; agentKinds: CliKind[] }[]
  >([]);
  const [triggerId, setTriggerId] = useState('');
  useEffect(() => {
    if (!teamSlug) {
      setTriggers([]);
      setTriggerId('');
      return;
    }
    let stale = false;
    teamApi
      .getTeam({ slug: teamSlug })
      .then(({ team }) => {
        if (stale) {
          return;
        }
        const entries = runTriggersOf(team).map((entry) => ({
          ...entry,
          agentKinds: [entry.agent],
        }));
        setTriggers(entries);
        setTriggerId(entries[0]?.id ?? '');
      })
      .catch(() => {
        if (!stale) {
          setTriggers([]);
          setTriggerId('');
        }
      });
    return () => {
      stale = true;
    };
  }, [teamSlug, teamApi]);

  // The app's shared answer, and only the data — every read below is a plain
  // `capabilities?.…`, never a loading readout of its own.
  const { capabilities } = useSharedCapabilities(capabilitiesApi);
  /**
   * Per CLI: `null` if it can reopen a conversation interactively
   * (`--resume`), else the daemon's own sentence for why it cannot. Derived,
   * never listed here — `AdapterConfig.handoff` is the fact, and a literal in
   * the renderer is how a second CLI gaining the ability silently keeps its
   * control hidden.
   *
   * A MAP, not the set of capable kinds it replaced. The set threw the reason
   * away, so the panel could only hide the control — and a cursor chat then
   * showed one lone unlabelled glyph where a claude chat showed two, with
   * nothing on screen or on hover to say why. An agent missing from the map is
   * UNKNOWN (the report has not landed), which is not the same as refused.
   */
  const terminalReasons = useMemo(
    () =>
      new Map<string, string | null>(
        (capabilities?.interactiveTerminals ?? []).map((row) => [
          row.agent,
          row.unavailableReason,
        ]),
      ),
    [capabilities],
  );
  /**
   * Approval capability per CLI, straight off the daemon's capability report.
   * Derived for the same reason as the terminal set above: the fact lives in
   * `AdapterConfig.approval`, and the moment the renderer decides it by agent
   * name, a CLI that gains a permission channel keeps a hidden chip.
   */
  const approvalCapabilityByAgent = useMemo(
    () =>
      new Map<string, AgentApprovalCapability>(
        (capabilities?.approvals ?? []).map((row) => [row.agent, row]),
      ),
    [capabilities],
  );
  /**
   * Asked about an arbitrary agent — the saved run configurations, and the
   * open thread's own CLI, which need not be the composer's.
   */
  const approvalCapabilityFor = useLatestCallback(
    (agent: CliKind): AgentApprovalCapability | undefined =>
      approvalCapabilityByAgent.get(agent),
    [approvalCapabilityByAgent],
  );
  /**
   * What the NEXT chat's CLI honours, or undefined until capabilities land.
   *
   * Memoized because `createChatRun` depends on it, on the same terms as
   * every other capability slice it reads.
   */
  const composerApprovalCapability = useMemo(
    () => approvalCapabilityFor(agentKind),
    [approvalCapabilityFor, agentKind],
  );
  /**
   * Why one CLI cannot be pointed at a config directory, from the capability
   * bag — null when it can, `undefined` while the answer has not arrived, which
   * a chip renders as nothing rather than as a guess.
   *
   * Asked about two DIFFERENT agents on this screen: the composer's, and the
   * session picker's, which is its own. Answering the second with the first is
   * how a claude profile came to be sent to cursor.
   */
  const configDirReasonFor = useLatestCallback(
    (agent: CliKind): string | null | undefined =>
      capabilities
        ? capabilities.configDirs.find((row) => row.agent === agent)
            ?.unavailableReason
        : undefined,
    [capabilities],
  );
  /**
   * Why the NEXT chat's CLI cannot take a config directory — null when it can,
   * `undefined` while the answer is still unknown, which the chip renders as
   * nothing rather than as a guess.
   *
   * Derived from the same capability read as the slices above, for the same
   * reason: `AdapterConfig.configDir.unavailableReason` is the fact, and a
   * renderer that decided this by agent name would keep the chip hidden for the
   * next CLI that gains one.
   */
  const composerConfigDirUnavailableReason = useMemo(
    () => configDirReasonFor(agentKind),
    [configDirReasonFor, agentKind],
  );

  /**
   * The same question for the SESSION PICKER's agent, which is its own.
   *
   * Read separately rather than reusing the composer's, and the bug that
   * forces it: the config directory the composer holds belongs to whichever
   * CLI the composer is pointed at — a claude profile while the picker is
   * showing cursor. Sent along anyway, it asked cursor to list conversations
   * under a directory that is not its store (an empty list, reading as "you
   * have no history") and would have 400'd the import, since the daemon
   * REFUSES a config directory for a CLI with no such mechanism.
   */
  const sessionConfigDirUnavailableReason = useMemo(
    () => configDirReasonFor(sessionAgent),
    [configDirReasonFor, sessionAgent],
  );
  /**
   * EVERY profile to ask the picker's CLI about — see `session-search.ts`.
   *
   * The PICKER's own agent's config directory, recents and named
   * configurations, never the composer's: `sessionAgent` is its own choice,
   * independent of whichever CLI the composer is currently pointed at, and each
   * CLI keeps a different layout in its directory. All three are profiles this
   * user has chosen, recorded in `settings.json`, which the daemon cannot
   * enumerate.
   */
  const sessionProfileDirs = useMemo(
    () =>
      sessionProfiles(
        configDirs[sessionAgent] ?? null,
        recentConfigDirsByAgent[sessionAgent] ?? [],
        sessionConfigDirUnavailableReason === null,
        configProfiles
          .filter((profile) => profile.agent === sessionAgent)
          .map((profile) => profile.dir),
      ),
    [
      configDirs,
      recentConfigDirsByAgent,
      configProfiles,
      sessionAgent,
      sessionConfigDirUnavailableReason,
    ],
  );

  /**
   * Hold the typed query back until typing stops.
   *
   * `SESSION_SEARCH_DEBOUNCE_MS` rather than none: the ask reads session files
   * on the daemon and, for cursor, spawns a process — measured at ~900ms for a
   * term matching nothing across a 3,029-session profile — so a request per
   * keystroke would queue work the user has already typed past.
   */
  useEffect(() => {
    if (!sessionPickerOpen) {
      return;
    }
    if (sessionQuery === sessionQueryAsked) {
      return;
    }
    const timer = setTimeout(
      () => setSessionQueryAsked(sessionQuery),
      SESSION_SEARCH_DEBOUNCE_MS,
    );
    return () => clearTimeout(timer);
  }, [sessionPickerOpen, sessionQuery, sessionQueryAsked]);

  // Cleared on every open rather than kept: a filter left over from last time
  // is an empty list whose reason is off screen.
  useEffect(() => {
    if (sessionPickerOpen) {
      setSessionQuery('');
      setSessionQueryAsked('');
    }
  }, [sessionPickerOpen]);

  /**
   * Re-read the fast actions whenever this screen comes back into view.
   *
   * Chats stays MOUNTED across nav switches — that is what keeps its live room
   * and active run alive — so its one-shot settings read never runs again.
   * Fast actions are edited on another screen, so without this the buttons
   * under the composer keep showing the set as it was when the app started:
   * an action added in Settings would not appear until the next launch, and a
   * deleted one would still be pressable.
   *
   * Only these keys, and only on the way IN: the rest of that read is composer
   * state the user may have moved since, and clobbering it on every nav switch
   * would throw away the folder or model they just chose.
   *
   * The three LISTS below are on the same footing as the actions — other
   * screens add to them (the team builder's profile picker writes the
   * recents, Settings the named profiles) — and more is at stake than a stale
   * menu: `chooseFolder` and `chooseConfigDir` write their recents back from
   * this screen's copy, so a copy read at mount erased whatever another screen
   * had added since, the next time a folder or profile was picked here.
   */
  useEffect(() => {
    if (!active) {
      return;
    }
    void window.geniro.getSettings().then((s) => {
      setFastActions(s.fastActions ?? []);
      setRunConfigs(s.runConfigs ?? []);
      setRecentFolders(s.recentFolders ?? []);
      setRecentConfigDirsByAgent(s.recentConfigDirs ?? {});
      setConfigProfiles(s.configProfiles ?? []);
    });
  }, [active]);

  /**
   * Delete the chats that have outstayed the archive retention the user set.
   *
   * HERE rather than in the daemon's own boot, and the reason is where the
   * policy lives: the window is a key in `settings.json`, which the daemon
   * never opens — so a sweep it started for itself would need the setting
   * mirrored into a second store, and the two would disagree the first time
   * somebody changed it. The daemon owns the destructive half and nothing else;
   * this decides whether it happens at all. A user who has not set a window is
   * simply a client that never calls the route.
   *
   * The setting is re-read on every tick rather than captured: this screen
   * stays mounted for the life of the app, so a window switched off at noon
   * must not go on sweeping until the next launch.
   *
   * The list is refreshed only when something was ACTUALLY deleted, because a
   * teardown announces nothing — the sidebar would otherwise keep offering rows
   * whose runs are gone until the next listing for some other reason. In the
   * steady state the answer is zero and this costs one request a day.
   */
  useEffect(() => {
    if (!chatApi || isHosted) {
      return;
    }
    let cancelled = false;
    const sweep = async (): Promise<void> => {
      const settings = await window.geniro.getSettings();
      const olderThanDays = settings.archiveRetentionDays;
      // A NUMBER is what arms the delete, so anything else — the `null` a user
      // who keeps their archive stores, and the `undefined` a settings.json
      // written before this key existed reads back as — leaves it disarmed.
      // Testing `!== null` alone would have handed the route an `undefined`
      // window, which is the one mistake this whole feature cannot afford.
      if (cancelled || typeof olderThanDays !== 'number') {
        return;
      }
      const { deleted } = await chatApi.sweepArchivedChats({
        sweepArchivedDto: { olderThanDays },
      });
      if (!cancelled && deleted > 0) {
        refreshRuns();
      }
    };
    // Swallowed rather than surfaced: this is housekeeping nobody asked for
    // right now, and an error strip about it would interrupt whatever the user
    // opened the app to do. A failed sweep costs nothing — the next tick
    // retries, and the rows it did not take are still in the archive.
    const run = (): void => {
      void sweep().catch(() => undefined);
    };
    run();
    const timer = setInterval(run, ARCHIVE_SWEEP_INTERVAL_MS);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [chatApi, refreshRuns, isHosted]);

  useEffect(() => {
    void window.geniro.getSettings().then((s) => {
      setFolder(s.projectFolder);
      setRecentFolders(s.recentFolders ?? []);
      setConfigDirs(s.configDirs ?? {});
      setRecentConfigDirsByAgent(s.recentConfigDirs ?? {});
      setConfigProfiles(s.configProfiles ?? []);
      setFastActions(s.fastActions ?? []);
      setRunConfigs(s.runConfigs ?? []);
      if (s.lastChatTarget) {
        setTarget(s.lastChatTarget);
      }
      // settings.json is a file the user can edit, and the mode vocabulary
      // lives in the daemon — so the stored string is checked against the
      // generated enum rather than trusted into a run's approval setting.
      if (isChatApprovalMode(s.lastApprovalMode)) {
        setApprovalMode(s.lastApprovalMode);
      }
      setModels(s.lastModels ?? {});
      setEfforts(s.lastEfforts ?? {});
      setContextWindows(s.lastContextWindows ?? {});
      setAutoCompactPercent(s.lastAutoCompactPercent ?? null);
      setModelParameters(s.lastModelParameters ?? {});
    });
    // Which CLIs are actually on this machine. The picker used to offer every
    // known kind unconditionally, so an agent that is not installed — or whose
    // binary is too old to be driven — looked exactly like a working one and
    // failed only AFTER a run had been created, as "exited with code 1".
    if (!isHosted) {
      void window.geniro.detectClis().then(setCliDetections);
      refreshGroups();
    }
  }, [
    client,
    chatApi,
    addItem,
    activateRun,
    refreshRuns,
    refreshGroups,
    isHosted,
  ]);

  useEffect(() => {
    // Follow the tail only when the user is already AT it. Scrolling them back
    // down while they are reading something further up is the whole complaint;
    // suppression is silent by design — no "jump to latest" affordance.
    //
    // No extra ref: the sentinel is a direct child of the `overflow-y-auto`
    // container, so its parent IS the scroll box.
    const scroller = transcriptEndRef.current?.parentElement;
    // A freshly opened run jumps to the tail unconditionally — see
    // pendingScrollRef. Instant, not smooth: animating a scroll the user never
    // asked for, through a transcript they have not seen, is just a delay.
    if (!scroller) {
      return;
    }
    if (pendingScrollRef.current) {
      if (items.length === 0) {
        return;
      }
      pendingScrollRef.current = false;
      followingRef.current = true;
      followTail(scroller);
      return;
    }
    if (!followingRef.current || touchGuardRef.current.active(Date.now())) {
      return;
    }
    followTail(scroller);
    // `liveText` too, not just `items`: a streaming tail grows the transcript
    // with no new item, and keying on `items` alone let the live text run off
    // the bottom of the viewport mid-turn.
  }, [items, liveText]);

  /**
   * Fetch the page before the oldest item on screen, and hold the reader's
   * place while it lands. Three callers: the scroll listener, the notice's own
   * button, and the fill effect below `transcriptEntries` — the last two exist
   * because a transcript that does not overflow its pane can never be scrolled.
   *
   * Hold the reader's place. Prepending a page inserts rows ABOVE the viewport,
   * which pushes everything they were reading down by exactly the height that
   * arrived — so the scroll offset is moved by the same amount, and nothing
   * appears to move at all.
   *
   * Over SEVERAL FRAMES, and that is the whole of a reported defect. The promise
   * resolves when the state is set, not when React has committed the rows and
   * the browser has laid them out — so a single correction here reads a
   * `scrollHeight` that has barely moved, applies almost nothing, and the page
   * then grows underneath the reader with nothing left to compensate. Measured
   * in the running app on a 30k-row thread: the transcript grew 42,865px →
   * 74,092px across one older page while `scrollTop` stayed put, which puts the
   * reader 31,227px away from what they were reading. REPORTED as "он обрезает
   * беседу почему-то" — the conversation had not been cut, they had been moved
   * off it.
   *
   * It anchors on a ROW rather than the total height (`holdReadingPlace`), so
   * growth BELOW the reader — a streaming reply — is not paid back as well.
   */
  const pageOlder = useLatestCallback(
    async (scroller: HTMLElement): Promise<boolean> => {
      const load = loadOlderRef.current;
      if (load === null) {
        return false;
      }
      const hold = holdReadingPlace(scroller, undefined, () =>
        touchGuardRef.current.active(Date.now()),
      );
      try {
        return await load();
      } finally {
        hold.release();
      }
    },
    [],
  );

  /**
   * The entries as they were last DRAWN, so a press can tell whether the page
   * it just loaded put anything on screen. Written from an effect rather than
   * during render: the question is what the reader can see, which is only
   * answerable after React has committed.
   */
  const drawnEntriesRef = useRef<readonly TranscriptEntry[]>([]);

  /**
   * Page back until the transcript actually GROWS UPWARD, or the conversation
   * runs out — the press behind `Load earlier messages`.
   *
   * One page is not one answer on a team run. Every row a callee streams
   * carries its call's id and is claimed by that call's block, so a page made
   * entirely of them extends a card that is already on screen — and usually a
   * COLLAPSED one — leaving the top-level list byte for byte what it was.
   * REPORTED for the third time as "it still cant load earlier message", and
   * measured on the reporter's own run `8ad93b70`: the newest 1,000 items fold
   * to 103 entries, and the 1,000 older ones (984 of them `call-2`'s, with no
   * user message and no `call_started` among them) fold to the same 103 — same
   * kinds, same first entry. The press worked, the rows arrived, and nothing
   * whatever changed on screen.
   *
   * So the loop is what the label promises, and it stops on the first page that
   * adds an entry ABOVE the ones already drawn. `OLDER_PAGES_PER_PRESS` bounds
   * it: a press is a person waiting, and a conversation whose every page folds
   * away is one where paging further is not what they need either.
   */
  const pageOlderUntilVisible = useLatestCallback(
    async (scroller: HTMLElement): Promise<void> => {
      for (let page = 0; page < OLDER_PAGES_PER_PRESS; page += 1) {
        const before = topEntryKey(drawnEntriesRef.current);
        if (!(await pageOlder(scroller))) {
          return;
        }
        // A macrotask, not a microtask: the prepend has to be COMMITTED and the
        // effect below run before the entries can be compared again.
        await new Promise<void>((resolve) => {
          setTimeout(resolve, 0);
        });
        if (topEntryKey(drawnEntriesRef.current) !== before) {
          return;
        }
      }
    },
    [pageOlder],
  );

  /**
   * Keep the tail glued to the bottom when a block grows AFTER it rendered.
   *
   * The effect above runs once per React commit, which is too early for the
   * cases the user actually hit: a thinking block that fills in, a code block
   * that gets highlighted, an image that finishes loading. All of them change
   * the transcript's HEIGHT with no new item and no new live text, so the
   * commit-time scroll lands short and the tail sits just below the fold.
   *
   * A `ResizeObserver` is what closes that gap — it fires on the layout change
   * itself rather than on the render that preceded it. It watches the scroller's
   * children (the scroller's own box never changes size; only its content does),
   * and is re-pointed whenever the child list changes.
   *
   * The `scroll` listener beside it owns the follow decision, so that a resize
   * arriving while the user is reading further up never yanks them down; see
   * `nextFollowState` for why the naive at-bottom read was not enough.
   */
  useEffect(() => {
    const scroller = transcriptEndRef.current?.parentElement;
    if (!scroller) {
      return;
    }
    lastScrollTopRef.current = scroller.scrollTop;
    // A freshly opened transcript is at its tail (`pendingScrollRef`), so the
    // control starts hidden rather than flashing on until the first scroll.
    setAboveTail(false);
    let olderAfterGesture: ReturnType<typeof setTimeout> | null = null;
    const pageOlderOnceLetGo = (): void => {
      if (olderAfterGesture !== null) {
        return;
      }
      if (!touchGuardRef.current.active(Date.now())) {
        void pageOlder(scroller);
        return;
      }
      olderAfterGesture = setTimeout(() => {
        olderAfterGesture = null;
        if (
          loadOlderRef.current !== null &&
          shouldLoadOlder(scroller, scroller.scrollTop)
        ) {
          pageOlderOnceLetGo();
        }
      }, TOUCH_SETTLE_MS);
    };
    const onScroll = (): void => {
      // Read ONCE, up front: both decisions below are about the direction this
      // scroll moved, and the ref is overwritten a few lines down. Passing the
      // ref itself to the second reader hands it `scrollTop === previous`,
      // which reads as "did not move" and silently disables the guard.
      const previousScrollTop = lastScrollTopRef.current;
      const now = Date.now();
      touchGuardRef.current.scrolled(now);
      const readerScrollingUp =
        upwardIntentRef.current.active(now) ||
        touchGuardRef.current.active(now);
      followingRef.current = nextFollowState(
        followingRef.current,
        scroller,
        previousScrollTop,
        readerScrollingUp,
      );
      if (
        followingRef.current &&
        !readerScrollingUp &&
        scroller.scrollTop < previousScrollTop &&
        !isScrolledToBottom(scroller)
      ) {
        followTail(scroller);
      }
      lastScrollTopRef.current = scroller.scrollTop;
      // Deliberately NOT `!followingRef.current`: the follow is sticky through
      // content that grows under a reader who never moved, which is exactly
      // when the tail runs away from them — the button is about where the
      // viewport IS, not about what the transcript intends to do next.
      setAboveTail(!isScrolledToBottom(scroller));
      // …and PAGE, once the reader is most of the way up AND still heading
      // that way. A chat opens on its newest 1,000 items (see `HISTORY_PAGE`),
      // so the rest is fetched only if somebody actually goes looking for it —
      // which a viewport travelling DOWN is not doing. See `shouldLoadOlder`
      // for the threshold, and for what reading position alone did to the
      // "Latest" button. Not while a finger or a fling owns the scroll: the
      // page lands above the reader and `holdReadingPlace` would have to move
      // them mid-gesture, which mobile WebKit fights.
      if (
        loadOlderRef.current !== null &&
        shouldLoadOlder(scroller, previousScrollTop)
      ) {
        pageOlderOnceLetGo();
      }
      // …and FORWARD, off a window a jump left the reader in. Appending below
      // the viewport moves nothing the reader is looking at, so it needs no
      // place-holding the way a prepend does.
      if (
        loadNewerRef.current !== null &&
        shouldLoadNewer(scroller, previousScrollTop)
      ) {
        void loadNewerRef.current();
      }
    };
    // A finger's scroll is announced to the follow logic BEFORE its first
    // `scroll` event — see `createTouchScrollGuard` for what reacting only to
    // `scroll` did on a phone.
    const guard = touchGuardRef.current;
    const onTouchStart = (): void => guard.touchStart(Date.now());
    const onTouchEnd = (): void => guard.touchEnd(Date.now());
    const intent = upwardIntentRef.current;
    const onWheel = (event: WheelEvent): void =>
      intent.wheel(event.deltaY, Date.now());
    const onPointerDown = (): void => intent.press();
    const onPointerUp = (): void => intent.release(Date.now());
    const onKeyDown = (event: KeyboardEvent): void => {
      if (
        event.target === document.body ||
        (event.target instanceof Node && scroller.contains(event.target))
      ) {
        intent.key(event.key, event.shiftKey, Date.now());
      }
    };
    // The END is heard on the WINDOW, not the scroller: a touch that began on
    // the live row keeps its target when that row is replaced by its durable
    // one, and the detached node's `touchend` never reaches the scroller — the
    // guard would then read "touching" until the next touch, and the tail
    // would stop following for good.
    scroller.addEventListener('scroll', onScroll, { passive: true });
    scroller.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchend', onTouchEnd, {
      passive: true,
      capture: true,
    });
    window.addEventListener('touchcancel', onTouchEnd, {
      passive: true,
      capture: true,
    });
    scroller.addEventListener('wheel', onWheel, { passive: true });
    scroller.addEventListener('pointerdown', onPointerDown, { passive: true });
    window.addEventListener('pointerup', onPointerUp, { capture: true });
    window.addEventListener('pointercancel', onPointerUp, { capture: true });
    window.addEventListener('keydown', onKeyDown, { capture: true });
    return () => {
      if (olderAfterGesture !== null) {
        clearTimeout(olderAfterGesture);
      }
      scroller.removeEventListener('scroll', onScroll);
      scroller.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchend', onTouchEnd, { capture: true });
      window.removeEventListener('touchcancel', onTouchEnd, { capture: true });
      scroller.removeEventListener('wheel', onWheel);
      scroller.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointerup', onPointerUp, { capture: true });
      window.removeEventListener('pointercancel', onPointerUp, {
        capture: true,
      });
      window.removeEventListener('keydown', onKeyDown, { capture: true });
    };
    // Its OWN effect, keyed on the run alone. The listener is on the scroller,
    // which does not change as rows arrive — re-adding it per transcript change
    // was pure churn, and per streaming TOKEN it was churn at token rate.
  }, [activeRunId]);

  useEffect(() => {
    const scroller = transcriptEndRef.current?.parentElement;
    if (!scroller) {
      return;
    }
    // jsdom has no ResizeObserver, and neither does an old runtime — the
    // commit-time effect above is still the baseline behaviour without it.
    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver(() => {
            if (
              !followingRef.current ||
              touchGuardRef.current.active(Date.now())
            ) {
              // Growth fires no `scroll` event, so this is the only moment the
              // control can learn that the tail has run away from a reader who
              // never moved — which is precisely the case it exists for: a
              // tool that renders half a screen of output while you are
              // reading further up.
              setAboveTail(!isScrolledToBottom(scroller));
              return;
            }
            followTail(scroller);
          });
    const repoint = (): void => {
      observer?.disconnect();
      // The scroller's OWN box first, and it is not redundant beside its
      // children: the tail can be pushed off-screen by the VIEWPORT shrinking
      // just as easily as by the content growing, and that half had no watcher
      // at all. Everything below this box in the column takes its height from
      // content — the composer growing as a message is typed, the attachment
      // strip appearing, an approval card opening, the fast-action bar — and
      // each of them shortens the transcript by exactly that much.
      //
      // Nothing else notices. No child resizes, so the child observations do
      // not fire; `scrollTop` does not move, so no `scroll` event is emitted;
      // and the commit-time effect is keyed on items and live text, neither of
      // which changed. The distance to the bottom simply grows and the newest
      // message slides out of view under the composer, with `aboveTail` still
      // reading false so the "Latest" button does not even offer a way back.
      // The next streamed token hides it again by re-following — which is what
      // made it "sometimes".
      observer?.observe(scroller);
      for (const child of Array.from(scroller.children)) {
        observer?.observe(child);
      }
    };
    repoint();
    // The element set is WATCHED rather than guessed at from a dependency list.
    //
    // This used to key on `liveText`, which is a fresh Map per streamed token
    // while the daemon coalesces nothing — so every token cost a `disconnect()`
    // plus one `observe()` per row in an unvirtualized transcript. But no
    // dependency list can stand in for the element set either: transcript rows
    // are derived from durable items, live text AND working agents, and a
    // single row's top-level block identity flips as it becomes a thinking or
    // working block. A `childList` observation is exactly the question — "did
    // the children change" — so it catches all of those and none of the text
    // deltas, which mutate character data rather than the child list.
    const children =
      typeof MutationObserver === 'undefined'
        ? null
        : new MutationObserver(repoint);
    children?.observe(scroller, { childList: true });
    return () => {
      observer?.disconnect();
      children?.disconnect();
    };
  }, [activeRunId]);

  /**
   * Take the reader back to the tail, and RE-ARM the follow.
   *
   * Both halves, because the button answers a state with two parts: the
   * viewport is above the bottom, and the transcript has stopped chasing it.
   * Scrolling alone would land at the tail and then let the next streamed token
   * leave it behind again — which is the same complaint one message later.
   *
   * `smooth`, unlike the open-a-thread jump: this one the user asked for, and
   * the movement is what tells them where they were taken from.
   */
  /**
   * Take the reader to one card in the transcript — a team's, or a call's.
   *
   * Arithmetic on the SCROLLER's own `scrollTop`, never `scrollIntoView` —
   * which is specified to move every scrollable ancestor and is what once
   * scrolled the whole window off the top (`scroll-to-bottom.ts` records the
   * measurement). `revealWithinBox` is the same rule expressed in `offsetTop`,
   * which cannot be used here: a team card sits many levels deep inside
   * turn blocks, so its `offsetTop` is measured against whichever ancestor
   * happens to be positioned rather than against the scroller.
   *
   * The tail-follow is switched OFF by the press: without that, the next
   * streamed token of a running turn drags the reader straight back down —
   * which for a card of a team that is still running is every second.
   *
   * The card is MARKED for as long as a search hit is (`data-revealed`, drawn
   * by `REVEALABLE_CARD_CLASS`): moved to a screen of look-alike cards, the
   * reader otherwise has to work out which of them they were sent to. Written
   * on the DOM node rather than through state — the card is several memoized
   * shells deep and React leaves an attribute it does not manage alone.
   */
  const revealMark = useRef<{
    card: HTMLElement;
    timer: ReturnType<typeof setTimeout>;
  } | null>(null);
  useEffect(
    () => () => {
      if (revealMark.current !== null) {
        clearTimeout(revealMark.current.timer);
      }
    },
    [],
  );
  const revealInTranscript = useLatestCallback((selector: string): void => {
    const scroller = transcriptEndRef.current?.parentElement;
    const card = scroller?.querySelector<HTMLElement>(selector);
    if (!scroller || !card) {
      return;
    }
    if (revealMark.current !== null) {
      clearTimeout(revealMark.current.timer);
      delete revealMark.current.card.dataset.revealed;
    }
    card.dataset.revealed = 'true';
    revealMark.current = {
      card,
      timer: setTimeout(() => {
        delete card.dataset.revealed;
        revealMark.current = null;
      }, JUMP_MARK_MS),
    };
    followingRef.current = false;
    // A margin above the card so it does not land flush against the top edge,
    // where a header would otherwise read as the card's own first line.
    scroller.scrollTop +=
      card.getBoundingClientRect().top -
      scroller.getBoundingClientRect().top -
      24;
    setAboveTail(!isScrolledToBottom(scroller));
  }, []);
  const revealWorkflow = useLatestCallback(
    (workflowId: string): void =>
      revealInTranscript(
        `[data-slot="workflow-card"][data-workflow="${CSS.escape(workflowId)}"]`,
      ),
    [revealInTranscript],
  );
  /**
   * The same jump to a CALL card, from the row an earlier call of its
   * conversation leaves behind (`CallContinuedRow`), which is the only way
   * that row can say where the work went.
   */
  const revealCallBlock = useLatestCallback(
    (cardId: string): void =>
      revealInTranscript(
        `[data-role="call-block"][data-call-block="${CSS.escape(cardId)}"]`,
      ),
    [revealInTranscript],
  );

  const [searchOpen, setSearchOpen] = useState(false);
  const [globalSearchOpen, setGlobalSearchOpen] = useState(false);
  // The hit waiting for its thread to load. Any other thread opened before it
  // lands — including going back to the one it was picked from — drops it.
  const [globalSearchTarget, setGlobalSearchTarget] = useState<{
    hit: GlobalChatSearchHit;
    from: string | null;
    arrived: boolean;
  } | null>(null);
  const [changesOpen, setChangesOpen] = useState(false);
  const chatSearch = useChatSearch(activeRunId, chatApi);

  // The jump state machine — reveal, mark, fetch-around, and what "Latest"
  // means once a jump has taken the reader off the tail. Its own module beside
  // `use-chat-search.ts`, the sibling half of the same feature; the scroll state
  // it acts on (`followingRef`, `aboveTail`) stays owned here, because a second
  // copy of "is the reader at the bottom" is how the Latest control and the
  // transcript come to disagree.
  /**
   * What a jump into a call reads — the cards, the daemon's calls and every row
   * held — assigned where each is computed further down, so the one jump
   * machine above them reads them as they stand at its next commit.
   */
  const callJumpRef = useRef<{
    entries: readonly TranscriptEntry[];
    calls: readonly RunCallState[];
    rows: readonly ChatItem[];
    loadThrough: CallConversationLoader['loadThrough'];
  }>({
    entries: [],
    calls: [],
    rows: [],
    loadThrough: () => Promise.resolve(false),
  });
  /**
   * A TEAM run's window is its own flow alone, and a hit inside a call is
   * a row of that call's card: the jump finds the call, opens the card, reads
   * its conversation back to the row and lands on it there.
   */
  const activeTeamId =
    runs.find((run) => run.id === activeRunId)?.teamId ?? null;
  /** Open a call's card, as the reader's own press on its header would. */
  const openCallCard = useLatestCallback(
    (blockId: string): void => {
      const runId = activeRunIdRef.current;
      if (runId !== null) {
        writeThreadFlag(runId, `call:${blockId}`, true);
      }
    },
    [activeRunIdRef],
  );
  const callJumps = useMemo<CallJumps | undefined>(
    () =>
      activeTeamId === null
        ? undefined
        : {
            locate: async (seq) => {
              const held = callJumpRef.current.rows.find(
                (row) => row.seq === seq,
              );
              if (held !== undefined) {
                return held.inCall ? held.inCall : null;
              }
              const runId = activeRunIdRef.current;
              if (runId === null) {
                return null;
              }
              const { items: [row] = [] } = await chatApi.listRunItems({
                runId,
                afterSeq: seq - 1,
                limit: 1,
                take: ListRunItemsTakeEnum.Oldest,
              });
              return row !== undefined && row.seq === seq && row.inCall
                ? row.inCall
                : null;
            },
            cardsOf: (callId) =>
              callBlockPath(callJumpRef.current.entries, callId).map(
                (block) => ({
                  id: block.id,
                  conversation: block.conversationCallIds[0] ?? block.callId,
                }),
              ),
            startOf: (callId) =>
              callJumpRef.current.calls.find((call) => call.callId === callId)
                ?.startSeq ?? null,
            openCard: openCallCard,
            loadThrough: (conversation, seq) =>
              callJumpRef.current.loadThrough(conversation, seq),
          },
    [activeTeamId, activeRunIdRef, chatApi, openCallCard],
  );
  /** The folds a row is drawn inside, from what the transcript holds now. */
  const foldsOfRow = useLatestCallback(
    (seq: number) => foldsHolding(callJumpRef.current.entries, seq),
    [],
  );
  const { mark, jumpToSeq, jumpToLatest, backToTail } = useTranscriptJump({
    threadId: activeRunId,
    items,
    endRef: transcriptEndRef,
    followingRef,
    setAboveTail,
    loadAround,
    returnToTail,
    calls: callJumps,
    foldsHolding: foldsOfRow,
  });

  useEffect(() => {
    // While another view is shown this screen is mounted but hidden, and a
    // dialog opened then is invisible yet holds the Escape stack.
    if (!active || isHosted) {
      return;
    }
    const onKey = (event: KeyboardEvent): void => {
      if (
        (event.metaKey || event.ctrlKey) &&
        event.shiftKey &&
        event.code === 'KeyF'
      ) {
        event.preventDefault();
        setGlobalSearchOpen(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [active, isHosted]);

  const openGlobalSearchHit = useLatestCallback(
    (hit: GlobalChatSearchHit): void => {
      setGlobalSearchOpen(false);
      setGlobalSearchTarget({
        hit,
        from: activeRunIdRef.current,
        arrived: hit.runId === activeRunIdRef.current,
      });
      if (hit.runId !== activeRunIdRef.current) {
        if (
          (hit.archived && chatScope === 'active') ||
          (!hit.archived && chatScope === 'archived')
        ) {
          showScope('all');
        }
        if (
          activityWindow !== null &&
          !runsRef.current.some((run) => run.id === hit.runId)
        ) {
          setActivityPreset('any');
          showActivityWindow(null);
        }
        void activateRun(hit.runId);
      }
    },
    [
      activateRun,
      activeRunIdRef,
      chatScope,
      showScope,
      activityWindow,
      showActivityWindow,
      runsRef,
    ],
  );

  useEffect(() => {
    if (!globalSearchTarget) {
      return;
    }
    const { hit, from, arrived } = globalSearchTarget;
    if (activeRunId !== hit.runId) {
      if (arrived || activeRunId !== from) {
        setGlobalSearchTarget(null);
      }
      return;
    }
    if (!arrived) {
      setGlobalSearchTarget({ ...globalSearchTarget, arrived: true });
      return;
    }
    if (loadingHistory) {
      return;
    }
    jumpToSeq(hit.seq);
    setGlobalSearchTarget(null);
  }, [globalSearchTarget, activeRunId, loadingHistory, jumpToSeq]);

  const openChatSearch = useLatestCallback((): void => setSearchOpen(true), []);
  const openChatChanges = useLatestCallback(
    (): void => setChangesOpen(true),
    [],
  );
  const closeChatChanges = useLatestCallback(
    (): void => setChangesOpen(false),
    [],
  );

  /**
   * Close the search and forget what it found.
   *
   * The query is dropped rather than kept for the next opening, because it is
   * scoped to ONE conversation: a thread switch while the dialog is shut would
   * otherwise reopen it showing the previous thread's hits under a field the
   * user has to clear before the surface means anything.
   */
  const resetChatSearch = chatSearch.reset;
  const closeChatSearch = useLatestCallback((): void => {
    setSearchOpen(false);
    resetChatSearch();
  }, [resetChatSearch]);

  /** Land on the hit, then get out of the way — the answer is the place. */
  const jumpToHit = useLatestCallback(
    (seq: number): void => {
      closeChatSearch();
      jumpToSeq(seq);
    },
    [closeChatSearch, jumpToSeq],
  );

  // Persist a chosen folder as the last-used default for the next new chat,
  // and remember it among the recent-folder suggestions (most recent first).
  const chooseFolder = useLatestCallback(
    (chosen: string): void => {
      setFolder(chosen);
      const next = [chosen, ...recentFolders.filter((f) => f !== chosen)].slice(
        0,
        5,
      );
      setRecentFolders(next);
      void window.geniro.updateSettings({
        projectFolder: chosen,
        recentFolders: next,
      });
    },
    [recentFolders],
  );

  const pickFolder = useLatestCallback(async (): Promise<void> => {
    const chosen = await window.geniro.pickProjectFolder();
    if (chosen) {
      chooseFolder(chosen);
    }
  }, [chooseFolder]);

  // Resolve the working directory for a new chat: reuse the default, else
  // prompt. Returns null when the user cancels the picker.
  const ensureFolder = useLatestCallback(async (): Promise<string | null> => {
    if (folder) {
      return folder;
    }
    const chosen = await window.geniro.pickProjectFolder();
    if (chosen) {
      chooseFolder(chosen);
    }
    return chosen;
  }, [folder, chooseFolder]);

  /**
   * Keep a profile among the recents without making it any chat's default —
   * PER AGENT, since each CLI keeps a different layout in its directory.
   *
   * Its own function because two callers need only this half:
   * {@link chooseConfigDir} composes it with setting the default, and the open
   * chat's profile switch ({@link changeRunConfigDir}) needs the recents alone —
   * repointing one thread at another account says nothing about what the next
   * chat should open as, the same rule the model chip follows. The recents ARE
   * shared across both callers, deliberately: they are the list of profiles
   * this user works in for that CLI, and a profile reached from a chat is
   * exactly as worth offering again as one reached from the composer.
   *
   * Takes `agent` explicitly rather than reading the composer's own
   * `agentKind`, which is what {@link applyRunConfigToComposer} needs: it
   * calls this in the same tick as `changeTarget`, before that state update
   * has taken effect, so `agentKind` would still name the PREVIOUS target.
   *
   * Functional `setState` throughout, for the same reason — this must not
   * close over a `recentConfigDirsByAgent` snapshot that a sibling call in the
   * same tick has already moved past.
   */
  const rememberConfigDir = useLatestCallback(
    (agent: CliKind, chosen: string): void => {
      setRecentConfigDirsByAgent((prev) => {
        const current = prev[agent] ?? [];
        if (current[0] === chosen) {
          return prev;
        }
        const next = {
          ...prev,
          [agent]: [chosen, ...current.filter((p) => p !== chosen)].slice(0, 5),
        };
        void window.geniro.updateSettings({ recentConfigDirs: next });
        return next;
      });
    },
    [],
  );

  /**
   * Same shape as {@link chooseFolder}, for the optional config directory —
   * remembered as the next chat's default (under its own agent's key), and
   * kept among that agent's recents so switching between two accounts is one
   * click rather than a dialog.
   *
   * `null` (the picker's "Default profile" row) clears the default without
   * touching the recents: the user is saying THIS chat runs as the CLI's own
   * account, not that they will never use that profile again.
   *
   * Takes `agent` explicitly — see {@link rememberConfigDir} for why a
   * closure over the composer's own `agentKind` is not safe here.
   */
  const chooseConfigDir = useLatestCallback(
    (agent: CliKind, chosen: string | null): void => {
      setConfigDirs((prev) => {
        const next = { ...prev };
        if (chosen === null) {
          delete next[agent];
        } else {
          next[agent] = chosen;
        }
        void window.geniro.updateSettings({ configDirs: next });
        return next;
      });
      if (chosen !== null) {
        rememberConfigDir(agent, chosen);
      }
    },
    [rememberConfigDir],
  );

  // The native dialog is the same directory picker the folder chip opens —
  // there is no profile-specific browse in the main process, and a second IPC
  // channel would only be a second name for `showOpenDialog({openDirectory})`.
  const pickConfigDir = useLatestCallback(async (): Promise<void> => {
    const chosen = await window.geniro.pickProjectFolder();
    if (chosen) {
      chooseConfigDir(agentKind, chosen);
    }
  }, [chooseConfigDir, agentKind]);

  /** The composer's chips as a new chat takes them, read when Send is pressed. */
  const composerChatFields = useLatestCallback(
    () => ({
      agentKind,
      // Omitted entirely when the composer is on the CLI default — the
      // daemon only passes `--model` when a run names one.
      ...(models[agentKind] ? { model: models[agentKind] } : {}),
      // Same rule as the model: omitted entirely on the CLI default. A CLI
      // with no effort control never has an entry, since its chip is absent.
      ...(efforts[agentKind] ? { effort: efforts[agentKind] } : {}),
      // Same rule again. Held true by `changeModel`, which clears the
      // remembered size whenever the model changes — the chip's own
      // rendering does not, since it draws the default sentinel for a size
      // the new model does not list while the stored word is still what
      // would be sent.
      ...(modelParameters[agentKind]
        ? { modelParameters: modelParameters[agentKind] }
        : {}),
      ...(contextWindows[agentKind]
        ? { contextWindow: contextWindows[agentKind] }
        : {}),
      ...(autoCompactPercent !== null ? { autoCompactPercent } : {}),
      // Sent only when this CLI honours the composer's pick; otherwise
      // omitted so the daemon applies its own default for that agent —
      // which is also what happens while capabilities are still loading.
      ...(composerApprovalCapability?.modes.includes(approvalMode)
        ? { approval: approvalMode }
        : {}),
      // Sent only when this CLI can actually load one — the daemon REFUSES
      // a config directory on a CLI without the mechanism (it is an
      // interactive choice, not something to silently drop), so sending a
      // directory left over from a claude chat would 400 every cursor run
      // the user started next. The chip is hidden in exactly that case, so
      // this guard and the chip read the same answer.
      ...(configDir !== null && composerConfigDirUnavailableReason === null
        ? { configDir }
        : {}),
      ...projectFieldOf(composerProject),
    }),
    // `composerApprovalCapability` belongs here: it starts undefined and only
    // fills in once capabilities load, so a callback that captured the first
    // render's value silently omitted the approval from every new run and
    // every chat opened on the daemon's default instead of the mode the chip
    // displayed. `composerConfigDirUnavailableReason` is in the list for that
    // same reason.
    [
      agentKind,
      approvalMode,
      composerApprovalCapability,
      composerConfigDirUnavailableReason,
      models,
      efforts,
      // `contextWindows` and `modelParameters` were BOTH missing here, and the
      // second is how the first was found: a pick made after this screen
      // mounted changed the state and not the captured closure, so the chip
      // showed `1m` and the run was created with nothing. Measured on the
      // model-parameter chip (`optimize_for` chosen, `model_parameters` null on
      // the row); the window has the identical shape and the identical fix.
      contextWindows,
      autoCompactPercent,
      modelParameters,
      configDir,
      composerProject,
    ],
  );

  // The folder's own project, by the rule a new run follows; asked again when
  // the projects change, so one made or moved meanwhile is seen.
  // A chosen project deleted since falls back to the folder's own, so the chip
  // and the run agree; an unanswered list keeps the choice.
  const chosenProjectGone =
    projectRefs !== null &&
    composerProject.source !== 'folder' &&
    composerProject.projectId !== null &&
    !projectRefs.some((project) => project.id === composerProject.projectId);
  useEffect(() => {
    if (chosenProjectGone) {
      setComposerProject(FOLDER_PROJECT);
    }
  }, [chosenProjectGone]);

  const folderProjectFor = composerProject.source === 'folder' ? folder : null;
  useEffect(() => {
    if (folderProjectFor === null) {
      return;
    }
    let live = true;
    const settle = (projectId: string | null): void => {
      if (live) {
        setComposerProject((current) =>
          current.source === 'folder'
            ? { projectId, source: 'folder' }
            : current,
        );
      }
    };
    apis.projects
      .resolveProjectForFolder({ path: folderProjectFor })
      .then(({ project }) => settle(project?.id ?? null))
      .catch(() => settle(null));
    return () => {
      live = false;
    };
  }, [apis, folderProjectFor, projects]);

  const createChatRun = useLatestCallback(
    async (cwd: string, composer: ReturnType<typeof composerChatFields>) =>
      chatApi.createChat({
        createChatDto: {
          ...composer,
          cwd,
          // Read at the MOMENT of creation rather than from mount-time state:
          // the value is snapshotted onto the run, and the user may have
          // edited it in Settings since this screen mounted. Caching it would
          // start the chat on instructions the settings screen no longer
          // shows. Omitted when empty so the daemon stores null.
          ...(await currentRunSettings()),
          ...(await chatGitStamp(cwd)),
        },
      }),
    [chatApi],
  );

  /**
   * Change an open chat's settings, mid-turn included. One path for every
   * chip: the model, the approval mode and the reasoning effort are the same
   * kind of choice — what the NEXT turn runs as.
   */
  const changeRunSettings = useLatestCallback(
    async (
      patch: {
        approval?: ChatApprovalMode;
        model?: string | null;
        effort?: string | null;
        contextWindow?: string | null;
        autoCompactPercent?: number | null;
        modelParameters?: Record<string, string>;
        configDir?: string | null;
      },
      runId: string | null = activeRunIdRef.current,
    ): Promise<void> => {
      if (!runId) {
        return;
      }
      try {
        const updated = await chatApi.updateChatSettings({
          runId,
          updateChatSettingsDto: patch,
        });
        setRuns((prev) =>
          prev.map((run) => (run.id === updated.id ? updated : run)),
        );
        void hostedRef.current?.onRunSettingsChanged?.(updated);
      } catch (err) {
        // A RUN_BUSY here is not a fault — it is the daemon saying this turn
        // was spawned with no permission gate, so its mode cannot be changed
        // until it settles. It is also not rare: only claude implements
        // `buildApprovalModePayload`, so EVERY mid-turn approval change on a
        // cursor chat lands here, and the chip is offered on cursor.
        //
        // `String(err)` printed the whole
        // `daemon PATCH /v1/chats/<id>/settings failed (409): {"code":…}`
        // envelope. The daemon wrote a real sentence for this; show that.
        setError(
          (isRunBusyError(err) ? daemonErrorDetail(err) : null) ?? String(err),
        );
      }
    },
    [chatApi],
  );

  /**
   * Point the OPEN chat at another account — the profile chip in its composer.
   *
   * REPORTED as "I wanna have ability to dynamically change config directory
   * for current claude threads to have an ability continue thread with other
   * account". The profile used to be stated in the header and nowhere else,
   * because it was fixed for the run's life; now that it changes something it
   * belongs where the run's other live choices are, which is the composer's
   * own rule.
   *
   * The conversation follows the switch — the daemon copies the CLI's session
   * into the new profile and writes a transcript line saying whether it could
   * — so nothing here has to explain the consequence: the answer lands in the
   * thread the user is looking at.
   */
  const changeRunConfigDir = useLatestCallback(
    (
      chosen: string | null,
      runId: string | null = activeRunIdRef.current,
    ): void => {
      // Reads `runs` rather than closing over `activeRun` (declared later in
      // this component) — the run's OWN agent, since the profile chip belongs
      // to whichever CLI this chat is already running.
      const agent = runs.find((run) => run.id === runId)?.agentKind;
      if (chosen !== null && agent) {
        rememberConfigDir(agent, chosen);
      }
      void changeRunSettings({ configDir: chosen }, runId);
    },
    [rememberConfigDir, changeRunSettings, runs],
  );

  /** The native dialog behind that chip, applied to the open chat. */
  const pickRunConfigDir = useLatestCallback(async (): Promise<void> => {
    const runId = activeRunIdRef.current;
    const chosen = await window.geniro.pickProjectFolder();
    if (chosen) {
      changeRunConfigDir(chosen, runId);
    }
  }, [changeRunConfigDir]);

  /**
   * Read one message attachment's bytes for the transcript. Stable per launch
   * handle, so the memoized rows below it never re-render for a new identity.
   */
  const loadAttachment = useLatestCallback(
    async (runId: string, attachmentId: string): Promise<string> => {
      const attachment = await chatApi.readChatAttachment({
        runId,
        attachmentId,
      });
      return attachment.data;
    },
    [chatApi],
  );

  /** Read one chat's metrics — the context breakdown and the thread's spend. */
  const loadChatMetrics = useChatMetricsLoader(chatApi, rememberRunContext);

  /**
   * Read what one command an agent started has PRINTED — the terminal behind a
   * row in the running-shells list.
   *
   * Keyed on the ACTIVE run for the same reason `loadMarkdownImage` is: the
   * shells on screen are this run's, the daemon resolves the output file from
   * this run's own transcript, and a call id means nothing without it.
   *
   * The daemon is given a CALL ID and never a path. The file it reads is
   * whatever that call's own reply announced, so this is a read of one file the
   * CLI itself named in this run's transcript rather than a file-read channel
   * with a validated argument.
   */
  const loadShellOutput = useLatestCallback(
    (callId: string) => {
      const runId = activeRunIdRef.current;
      if (!runId) {
        throw new Error('no run to read this command against');
      }
      return chatApi.readShellOutput({ runId, callId });
    },
    [chatApi],
  );

  /**
   * Read one AGENT-REFERENCED image for the transcript — `![](/tmp/shots/x.png)`
   * in a message the agent wrote.
   *
   * Keyed on the ACTIVE run rather than taking a run id, because the reference
   * carries no run and a relative one is meaningless without the cwd the agent
   * was working in; the transcript on screen is this run's, so this run's cwd is
   * the base. Returns a ready `data:` URL — the CSP is `img-src 'self' data:`,
   * which is the other half of why an `<img src="file://…">` never rendered.
   */
  const loadMarkdownImage = useLatestCallback(
    async (path: string): Promise<string> => {
      const runId = activeRunIdRef.current;
      if (!runId) {
        throw new Error('no run to resolve this image against');
      }
      return readLocalImageDataUrl(chatApi, runId, path);
    },
    [chatApi],
  );

  const loadMemory = useLatestCallback(
    (handle: string) => readMemoryByHandle(apis.memories, handle),
    [apis],
  );

  const loadKnowledge = useLatestCallback(
    async (lookup: KnowledgeLookup) => {
      const runId = activeRunId ?? undefined;
      const { elsewhere } = lookup;
      if ('handle' in lookup) {
        const { documents } = await apis.knowledge.listKnowledge(
          elsewhere === undefined
            ? { handle: lookup.handle, runId }
            : { handle: lookup.handle },
        );
        return elsewhere === undefined
          ? documents
          : headsInNamedPlace(documents, elsewhere);
      }
      if (elsewhere !== undefined) {
        const { documents } = await apis.knowledge.listKnowledge({
          q: lookup.search ?? undefined,
        });
        return headsInNamedPlace(documents, elsewhere);
      }
      if (runId === undefined) {
        throw new Error('no run to search for');
      }
      const { documents } = await apis.knowledge.searchKnowledgeForRun({
        runId,
        q: lookup.search ?? undefined,
      });
      return documents;
    },
    [apis, activeRunId],
  );

  const openKnowledge = useLatestCallback(
    (target: KnowledgeOpenTarget) =>
      onOpenKnowledge?.(
        'handle' in target
          ? { ...target, runId: activeRunId ?? undefined }
          : target,
      ),
    [onOpenKnowledge, activeRunId],
  );

  /**
   * Ask the picked CLI what conversations it holds, whenever the question
   * changes — which CLI, and under which profile.
   *
   * Every folder, deliberately: the picker searches paths as well as titles, so
   * narrowing the QUESTION to the composer's own folder would only hide the
   * conversations the user came here to find in some other project.
   *
   * Only while the dialog is OPEN. The listing spawns a cursor process, so a
   * hook that ran on mount would launch one for a control nobody has pressed.
   */
  useEffect(() => {
    if (!sessionPickerOpen) {
      return;
    }
    let stale = false;
    setSessionsLoading(true);
    setSessionsError(null);
    // One ask per PROFILE, folded into one list. Concurrent rather than in
    // turn: they are independent questions to independent stores, and asking
    // them sequentially would make opening the picker cost the sum of every
    // account the user has. Bounded rather than all at once, because each ask
    // is a full-profile scan and nothing cancels a superseded one — see
    // `SESSION_SEARCH_CONCURRENCY`.
    void mapWithLimit(
      sessionProfileDirs,
      SESSION_SEARCH_CONCURRENCY,
      async (profile): Promise<ProfileAnswer> =>
        agentsApi
          .listAgentSessions({
            agent: sessionAgent,
            // The profile is part of the QUESTION, and the answer's rows are
            // tagged with it — an id listed under one profile is not
            // resumable under another, so the import has to know which store
            // the row the user pressed came out of.
            ...(profile === null ? {} : { configDir: profile }),
            // Searched on the daemon, which is the only side that can read
            // what was SAID in a conversation. Absent for an empty box, so
            // the unfiltered listing is exactly the request it always was.
            ...(sessionQueryAsked === '' ? {} : { query: sessionQueryAsked }),
          })
          .then((listing) => ({ configDir: profile, listing, error: null }))
          // Caught PER PROFILE: one directory the user has since moved away
          // must cost its own rows and not the whole dialog, which is what a
          // single rejected `Promise.all` would do.
          .catch((err: unknown) => ({
            configDir: profile,
            listing: null,
            error: daemonErrorDetail(err),
          })),
    )
      .then((answers) => {
        if (stale) {
          return;
        }
        setSessionListing(mergeSessionListings(answers, SESSION_LIST_LIMIT));
        // Only when NOTHING answered. A profile that failed beside profiles
        // that did is reported in the merged `partialReason`, under the rows —
        // an error strip over a working list reads as the list being wrong.
        const failed = answers.filter((answer) => answer.listing === null);
        setSessionsError(
          failed.length === answers.length ? (failed[0]?.error ?? null) : null,
        );
      })
      .finally(() => {
        if (!stale) {
          setSessionsLoading(false);
        }
      });
    return () => {
      stale = true;
    };
  }, [
    sessionPickerOpen,
    sessionAgent,
    sessionProfileDirs,
    sessionQueryAsked,
    agentsApi,
  ]);

  /**
   * Take over one of those conversations: create a chat bound to it and open
   * it.
   *
   * The new run's cwd is the SESSION's, never the composer's — a resumed
   * conversation is about the tree it was reasoning over, and continuing it
   * somewhere else is how an agent starts confidently answering about the
   * wrong project. Its title is the session's, so the sidebar row says what
   * the thread is rather than repeating the folder.
   *
   * The daemon does the import inside this one call (it copies what has to be
   * copied and writes the transcript), which is why the dialog stays up with
   * the row spinning rather than closing optimistically: a thread that opens
   * empty and fills in later is indistinguishable from one that failed.
   */
  const resumeSession = useLatestCallback(
    async ({ session, configDir: profile }: ProfiledSession): Promise<void> => {
      if (session.cwd === null) {
        return;
      }
      setResumingSessionId(session.id);
      setSessionsError(null);
      try {
        const run = await chatApi.createChat({
          createChatDto: {
            agentKind: sessionAgent,
            cwd: session.cwd,
            resumeSessionId: session.id,
            // An imported conversation is a new run like any other, so it gets
            // the same snapshot — read now, for the same freshness reason. The
            // stamp is taken against the SESSION's folder, like the run itself.
            ...(await currentRunSettings()),
            ...(await chatGitStamp(session.cwd)),
            ...(session.title ? { title: session.title } : {}),
            ...(models[sessionAgent] ? { model: models[sessionAgent] } : {}),
            ...(efforts[sessionAgent] ? { effort: efforts[sessionAgent] } : {}),
            ...(modelParameters[sessionAgent]
              ? { modelParameters: modelParameters[sessionAgent] }
              : {}),
            ...(contextWindows[sessionAgent]
              ? { contextWindow: contextWindows[sessionAgent] }
              : {}),
            // The two a NEW chat carries and this one did not, so a resumed
            // thread opened on the daemon's defaults whatever the composer
            // said. The approval on `createChatRun`'s own terms, only asked of
            // the SESSION's CLI: the composer's modes are its own agent's, and
            // the daemon refuses a mode the CLI does not honour.
            ...(autoCompactPercent !== null ? { autoCompactPercent } : {}),
            ...((approvalCapabilityFor(sessionAgent)?.modes ?? []).includes(
              approvalMode,
            )
              ? { approval: approvalMode }
              : {}),
            // The profile the ROW was listed under, never the composer's:
            // with several accounts on the list, resuming under the wrong one
            // asks a CLI to continue a session that is not in its store.
            ...(profile === null ? {} : { configDir: profile }),
          },
        });
        addRun(run);
        setSessionPickerOpen(false);
        await activateRun(run.id);
      } catch (err) {
        setSessionsError(daemonErrorDetail(err));
      } finally {
        setResumingSessionId(null);
      }
    },
    // Every value the body reads, for `createChatRun`'s reason: `modelParameters`
    // and `contextWindows` were missing, so a pick made after the last change to
    // one of these reached the chip and never the import.
    [
      sessionAgent,
      models,
      efforts,
      modelParameters,
      contextWindows,
      autoCompactPercent,
      approvalMode,
      approvalCapabilityFor,
      chatApi,
      activateRun,
      addRun,
    ],
  );

  /**
   * The run the next message belongs to — the open one, or a freshly created
   * chat.
   *
   * Answers with the RUN it created rather than its id alone, because a caller
   * needs the status the daemon gave it and has nowhere else to read it: the
   * row is only in `runs` after a commit, and `runsRef` is an effect-synced
   * mirror a commit behind that. `null` for a run that already exists — the
   * list has held that one all along.
   */
  const ensureRun = useLatestCallback(async (): Promise<{
    runId: string;
    created: ChatRun | null;
  } | null> => {
    if (activeRunIdRef.current) {
      return { runId: activeRunIdRef.current, created: null };
    }
    const composer = composerChatFields();
    const cwd = await ensureFolder();
    if (!cwd) {
      setError('Choose a folder for this chat first.');
      return null;
    }
    const run = await createChatRun(cwd, composer);
    addRun(run);
    await activateRun(run.id);
    return { runId: run.id, created: run };
  }, [ensureFolder, composerChatFields, createChatRun, activateRun, addRun]);

  /** The sidebar's + : back to the new-run composer. Nothing is created —
   *  the run (chat or team) is only seeded when the composer sends. */
  const newChat = useLatestCallback((): void => {
    deactivateRun();
    refreshRuns();
    setComposerProject((current) =>
      current.source === 'folder' ? current : FOLDER_PROJECT,
    );
  }, [deactivateRun, refreshRuns]);

  useEffect(() => {
    if (!active || firstLaunchAgent === null) {
      return;
    }
    newChat();
    changeTarget(firstLaunchAgent);
    setMobileComposeOpen(true);
    onFirstLaunchHandled?.();
  }, [active, firstLaunchAgent, newChat, changeTarget, onFirstLaunchHandled]);

  /**
   * Shelve one chat and take its row off whichever list is on screen.
   *
   * Below `newChat` for the reason `confirmDelete` is: it hands the window
   * back to the composer when the thread being filed away is the open one.
   */
  const archiveRun = useLatestCallback(
    async (runId: string): Promise<void> => {
      const archived = await chatApi.archiveChat({ runId });
      // Re-filed rather than dropped: under `Show all` the row stays and only
      // its actions change. It is only under `Active chats` that it has left
      // the listing, and there leaving its transcript up would put a thread on
      // screen with no row anywhere beside it.
      placeRun(archived, newChat);
    },
    [chatApi, placeRun, newChat],
  );

  /**
   * Every archive ASKS — the running one because it cancels a turn on the way,
   * the settled one because the row leaves the list and nothing afterwards
   * offers it back.
   *
   * A settled chat used to be shelved in one press, on the reasoning that
   * archiving destroys nothing and unarchive is right there. What that misses
   * is where the press IS: the row's own menu, one entry from Delete, on a
   * gesture whose whole visible effect is a conversation disappearing from the
   * sidebar. The dialog still says which of the two it is asking about — only
   * the running arm loses anything, and only it is drawn destructive.
   */
  const handleArchiveRun = useLatestCallback(
    (runId: string): void => {
      const run = runsRef.current.find((r) => r.id === runId);
      if (!run) {
        return;
      }
      setArchiveError(null);
      setArchiving(run);
    },
    [runsRef],
  );

  /**
   * Watches for the stretch the daemon queues when this thread is archived.
   * Nothing is shown unless one comes back: a thread with no signal, or lessons
   * switched off, queues none. The watch ends at the first queued stretch, or
   * after {@link ARCHIVE_LESSON_WATCH_MS}.
   */
  const watchArchivedLessons = useLatestCallback(
    (runId: string): void => {
      stopArchiveLessonWatch.current?.();
      let finished = false;
      let unsubscribe: () => void = () => undefined;
      const timer = setTimeout(() => finish(), ARCHIVE_LESSON_WATCH_MS);
      const finish = (): void => {
        finished = true;
        clearTimeout(timer);
        unsubscribe();
        stopArchiveLessonWatch.current = null;
      };
      const look = (): void => {
        if (finished) {
          return;
        }
        apis.lessons
          .listLessonSegments({ runId, status: 'queued' })
          .then((answer) => {
            const segment = answer.segments.reduce<LessonSegment | null>(
              (kept, next) =>
                kept === null || next.toSeq > kept.toSeq ? next : kept,
              null,
            );
            if (finished || segment === null) {
              return;
            }
            finish();
            return apis.lessons
              .getLessonsSpend()
              .then(
                (spend) => spend.todayUsd,
                () => null,
              )
              .then((todayUsd) => setArchiveLessons({ segment, todayUsd }));
          })
          .catch((err: unknown) => {
            finish();
            setError(describeDaemonError(err));
          });
      };
      if (client !== null) {
        unsubscribe = client.onLessonsChanged((event) => {
          if (event.runId === null || event.runId === runId) {
            look();
          }
        });
      }
      stopArchiveLessonWatch.current = finish;
      look();
    },
    [apis, client, setError],
  );

  const skipArchivedLessons = useLatestCallback(
    (segment: LessonSegment): void => {
      setArchiveLessons(null);
      apis.lessons
        .skipLessonSegment({ segmentId: segment.id })
        .catch((err: unknown) => {
          if (daemonErrorStatus(err) === 409) {
            return;
          }
          setError(describeDaemonError(err));
        });
    },
    [apis, setError],
  );

  const confirmArchive = useLatestCallback(async (): Promise<void> => {
    if (!archiving) {
      return;
    }
    setArchiveBusy(true);
    setArchiveError(null);
    try {
      await archiveRun(archiving.id);
      setArchiving(null);
      watchArchivedLessons(archiving.id);
    } catch (err) {
      setArchiveError(String(err));
    } finally {
      setArchiveBusy(false);
    }
  }, [archiving, archiveRun, watchArchivedLessons]);

  /**
   * Put an archived chat back, from its SIDEBAR ROW.
   *
   * The same re-file as archive, and it needs the open-run branch just as much:
   * an archived row is activatable, so the thread being put back can be the
   * one on screen.
   */
  const handleUnarchiveRun = useLatestCallback(
    (runId: string): void => {
      void chatApi
        .unarchiveChat({ runId })
        .then((run) => placeRun(run, newChat))
        .catch((err: unknown) => setError(String(err)));
    },
    [chatApi, placeRun, newChat, setError],
  );

  /**
   * Put the OPEN chat back, from the control above its own composer.
   *
   * Deliberately not {@link handleUnarchiveRun}: this control is only ever on
   * screen when the run is the open one, and it exists to make THIS
   * conversation usable again — so on the one scope that would drop the row
   * (`Archived only`) it moves the sidebar to the desk and keeps the thread
   * open, rather than taking the hand-back branch and landing the user on the
   * landing composer, which is the opposite of what the button says.
   */
  const handleUnarchiveOpenRun = useLatestCallback(
    (runId: string): void => {
      void chatApi
        .unarchiveChat({ runId })
        .then(async (run) => {
          if (chatScope === 'archived') {
            showScope('active');
            await activateRun(runId);
            return;
          }
          // `all` keeps it listed; the re-file is what re-enables the composer.
          placeRun(run, newChat);
        })
        .catch((err: unknown) => setError(String(err)));
    },
    [chatApi, chatScope, showScope, activateRun, placeRun, newChat, setError],
  );

  /**
   * Switch what the sidebar lists, keeping the open thread only where the new
   * scope still holds it.
   *
   * Closing unconditionally was right while the filter had two disjoint sides —
   * the thread on screen always belonged to the one being left. `Show all`
   * breaks that: it holds every thread, so closing on the way in would shut a
   * conversation the user is reading to show them a list that still contains
   * it. A thread the new scope does NOT hold is still closed, because it would
   * otherwise render on with its row absent from `runs` — and everything the
   * transcript reads off that row goes with it: the header (title, status,
   * Stop) disappears, and the archived-composer gate reads `undefined` and
   * re-ENABLES a composer whose next send the daemon refuses.
   */
  const handleShowScope = useLatestCallback(
    (next: ChatListScope): void => {
      const open = runsRef.current.find((run) => run.id === activeRunId);
      const kept = open !== undefined && inScope(open, next, activityWindow);
      if (!kept) {
        deactivateRun();
      }
      showScope(next);
    },
    [activeRunId, runsRef, deactivateRun, showScope, activityWindow],
  );

  const handleActivityWindow = useLatestCallback(
    (preset: ActivityPreset, next: ActivityWindow | null): void => {
      const open = runsRef.current.find((run) => run.id === activeRunId);
      if (open !== undefined && !inScope(open, chatScope, next)) {
        deactivateRun();
      }
      setActivityPreset(preset);
      showActivityWindow(next);
    },
    [activeRunId, runsRef, deactivateRun, showActivityWindow, chatScope],
  );

  const confirmDelete = useLatestCallback(async (): Promise<void> => {
    if (!deleting) {
      return;
    }
    setDeleteBusy(true);
    setDeleteError(null);
    try {
      // The sidebar lists both kinds of run, and each owns its own teardown:
      // the chat route REFUSES a team run (its graph executor has state
      // the chat path knows nothing about), so routing every row through it
      // left the team rows permanently undeletable.
      const extractLessons = extractLessonsOnDelete ? 'true' : undefined;
      try {
        await (deleting.teamId
          ? teamApi.deleteTeamRun({ runId: deleting.id, extractLessons })
          : chatApi.deleteChat({ runId: deleting.id, extractLessons }));
      } catch (err) {
        // The run is ALREADY gone, which is what was asked for — so this falls
        // through to the success path rather than being reported. It is the
        // routine outcome of pressing Delete on a row another client destroyed:
        // until `run_deleted` existed nothing could correct such a row, and it
        // answered every press with `404 RUN_NOT_FOUND` and stayed put, which
        // is how a user came to have a row they could neither open nor delete.
        // Even with the broadcast this stays, for the window between the delete
        // landing and the announce arriving.
        if (daemonErrorCode(err) !== 'RUN_NOT_FOUND') {
          throw err;
        }
      }
      // Nothing can ever show it again, so it must not be kept — the same rule
      // the daemon's own per-run maps follow, announced there on the bus.
      forgetContextReading(deleting.id);
      forgetThread(deleting.id);
      setDeleting(null);
      // The open transcript belongs to a run that no longer exists: leave its
      // room and fall back to the composer, rather than leaving a dead
      // transcript on screen whose Send would 404.
      dropRun(deleting.id, newChat);
    } catch (err) {
      setDeleteError(String(err));
    } finally {
      setDeleteBusy(false);
    }
  }, [deleting, chatApi, teamApi, dropRun, newChat, forgetContextReading]);

  /**
   * A run destroyed somewhere else — another window, the browser client, a
   * teardown — leaves this list holding a row for it.
   *
   * The daemon broadcasts the deletion to EVERY client rather than to the run's
   * room, because the row that has to disappear is in every sidebar and a
   * client only ever joins the one run it is showing. Without it nothing here
   * could learn the fact at all: `run_status` can only describe runs that still
   * exist, so a ghost row survived until the next full re-list — and answered a
   * click with `404 RUN_NOT_FOUND`, which is the reported "I cant delete thread
   * from app".
   *
   * Subscribed HERE rather than in `use-chat-run`, where its siblings live,
   * because closing the open transcript is this component's own business —
   * `newChat` resets the composer as well as leaving the room, and the hook
   * holds neither.
   */
  useEffect(
    () =>
      client.onRunDeleted((runId) => {
        forgetContextReading(runId);
        forgetThread(runId);
        dropRun(runId, newChat);
        // A deleted thread's analysis went with it (the daemon's cascade), so
        // neither its popup nor its setup dialog has a subject left.
        setAnalysisOf((open) => (open?.id === runId ? null : open));
        setAnalyzingRun((open) => (open?.id === runId ? null : open));
      }),
    [client, dropRun, newChat, forgetContextReading],
  );

  /**
   * A run re-filed somewhere else — archived, unarchived, renamed, pinned or
   * moved into a group on the phone or in another window — moves here too.
   *
   * Broadcast by the daemon for `run_deleted`'s reason: the row is in every
   * sidebar while a client joins only the run it shows. REPORTED as "I deleted
   * threads from mobile, but still can see it on PC" — the phone had archived
   * them, and nothing told the desktop. Here rather than in `use-chat-run`
   * for the reason its sibling above is: closing the open thread is `newChat`.
   */
  useEffect(
    () => client.onRunsChanged((runs) => refileChangedRuns(runs, newChat)),
    [client, refileChangedRuns, newChat],
  );

  /**
   * The GROUP list changed somewhere else — a group made, renamed, folded,
   * reordered or deleted on the phone or in another window — so read it again.
   * Until this the list was read once per connection, and a group made on one
   * device was missing from the other's sidebar until a reconnect. A deleted
   * group's chats need nothing: a row naming a group the list no longer holds
   * already falls into the loose section (`runGroupSections`).
   */
  useEffect(
    () => client.onGroupsChanged(refreshGroups),
    [client, refreshGroups],
  );

  const [pendingSends, setPendingSends] = useState<
    ReadonlyMap<string, PendingSend>
  >(() => new Map());

  /**
   * Start one turn: mark the run working, send, render the user message
   * (addItem de-dupes when the WS copy arrives).
   *
   * The `running` written here is a MIRROR of a turn the daemon accepted, so a
   * send that never landed puts it back. Without that, a refused message left
   * the row saying `running` with nothing running and nothing left to correct
   * it: the badge stayed wrong, and the next activation read the row, found no
   * terminal item, and re-armed `streaming` — a chat reading `Working… 4s` over
   * an empty transcript, forever, which is exactly what was reported. Rolled
   * back only from `running`, and only to the status this call overwrote, so a
   * genuinely busy run (a RUN_BUSY refusal) keeps the state it already had.
   *
   * Rethrows: every caller has its own way of putting the message back in front
   * of the user, and swallowing here would lose it.
   */
  const startTurn = useLatestCallback(
    async (
      runId: string,
      text: string,
      images?: SendMessageDtoImagesInner[],
      /**
       * What the run's status was, for a caller holding a row the list has yet
       * to commit — a chat created by this very send. `runsRef` is an
       * effect-synced mirror and cannot answer for one: it is a commit behind,
       * so the rollback below read nothing and never fired.
       */
      statusBefore?: ChatRun['status'],
      clientMessageId = randomId(),
      queueTerms?: QueueSendTerms,
    ): Promise<void> => {
      await hostedRef.current?.onBeforeSend?.();
      // The live plane belongs to the chat that is ON SCREEN. A background
      // drain (see the `run_status` handler) starts a real turn in a thread
      // the user is not looking at — clearing THIS chat's error banner and
      // arming its Stop button for it would describe the wrong conversation,
      // and `streaming` is a single reading for the open transcript.
      //
      // Safe for the first send of a new chat: `ensureRun` awaits
      // `activateRun`, which sets this ref before its first await.
      if (runId === activeRunIdRef.current) {
        setError(null);
        setStreaming(true);
        turnEndReportedRef.current = false;
        // A message goes to the END of the conversation, so the reader has to be
        // AT the end to see it. Parked on a window fetched around a search hit,
        // the append is suppressed (`useChatRun`'s `awayFromTail`, which exists
        // so a live row is never drawn under one from hours earlier) — and that
        // is right for a row the daemon pushes and wrong for the row the user
        // just wrote: they would get a Stop button over an old transcript with
        // nothing saying where their message went. Awaited BEFORE the send, so
        // the row lands in a window that can hold it. `returnToTail` is
        // idempotent, so this costs nothing when the reader is already there.
        await returnToTail();
      }
      const before =
        runsRef.current.find((run) => run.id === runId)?.status ??
        statusBefore ??
        null;
      setRuns((prev) =>
        prev.map((run) =>
          run.id === runId ? { ...run, status: 'running' } : run,
        ),
      );
      let held: PendingSend | null = null;
      const holdWhileRestoring = (): void => {
        const pending: PendingSend = {
          runId,
          text,
          imageCount: images?.length ?? 0,
          sentAt: new Date().toISOString(),
          // Another run's window says nothing about this run's seqs, so its
          // own row can only take the place of the held one at the settle.
          afterSeq:
            runId === activeRunIdRef.current
              ? (itemsRef.current.at(-1)?.seq ?? -1)
              : Number.MAX_SAFE_INTEGER,
        };
        held = pending;
        setPendingSends((prev) => new Map(prev).set(runId, pending));
      };
      try {
        const sendMessageDto = {
          text,
          clientMessageId,
          ...(images?.length ? { images } : {}),
          ...queueTerms,
        };
        const run = runsRef.current.find((row) => row.id === runId);
        // A chat in a TASK's worktree outlives it — the board collects that
        // once the card is Done — so a refusal naming the missing folder puts
        // the worktree back and sends once more (`sendRestoringWorktree`).
        const userItem = await sendRestoringWorktree(
          () =>
            // A team run's message goes to the agents its trigger feeds,
            // which only the executor knows — the chat route refuses one.
            run?.teamId != null
              ? teamApi.sendTeamRunMessage({ runId, sendMessageDto })
              : chatApi.sendChatMessage({ runId, sendMessageDto }),
          run ?? null,
          restoreWorktree,
          holdWhileRestoring,
        );
        addItem(userItem, true);
      } catch (err) {
        if (before !== null) {
          setRuns((prev) =>
            prev.map((run) =>
              run.id === runId && run.status === 'running'
                ? { ...run, status: before }
                : run,
            ),
          );
        }
        throw err;
      } finally {
        setPendingSends((prev) => {
          if (held === null || prev.get(runId) !== held) {
            return prev;
          }
          const next = new Map(prev);
          next.delete(runId);
          return next;
        });
      }
    },
    [chatApi, teamApi, addItem, restoreWorktree],
  );

  /**
   * The `/` popup's rows, mirrored for the two send paths.
   *
   * Both are declared above the `useAgentSkills` call that produces them — a
   * ref is how the rest of this component already reaches state that is
   * resolved later (`runsRef`), and the alternative is moving a 200-line
   * callback for one lookup.
   */
  const skillsRef = useRef<readonly AgentSkill[]>([]);

  /**
   * Refuse a slash command this agent does not have, rather than letting it
   * reach the model as prose — see `unknownSlashCommand` for why neither
   * transport catches it. True means the send was stopped and the composer is
   * showing why, with the text still in the box to be corrected.
   */
  const refuseUnknownCommand = useLatestCallback((text: string): boolean => {
    const unknown = unknownSlashCommand(text, skillsRef.current);
    if (unknown === null) {
      return false;
    }
    setError(
      `No /${unknown} command for this agent — press / to see what it has.`,
    );
    return true;
  }, []);

  /** The new-run composer's start: seed a fresh team run (fired from its
   *  trigger) or create a chat run and send its first message. */
  const send = useLatestCallback(async (): Promise<void> => {
    // Spelled the way THIS agent spells it — see `withAgentSlashSpelling`. It
    // wraps the trim rather than sitting beside the refusal below, so every
    // use of `text` downstream (the send body, the optimistic row) is the one
    // string, and none of them can be the pre-rewrite one.
    const text = withAgentSlashSpelling(
      composerText.get().trim(),
      skillsRef.current,
    );
    const images = attachments.toWire();
    // The staged form of those same images, kept so a refusal can put the
    // composer back exactly as it was — `toWire` is the send body, which the
    // thumbnails cannot be rebuilt from.
    const staged = attachments.attachments;
    const sentKeys = staged.map((attachment) => attachment.key);
    // An image on its own is a complete message; only the fully empty composer
    // is a no-op. A paste still being read is refused rather than sent without
    // the image — see `useAttachments`' `reading`.
    if ((!text && images.length === 0) || streaming || attachBusy) {
      return;
    }
    setError(null);
    if (refuseUnknownCommand(text)) {
      return;
    }
    try {
      // A team target ALWAYS seeds a fresh run — never routes the task
      // into whatever run happens to be open (activateRun leaves the old room).
      if (teamSlug) {
        const cwd = await ensureFolder();
        if (!cwd) {
          setError('Choose a folder for this run first.');
          return;
        }
        setInput('');
        attachments.clear(sentKeys);
        const run = await teamApi.startTeamRun({
          slug: teamSlug,
          // A team run snapshots the instructions exactly as a chat does;
          // every agent node then composes them behind its own role.
          runTeamDto: {
            cwd,
            prompt: text,
            ...(images.length > 0 ? { images } : {}),
            ...(await currentRunSettings()),
            // The folder's commit, as a chat is stamped with it — what the team's
            // line totals are measured against.
            ...(await chatGitStamp(cwd)),
            ...projectFieldOf(composerProject),
          },
        });
        addRun(run);
        await activateRun(run.id);
        // A run can fail-fast within the activation window (missing CLI →
        // instant terminal item in the replayed history); re-arming Stop then
        // would wedge the composer on a run that will emit nothing more.
        if (!sawTerminalRef.current) {
          setStreaming(true);
        }
        return;
      }
      // Emptied BEFORE the run is created, which is the whole fix: creating it
      // ACTIVATES it, and an activation parks whatever the composer is holding
      // as that thread's draft (`swapDraft`). With the message still on screen,
      // the thing being parked was the message being sent — so it came back the
      // next time the landing card was opened, and a switch landing inside the
      // create/join/fetch window parked it on the new thread instead. The
      // team branch above has always cleared first; this one did not.
      setInput('');
      attachments.clear(sentKeys);
      const target = await ensureRun();
      if (!target) {
        // No folder chosen — the run was never made, so the message is still
        // the user's to send. Putting it back is not optional: this path is
        // reached by pressing Send.
        setInput((current) => (current.length === 0 ? text : current));
        attachments.restore(staged);
        return;
      }
      // Renders the user message even if join raced the publish; addItem
      // de-dupes when the WS copy arrives.
      await startTurn(target.runId, text, images, target.created?.status);
    } catch (err) {
      // The daemon's own sentence, exactly as `drainQueue` and `sendQueuedNow`
      // already do it — this catch was the one send path left printing the raw
      // envelope, and it is the path a FIRST message takes, so a refusal of the
      // very thing it carried reached the user as
      // `daemon POST /v1/chats/…/messages failed (413): {"statusCode":413,…}`.
      setError(daemonErrorDetail(err) ?? String(err));
      setStreaming(false);
      // A failed send must leave the typed task editable (mirror drainQueue's
      // restoreHead) — but never clobber anything typed since. The staged
      // images come back with it, so a retry does not require re-pasting the
      // screenshot: they are PUT back now, rather than merely left alone, since
      // the composer is emptied up front. Before, they were neither — the
      // activation cleared them and this path never restored them, so the one
      // send that could fail on its attachments was also the one that threw
      // them away.
      setInput((current) => (current.length === 0 ? text : current));
      if (attachmentsRef.current.length === 0) {
        attachments.restore(staged);
      }
    }
  }, [
    streaming,
    teamSlug,
    teamApi,
    ensureFolder,
    activateRun,
    ensureRun,
    startTurn,
    attachments,
    attachBusy,
    refuseUnknownCommand,
    addRun,
  ]);

  // What the queue sends through, and what it reports. A drain's failure is
  // shown only in the chat it happened in — a background drain's banner would
  // name a failure over a transcript that has nothing to do with it. A Send-now
  // that started the turn itself turns the working state off again.
  useEffect(() => {
    messageQueue.handlersRef.current = {
      activeRunId: () => activeRunIdRef.current,
      send: (runId, text, images, clientMessageId, terms) =>
        startTurn(runId, text, images, undefined, clientMessageId, terms),
      isWorking: () => streamingRef.current,
      onHeldForAnswer: (runId) => {
        if (runId === activeRunIdRef.current) {
          setStreaming(false);
        }
      },
      onFailed: (runId, err, { steer, wasWorking }) => {
        if (steer) {
          if (!wasWorking) {
            setStreaming(false);
          }
          setError(daemonErrorDetail(err) ?? String(err));
          return;
        }
        if (runId === activeRunIdRef.current) {
          setError(daemonErrorDetail(err) ?? String(err));
          setStreaming(false);
        }
      },
    };
    drainQueueRef.current = (runId) => void messageQueue.drain(runId);
  });

  /**
   * The open transcript's composer: a follow-up into the ACTIVE chat run —
   * never a run start (team runs take one task; their composer is off).
   *
   * While the agent is working the message is HELD in this run's queue and
   * shown in the strip above the composer — it is not handed to the CLI, and
   * it becomes a transcript bubble only when it is actually POSTed.
   *
   * This is the inverse of what it used to do, and the inversion is the fix.
   * Sending unconditionally meant that on claude — whose stream-json stdin
   * takes a message into a turn already running — a second thought typed while
   * the agent worked was injected at the next tool boundary. So a message the
   * user meant as "do this next" silently redirected the turn in flight, with
   * no moment left at which they could edit or withdraw it. Holding it gives
   * them that moment; mid-turn delivery survives as the strip's explicit "send
   * now" ({@link steerQueued}), offered only where the daemon says the CLI has
   * a channel for one.
   *
   * The RUN_BUSY catch below is NOT redundant with the hold. `streaming` is
   * the renderer's belief and RUN_BUSY is the daemon's fact; they disagree
   * whenever the run list has not loaded yet, or a turn wedged without
   * settling. Every one of those disagreements used to surface a raw 409 as a
   * red banner.
   */
  const sendFollowUp = useLatestCallback(async (): Promise<void> => {
    // Rewritten before anything reads it, for the reason `send` states — and it
    // matters more here, where the text may sit in the queue for the length of
    // a turn before it is handed over.
    const text = withAgentSlashSpelling(
      composerText.get().trim(),
      skillsRef.current,
    );
    const images = attachments.toWire();
    const clientMessageId = randomId();
    // The staged form of the same images: what a failure puts back, and the
    // KEYS the stage gives up — never the whole stage, which may hold a read
    // that landed after this press and is not part of it.
    const staged = attachments.attachments;
    const sentKeys = staged.map((attachment) => attachment.key);
    const runId = activeRunIdRef.current;
    // A paste still being read is refused rather than sent without it — the
    // button says so while it lasts.
    if ((!text && images.length === 0) || !runId || attachBusy) {
      return;
    }
    // BEFORE the queue branch below, not after: a command the agent does not
    // have is no better for having waited — queueing it would defer the same
    // prose-to-the-model send by however long the turn takes, and put the
    // refusal in front of the user long after they typed it.
    //
    // A geniro command (`/compact`) is NOT refused here, and used to be. It
    // needs an idle run — the daemon says so with a RUN_BUSY, which is the
    // answer the queue is built on — so the composer answered "wait for this
    // turn to finish" up front and the command never went anywhere. Reported
    // against exactly that line: "Компакт должно вставаться в очередь, как и до
    // этого. Это должно работать." It queues like anything else now, and the
    // drain hands it over when the turn ends, which is also the moment it can
    // compact what that turn just said.
    if (refuseUnknownCommand(text)) {
      return;
    }
    // Sending RE-ARMS the follow, wherever the reader had scrolled to. The
    // suppression rule is about not dragging somebody away from what they are
    // reading — and typing into the composer is them saying they are done
    // reading it. Without this, a user who scrolled up, came back to the box
    // and asked a question watched the answer arrive off-screen, with the
    // transcript still frozen where they had left it.
    //
    // Only the FOLLOW, not a scroll of its own: the message lands as an item a
    // frame later, and the tail-follow effect takes it from there.
    followingRef.current = true;
    setAboveTail(false);
    // A HELD turn is not a working agent. Its CLI printed its turn-end line
    // some time ago and the process is alive only so the delegates it launched
    // have somewhere to report; it is sitting on an idle stdin. Holding a
    // message back from it buys the user nothing — there is no turn in flight
    // to be redirected, which is the entire reason the queue exists — and costs
    // them the wait, since the drain does not fire until the last delegate
    // returns, which can be many minutes. Reported as "if claude is running
    // agents in background it's like it stopped to work until it gets a
    // notification from them… we should not send the message to the queue while
    // it's just waiting for listeners".
    //
    // A team manager parked inside `await_agent` is the same fact arriving
    // from the call runtime instead: its turn is `running`, and it is sitting
    // in a tool call that cannot return until a callee it briefed does. The
    // message was going into the queue, where pressing "send now" on that very
    // message delivered it fine — which is what proves the wait is not a busy
    // agent. REPORTED as "если менеджер просто ждет в бэкграунде каких-то своих
    // агентов, он должен принимать сообщения по default".
    // Background work the run carries — sub-agents still out, a detached
    // command still up — parks nothing while the agent is still producing its
    // reply: a message typed then queues, whatever is out. Once the reply is
    // over it is read at once. See {@link activeRunHeld}, which the button's
    // label reads, so the two cannot say different things about one press.
    //
    // The WHOLE decision is `followUpDelivery` (chats/follow-up-delivery.ts),
    // summed up in .claude/rules/ui-chats.md → "Sending and the queue". A SYNC
    // sub-agent is the agent's own tool call, so a message typed during one
    // queues.
    //
    // Is something the user wrote EARLIER still waiting? Then this goes behind
    // it, whatever the run is doing — a queue the composer can jump is not a
    // queue.
    //
    // `working` alone decided that, and it is false in every window where the
    // queue outlives the turn behind it: after Stop (which deliberately leaves
    // the queue standing), while a drain sits out its RUN_BUSY backoff or its
    // POST is in flight, on a run reopened before its drain ran, on a held run
    // whose queue is deeper than the one message the hold released. Typing in
    // any of them handed the NEWEST message straight to the CLI past the older
    // ones, which is the reported "первым будет доставлено то, которое я написал
    // последним, но должно быть фифа".
    const decision = followUpDelivery({
      streaming,
      queued: hasQueuedMessages(runId),
      held: holdingRef.current.has(runId),
      awaitingCalls: awaitingCallsRef.current.has(runId),
      rootsIdle: rootsIdleRef.current.has(runId),
      subagentsOut: delegatesOutRef.current.has(runId),
      shellsOut: shellsOutRef.current.has(runId),
    });
    if (decision.action === 'queue') {
      setInput('');
      enqueueMessage(runId, { text, images, clientMessageId });
      attachments.clear(sentKeys);
      // A queue nothing is driving needs the kick — there is no turn in flight
      // whose terminal item would fire the drain, so without this the backlog
      // waits for the user to leave the chat and come back. Not while the agent
      // is working: that drain would spend its whole RUN_BUSY backoff refusing,
      // and hold `drainingRef` against the drain the turn's own ending fires.
      if (decision.kickDrain) {
        drainQueueRef.current(runId);
      }
      return;
    }
    // Emptied BEFORE the await, text AND images — the rule `send` already
    // follows, and for its reason. `startTurn` awaits (the return to the tail,
    // then the POST), and a thread switch landing in that window parks whatever
    // the composer holds as THIS thread's draft: with the images still staged,
    // the one just sent would come back staged here, and a clear after the
    // await would wipe the images of the thread switched TO. Everything after
    // the await is therefore addressed to `runId`, never to the screen.
    setInput('');
    attachments.clear(sentKeys);
    try {
      await startTurn(runId, text, images, undefined, clientMessageId);
    } catch (err) {
      if (isRunBusyError(err)) {
        // The CLI cannot be told anything mid-turn (or the turn settled as
        // this was in flight). Queue it — the composer shows it pending and
        // the drain sends it the moment the turn ends. Not an error: this is
        // the documented fallback, and a red banner for it would report a
        // failure the user has no action for.
        //
        // Deliberately NOT gated on `streaming`. That flag is the renderer's
        // own belief, and the daemon's RUN_BUSY is the fact — they disagree
        // whenever the run list has not loaded yet (`refreshRuns` is
        // fire-and-forget while `activateRun` reads `runsRef.current`), or
        // when a turn wedged without settling. Every one of those disagreements
        // used to surface the raw 409 JSON as a red banner.
        enqueueMessage(runId, { text, images, clientMessageId });
        // ...and kick the drain, which is what makes the queue more than a
        // holding pen here. The automatic drain fires on a TERMINAL ITEM, and in
        // this branch the renderer already believed no turn was running — so
        // when the disagreement is the daemon finishing a turn's teardown (its
        // process being reaped a moment after the terminal item), there is no
        // further item coming and the message would sit in the strip until the
        // user left the chat and came back. The drain's own RUN_BUSY backoff
        // covers exactly that window; a genuinely busy run falls through it and
        // is still drained by its terminal item, unchanged.
        drainQueueRef.current(runId);
        return;
      }
      // Same rule as the other three send paths: show what the daemon said —
      // in the thread it happened in and only there, the rule `drainQueue`
      // already keeps. The banner and the live state are the OPEN thread's,
      // and a switch made during the send means that is somebody else's.
      if (activeRunIdRef.current === runId) {
        setError(daemonErrorDetail(err) ?? String(err));
        if (!streaming) {
          setStreaming(false);
        }
      }
      // Mirror drainQueue's restoreHead: a failed follow-up keeps its text and
      // its images — in its own thread's composer, wherever the user now is.
      restoreUnsent(runId, text, staged);
    }
  }, [
    streaming,
    startTurn,
    enqueueMessage,
    attachments,
    attachBusy,
    refuseUnknownCommand,
    restoreUnsent,
  ]);

  const cancel = useLatestCallback(async (): Promise<void> => {
    const runId = activeRunIdRef.current;
    if (!runId) {
      return;
    }
    try {
      const activeIsTeam =
        runsRef.current.find((r) => r.id === runId)?.teamId != null;
      const { cancelled } = activeIsTeam
        ? await teamApi.cancelTeamRun({ runId })
        : await chatApi.cancelChat({ runId });
      // A live/claimed turn was cancelled → its terminal item arrives over WS and
      // clears the working state. `cancelled: false` means nothing was in flight
      // (the turn already finished), so clear it here rather than stay on Stop.
      if (!cancelled) {
        setStreaming(false);
      }
    } catch (err) {
      setError(String(err));
    }
  }, [chatApi, teamApi]);

  /**
   * Call off the continue geniro promised this run at a usage-limit reset. The
   * chip goes away when the daemon announces the run's emptied list, not here —
   * the announce is what every other window sees too.
   */
  const [cancellingResetWakes, setCancellingResetWakes] = useState(false);
  const cancelResetWakes = useLatestCallback(
    (runId: string): void => {
      setCancellingResetWakes(true);
      void teamApi
        .cancelTeamRunResetWakes({ runId })
        .catch((err: unknown) => setError(String(err)))
        .finally(() => setCancellingResetWakes(false));
    },
    [teamApi, setError],
  );

  const respondApproval = useLatestCallback(
    (
      item: ChatItem,
      allow: boolean,
      answer?: string,
      images?: SendMessageDtoImagesInner[],
      optionId?: string,
    ): void => {
      const requestId = payloadString(item.payload, 'id');
      if (requestId) {
        // Arity-preserving: a one-time verdict keeps the call it always made.
        if (optionId === undefined) {
          client.sendVerdict(item.runId, requestId, allow, answer);
        } else {
          client.sendVerdict(item.runId, requestId, allow, answer, optionId);
        }
      }
      if (!images?.length) {
        return;
      }
      // The verdict FIRST, then the picture. The answer reaches the model as
      // `updatedInput.response` — a string field of the CLI's own tool input,
      // with nowhere for bytes to go — so the image travels the one channel
      // that carries real image blocks: a user message into the turn that the
      // verdict just unblocked. The answer text already says one is coming.
      //
      // A RUN_BUSY here is not a failure: the turn settled as this flew, and
      // the queue then delivers the image the moment the next turn can take
      // it, exactly as it would for anything typed in the composer.
      void startTurn(item.runId, '', images).catch((err: unknown) => {
        if (isRunBusyError(err)) {
          enqueueMessage(item.runId, { text: '', images });
          return;
        }
        setError(String(err));
      });
    },
    [client, startTurn, enqueueMessage],
  );

  /**
   * The window and every row filed under one of the run's calls (`inCall`) —
   * a page's card rows, live rows, an opened card's pages — which a team
   * run's window never holds. What every reader below that is about a call's
   * turns, cards, shells or pages reads.
   */
  const transcriptRows = useMemo(() => {
    const inCalls = anchors.filter(isCallRow);
    return inCalls.length === 0 ? items : mergeAnchorRows(items, inCalls);
  }, [items, anchors]);
  const verdicts = useMemo(
    () => collectVerdicts(transcriptRows),
    [transcriptRows],
  );
  // Memoized so the set is referentially stable across composer keystrokes —
  // a fresh Set per render would re-render every memoized row shell below.
  const cardBacked = useMemo(
    () => cardBackedRequestIds(transcriptRows),
    [transcriptRows],
  );
  // Which requests died with their turn. READ from the transcript, never
  // inferred from it: the renderer used to reconstruct this by scanning for a
  // later terminal item with a matching callId, which could not tell a callee
  // sub-turn settling from the node's own turn ending, and saw nothing at all
  // for a turn that failed before it started. The daemon knows both.
  const unanswerableIds = useMemo(
    () => unanswerableRequestIds(transcriptRows),
    [transcriptRows],
  );
  /**
   * The agents holding an approval card nobody has answered yet.
   *
   * The SAME three exclusions the card itself renders with (a persisted
   * verdict, a request its turn took down with it, a verdict_ack that came
   * back dead) — read from the one place they already live rather than
   * re-derived, so a card that shows as answered can never still count as
   * waiting here.
   */
  const openRequestId = useLatestCallback(
    (item: ChatItem): string | null => {
      if (item.kind !== 'approval_request') {
        return null;
      }
      const id = payloadString(item.payload, 'id');
      if (
        id === null ||
        verdicts.has(id) ||
        unanswerableIds.has(id) ||
        deadRequestKeys.has(`${item.runId}:${id}`)
      ) {
        return null;
      }
      return id;
    },
    [verdicts, unanswerableIds, deadRequestKeys],
  );
  /**
   * What the open run holds AS A WHOLE, from the daemon — its open cards, calls,
   * delegates, commands and teams. Every readout below that is not the
   * transcript's own rows reads it, with the window's own reading winning where
   * it holds the same thing (`use-run-state.ts`).
   */
  const { state: runState, refresh: refreshRunState } = useRunState(
    chatApi,
    client,
    activeRunId,
    reconnectNonce,
  );
  const pressRaisedWorkingRef = useRef(false);
  const beforeHostedPress = useLatestCallback(
    async (action: LiveAction): Promise<void> => {
      if (pressStartsTurn(action)) {
        pressRaisedWorkingRef.current = await startHostedTurn(
          activeRunIdRef.current,
        );
        return;
      }
      await hostedRef.current?.onBeforeSend?.();
    },
    [startHostedTurn],
  );
  const hostedPressSettled = useLatestCallback(
    (taken: boolean, action: LiveAction): void => {
      if (!pressStartsTurn(action)) {
        return;
      }
      if (pressRaisedWorkingRef.current && !taken) {
        refuseHostedTurn();
      }
      pressRaisedWorkingRef.current = false;
    },
    [refuseHostedTurn],
  );
  const pressHooks: PressHooks | undefined = isHosted
    ? { beforePress: beforeHostedPress, onPressSettled: hostedPressSettled }
    : undefined;
  /** The agents' buttons on this chat, and their press — see `useChatActions`. */
  const pressableActions = useChatActions(
    activeTeamId === null ? chatApi : teamApi,
    activeRunId,
    runState,
    refreshRunState,
    pressHooks,
  );
  /**
   * The card rows to read open requests from: the window's, and every card the
   * daemon still holds open that the window does not — a question asked above
   * the loaded page is still a question, and still the one the turn waits on.
   */
  const requestRows = useMemo(
    () =>
      // Off the tail the window is HISTORY: a card in it may have been answered
      // by a verdict below the page, so only the daemon can say what is open.
      awayFromTail
        ? runState.openRequests
        : withAnchors(items, runState.openRequests),
    [items, runState.openRequests, awayFromTail],
  );
  const awaitingAnswer = useMemo(() => {
    const keys = new Set<string>();
    for (const item of requestRows) {
      if (openRequestId(item) === null) {
        continue;
      }
      // A team proposal's card stands across turns, so while one runs the
      // agent is working, not waiting on it — the daemon's `awaiting` reads it
      // the same way. Counted here, every turn beside it read as blocked.
      if (
        streaming &&
        standsAcrossTurns(payloadString(item.payload, 'toolName'))
      ) {
        continue;
      }
      keys.add(liveTextKey(item.memberId));
    }
    return keys;
  }, [requestRows, openRequestId, streaming]);
  /**
   * EVERY open request, oldest first — lifted OUT of the transcript so none of
   * them can scroll away.
   *
   * A card rendered in transcript order scrolls away like any other row, so a
   * long turn leaves the agent parked on a question the user cannot see —
   * "it is waiting for an answer but the block is hanging somewhere above".
   * Worse, nothing on screen then explains why the run has gone quiet.
   *
   * EVERY open request is lifted out, not just the pinned one. A team run
   * can have two nodes asking at once, and leaving the others in transcript
   * order gave the older one a fully live card that scrolled away — the exact
   * failure the pin was built to end, reintroduced for every question but the
   * newest. The transcript leaves a marker in each slot instead of a second
   * live copy, because two sets of buttons over one one-shot verdict channel is
   * a race the card cannot win.
   *
   * Derived from the persisted items, so it survives a chat switch and a
   * reload the same way the transcript does.
   */
  const openRequests = useMemo(
    () => requestRows.filter((item) => openRequestId(item) !== null),
    [requestRows, openRequestId],
  );
  /**
   * The one shown: the NEWEST, which is what the turn is actually blocked on.
   *
   * The others stay MOUNTED and hidden rather than being unrendered, which is
   * what keeps a half-typed answer alive when a newer question takes the pin.
   * Unmounting resets the card's picks, its typed text and every staged
   * attachment — and the user has no way to get any of it back.
   */
  const pinnedRequest = openRequests.at(-1) ?? null;
  /**
   * ONE card builder for both placements — the pinned slot and the settled
   * transcript row. The two differ only in WHERE they hang, and a second copy
   * of this JSX is how the pinned card would come to accept an answer the
   * transcript row could not show.
   */
  const approvalCardFor = useLatestCallback(
    (item: ChatItem): React.JSX.Element => {
      const requestId = payloadString(item.payload, 'id');
      const settled = requestId ? (verdicts.get(requestId) ?? null) : null;
      return (
        <ApprovalCard
          toolName={payloadString(item.payload, 'toolName') ?? 'tool'}
          input={(item.payload as { input?: unknown } | null)?.input ?? null}
          questions={
            (item.payload as { questions?: unknown } | null)?.questions
          }
          options={(item.payload as { options?: unknown } | null)?.options}
          requestId={requestId}
          threadTitle={payloadString(item.payload, 'threadTitle')}
          threadText={payloadString(item.payload, 'threadText')}
          verdict={settled?.allow ?? null}
          verdictOption={settled?.optionLabel ?? null}
          // The user's own words, read back from the SAME item that settled the
          // card — so a card can never show an answer the transcript does not
          // hold, and a replayed transcript reads exactly like the live one.
          answer={settled?.answer ?? null}
          outcome={settled?.outcome ?? null}
          onOpenTeam={onOpenTeam}
          onOpenProject={onOpenProject}
          expired={
            requestId !== null &&
            (unanswerableIds.has(requestId) ||
              // A DIFFERENT plane, deliberately kept: the live verdict_ack
              // round-trip, which is what corrects a card the daemon never got
              // to annotate.
              deadRequestKeys.has(`${item.runId}:${requestId}`))
          }
          onRespond={(allow, answer, images, optionId) =>
            respondApproval(item, allow, answer, images, optionId)
          }
        />
      );
    },
    [
      verdicts,
      unanswerableIds,
      deadRequestKeys,
      respondApproval,
      onOpenTeam,
      onOpenProject,
    ],
  );

  const activeRun = runs.find((run) => run.id === activeRunId) ?? null;

  useEffect(() => {
    hostedRef.current?.onWorkingChange?.(streaming);
  }, [streaming]);
  const hostedAwaiting = activeRun?.awaiting ?? null;
  useEffect(() => {
    hostedRef.current?.onAwaitingChange?.(hostedAwaiting);
  }, [hostedAwaiting]);
  // A turn whose ending reached this screen only as a replay (the socket was
  // down when it ended) is reported when the working state comes down.
  const wasStreamingRef = useRef(streaming);
  useEffect(() => {
    if (streaming) {
      turnEndReportedRef.current = false;
    } else if (wasStreamingRef.current && !turnEndReportedRef.current) {
      turnEndReportedRef.current = true;
      void hostedRef.current?.onTurnSettled?.();
    }
    wasStreamingRef.current = streaming;
  }, [streaming]);
  const initialDraftUsedRef = useRef(false);
  useEffect(() => {
    const initial = hostedRef.current?.initialDraft ?? '';
    if (activeRunId === null || initialDraftUsedRef.current) {
      return;
    }
    initialDraftUsedRef.current = true;
    if (initial !== '' && composerText.get() === '') {
      setInput(initial);
    }
  }, [activeRunId, composerText, setInput]);
  // A hosted surface shows one conversation; a queue left under any other run
  // (one thrown away, an analysis replaced) can never be drawn or sent.
  const { forgetRun, queues: queuedByRun } = messageQueue;
  useEffect(() => {
    if (!isHosted || activeRunId === null) {
      return;
    }
    for (const runId of Object.keys(queuedByRun)) {
      if (runId !== activeRunId) {
        forgetRun(runId);
      }
    }
  }, [isHosted, activeRunId, queuedByRun, forgetRun]);
  const discardHosted = useLatestCallback((): void => {
    const discard = hostedRef.current?.discard;
    if (discard === undefined) {
      return;
    }
    deactivateRun();
    void discard()
      .then(refreshRuns)
      .catch((err: unknown) => setError(describeDaemonError(err)));
  }, [deactivateRun, refreshRuns, setError]);
  // The open thread's analysis, for its Analyze button — see `useThreadAnalysis`.
  const analysisMark = useThreadAnalysis({
    chatApi,
    client,
    sourceRunId: activeRun && !isAnalysisRun(activeRun) ? activeRun.id : null,
    refreshKey: analysisGeneration,
  });
  // The open thread's lessons state, for its Reflect now button.
  const lessonsMark = useThreadLessons({
    lessonsApi: apis.lessons,
    client,
    sourceRunId: activeRun && !isAnalysisRun(activeRun) ? activeRun.id : null,
    refreshKey: lessonsGeneration,
  });
  // The repository a TASK run's worktree was cut from, for the header chip —
  // asked only for a task's run, whose folder geniro named by the task's id.
  const taskWorktreeOf = useWorktreeOrigin(
    activeRun?.taskId != null ? activeRun.cwd : null,
  );
  /**
   * The daemon's own per-node context readings for a TEAM run — the source
   * that made `NodeState.contextTokens` reach a client at all.
   *
   * Asked on open and on reconnect; everything in between arrives as a live
   * delta, which outranks it. See {@link useNodeDurableReadings}.
   */
  // How many turns the loaded window has seen settle — it moves once per turn,
  // which is exactly when a node's SPEND totals change.
  const settledTurnCount = useMemo(
    () =>
      transcriptRows.reduce(
        (n, item) => (item.kind === 'turn_complete' ? n + 1 : n),
        0,
      ),
    [transcriptRows],
  );
  const [nodeReadingsNonce, setNodeReadingsNonce] = useState(0);
  const nodeReadings = useNodeDurableReadings(
    activeRunId,
    activeRun?.teamId != null,
    teamApi,
    reconnectNonce,
    settledTurnCount,
    client,
    nodeReadingsNonce,
  );
  const setOwnPoolMember = useLatestCallback(
    async (
      memberId: string,
      member: number,
    ): Promise<SetPoolMemberResultDto> => {
      if (activeRunId === null) {
        throw new Error('no run is open');
      }
      const answer = await teamApi.setTeamRunPoolMember({
        runId: activeRunId,
        memberId,
        setTeamRunPoolMemberDto: { member },
      });
      setNodeReadingsNonce((nonce) => nonce + 1);
      return answer;
    },
    [activeRunId, teamApi],
  );
  /**
   * The same two ranks, handed to every call block in the transcript.
   *
   * A block can fold only its callee's SETTLED turns, so without this its ring
   * is empty for the whole of a call and fills at the settle — REPORTED against
   * a running cursor call. See `CalleeContextResolverContext` for why it travels
   * as a context, and `ChatProviders` for why it is provided there.
   */
  /**
   * What each call's start row said, from the daemon's own record — the brief,
   * title and caller a call card is drawn with. The loaded window routinely
   * begins after a long call started, and the card rebuilt from its later rows
   * otherwise named only the callee: REPORTED as an "Engineer" card with no
   * caller and no calls.
   */
  const callStarts = useMemo(() => {
    const starts = new Map<string, CallStartReading>();
    for (const reading of nodeReadings.values()) {
      for (const call of reading.calls) {
        if (call.start !== null) {
          starts.set(call.callId, call.start);
        }
      }
    }
    return starts;
  }, [nodeReadings]);
  /**
   * The window with its anchors laid in — what every STRUCTURAL fold reads:
   * the transcript's cards, the agents' activity, the dynamic-workflow cards.
   * The window alone is still what pages and what is drawn row by row; an
   * anchor only ever builds the card it belongs to (`history-anchors.ts`).
   */
  const { foldItems, entries: durableEntries } = useDurableTranscript({
    delegateState: runState,
    items,
    anchors,
    runId: activeRun?.id ?? null,
    // The daemon's task list is an input too. It is folded and broadcast AFTER
    // the item that moved it, so keyed on `items` alone the latest card kept the
    // previous list's rows until some unrelated item arrived.
    taskList: activeRun?.taskList,
    collapseToolSteps,
  });
  const ownToolSeqs = useMemo(
    () => ownToolCallSeqsByCall(transcriptRows),
    [transcriptRows],
  );
  const callClocks = useMemo(
    () => continueCallClocks(durableCallClocks(nodeReadings), transcriptRows),
    [nodeReadings, transcriptRows],
  );
  const resolveCallReading = useLatestCallback(
    (calleeMemberId: string, callIds: readonly string[]): CalleeReading => ({
      ...resolveConversationContext(
        liveText,
        nodeReadings,
        calleeMemberId,
        callIds,
      ),
      spend: resolveConversationSpend(nodeReadings, calleeMemberId, callIds),
      liveCost: liveConversationCost(liveText, calleeMemberId, callIds),
      toolCalls: resolveConversationToolCalls(
        nodeReadings,
        calleeMemberId,
        callIds,
        ownToolSeqs,
      ),
      clocks: conversationClocks(callClocks, callIds),
    }),
    [liveText, nodeReadings, ownToolSeqs, callClocks],
  );
  /**
   * The direct line to a running call's callee, past the agent that called it.
   * Team runs only — a chat holds no calls. The queues live here, above
   * every call block, so folding a card does not lose what is waiting.
   */
  const activeTeamRunId = activeRun?.teamId != null ? activeRun.id : null;
  const sendCallMessage = useLatestCallback(
    async (
      target: CallTarget,
      text: string,
      images: SendMessageDtoImagesInner[],
      clientMessageId: string,
    ): Promise<void> => {
      const userItem = await teamApi.sendTeamCallMessage({
        runId: target.runId,
        memberId: target.memberId,
        callId: target.callId,
        sendMessageDto: {
          text,
          clientMessageId,
          ...(images.length > 0 ? { images } : {}),
        },
      });
      addItem(userItem, true);
    },
    [teamApi, addItem],
  );
  const callQueues = useCallMessageQueues(sendCallMessage);
  const callChannel = useMemo((): CallMessageChannel | null => {
    if (activeTeamRunId === null) {
      return null;
    }
    return {
      runId: activeTeamRunId,
      queues: callQueues,
      followUpOf: (agent) => {
        if (!capabilities) {
          return null;
        }
        if (agent === null) {
          return {
            unavailableReason:
              'This team no longer says which CLI runs this agent',
            interrupts: false,
          };
        }
        return capabilities.followUps.find((f) => f.agent === agent) ?? null;
      },
    };
  }, [activeTeamRunId, callQueues, capabilities]);
  // User messages a turn accepted and then dropped because it ended before
  // the agent took them, each drawn "not sent" with a Resend.
  const notSentIds = useMemo(
    () => notSentDeliveryIds(transcriptRows),
    [transcriptRows],
  );
  // The rows the call cards are folded from: a call's `call_started` can be an
  // anchor from before the loaded window.
  const foldItemsRef = useRef(foldItems);
  foldItemsRef.current = foldItems;
  /** A dropped message's words and pictures, read back from its own row. */
  const unsentContent = useLatestCallback(
    (item: ChatItem) => unsentMessageContent(item, loadAttachment),
    [loadAttachment],
  );
  const resendNotSent = useLatestCallback(
    (item: ChatItem): void => {
      const runId = item.runId;
      void unsentContent(item)
        .then(({ text, images }) => {
          // A message to ONE callee goes back to that callee's call, never to
          // the agents the run's trigger feeds.
          const call = callTargetOf(item, foldItemsRef.current);
          if (call === null) {
            throw new Error(
              'This message was for a call that is no longer on screen — send it from that call.',
            );
          }
          if (call !== 'run') {
            callQueues.enqueue(call, text, images);
            void callQueues.drain(call);
            return;
          }
          enqueueMessage(runId, { text, images, clientMessageId: randomId() });
          // The kick `sendFollowUp` would make for a message typed now: not
          // while the agent is working, whose turn end drains the queue anyway.
          // Read at this moment, after the pictures loaded, from the refs.
          const decision = followUpDelivery({
            streaming: activeRunIdRef.current === runId && streamingRef.current,
            queued: true,
            held: holdingRef.current.has(runId),
            awaitingCalls: awaitingCallsRef.current.has(runId),
            rootsIdle: rootsIdleRef.current.has(runId),
            subagentsOut: delegatesOutRef.current.has(runId),
            shellsOut: shellsOutRef.current.has(runId),
          });
          if (decision.action !== 'queue' || decision.kickDrain) {
            drainQueueRef.current(runId);
          }
        })
        .catch((err: unknown) => {
          if (activeRunIdRef.current === runId) {
            setError(describeDaemonError(err));
          }
        });
    },
    [unsentContent, callQueues, enqueueMessage],
  );
  const notSent = useMemo(
    () => ({ unsent: notSentIds, resend: resendNotSent }),
    [notSentIds, resendNotSent],
  );
  // A drop that happens NOW also puts the words back in the composer — only
  // into an empty one, which `restoreUnsent` already guarantees. A message to a
  // callee is left to its own row: the composer would send it to the trigger.
  // Each live marker waits for the render holding its rows (it can arrive in
  // the same batch as the message it names), is restored once, and is dropped
  // with its thread.
  const [liveUnsent, setLiveUnsent] = useState<
    readonly { rowId: string; runId: string; deliveryIds: string[] }[]
  >([]);
  onLiveUnsentRef.current = (
    runId: string,
    deliveryIds: string[],
    rowId: string,
  ): void => {
    setLiveUnsent((pending) =>
      pending.some((entry) => entry.rowId === rowId)
        ? pending
        : [...pending, { rowId, runId, deliveryIds }],
    );
  };
  useEffect(() => {
    if (liveUnsent.length === 0) {
      return;
    }
    const resolved: string[] = [];
    for (const entry of liveUnsent) {
      if (entry.runId !== activeRunId) {
        resolved.push(entry.rowId);
        continue;
      }
      const dropped = transcriptRows.filter((row) => {
        const id = userDeliveryId(row);
        return (
          id !== null &&
          entry.deliveryIds.includes(id) &&
          payloadString(row.payload, 'callId') === null
        );
      });
      if (dropped.length === 0) {
        continue;
      }
      resolved.push(entry.rowId);
      const { runId } = entry;
      void Promise.all(dropped.map(unsentContent))
        .then((contents) => {
          restoreUnsent(
            runId,
            contents.map((content) => content.text).join('\n\n'),
            contents.flatMap((content) =>
              content.images.map((image) => stagedFrom(image, runId)),
            ),
          );
        })
        .catch((err: unknown) => {
          // The row still says "not sent" and offers Resend.
          reportRendererIssue('could not restore a message that was not sent', {
            runId,
            error: String(err),
          });
        });
    }
    if (resolved.length > 0) {
      setLiveUnsent((pending) =>
        pending.filter((entry) => !resolved.includes(entry.rowId)),
      );
    }
  }, [liveUnsent, activeRunId, transcriptRows, unsentContent, restoreUnsent]);
  /**
   * The open thread is shelved, so its composer is inert.
   *
   * Read off the ROW rather than off `chatScope`: the scope says what the list
   * covers, and the question here is about this one conversation — under
   * `Show all` the two are listed side by side. The
   * daemon refuses the send either way (`RUN_ARCHIVED`), and a composer that
   * accepted text only to have it bounced is the shape this exists to avoid.
   */
  const activeRunArchived = activeRun?.archivedAt != null;

  /**
   * What each thread OPENED, as GitHub currently has it — the only pull
   * requests any chat surface draws.
   *
   * Addressed by URL off the run row the daemon captured them onto, so they
   * survive a branch switch and span repositories. What is merely open on the
   * branch a folder sits on is NOT listed: it is not this conversation's work,
   * and listing it beside these put the thread's own pull request on the panel
   * twice.
   */
  const { byKey: resolvedThreadPullRequests } = useThreadPullRequests(runs);
  const openedByActiveThread = useMemo(
    () => threadPullRequestsOf(activeRun ?? null, resolvedThreadPullRequests),
    [activeRun, resolvedThreadPullRequests],
  );

  // ONE read of the run's folder and the worktrees its agents worked in,
  // feeding the header's changes chip AND the dialog behind it. Kept here
  // rather than inside the dialog because the chip states the figures without
  // anything being opened — see `useChatChanges`.
  const workFolders = useRunWorkFolders(
    chatApi,
    activeRunId,
    activeRun?.cwd ?? null,
    activeRun?.createdAt ?? null,
    streaming,
  );
  const chatChanges = useChatChanges(
    activeRun?.cwd ?? null,
    activeRun?.startSha ?? null,
    workFolders,
    changesPullRequestsOf(openedByActiveThread),
  );
  const refreshChatChanges = chatChanges.refresh;
  // What the DIALOG asks for when it opens: past the freshness floor, because
  // the reader is looking at it now — which is exactly the distinction the floor
  // exists to draw against the ambient turn-settle refresh below.
  const readChangesNow = useLatestCallback(
    (): void => refreshChatChanges(true),
    [refreshChatChanges],
  );

  // A turn ENDING is the moment the folder can have changed — it is what the
  // agent was doing. Bounded by the hook's own freshness floor, so a thread
  // settling several turns a minute (a delegate reporting back opens a
  // continuation turn of its own) does not spend its life running `git diff`.
  useEffect(() => {
    if (!streaming) {
      refreshChatChanges();
    }
  }, [streaming, refreshChatChanges]);

  /** Each of the open thread's pull requests' newest recorded outcome. */
  // Keyed on the list and GitHub's answers alone, never `activeRun`: a
  // run-status announce that carries no list keeps its reference, and a fresh
  // value here re-renders every transcript row.
  const activeRunPullRequests = activeRun?.pullRequests;
  const activeRunOutcomes = useMemo(
    () =>
      runOutcomesOf(
        activeRunPullRequests,
        threadPullRequestsOf(
          { pullRequests: activeRunPullRequests },
          resolvedThreadPullRequests,
        ),
      ),
    [activeRunPullRequests, resolvedThreadPullRequests],
  );
  /** The ONE pull request each sidebar row names ({@link rowPullRequestOf}). */
  const rowPullRequestByRun = useMemo(() => {
    const byRun = new Map<string, PullRequestInfo>();
    for (const run of runs) {
      const pullRequest = rowPullRequestOf(run, resolvedThreadPullRequests);
      if (pullRequest !== null) {
        byRun.set(run.id, pullRequest);
      }
    }
    return byRun;
  }, [runs, resolvedThreadPullRequests]);

  // Push the open thread's name up to the shell's title bar. An effect rather
  // than a render-time call because it writes to a parent's state, and it runs
  // on the LABEL rather than on the run object so a rename re-reports without
  // waiting for anything else about the run to change.
  const activeLabel = activeRun ? runLabel(activeRun, teamNames) : null;
  useEffect(() => {
    onTitleChange?.(activeLabel);
  }, [activeLabel, onTitleChange]);
  /**
   * Is there anything to send? An attached image is a complete message on its
   * own ("what's wrong with this?" is carried by the screenshot), so gating the
   * send buttons on typed text alone would stage a paste that can never leave.
   */
  const hasText = useComposerTextFact(
    composerText,
    (text) => text.trim().length > 0,
  );
  const hasContent = hasText || attachments.attachments.length > 0;

  /** The open transcript's pending queue (queues persist per run). */
  const queued = activeRunId ? (queues[activeRunId] ?? []) : [];
  // The active team's node inventory: its agent nodes (the agents panel),
  // its triggers (the run composer's inactive info chips), and every node id
  // it knows (so trigger status items are never mistaken for an unknown
  // agent's). Filled by the snapshot effect further down; declared here
  // because the `/` autocomplete below reads it.
  const [wfNodes, setWfNodes] = useState<{
    agents: TeamMember[];
    triggers: RunTrigger[];
    allIds: Set<string>;
    /**
     * The member the trigger names — the one the run is a conversation WITH,
     * so its rows need no identity (see {@link rootAgentOf}).
     */
    rootId: string | null;
    /** Whether the run's team hands stages between their leads. */
    relay: boolean;
  }>({
    agents: [],
    triggers: [],
    allIds: new Set(),
    rootId: null,
    relay: false,
  });
  /**
   * The member a message written into the open team run goes to now — the
   * run's lead (see {@link runLeadOf}); null for a chat and until the run's
   * snapshot has loaded.
   */
  const runLead = activeRun?.teamId
    ? runLeadOf(activeRun.currentLead, wfNodes.allIds, wfNodes.rootId)
    : null;
  /** A relay run's lead by name — what the shelf chip and the placeholder say; null otherwise. */
  const relayLeadName =
    wfNodes.relay && runLead !== null
      ? (wfNodes.agents.find((agent) => agent.id === runLead)?.name ?? runLead)
      : null;
  const feedIds = useMemo(
    (): string[] => (runLead === null ? [] : [runLead]),
    [runLead],
  );
  /**
   * The member a message written into the open TEAM run lands in — the run's
   * current lead, which the daemon's `deliverFollowUp` hands it to. Empty for
   * a chat, and until the run's snapshot has loaded.
   */
  const teamFeedAgents = useMemo((): TeamMember[] => {
    const fed = new Set(feedIds);
    return wfNodes.agents.filter((node) => fed.has(node.id));
  }, [wfNodes, feedIds]);
  // ── The composer's `/` skill autocomplete ──────────────────────────────
  // Which agents the current composer's message reaches, under which account,
  // and in which folder. A new-run team target resolves through its
  // SELECTED trigger (the run prompt is delivered to the agents that trigger
  // feeds). An OPEN team run asks about the agents a follow-up lands in,
  // each under its own node's profile: its composer takes messages, and it
  // answered no agents at all for as long as it had been disabled — REPORTED
  // as a Dev Team thread offering no `/` suggestions while the Manager ran
  // `/geniro:resolve` perfectly well.
  const skillTargets = useMemo((): SkillTarget[] => {
    if (activeRunId !== null) {
      if (!activeRun) {
        return [];
      }
      if (activeRun.teamId !== null) {
        return teamFeedAgents.map((node) => ({
          kind: node.agent,
          configDir: node.configDir ?? null,
        }));
      }
      return activeRun.agentKind
        ? [{ kind: activeRun.agentKind, configDir: activeRun.configDir }]
        : [];
    }
    if (teamSlug) {
      // Null: a library trigger lists only its agents' kinds, not profiles.
      return (
        triggers.find((entry) => entry.id === triggerId)?.agentKinds ?? []
      ).map((kind) => ({ kind, configDir: null }));
    }
    return [{ kind: agentKind, configDir }];
  }, [
    activeRunId,
    activeRun,
    teamFeedAgents,
    teamSlug,
    triggers,
    triggerId,
    agentKind,
    configDir,
  ]);
  /**
   * The ACCOUNT every vocabulary on this screen is about, scoped exactly like
   * `modelKind` and `effortModel`: whichever composer is on screen owns the
   * answer, since only one is.
   *
   * It exists because each of those listings — the models, the levels, the
   * windows, the parameters, and the `/` skills — is a fact about a
   * SUBSCRIPTION, and the subscription is the config directory. Asked without
   * it, the first profile to load its answer had that account's vocabulary
   * cached under the CLI's name and served to every chat afterwards. Null for a
   * team target, whose nodes each name their own profile in the YAML.
   */
  const vocabularyConfigDir = useMemo((): string | null => {
    if (activeRunId !== null) {
      return activeRun && activeRun.teamId === null
        ? activeRun.configDir
        : null;
    }
    return teamSlug ? null : configDir;
  }, [activeRunId, activeRun, teamSlug, configDir]);
  const skillCwd = activeRunId !== null ? (activeRun?.cwd ?? null) : folder;
  const skillQuery = useComposerTextFact(composerText, slashQuery);
  const skills = useAgentSkills(
    agentsApi,
    skillTargets,
    skillCwd,
    // Refreshed as the `/` popup opens, so it never shows a stale first read.
    skillQuery !== null,
  );
  // Assigned during render rather than from an effect: the two send paths read
  // it in a click handler, which cannot run before the render that produced
  // this list has committed.
  skillsRef.current = skills;
  // The model rows come from the CLI itself — never a list baked into the app.
  // Which CLI to ask follows whichever composer is on screen: an open chat's
  // own agent, or the agent the next run would start (none for a team,
  // whose nodes each name their model in the YAML).
  const modelKind = useMemo((): CliKind | null => {
    if (activeRunId !== null) {
      return activeRun && activeRun.teamId === null
        ? activeRun.agentKind
        : null;
    }
    return teamSlug ? null : agentKind;
  }, [activeRunId, activeRun, teamSlug, agentKind]);
  /**
   * The MODEL the effort listing is about, scoped exactly like `modelKind`:
   * whichever composer is on screen owns the answer, since only one is.
   *
   * It exists because the levels belong to the model and not to the CLI — a
   * cursor chat on `grok-4.6` has no `max`, one on `claude-opus-5` does — so a
   * listing asked without it offers levels the chosen model refuses. Null is a
   * real value here (no model picked, or a team target) and the daemon
   * answers it with the CLI-wide union.
   */
  const effortModel = useMemo((): string | null => {
    if (activeRunId !== null) {
      return activeRun && activeRun.teamId === null ? activeRun.model : null;
    }
    return teamSlug ? null : (models[agentKind] ?? null);
  }, [activeRunId, activeRun, teamSlug, models, agentKind]);
  // After `effortModel`, so the model list is asked in the same request as the
  // three listings below (`requestAgentVocabulary`).
  const { models: agentModels, loading: agentModelsLoading } = useAgentModels(
    agentsApi,
    modelKind,
    vocabularyConfigDir,
    effortModel,
  );
  // Same scoping as the models above — whichever CLI the visible composer is
  // about, or none at all for a team target — narrowed to that composer's
  // own model, which is what makes the chip offer only what will apply.
  const agentEfforts = useAgentEfforts(
    agentsApi,
    modelKind,
    effortModel,
    vocabularyConfigDir,
  );
  // The window sizes THIS composer's model offers, scoped exactly like the
  // effort listing above and for a stronger version of the same reason: twelve
  // of a cursor account's models carry the axis at all and their vocabularies
  // differ, so a listing asked without the model has nothing to answer with.
  const agentContextWindows = useAgentContextWindows(
    agentsApi,
    modelKind,
    effortModel,
    vocabularyConfigDir,
  );
  // And everything those two do not cover, scoped identically — the set of
  // chips itself is the model's answer here, not just their contents.
  const agentModelParameters = useAgentModelParameters(
    agentsApi,
    modelKind,
    effortModel,
    vocabularyConfigDir,
  );
  /**
   * Whether the three listings above are still on their way, as ONE flag: they
   * are one question to the user — what can this model be run with — and the
   * daemon answers all three from a single `cursor-agent acp` handshake, so
   * they arrive together anyway.
   */
  const modelSettingsLoading =
    agentEfforts.loading ||
    agentContextWindows.loading ||
    agentModelParameters.loading;
  // ONE git read: the landing composer's, following the folder picked for the
  // NEXT run — the only place a branch is chosen. The transcript composer used
  // to run a second read for a read-only branch chip beside its own cwd; that
  // chip is gone, and keeping the read alive would mean an IPC call per run
  // whose only surviving effect was an error strip about a control nobody sees.
  const git = useGitInfo(folder);

  /**
   * Press a fast action: write its description into the message box.
   *
   * That is the whole of it — nothing is sent, and no chip moves. An action
   * carries no folder and no agent precisely so that it works under whatever
   * the composer is already set to; a press that also re-pointed the run would
   * make the button a second, invisible source of the setup and silently undo
   * choices the user had just made by hand.
   *
   * Appended rather than substituted when the box already holds text: what is
   * there is the user's own typing, and a button that eats it is a button
   * nobody presses twice. A blank line between them, so two actions pressed in
   * a row read as two instructions rather than one run-on sentence.
   */
  const insertFastAction = useLatestCallback((action: FastAction): void => {
    setInput((current) => appendDraft(current, action.description));
    // A COUNTER rather than a direct focus call: the caret belongs at the end
    // of the text this press just added, and the textarea's DOM value is still
    // the old one until React commits. The effect below runs after that.
    setFastActionPresses((n) => n + 1);
  }, []);

  /**
   * Put the cursor back where the user types, after a fast action wrote into
   * it. Skipped on mount — `0` is "no action has been pressed", and stealing
   * focus on arrival would scroll the new-chat screen to the composer before
   * the user has looked at anything.
   */
  useEffect(() => {
    if (fastActionPresses === 0) {
      return;
    }
    const field = newChatInputRef.current;
    if (field === null) {
      return;
    }
    field.focus();
    field.setSelectionRange(field.value.length, field.value.length);
  }, [fastActionPresses]);

  /**
   * Write the configuration list, rolling back the screen if the write fails.
   *
   * Straight to `window.geniro.updateSettings` and NOT through any helper that
   * swallows a rejection: the whole patch is refused as one, so a screen that
   * kept showing an entry settings.json does not have would then fail every
   * later save on that same entry.
   */
  const persistRunConfigs = useLatestCallback(
    (next: RunConfig[], previous: RunConfig[]): void => {
      setRunConfigs(next);
      void window.geniro.updateSettings({ runConfigs: next }).catch(() => {
        setRunConfigs(previous);
        setError(
          'Could not save that configuration — your other settings are unchanged. Try a shorter name, or remove one you no longer use.',
        );
      });
    },
    [setError],
  );

  const saveRunConfig = useLatestCallback(
    (draft: RunConfigDraft, id: string | null): void => {
      persistRunConfigs(upsertRunConfig(runConfigs, draft, id), runConfigs);
    },
    [runConfigs, persistRunConfigs],
  );

  const deleteRunConfig = useLatestCallback(
    (id: string): void => {
      persistRunConfigs(
        runConfigs.filter((c) => c.id !== id),
        runConfigs,
      );
    },
    [runConfigs, persistRunConfigs],
  );

  const reorderRunConfigs = useLatestCallback(
    (next: RunConfig[]): void => persistRunConfigs(next, runConfigs),
    [runConfigs, persistRunConfigs],
  );

  /**
   * The configuration the composer currently describes, so "new" opens on what
   * the user is already looking at rather than on a blank form. Null without a
   * folder: a configuration with no cwd is not one this app can start.
   */
  const captureCurrentRunConfig = useLatestCallback(
    (name: string): RunConfigDraft | null =>
      folder === null
        ? null
        : captureRunConfig({
            name,
            target,
            cwd: folder,
            branch: git.info?.branch ?? null,
            configDir,
            models,
            efforts,
            contextWindows,
            modelParameters,
            approval: approvalMode,
            projectId: composerProject.projectId,
          }),
    [
      composerProject,
      folder,
      target,
      git.info,
      configDir,
      models,
      efforts,
      contextWindows,
      modelParameters,
      approvalMode,
    ],
  );

  const rememberModelParameters = useLatestCallback(
    (kind: CliKind, parameters: Record<string, string>): void => {
      setModelParameters((current) => {
        const next = { ...current };
        if (Object.keys(parameters).length === 0) {
          delete next[kind];
        } else {
          next[kind] = parameters;
        }
        void window.geniro.updateSettings({ lastModelParameters: next });
        return next;
      });
    },
    [],
  );

  /**
   * Select an applied configuration's target and every setting it holds. A
   * team says NOTHING about any CLI's model, effort or profile — its nodes
   * each name their own. These setters PERSIST and `null` through them DELETES
   * the remembered entry, so writing the blanks a team reports would erase the
   * user's own claude choices.
   */
  const seedComposerTarget = useLatestCallback(
    (seed: ProjectTargetSeed): void => {
      changeTarget(seed.target);
      if (seed.isTeam) {
        return;
      }
      chooseConfigDir(seed.agentKind, seed.configDir);
      if (seed.approval !== null) {
        changeApprovalMode(seed.approval);
      }
      changeModel(seed.agentKind, seed.model);
      changeEffort(seed.agentKind, seed.effort);
      changeContextWindow(seed.agentKind, seed.contextWindow);
      // Written WHOLE rather than per parameter: the configuration is the
      // answer for this CLI, so a setting it does not name is one the user
      // deliberately left at the model's default — and merging would leave
      // whatever the composer happened to be carrying from the last chat.
      rememberModelParameters(seed.agentKind, seed.modelParameters);
    },
    [
      changeTarget,
      chooseConfigDir,
      changeApprovalMode,
      changeModel,
      changeEffort,
      changeContextWindow,
      rememberModelParameters,
    ],
  );

  /**
   * Preselect a picked project's default target. Unlike a configuration, a
   * project leaves most settings unnamed to mean "inherit", so only what it
   * names is written and the user's remembered choices stay otherwise.
   */
  const seedProjectTarget = useLatestCallback(
    (project: ProjectTargetRef): void => {
      const seed = projectTargetSeed(project);
      if (seed === null) {
        return;
      }
      changeTarget(seed.target);
      if (seed.isTeam) {
        return;
      }
      if (seed.configDir !== null) {
        chooseConfigDir(seed.agentKind, seed.configDir);
      }
      if (seed.approval !== null) {
        changeApprovalMode(seed.approval);
      }
      if (seed.model !== null) {
        changeModel(seed.agentKind, seed.model);
      }
      if (seed.effort !== null) {
        changeEffort(seed.agentKind, seed.effort);
      }
      if (seed.contextWindow !== null) {
        changeContextWindow(seed.agentKind, seed.contextWindow);
      }
      if (Object.keys(seed.modelParameters).length > 0) {
        rememberModelParameters(seed.agentKind, seed.modelParameters);
      }
    },
    [
      changeTarget,
      chooseConfigDir,
      changeApprovalMode,
      changeModel,
      changeEffort,
      changeContextWindow,
      rememberModelParameters,
    ],
  );

  /**
   * Start the new-chat screen from a saved configuration: seed every chip it
   * names, then take the folder to its branch.
   *
   * It SEEDS rather than creating a run, which is the whole distinction from a
   * fast action beside it — a configuration answers "where and with what",
   * leaving the user to write the message, while an action answers "what do I
   * say" and leaves the setup alone. Neither is the other, and folding them
   * together is what deleted this feature once already.
   */
  const applyRunConfigToComposer = useLatestCallback(
    async (config: RunConfig): Promise<void> => {
      const applied = applyRunConfig(config);
      if (applied === null) {
        setError(
          `“${config.name}” starts ${config.target}, which this version cannot run. Edit the configuration to pick another agent.`,
        );
        return;
      }
      setRunConfigPickerOpen(false);
      setRunConfigBranchNotice(null);
      setError(null);
      // The strip reads `error ?? attachments.error ?? git.error ?? notice`, so
      // a leftover message from an earlier manual branch switch would OUTRANK
      // this apply's own refusal and silently stand in for it.
      git.clearError();
      // Land on the new-chat screen: it is what the feature promises, and the
      // only view that renders both the seeded chips AND the strip the branch
      // notice below reports through. The picker is reachable from the sidebar
      // with a thread open, where applying would otherwise seed a composer off
      // screen and swallow the refusal.
      newChat();
      setMobileComposeOpen(true);

      chooseFolder(applied.cwd);
      setComposerProject(
        applied.projectId === null
          ? FOLDER_PROJECT
          : { projectId: applied.projectId, source: 'config' },
      );
      seedComposerTarget(applied);
      if (applied.branch === null) {
        return;
      }
      const info = await window.geniro.getGitInfo(applied.cwd);
      if (!info.isRepo) {
        setRunConfigBranchNotice(
          `“${config.name}” names the branch ${applied.branch}, but that folder is not a git repository.`,
        );
        return;
      }
      if (info.branch === applied.branch) {
        return;
      }
      const result = await window.geniro.switchBranch(
        applied.cwd,
        applied.branch,
      );
      if (!result.ok) {
        // `?? null`, never a bare read: this crosses the IPC boundary, and a
        // reply without the field would otherwise take the worktree arm and
        // name the folder `undefined` to the user.
        const heldBy = result.worktree ?? null;
        setRunConfigBranchNotice(
          // The worktree refusal states the PATH, which the generic wrapping
          // would not: git's own refusal is not something the user can act on
          // without knowing where the branch actually is, and this is the one
          // surface that cannot offer to go there (see `composerNotice`).
          heldBy === null
            ? `Still on ${info.branch ?? 'a detached HEAD'} — could not switch to ${applied.branch}: ${result.error}`
            : `“${config.name}” names ${applied.branch}, which is checked out in the worktree at ${heldBy} — this folder stays on ${info.branch ?? 'a detached HEAD'}.`,
        );
      }
      // Re-read either way, and NAME the folder: the chip must show the branch
      // the folder is ACTUALLY on. The hook's own read fires only when the
      // folder CHANGES, so a configuration naming the folder already selected
      // refetches nothing. Passing `applied.cwd` is also what stops this
      // re-reading the PREVIOUS folder — `chooseFolder` above set React state
      // this callback cannot see.
      await git.refresh(applied.cwd);
    },
    [newChat, seedComposerTarget, chooseFolder, git, setError],
  );

  // What each composer's error strip shows. The screen-level `error` wins, then
  // the shared attachment reader, then that composer's own git read — and the
  // strip is rendered from exactly this value, so a lone attachment failure
  // cannot be computed into the text of a strip whose visibility never
  // considered it (it was, and stayed invisible).
  /**
   * The strip under the composer: what it says, and how loudly.
   *
   * Layered — screen error, then the shared attachment reader, then this
   * composer's own git read — but carrying a TONE, because the last of the
   * three is not always a failure: a branch switch refused over uncommitted
   * work is the guard doing its job, and it comes with an offer to pull the
   * branch up to date without losing that work.
   */
  const composerNotice: GitNotice | null =
    error !== null
      ? {
          message: error,
          tone: 'error',
          offerPull: false,
          carryTo: null,
          useFolder: null,
        }
      : (attachments.error ?? fileAttach.error) !== null
        ? {
            message: (attachments.error ?? fileAttach.error)!,
            tone: 'error',
            offerPull: false,
            carryTo: null,
            useFolder: null,
          }
        : (git.notice ??
          (runConfigBranchNotice === null
            ? null
            : {
                message: runConfigBranchNotice,
                tone: 'error',
                offerPull: false,
                carryTo: null,
                // No offer here, deliberately: a configuration names a FOLDER
                // as well as a branch, so pointing the run at the worktree that
                // holds the branch would run it somewhere the user's own saved
                // answer does not name. The sentence still says where it is.
                useFolder: null,
              }));
  /**
   * The worktree the strip is offering, hoisted out of the notice so the click
   * handler closes over a `const` string: TypeScript drops the narrowing of a
   * PROPERTY inside a callback, and the alternative is a `!` on the one value
   * that decides which folder the run uses.
   */
  const noticeUseFolder = composerNotice?.useFolder ?? null;
  const transcriptError = error ?? attachments.error ?? fileAttach.error;
  /**
   * Close the strip. Every source is cleared, not just the one on top: they are
   * layered, so clearing only `error` would swap one stale failure for an older
   * one and read as a close button that does not close.
   */
  const dismissError = (): void => {
    setError(null);
    attachments.clearError();
    fileAttach.clearError();
    git.clearError();
    setRunConfigBranchNotice(null);
  };
  const skillMatches = useMemo(
    () => (skillQuery === null ? [] : filterSkills(skills, skillQuery)),
    [skills, skillQuery],
  );
  const [skillHighlight, setSkillHighlight] = useState(0);
  // The one query string Escape dismissed — editing the token re-opens.
  const [dismissedQuery, setDismissedQuery] = useState<string | null>(null);
  useEffect(() => setSkillHighlight(0), [skillQuery]);
  const skillMenuOpen =
    skillQuery !== null &&
    skillQuery !== dismissedQuery &&
    skillMatches.length > 0;
  // Narrowing the query can shrink the list under the highlight — clamp.
  const highlightedIndex = Math.min(skillHighlight, skillMatches.length - 1);
  const pickSkill = useLatestCallback((skill: AgentSkill): void => {
    // `/name ` no longer parses as a bare slash token, so picking closes
    // the menu by construction; the caret lands ready for arguments.
    setInput(applySkill(skill));
  }, []);
  /** Menu-first key protocol for both composer textareas; true = consumed. */
  const handleSkillMenuKeys = (
    event: React.KeyboardEvent<HTMLTextAreaElement>,
  ): boolean => {
    if (!skillMenuOpen) {
      return false;
    }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      const delta = event.key === 'ArrowDown' ? 1 : -1;
      setSkillHighlight(
        (highlightedIndex + delta + skillMatches.length) % skillMatches.length,
      );
      return true;
    }
    if (
      event.key === 'Tab' ||
      (event.key === 'Enter' &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.shiftKey)
    ) {
      event.preventDefault();
      const highlighted = skillMatches[highlightedIndex];
      if (highlighted) {
        pickSkill(highlighted);
      }
      return true;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      setDismissedQuery(skillQuery);
      return true;
    }
    return false;
  };

  /**
   * Set when the active run's team is GONE from the library (a 404, not a
   * failed request) — the run's own history survives it, so the transcript
   * stays readable, but nothing about it can be recovered and every panel that
   * reads the graph stays empty. The banner turns that dead end into the one
   * action that resolves it: delete the run.
   */
  const [missingTeam, setMissingTeam] = useState<string | null>(null);
  const [runStageDefinitions, setRunStageDefinitions] = useState<
    readonly TeamStage[] | null
  >(null);
  useEffect(() => {
    let cancelled = false;
    const teamId = activeRun?.teamId;
    const runId = activeRun?.id;
    setMissingTeam(null);
    setRunStageDefinitions(null);
    if (!teamId || !runId) {
      setWfNodes({
        agents: [],
        triggers: [],
        allIds: new Set(),
        rootId: null,
        relay: false,
      });
      return;
    }
    // The RUN's own copy of its graph, never the library's current one — so
    // editing a team changes no run already made from it ("old teams
    // chats should not be changed if i change current team").
    void teamApi
      .getTeamRunSnapshot({ runId })
      .then(({ team }) => {
        if (cancelled) {
          return;
        }
        setWfNodes({
          agents: team.members,
          triggers: runTriggersOf(team),
          allIds: new Set(team.members.map((member) => member.id)),
          rootId: rootAgentOf(team),
          relay: team.mode === 'relay',
        });
        setRunStageDefinitions(team.stages ?? null);
      })
      .catch((err: unknown) => {
        if (cancelled) {
          return;
        }
        setWfNodes({
          agents: [],
          triggers: [],
          allIds: new Set(),
          rootId: null,
          relay: false,
        });
        // A deleted team is not a failure to report as one: the request
        // worked, the graph is simply gone. Say that in the user's terms and
        // let the banner offer the way out, instead of pasting a 404 body
        // under a caption about "terminal targets".
        if (daemonErrorStatus(err) === 404) {
          setMissingTeam(teamId);
          setError(
            `The team “${teamId}” is no longer in your library, so this run's agents and terminals cannot be loaded. Its transcript above is all that is left of it.`,
          );
          return;
        }
        setError(
          `Could not load team terminal targets: ${err instanceof Error ? err.message : String(err)}`,
        );
      });
    return () => {
      cancelled = true;
    };
  }, [activeRun?.id, activeRun?.teamId, teamApi]);

  /**
   * Why THIS run's CLI cannot be handed a message mid-turn, or null when it
   * can — what decides whether the strip offers "send now".
   *
   * Derived from the daemon's report for the same reason as the two sets
   * above: `AdapterConfig.followUp` is the fact, and the moment the renderer
   * decides it by agent name, a CLI that gains the channel keeps a dead
   * control. Undefined-safe by construction — while capabilities are loading
   * there is no row, and the honest answer is "not right now", which reads as
   * a disabled button rather than one that queues without saying so.
   */
  /**
   * The CLIs a message sent into this run lands in. A chat has its one agent;
   * a TEAM run has no agent kind of its own, and the daemon hands a
   * follow-up to every agent the trigger feeds — so those are the agents the
   * question is about. Reading `activeRun.agentKind` alone answered "no agent"
   * for every team run, leaving the queue's send control inert over a
   * running Manager whose CLI takes a message mid-turn perfectly well:
   * REPORTED as "queued messages doesn't work in team — I can't send them
   * from queue".
   */
  const steerAgents = useMemo((): string[] => {
    if (!activeRun) {
      return [];
    }
    if (!activeRun.teamId) {
      return activeRun.agentKind ? [activeRun.agentKind] : [];
    }
    return [...new Set(teamFeedAgents.map((node) => node.agent))];
  }, [activeRun, teamFeedAgents]);

  // Whether Send-now can reach those agents mid-turn, and whether it stops
  // what they are doing — see `steerReadiness`.
  const { reason: steerUnavailableReason, interrupts: steerInterrupts } =
    useMemo(
      () => steerReadiness(capabilities?.followUps ?? [], steerAgents),
      [capabilities, steerAgents],
    );
  // Node display metadata for the transcript (names + kinds), and the
  // transcript folded into render entries — consecutive tool calls collapse
  // into expandable groups.
  const nodeMeta = useMemo(() => {
    const map = new Map<string, TranscriptNodeMeta>();
    for (const node of wfNodes.agents) {
      // `agent` rides along so a block header can name the CLI under a node —
      // the graph is the only thing that knows it, and no transcript item
      // carries it.
      map.set(node.id, {
        name: node.name,
        kind: 'agent',
        agent: node.agent,
        ...(node.pool?.length
          ? { pool: [node.agent, ...node.pool.map((member) => member.agent)] }
          : {}),
        ...(node.avatar ? { avatar: node.avatar } : {}),
      });
    }
    return map;
  }, [wfNodes]);
  // Live per-agent state for the agents panel, derived purely from the
  // transcript (status items count parallel turns; call items list threads;
  // turn_complete usage carries context/spend).
  const windowActivity = useMemo(
    () => computeAgentActivity(foldItems, callStarts),
    [foldItems, callStarts],
  );
  // A node whose status rows are above the loaded page takes its status from
  // the daemon's own `node_state` — see `withDurableNodeStatus`. The run ROW
  // gates a `running` reading, so a daemon that died mid-turn cannot leave a
  // `Working…` row under a finished run.
  const runRowSettled =
    activeRun !== null && isSettledRunStatus(activeRun.status);
  // The team's agents, whose cards the panel draws whatever the window
  // holds — a settled durable row may fill their status in.
  const wfAgentIds = useMemo(
    () => new Set(wfNodes.agents.map((node) => node.id)),
    [wfNodes.agents],
  );
  const activity = useMemo(
    () =>
      withDurableNodeStatus(
        windowActivity,
        nodeReadings,
        runRowSettled,
        !awayFromTail,
        wfAgentIds,
      ),
    [windowActivity, nodeReadings, runRowSettled, awayFromTail, wfAgentIds],
  );
  // Which calls are one CONVERSATION — the rule the transcript's call blocks
  // and the activity fold already apply, read here for the two panel feeds that
  // are keyed by a row's call id (task lists, and the shelf's shell names).
  // The daemon's list of calls names every call's `thread`, where the readings
  // behind `callStarts` are capped — so a conversation older than both the
  // window and that cap still reads as one.
  const callChains = useMemo(() => {
    const starts = new Map<string, { thread: string | null }>(callStarts);
    for (const call of runState.calls) {
      if (!starts.has(call.callId)) {
        starts.set(call.callId, { thread: call.thread });
      }
    }
    return resolveCallChains(foldItems, starts);
  }, [foldItems, callStarts, runState.calls]);
  /**
   * Each agent's OWN task list as it stands now, for the side panel.
   *
   * The panel and not the composer: it is the same kind of derived, per-agent
   * state as the delegate list beside it, and it belongs where a reader already
   * looks for "what is this agent doing". The transcript cards stay as the
   * history of the list moving, exactly as a sub-agent has both a block in the
   * flow and a row in the panel.
   *
   * Keyed by node id (`null` for a 1:1 chat), and a delegate's rows are excluded
   * — its list lives in its own block, whose header carries its count.
   */
  const tasksByAgent = useMemo(() => {
    // Re-keyed to the PANEL's agent ids here rather than in the fold: a 1:1
    // chat's rows carry `nodeId: null` while its agent card is keyed by
    // `CHAT_AGENT_KEY`, and that mapping is this screen's own — the fold has no
    // business knowing it.
    //
    // A LIST per agent, one entry per CONVERSATION it kept a checklist in: a
    // node called several times runs one conversation per call, each numbering
    // its tasks from 1, so the panel draws each under its own instance — and a
    // call that CONTINUED an earlier one's thread is that same conversation, so
    // its list is combined into it (`conversationTaskLists`).
    const raw = new Map<
      string,
      {
        callId: string | null;
        tasks: InstanceTaskList['tasks'];
        snapshot: boolean;
      }[]
    >();
    const add = (
      memberId: string | null,
      callId: string | null,
      tasks: InstanceTaskList['tasks'],
      snapshot: boolean,
    ): void => {
      const key = memberId ?? CHAT_AGENT_KEY;
      const lists = raw.get(key) ?? [];
      lists.push({ callId, tasks, snapshot });
      raw.set(key, lists);
    };
    const byConversation = (): Map<string, InstanceTaskList[]> =>
      new Map(
        [...raw].map(([key, lists]) => [
          key,
          conversationTaskLists(lists, callChains),
        ]),
      );
    // The DAEMON's fold wins, and that is the whole of the fix: it folded every
    // announcement the run has ever written, while the fold below can only see
    // the transcript WINDOW this client loaded. Neither shipped CLI re-states
    // the list — measured, claude sends one-row patches and no snapshot at all —
    // so past `HISTORY_PAGE` items the opening announcement falls out and the
    // local fold reports a total that has shrunk (`3/3` for a list of six).
    //
    // The local fold stays as the fallback rather than being deleted: a run row
    // written before this column existed carries an empty list until its agent
    // announces again, and the transcript can still answer for it meanwhile.
    const folded = activeRun?.taskList ?? [];
    if (folded.length > 0) {
      for (const group of folded) {
        // The group's own `snapshot` flag, which means what the transcript
        // fold's does — so a later call's full restatement replaces the
        // earlier list here exactly as it does on the call's card.
        add(group.memberId, group.callId, group.tasks, group.snapshot);
      }
      return byConversation();
    }
    for (const list of taskListsByThread(transcriptRows, subagentIdOf)) {
      add(list.memberId, list.callId, list.tasks, list.snapshot);
    }
    return byConversation();
  }, [transcriptRows, activeRun?.taskList, callChains]);
  /**
   * The agents whose turn is in flight — the transcript draws each of them a
   * row even when they have nothing to say yet, so the flow never goes silent
   * between a tool batch and the next words.
   *
   * A chat's one agent is running when the run is; a team node is running
   * when it has an unsettled turn. Both are read from state the transcript
   * already derives, so nothing new has to be tracked to answer it.
   */
  const workingAgents = useMemo(() => {
    const keys = new Set<string>();
    // A window from the MIDDLE of the conversation is history: whatever turn
    // it shows open ended somewhere below it, and what is working now belongs
    // under the tail, which is not on screen. Drawing the row here put a live
    // "Tuning… 224h 12m" under the first message of an archived thread.
    if (!activeRun || awayFromTail) {
      return keys;
    }
    if (!activeRun.teamId) {
      if (streaming || activeRun.status === 'running') {
        keys.add(CHAT_LIVE_KEY);
      }
    } else {
      for (const [memberId, nodeActivity] of activity) {
        if (memberId !== CHAT_AGENT_KEY && nodeActivity.activeTurns > 0) {
          keys.add(memberId);
        }
      }
    }
    // An agent parked on a question is NOT working — it is waiting on the
    // person reading the card. Its turn is genuinely still in flight, so every
    // signal above says "running", and the fallback drew a spinning
    // "Working… 4m 12s" directly under the question it was waiting for an
    // answer to. Removing it leaves the card as the only thing on screen,
    // which is the truth: nothing moves until it is answered.
    for (const key of awaitingAnswer) {
      keys.delete(key);
    }
    return keys;
  }, [activeRun, activity, awaitingAnswer, awayFromTail, streaming]);
  /**
   * The badge for the run currently on screen.
   *
   * Only the ACTIVE run gets this treatment, and that is a limit of what is
   * knowable rather than an oversight: `streaming` and `awaitingAnswer` are both
   * derived from the open transcript's items, and the renderer holds no items
   * for a chat it is not looking at. A background row keeps the daemon's own
   * status, which the client-wide `run_status` broadcast already keeps honest.
   */
  /**
   * The run's row has SETTLED — whatever it settled as.
   *
   * `completed` is included, and it did not used to be. The reasoning against
   * it was that a `completed` row is the stale value this signal exists to
   * override, so treating it as a stop would let the badge suppress itself —
   * true only while the override was the FACT of a delegate being unreturned.
   * It is not: `subagentBlockStatus` reads the moment, so a delegate that has
   * produced rows since the settle is still working and still overrides the
   * row, which is the case the signal was written for (a run row reading
   * `completed` while delegates were visibly working — and the daemon flips
   * that row back to `running` for it besides).
   *
   * What excluding `completed` cost is the opposite failure, with no way out of
   * it: a turn whose delegate never reported left the badge reading `running`
   * for good — no process, no rows, no settle the notification rules could see.
   * That is the reported "the sub-agent is done and the status never changed",
   * and the reported "I get no notification when a chat finishes".
   */
  const runRowStopped =
    activeRun !== null && isSettledRunStatus(activeRun.status);
  /**
   * WHEN it stopped, which is what a delegate's status is actually read
   * against — see {@link subagentBlockStatus}. The run row's own `updatedAt` is
   * the settle moment and not merely the newest thing about the run: items do
   * not touch that row, so it stands still while a delegate keeps writing
   * (measured — run `d8cb70c0` carries an `updatedAt` 149s BEFORE its own last
   * item), which is exactly the gap that makes "has this delegate spoken
   * since?" answerable.
   */
  const runStoppedAt = useMemo(
    () => (runRowStopped ? settleMomentOf(activeRun, items) : null),
    [runRowStopped, activeRun, items],
  );
  /**
   * A delegate of this run that is AUDIBLE — still writing rows.
   *
   * Narrowed from "is any delegate out" for the turn-end notification: the
   * reading it fires on leaves out a delegate the CLI only declared out, which
   * the run ROW counts (`subagentsOut`, see below). Cursor's background
   * delegates are permanently that second kind, since their steps never reach
   * this wire, so folding them in here would keep a finished cursor run from
   * ever announcing its end. The badge reads both kinds as `running`.
   */
  const subagentRunning = useMemo(
    () => anySubagentRunning(durableEntries, runStoppedAt),
    [durableEntries, runStoppedAt],
  );
  /**
   * The badge reading WITHOUT the background-command clause — what the run
   * would say if the only question were whether its agent is working.
   *
   * It exists because the two readings are owed to different consumers. The
   * notification and the unseen mark fire on the transition INTO a settled
   * status, and both mean "your agent has stopped, come and look" — which a
   * `pnpm dev` running on in the background does not change. Feeding them the
   * badge below would have suppressed the turn-end banner and the unread dot
   * for every chat that left a command running, which is most of them.
   *
   * So the divergence is deliberate and narrow, against the rule those hooks
   * are documented with ("the SAME status the sidebar badge shows"): the
   * banner reports the TURN ending, the badge reports what is still out. Two
   * facts, not one fact spelled two ways.
   */
  const agentRunStatus = useMemo(
    () =>
      activeRun
        ? displayRunStatus({
            status: activeRun.status,
            streaming,
            // The run row's own reading too, which every OTHER sidebar row
            // already takes: a card the daemon holds open is a question
            // whether or not this client has drawn it yet.
            awaitingAnswer:
              awaitingAnswer.size > 0 || activeRun.awaiting != null,
            subagentRunning,
            heldForBackgroundWork: holding.has(activeRun.id),
            teamLeadsDone: rootsIdle.has(activeRun.id),
          })
        : 'pending',
    [activeRun, streaming, awaitingAnswer, subagentRunning, holding, rootsIdle],
  );
  const activeRunStatus = useMemo(
    () =>
      activeRun
        ? displayRunStatus({
            status: activeRun.status,
            streaming,
            awaitingAnswer:
              awaitingAnswer.size > 0 || activeRun.awaiting != null,
            subagentRunning,
            heldForBackgroundWork: holding.has(activeRun.id),
            // The RUN ROW's count, not this thread's transcript — the same
            // fact the unfocused rows read, which is the whole of the
            // blinking fix. See {@link rowRunStatus}.
            shellsRunning: shellsOut.has(activeRun.id),
            // Row-carried like the shells beside it, and for the identical
            // reason: derived from THIS thread's transcript it would be
            // knowable for the open chat and no other, so the badge would
            // change when the user looked away.
            subagentsOut: delegatesOut.has(activeRun.id),
            monitorsRunning: activeRun.monitorsOpen > 0,
          })
        : 'pending',
    [
      activeRun,
      streaming,
      awaitingAnswer,
      subagentRunning,
      holding,
      shellsOut,
      delegatesOut,
    ],
  );
  /**
   * The settle moment the transcript reads — WHEN this run stopped, or null
   * while it has not.
   *
   * Broader than {@link runStoppedAt} on purpose, and the two must not be
   * merged: that one answers "did the run stop for a reason that outranks a
   * delegate still being out", so it deliberately excludes `completed`; this
   * one drives the blocks themselves, where a completed run genuinely does end
   * a tool call that never returned. What both now share is that a settle is a
   * MOMENT — a delegate that has produced rows since is working, whichever
   * predicate said the run was over.
   */
  const activeRunSettledAt = useMemo(
    () =>
      isSettledRunStatus(activeRunStatus)
        ? settleMomentOf(activeRun, items)
        : null,
    [activeRun, activeRunStatus, items],
  );
  const daemonOpenCalls = useMemo(
    () => runningCallCallees(runState.calls),
    [runState.calls],
  );
  const activePendingSend =
    activeRunId === null ? undefined : pendingSends.get(activeRunId);
  const transcriptEntries = useMemo(
    () =>
      // No live rows over a thread whose first page has not landed. The
      // working row is drawn from the run's STATUS, which the sidebar row
      // already carries, so it was the only thing on an opened running thread
      // for the length of the fetch — REPORTED as a flash of one
      // `Tinkering… 0s` card on an empty pane — and as an entry it also hid
      // the "Loading conversation…" placeholder, which needs an empty list.
      loadingHistory && durableEntries.length === 0
        ? durableEntries
        : withLiveText(
            withPendingSend(durableEntries, activePendingSend, items),
            liveText,
            workingAgents,
            activeRun?.id ?? null,
            daemonOpenCalls,
          ),
    [
      loadingHistory,
      durableEntries,
      activePendingSend,
      items,
      liveText,
      workingAgents,
      activeRun?.id,
      daemonOpenCalls,
    ],
  );
  useEffect(() => {
    drawnEntriesRef.current = transcriptEntries;
  }, [transcriptEntries]);
  /**
   * Keep paging while what is loaded does not FILL the pane.
   *
   * Scrolling is the pager's trigger, and a transcript shorter than its pane
   * has no scroll to give — so it never asked. That is not an edge case on a
   * team run: every row a callee streams folds into ONE call card, so the
   * newest 1,000 items routinely render as a single row. REPORTED as "it cannot
   * load messages" over exactly that — "Scroll up for earlier messages" above
   * one card and a pane of nothing. Re-checked on every render of the entries,
   * since a page that also folds into that card leaves the pane just as short.
   *
   * A page that fails or adds nothing stops it for this run: without that a
   * daemon refusing the read would be asked again on every streamed token.
   * The notice's button is still there to try again.
   */
  const fillStoppedRef = useRef<string | null>(null);
  useEffect(() => {
    const scroller = transcriptEndRef.current?.parentElement;
    if (
      !scroller ||
      !hasOlder ||
      loadingOlder ||
      activeRunId === null ||
      fillStoppedRef.current === activeRunId ||
      // jsdom, and a pane not laid out yet: nothing measured is not "short".
      scroller.clientHeight === 0 ||
      scroller.scrollHeight - scroller.clientHeight > scroller.clientHeight / 2
    ) {
      return;
    }
    const runId = activeRunId;
    void pageOlder(scroller).then((grew) => {
      if (!grew) {
        fillStoppedRef.current = runId;
      }
    });
  }, [transcriptEntries, hasOlder, loadingOlder, activeRunId, pageOlder]);
  /**
   * The same, FORWARD, for a window a jump left the reader in.
   *
   * Scrolling down is what asks for the next page, and a window whose rows fold
   * into a few call cards has no scroll to give — measured on the reported
   * team: the thousand rows after its first message drew ELEVEN entries,
   * shorter than the pane, so the rest of the conversation could not be
   * reached by scrolling at all. Keeps reading until the pane has something
   * below the fold or the window reaches the tail (which ends the away state
   * and with it this effect); a page that adds nothing stops it for the run.
   */
  const fillNewerStoppedRef = useRef<string | null>(null);
  const fillNewerInFlightRef = useRef(false);
  // Re-runs the effect once a page has landed: the rows it brought commit while
  // the in-flight flag is still up, so their own render cannot ask again.
  const [fillNewerTick, setFillNewerTick] = useState(0);
  // Each jump is a fresh window: a stop recorded against an earlier one in the
  // same thread must not keep this one from filling.
  useEffect(() => {
    if (awayFromTail) {
      fillNewerStoppedRef.current = null;
    }
  }, [awayFromTail]);
  useEffect(() => {
    const scroller = transcriptEndRef.current?.parentElement;
    if (
      !scroller ||
      !awayFromTail ||
      activeRunId === null ||
      fillNewerInFlightRef.current ||
      fillNewerStoppedRef.current === activeRunId ||
      scroller.clientHeight === 0 ||
      scroller.scrollHeight - scroller.clientHeight > scroller.clientHeight / 2
    ) {
      return;
    }
    const runId = activeRunId;
    fillNewerInFlightRef.current = true;
    void loadNewer()
      .then((grew) => {
        if (!grew) {
          fillNewerStoppedRef.current = runId;
        }
      })
      .finally(() => {
        fillNewerInFlightRef.current = false;
        setFillNewerTick((tick) => tick + 1);
      });
  }, [transcriptEntries, awayFromTail, activeRunId, loadNewer, fillNewerTick]);
  /**
   * The dynamic workflows this run launched — the SAME reading the transcript's
   * cards are built from, handed to the shelf above the composer and to the
   * side panel.
   *
   * One derivation for three surfaces, which is the point of `workflowCardsOf`
   * being exported at all: a chip that folded its own roster would sooner or
   * later say `3 running` beside a card saying two.
   */
  const runWorkflows = useMemo(
    () => workflowCardsOf(withAnchors(foldItems, runState.workflowRows)),
    [foldItems, runState.workflowRows],
  );
  /**
   * Every call's card, found by any call id it holds — where an INSTANCE's
   * latest words and spend are already folded, so the panel's instance row and
   * the transcript's block cannot disagree.
   */
  const callBlockIndex = useMemo(
    () => indexCallBlocks(durableEntries),
    [durableEntries],
  );
  // In a LAYOUT effect: it runs ahead of every passive effect of the commit,
  // the jump machine's included, and never for a render React discards.
  useLayoutEffect(() => {
    callJumpRef.current = {
      entries: durableEntries,
      calls: runState.calls,
      rows: transcriptRows,
      loadThrough: callConversations.loadThrough,
    };
  }, [durableEntries, runState.calls, transcriptRows, callConversations]);
  /** For the wake divider: how to open a call's card, or null when it is not loaded. */
  const revealCall = useLatestCallback(
    (callId: string): (() => void) | null => {
      const block = callBlockIndex.get(callId);
      return block === undefined ? null : () => revealCallBlock(block.id);
    },
    [callBlockIndex, revealCallBlock],
  );
  /**
   * The agents this team run has started, for the working-agents card. Which
   * calls ever ran is the daemon's, over the whole run; the window only says
   * what has moved since it read them.
   */
  const startedAgents = useMemo((): WorkingAgentRow[] => {
    if (activeRun?.teamId == null) {
      return [];
    }
    const callsById = new Map(
      runState.calls.map((call) => [call.callId, call] as const),
    );
    // A card open on a page that holds its start and not its end is over by
    // the daemon's word once every call it holds is (`callEndedPerDaemon`).
    const open = openCallBlocks(durableEntries).filter(
      (block) =>
        !block.callIds.every(
          (callId) => callEndedPerDaemon(callsById, runState, callId) !== null,
        ),
    );
    return workingAgentRows({
      calls: runState.calls,
      chains: callChains,
      blocks: { open, drawn: new Set(callBlockIndex.keys()) },
      runSettled: isSettledRunStatus(activeRun.status),
      nodes: nodeMeta,
      clocks: callClocks,
    });
  }, [
    activeRun?.teamId,
    activeRun?.status,
    durableEntries,
    callBlockIndex,
    callChains,
    nodeMeta,
    runState,
    callClocks,
  ]);
  /**
   * A call whose card a link asked to OPEN (`openCall`), waiting until the
   * transcript draws it: then every card around it is opened, outermost first
   * (a card inside another is mounted only while that one is open), and the
   * card is revealed once that has rendered. Dropped with the thread, and
   * after `OPEN_CALL_WAIT_MS` — a jump that never arrives must not open the
   * card whenever the reader later scrolls to it.
   */
  const [callToOpen, setCallToOpen] = useState<string | null>(null);
  const [revealAfterOpen, setRevealAfterOpen] = useState<string | null>(null);
  useEffect(() => {
    setCallToOpen(null);
    setRevealAfterOpen(null);
  }, [activeRunId]);
  useEffect(() => {
    if (callToOpen === null) {
      return;
    }
    const timer = setTimeout(() => setCallToOpen(null), OPEN_CALL_WAIT_MS);
    return () => clearTimeout(timer);
  }, [callToOpen]);
  useEffect(() => {
    if (callToOpen === null) {
      return;
    }
    const path = callBlockPath(durableEntries, callToOpen);
    if (path.length === 0) {
      return;
    }
    setCallToOpen(null);
    for (const block of path) {
      openCallCard(block.id);
    }
    setRevealAfterOpen(path[path.length - 1]!.id);
  }, [callToOpen, durableEntries, openCallCard]);
  useEffect(() => {
    if (revealAfterOpen !== null) {
      setRevealAfterOpen(null);
      revealCallBlock(revealAfterOpen);
    }
  }, [revealAfterOpen, revealCallBlock]);
  // A callee's button card links to the call it was answering: its card,
  // opened. A card the window does not draw — off the page, or inside a card
  // whose conversation is not read yet — is reached by the jump machine,
  // which pages and opens its way to the call's start row first.
  const openCall = useLatestCallback(
    (callId: string): void => {
      setCallToOpen(callId);
      if (callBlockIndex.has(callId)) {
        return;
      }
      const start = runState.calls.find(
        (call) => call.callId === callId,
      )?.startSeq;
      if (start !== undefined) {
        jumpToSeq(start);
      }
    },
    [callBlockIndex, runState.calls, jumpToSeq],
  );
  const chatActions = useMemo(
    () => ({ ...pressableActions, openCall }),
    [pressableActions, openCall],
  );
  /**
   * How long each of this run's turns worked — see `turn-duration.ts`.
   *
   * Derived from the DURABLE rows, like `turnStartedAt` above and for the same
   * reason: a reload, a tab switch or a mid-turn reconnect must not change the
   * answer. Computed once here and handed down by context rather than per row,
   * since every `turn_complete` in the transcript needs its own entry and the
   * shells between are memoized.
   */
  const turnScan = useMemo(
    // A TEAM's work belongs to its nodes — several of which run at once —
    // and the run itself has no turn at all; a chat is the other way round.
    // The two transcripts are scanned as the different things they are.
    () =>
      scanTurns(transcriptRows, {
        nodeScoped: activeRun?.teamId != null,
      }),
    [transcriptRows, activeRun?.teamId],
  );
  const turnDurations = turnScan.durations;
  /** What this whole thread has worked, for the header. */
  const threadWorked = useMemo(
    () => threadWorkedMs(turnDurations),
    [turnDurations],
  );
  /**
   * The team header's paused stretches are the daemon's, re-read when any
   * row they are folded from lands (`movesPausedSpans`). The run-row flags in
   * the clock key announce before that row is written, and only its arrival
   * proves the daemon has it; the flags cover a transcript scrolled away from
   * its tail. Over `transcriptRows`, because a callee's card or turn start
   * lands among the call rows, never in a team run's window.
   */
  const clockRowCount = useMemo(
    () => transcriptRows.filter(movesPausedSpans).length,
    [transcriptRows],
  );
  /**
   * What this thread has SPENT, for the header beside what it worked.
   *
   * Re-asked on `threadWorked.turns` — the count of settled turns — because
   * that is what moves the spend, and a count changes exactly once per turn
   * rather than on every delta the turn streams. A team also re-asks on its
   * clock key, for the paused stretches.
   */
  const threadTotals = useChatTotals(
    chatApi,
    activeRunId,
    threadWorked.turns,
    client,
    activeRun?.teamId != null
      ? [
          activeRun.awaiting ?? '',
          shellsOut.has(activeRun.id),
          delegatesOut.has(activeRun.id),
          clockRowCount,
        ].join('|')
      : '',
  );
  /**
   * The newest user message the loaded window holds — the timeline rail's
   * second refresh trigger.
   *
   * It moves when a message is SENT and at no other time: the items arrive in
   * seq order, so paging older history in prepends rows whose seqs are all
   * lower and this figure is unchanged. That is what lets the rail follow the
   * conversation without a fetch every time the reader scrolls up.
   */
  const latestUserSeq = useMemo(
    () =>
      transcriptRows.reduce(
        (seq, item) =>
          item.kind === 'message' && item.role === 'user' ? item.seq : seq,
        0,
      ),
    [transcriptRows],
  );
  /**
   * The newest paragraph the agent WROTE in the loaded window — a `message`
   * that is not the user's, or a `reasoning` row — the timeline's third refresh
   * trigger, which is what keeps the stretch being worked live. The same rows
   * the daemon counts as a stretch's messages.
   */
  const latestAgentSeq = useMemo(
    () =>
      transcriptRows.reduce(
        (seq, item) =>
          (item.kind === 'message' && item.role !== 'user') ||
          item.kind === 'reasoning'
            ? item.seq
            : seq,
        0,
      ),
    [transcriptRows],
  );
  /**
   * Every user message in the thread, whatever the loaded window holds.
   *
   * The daemon's own fold: a long chat opens on its newest 1,000 items, so a
   * rail built from `items` would draw the tail of the conversation and present
   * it as the whole of it — see `use-chat-timeline.ts`.
   */
  const timeline = useChatTimeline(
    chatApi,
    activeRunId,
    threadWorked.turns,
    latestUserSeq,
    latestAgentSeq,
  );
  /**
   * The newest page published in the loaded window — the artifact listing's
   * one refresh trigger. Nothing about an already-published page changes until
   * it is republished, and that writes another row, so this covers every way
   * the list can move.
   */
  const latestArtifactSeq = useMemo(
    () =>
      transcriptRows.reduce(
        (newest, item) =>
          item.kind === 'show_artifact' && item.seq > newest
            ? item.seq
            : newest,
        0,
      ),
    [transcriptRows],
  );
  /**
   * The pages this run published, read from the DAEMON — a fold over `items`
   * would drop one published earlier in a long thread, and the panel is the
   * page's only stable entry point once its card has scrolled away. See
   * `use-run-artifacts.ts`.
   */
  const publishedArtifacts = useRunArtifacts(
    chatApi,
    activeRunId,
    latestArtifactSeq,
  ).artifacts;
  /**
   * The newest team note in the loaded window and the open call cards — the
   * team-notes listing's one refresh trigger: a note is append-only, so a new
   * row is the only way the list moves.
   */
  const latestTeamNoteSeq = useMemo(
    () =>
      transcriptRows.reduce(
        (newest, item) =>
          item.kind === 'team_note' && item.seq > newest ? item.seq : newest,
        0,
      ),
    [transcriptRows],
  );
  /**
   * The notes popup while open — the user's own notes and the team notes —
   * with the team note it was opened on: from the agents panel's control row,
   * the shelf chip, or a note's row in the transcript.
   */
  const [notesView, setNotesView] = useState<{
    selected: number | null;
  } | null>(null);
  // A thread switch closes it: it belongs to the run it was opened over.
  useEffect(() => {
    setNotesView(null);
  }, [activeRunId]);
  const openTeamNote = useLatestCallback((seq: number) => {
    setNotesView({ selected: seq });
  }, []);
  /** The progress popup — stages, goals and outcome — from the shelf chip or the panel's Goals row. */
  const [progressOpen, setProgressOpen] = useState(false);
  useEffect(() => {
    setProgressOpen(false);
  }, [activeRunId]);
  const openProgress = useLatestCallback(() => setProgressOpen(true), []);
  /**
   * The newest outcome the open run's pull-request list carries — the outcome
   * history's one refresh trigger, moved by every announce of a written outcome.
   */
  const latestOutcomeSeq = useMemo(
    () =>
      (activeRunPullRequests ?? []).reduce(
        (newest, row) => Math.max(newest, row.outcome?.seq ?? 0),
        0,
      ),
    [activeRunPullRequests],
  );
  /** Every outcome the open run recorded per pull request — a team run's only. */
  const { pullRequests: pullRequestOutcomes } = useRunOutcomes(
    chatApi,
    activeRun?.teamId != null ? activeRunId : null,
    latestOutcomeSeq,
  );
  /** The run's team notes, read from the daemon — a team run's only. */
  const { notes: teamNotes } = useRunTeamNotes(
    chatApi,
    activeRun?.teamId != null ? activeRunId : null,
    latestTeamNoteSeq,
  );
  const latestShowArtifactResult = useMemo(
    () =>
      activeRunId === null
        ? latestArtifactSeq
        : latestShowArtifactResultSeq(
            transcriptRows,
            activeRunId,
            latestArtifactSeq,
          ),
    [transcriptRows, activeRunId, latestArtifactSeq],
  );
  /**
   * The open run's shared pages and the Share control's actions. Desktop only:
   * a paired phone gets no control, and the daemon refuses it anyway.
   */
  const artifactSharing = useArtifactSharing(
    isRemoteRuntime() ? null : apis.shares,
    activeRunId,
    latestShowArtifactResult,
    client,
  );
  /**
   * The messages other threads sent this one that still wait for its next turn
   * — the shelf's chip lists them and takes one away on Remove.
   */
  const waitingMessages = useWaitingMessages(chatApi, client, activeRunId);
  /**
   * Stop one of this thread's running commands — ASKED FOR as "i wanna have an
   * ability to kill terminals".
   *
   * Bound to the OPEN run here rather than taking one, like the panel's export
   * control beside it: every list that draws this button is per-thread, so a
   * shell id is only ever addressed within the conversation on screen — which
   * is also the daemon's own scoping, since a call id names nothing there
   * unless that run opened it.
   *
   * `killed: false` is an ORDINARY answer rather than a failure — the list is a
   * snapshot, so a command that ended by itself between the render and the
   * press is the common race — but it is still worth SAYING, because the user
   * pressed a button and the process they were looking at was not the thing
   * that stopped. The daemon writes the sentence; nothing here composes one.
   *
   * It re-reads either way. A kill on a live run moves `Run.shellsOpen`, which
   * the hook already watches, but the case this exists for is the other one: a
   * command left over from a conversation whose CLI is long gone, where that
   * count is already zero and nothing would ever fetch again.
   */
  const handleKillShell = useLatestCallback(
    async (shell: ShellRun): Promise<void> => {
      if (activeRunId === null) {
        return;
      }
      setError(null);
      try {
        const answer = await chatApi.killChatShell({
          runId: activeRunId,
          callId: shell.id,
        });
        if (!answer.killed && answer.reason !== null) {
          setError(`${shell.command}: ${answer.reason}`);
        }
      } catch (err) {
        setError(String(err));
      } finally {
        refreshRunState();
      }
    },
    [activeRunId, chatApi, refreshRunState, setError],
  );

  /** Stop one monitor from the shelf, as the processes popup's Stop does. */
  const handleStopMonitor = useLatestCallback(
    async (monitor: OpenMonitor): Promise<void> => {
      if (activeRunId === null) {
        return;
      }
      setError(null);
      try {
        const answer = await chatApi.stopDetachedProcesses({
          runId: activeRunId,
          stopDetachedProcessesDto: { monitorIds: [monitor.id] },
        });
        if (!answer.stoppedMonitorIds.includes(monitor.id)) {
          setError(`${monitor.description}: the monitor could not be stopped`);
        }
      } catch (err) {
        setError(String(err));
      } finally {
        refreshRunState();
      }
    },
    [activeRunId, chatApi, refreshRunState, setError],
  );

  /**
   * The timeline as the agents panel takes it — its markers plus the jump.
   *
   * Memoized rather than built inline at the call site: the panel draws this
   * control twice (the row and the folded rail), and a fresh object per render
   * would churn both on every streamed token.
   */
  const timelinePanel = useMemo(
    () => ({
      markers: timeline.markers,
      partialReason: timeline.partialReason,
      onJump: jumpToSeq,
      // The reading the header's own `live` controls take, so the timeline's
      // live dot and the rest of the screen cannot disagree about the run.
      inProgress: isWorkingRunStatus(activeRunStatus),
    }),
    [timeline.markers, timeline.partialReason, jumpToSeq, activeRunStatus],
  );
  /**
   * What the header states about the thread as a WHOLE — the daemon's answer
   * where it has one, this component's fold where it does not.
   *
   * The fold is over the LOADED window now (a long chat opens on its newest
   * 1,000 items), so it can only ever describe the tail of a long conversation.
   * The daemon counts every `turn_complete` row the run ever wrote, which is
   * the figure the header claims to be showing.
   *
   * It is a preference and not a replacement because the two measure worked
   * time differently, and only one of them can answer for every CLI: the
   * daemon reports the time the AGENT reported, which cursor never does over
   * ACP — `workedMs` is null there, and the fold's wall-clock-minus-parked
   * reading is the only figure that exists. So each side covers what the other
   * cannot, and neither invents a number.
   */
  const threadTotalsShown = useMemo(
    () => ({
      ms: threadTotals.workedMs ?? threadWorked.ms,
      turns: threadTotals.turns ?? threadWorked.turns,
    }),
    [threadTotals.workedMs, threadTotals.turns, threadWorked],
  );
  /**
   * What THIS run is doing, for the live rows — the same sentence the sidebar
   * badge carries, so the transcript and the badge cannot say different things
   * about one run.
   */
  const activeActivity =
    activeRunId === null ? null : (activities.get(activeRunId) ?? null);
  /**
   * This run's agent is parked rather than working — the run reads `running`
   * because of work that is NOT the agent producing a reply.
   *
   * A turn held for its delegates ({@link holding}), a manager inside a wait on
   * its own callees ({@link awaitingCalls}), and a TEAM whose trigger-fed
   * agents have all ended their turns ({@link rootsIdle}) park it outright.
   * Background sub-agents ({@link delegatesOut}) and a detached command
   * ({@link shellsOut}) park it only once its reply is over: the daemon counts
   * them across turn boundaries, so mid-reply they say nothing about whether
   * the agent will read a message soon, and a message typed then queues.
   *
   * ONE reading, because every surface that reads it asks the same question:
   * does a message typed now go straight out, and does the button say Send or
   * Queue. The composer's own send path reads the refs for the same reason —
   * see `sendFollowUp`.
   */
  const activeFacts: ParkedFacts | null =
    activeRunId === null
      ? null
      : {
          streaming,
          held: holding.has(activeRunId),
          awaitingCalls: awaitingCalls.has(activeRunId),
          rootsIdle: rootsIdle.has(activeRunId),
          subagentsOut: delegatesOut.has(activeRunId),
          shellsOut: shellsOut.has(activeRunId),
        };
  const activeParkedReason =
    activeFacts === null ? null : parkedReason(activeFacts);
  const activeRunHeld = activeParkedReason !== null;
  /**
   * What the composer's button says a press will do — the SAME decision
   * `sendFollowUp` acts on, read off the same facts, so the label cannot say
   * Send over a press that queues. It did, with no turn running and earlier
   * messages still waiting (after a Stop, most visibly), because the label
   * asked only whether a turn was streaming.
   */
  const composerButton =
    activeRunId === null || activeFacts === null
      ? null
      : followUpButton(
          followUpDelivery({ ...activeFacts, queued: queued.length > 0 }),
          activeParkedReason,
          pausedQueues.has(activeRunId),
        );
  /**
   * The open turn as a CHAT header (and each agent's figure) should measure it:
   * the hold counted as a parked stretch, exactly like an approval card's wait.
   * A team header reads only the turn starts and the daemon's paused
   * stretches (`clockMs`).
   *
   * The header's figure is "how much work is in here", not how long the window
   * has been open, and while a turn is held nobody is working — the agent has
   * said its piece and the process is alive for its listeners. Folded in here
   * rather than inside `scanTurns`, because a hold leaves NO transcript row to
   * scan for (`turn_held` maps to no item, deliberately): it is a live fact
   * about the run, and this is where the live facts are.
   */
  const openTurnForHeader = useMemo(
    () =>
      parkWhileHeld(
        // A node working one turn for longer than the loaded page has its
        // opening row above it — `withDurableOpenTurns` reads the start off the
        // node's own row, or every clock built on this froze. A chat's turn is
        // the RUN's, and its start is the daemon's run-state reading.
        withDurableChatTurn(
          withDurableOpenTurns(turnScan.open, nodeReadings, (memberId) =>
            windowHoldsStatus(windowActivity, memberId),
          ),
          runState.turnStartedAt,
          CHAT_AGENT_KEY,
        ),
        // A chat's holds are the daemon's: it knows the ones that ended and
        // when the standing one began, which a window opened mid-turn cannot.
        // The live announce stands in while the re-read it triggers is out.
        heldSinceOf(runState.turnHeldSince) ??
          (activeRunId === null ? undefined : holding.get(activeRunId)),
        runState.turnHeldMs,
      ),
    [
      turnScan.open,
      nodeReadings,
      windowActivity,
      holding,
      activeRunId,
      runState.turnStartedAt,
      runState.turnHeldSince,
      runState.turnHeldMs,
    ],
  );
  /**
   * The open turns any LIVE readout may count — the header's total and each
   * agent card's alike.
   *
   * Both guards belong HERE rather than at either call site, on the rule
   * `shellsByAgent` below already follows: two readouts of one figure that
   * apply different guards are two answers to one question. `parkWhileHeld`
   * because a hold is the run NOT working, so a card that kept climbing through
   * one would out-count the header and then jump backwards at the settle; and
   * the settled check because `scanTurns` emits an open turn for any thread
   * with a start and no terminal row — a daemon that died mid-turn leaves
   * exactly that, and a clock reading off the rows alone ticks for days on a
   * thread nothing is working on.
   */
  const openTurnsShown = isSettledRunStatus(activeRunStatus)
    ? undefined
    : openTurnForHeader;
  // A 1:1 chat has exactly one agent, so the transcript needs no per-turn
  // identity: avatars and `claude · 18:43` lines only earn their space when
  // several agents share a flow. Keyed on the RUN (a team run always keeps
  // them), never on "how many agents happened to speak so far" — that would
  // make the frame pop in mid-run as a second node starts.
  const soloAgent = activeRun !== null && activeRun.teamId === null;
  /**
   * The open chat's sub-agents, listed as threads of the agent that launched
   * them, newest last.
   *
   * Sourced from the FOLD rather than from `activity`: the delegates and their
   * state are already derived there, and re-deriving them from the raw items
   * for the panel is the mirror-instead-of-extract shape that put the same
   * logic in four places once before.
   *
   * `stopped` maps to `cancelled` — a delegate whose turn ended before it
   * reported back did stop without completing, and `cancelled` is the only
   * status in the vocabulary that says that. It is the nearest true word, not
   * a claim that the user cancelled it.
   */
  const subagentThreads = useMemo(
    () =>
      withDurableDelegates(
        subagentThreadsByAgent(
          collectSubagentBlocks(durableEntries),
          CHAT_AGENT_KEY,
        ),
        runState.delegates,
        CHAT_AGENT_KEY,
      ),
    [durableEntries, runState.delegates],
  );
  const agents = useMemo((): AgentDisplay[] => {
    if (!activeRun) {
      return [];
    }
    if (!activeRun.teamId) {
      // A 1:1 chat has exactly one agent; its working state is the run's,
      // and its one thread IS the conversation.
      const chatActivity = activity.get(CHAT_AGENT_KEY);
      // `activeTurns` still keys off raw liveness: a chat parked on a question
      // genuinely HAS a turn open, it is just not advancing.
      const running = streaming || activeRun.status === 'running';
      return [
        {
          id: CHAT_AGENT_KEY,
          name: activeRun.agentKind ?? 'agent',
          agent: activeRun.agentKind,
          // What its turns have RUN on, else what the chat asked for. The two
          // differ whenever the run row names nothing (the CLI's own current
          // model) or names something the CLI refused, and the reported one is
          // the answer to "what is this agent".
          model: chatActivity?.contextModel ?? activeRun.model,
          // The profile this chat's turns ACTUALLY run under — the folder's
          // pin where there is one, the chat's own pick otherwise (null on the
          // chats that run as the CLI's default). A team node reads its
          // from the graph; a chat reads its from the run row, and the MCP
          // panel needs it either way — a profile carries its own servers, so
          // two chats in one folder under different profiles genuinely load
          // different sets.
          //
          // The EFFECTIVE one, because this listing answers "what can this
          // agent see": reading the requested profile showed the reporter 15
          // servers while their agent had loaded the pinned profile's 50, one
          // of which was the row they came looking for.
          configDir: effectiveConfigDir(activeRun),
          // The SAME badge rule the header uses. This used to be a second one,
          // built from `streaming` and the row alone, so it could never report
          // `needs-input` — a chat parked on a question read "needs more info"
          // in the header and "running" in this panel at the same instant.
          status: activeRunStatus,
          activeTurns: running ? 1 : 0,
          // LIVE first: the delta plane reports the window as of the turn's
          // latest request, while `activity` can only report the last
          // COMPLETED turn — which is exactly the staleness the meter was
          // criticised for. Falls back the moment the live plane is quiet.
          // …then the RUN ROW, in the composer ring's own order (`chatContext`).
          // Skipping it put the last SETTLED turn's figure on this card beside a
          // ring reading the daemon's newer one — `2%` against `46%` on a
          // thread reopened mid-turn.
          ...agentContextFields(
            chatContextFigures({
              live: liveText.get(CHAT_LIVE_KEY),
              run: activeRun,
              transcript: chatActivity,
              // The card has no recalled reading to fall back on.
              itemsLoaded: true,
              recall: () => null,
            }),
          ),
          // The DAEMON's totals over every turn, the figures the header and
          // the context readout state — the transcript fold covers only the
          // loaded window, so on a long thread it left the oldest turns out and
          // the card read a smaller spend than the readout beside it. The fold
          // stays underneath for the moment before the totals read lands.
          ...spentOf(
            withLiveCost(
              threadTotals.costUsd !== null
                ? {
                    tokens: null,
                    costUsd: threadTotals.costUsd,
                    estimatedCostUsd: threadTotals.estimatedCostUsd,
                  }
                : {
                    tokens: null,
                    costUsd: chatActivity?.spentUsd ?? null,
                    estimatedCostUsd: chatActivity?.spentEstimatedUsd ?? null,
                  },
              liveCostOf(liveText.get(CHAT_LIVE_KEY)),
            ),
          ),
          runningCost: liveCostOf(liveText.get(CHAT_LIVE_KEY)),
          inputTokens:
            threadTotals.inputTokens ?? chatActivity?.inputTokens ?? null,
          outputTokens:
            threadTotals.outputTokens ?? chatActivity?.outputTokens ?? null,
          cacheTokens:
            threadTotals.cacheTokens ?? chatActivity?.cacheTokens ?? null,
          threads: [
            {
              id: 'main',
              kind: 'main',
              label: 'Conversation',
              status: activeRunStatus,
              sessionId: null,
            },
            ...(subagentThreads.get(CHAT_AGENT_KEY) ?? []),
          ],
        },
      ];
    }
    /**
     * One node's call threads, each carrying its OWN context reading — the live
     * one off the per-call owner key the daemon publishes it under
     * (`partialOwnerKey`), and below it the daemon's durable `call_context` row.
     *
     * The durable half is what makes these rings survive: the live plane is
     * dropped the moment a run settles and never exists at all for a window
     * that reloaded, so a per-call ring drawn from it alone shows nothing
     * outside a running turn.
     *
     * The rule itself lives in `resolveConversationContext`, which the call
     * block's own ring reads too, through `resolveCallReading` above. It is
     * written once for the reason `cardContextOf` below gives: an order written
     * down twice is an order two surfaces eventually disagree on.
     */
    /**
     * What a node's CARD states it spent: the daemon's totals over every turn
     * the run wrote, else the window's fold. The fold sums only the loaded
     * window, so on a long run an agent's oldest turns fell out of its cost.
     */
    const nodeSpendOf = (
      memberId: string,
      nodeActivity: AgentActivity | undefined,
    ): Pick<
      AgentDisplay,
      | 'spentUsd'
      | 'spentEstimatedUsd'
      | 'runningCost'
      | 'inputTokens'
      | 'outputTokens'
      | 'cacheTokens'
    > => {
      const totals = nodeReadings.get(memberId)?.totals;
      // What the agent's running turns have spent that no row records yet —
      // its own conversation and every call it is answering — on top of
      // either figure below.
      const live = liveNodeCost(liveText, memberId);
      if (totals === undefined || totals.turns === 0) {
        return {
          ...spentOf(
            withLiveCost(
              {
                tokens: null,
                costUsd: nodeActivity?.spentUsd ?? null,
                estimatedCostUsd: nodeActivity?.spentEstimatedUsd ?? null,
              },
              live,
            ),
          ),
          runningCost: live,
          inputTokens: nodeActivity?.inputTokens ?? null,
          outputTokens: nodeActivity?.outputTokens ?? null,
          cacheTokens: nodeActivity?.cacheTokens ?? null,
        };
      }
      return {
        ...spentOf(
          withLiveCost(
            {
              tokens: null,
              costUsd: totals.costUsd,
              estimatedCostUsd: totals.estimatedCostUsd,
            },
            live,
          ),
        ),
        runningCost: live,
        inputTokens: totals.inputTokens,
        outputTokens: totals.outputTokens,
        cacheTokens:
          totals.cacheReadTokens === null && totals.cacheCreationTokens === null
            ? null
            : (totals.cacheReadTokens ?? 0) + (totals.cacheCreationTokens ?? 0),
      };
    };
    const stateCalls = new Map(
      runState.calls.map((call) => [call.callId, call] as const),
    );
    /**
     * The pool member a conversation runs on: its newest call's card when the
     * window holds one (which sees a hand-off the moment it lands), else the
     * daemon's list of the run's calls. A conversation stays on one member.
     */
    const conversationMember = (
      block: CallBlockEntry | undefined,
      callIds: readonly string[],
    ): number | null =>
      block?.member ??
      stateCalls.get(callIds[callIds.length - 1] ?? '')?.member ??
      null;
    const callThreadsOf = (
      memberId: string,
      nodeActivity: AgentActivity | undefined,
    ): AgentThread[] => {
      const fromWindow = threadsOf(nodeActivity).map((thread): AgentThread => {
        if (thread.kind === 'main') {
          // The node's OWN conversation streams on the node's own key, and that
          // live reading outranks the one folded from its settled turns.
          const live = liveText.get(memberId);
          // The node's own conversation's spend, over the whole run, plus what
          // its running turn has spent that no row records yet.
          const spend = withLiveCost(
            spendOfTotals(nodeReadings.get(memberId)?.mainTotals),
            liveCostOf(live),
          );
          return {
            ...thread,
            contextTokens: live?.contextTokens ?? thread.contextTokens ?? null,
            contextEstimated:
              live?.contextTokens == null && thread.contextEstimated === true,
            contextWindowTokens:
              live?.contextWindowTokens ?? thread.contextWindowTokens ?? null,
            spentTokens: spend?.tokens ?? thread.spentTokens ?? null,
            ...(spend?.costUsd != null
              ? spentOf(spend)
              : {
                  spentUsd: thread.spentUsd ?? null,
                  spentEstimatedUsd: thread.spentEstimatedUsd ?? null,
                }),
            promptCacheExpiresAt:
              nodeReadings.get(memberId)?.promptCacheExpiresAt ?? null,
          };
        }
        if (thread.kind !== 'call') {
          return thread;
        }
        const block = callBlockOfConversation(callBlockIndex, thread.callIds);
        // A call the page reads as out but the daemon says is over — the page
        // holds its start and not its end — is over (`callEndedPerDaemon`).
        const openCallIds = thread.openCallIds.filter(
          (callId) => callEndedPerDaemon(stateCalls, runState, callId) === null,
        );
        const status =
          thread.status === 'running' && openCallIds.length === 0
            ? (callEndedPerDaemon(
                stateCalls,
                runState,
                thread.callIds[thread.callIds.length - 1] ?? '',
              ) ?? thread.status)
            : // The activity fold opens every call as running at its
              // `call_started`; the card knows it is still waiting to start.
              thread.status === 'running' && block?.queued === true
              ? 'queued'
              : thread.status;
        // The daemon's whole-run figure first: the window's fold sums only the
        // turns it holds, so a conversation started above it read a fraction.
        const usage = withLiveCost(
          resolveConversationSpend(nodeReadings, memberId, thread.callIds) ??
            (block === undefined ? null : callBlockUsage(block)),
          liveConversationCost(liveText, memberId, thread.callIds),
        );
        return {
          ...thread,
          openCallIds,
          status,
          // The conversation's newest call carrying a reading — the latest
          // call's, until a continuation that has not reported yet has one.
          ...resolveConversationContext(
            liveText,
            nodeReadings,
            memberId,
            thread.callIds,
          ),
          latest: block === undefined ? null : callBlockLatest(block),
          spentTokens: usage?.tokens ?? null,
          ...spentOf(usage),
          member: conversationMember(block, thread.callIds),
          promptCacheExpiresAt: resolveConversationCacheExpiry(
            nodeReadings,
            memberId,
            thread.callIds,
          ),
          clocks: conversationClocks(callClocks, thread.callIds),
        };
      });
      // Calls OLDER than the loaded window, known only from the daemon's
      // per-call readings. A call's `call_started` row is the only thing that
      // names it in the transcript, so a node called earlier in a long run had
      // a ring on its card and no instance at all — REPORTED as "strange
      // researcher card with some context but without calls". Each keeps its
      // own ring; it is `running` only while its own key is streaming.
      //
      // How each such call STANDS and what it was asked comes from the daemon's
      // own list of the run's calls (`runState.calls`), which covers every call
      // where the readings are capped and carry a window and nothing else. A
      // call whose rows the window holds has a block, built from its anchored
      // start and settle, and the block's reading is fresher still.
      // EVERY call a window conversation holds, not only its head: a
      // conversation continued with `thread` is one instance, so its earlier
      // calls listed again here drew the same Engineer twice — and, once spend
      // came from the whole run, counted its cost twice.
      const inWindow = new Set(
        fromWindow.flatMap((thread) =>
          thread.kind === 'call' ? [thread.id, ...thread.callIds] : [thread.id],
        ),
      );
      const readings = nodeReadings.get(memberId)?.calls ?? [];
      const olderIds = [
        ...new Set([
          ...readings.map((call) => call.callId),
          ...runState.calls
            .filter((call) => call.calleeMemberId === memberId)
            .map((call) => call.callId),
          ...[...callBlockIndex.values()]
            .filter((block) => block.calleeMemberId === memberId)
            .map((block) => block.callId),
        ]),
      ]
        .filter((callId) => !inWindow.has(callId))
        .sort(compareCallIds);
      const statusOfCall = (callId: string): RunStatusKind => {
        const block = callBlockIndex.get(callId);
        const recorded = stateCalls.get(callId);
        return block !== undefined
          ? (callEndedPerDaemon(stateCalls, runState, callId) ??
              callThreadStatusOf(block))
          : recorded !== undefined
            ? recorded.status === 'running' && recorded.queued
              ? 'queued'
              : recorded.status
            : liveText.has(partialOwnerKey(memberId, callId))
              ? 'running'
              : 'completed';
      };
      // One instance per CONVERSATION, as the window's own threads are: a call
      // continued with `thread` is the same callee session, so listing each of
      // its calls drew one Engineer per message it was sent.
      const conversations = new Map<string, string[]>();
      for (const callId of olderIds) {
        const root = conversationRoot(callChains, callId);
        conversations.set(root, [...(conversations.get(root) ?? []), callId]);
      }
      const older = [...conversations.values()].map((callIds): AgentThread => {
        const head = callIds[callIds.length - 1]!;
        const block = callBlockOfConversation(callBlockIndex, callIds);
        const usage = withLiveCost(
          resolveConversationSpend(nodeReadings, memberId, callIds) ??
            (block === undefined ? null : callBlockUsage(block)),
          liveConversationCost(liveText, memberId, callIds),
        );
        const openCallIds = callIds.filter((callId) => {
          const status = statusOfCall(callId);
          return (
            status === 'running' ||
            status === 'pending' ||
            status === 'held' ||
            status === 'queued'
          );
        });
        const status =
          openCallIds.length === 0
            ? statusOfCall(head)
            : openCallIds.every((callId) => statusOfCall(callId) === 'queued')
              ? 'queued'
              : 'running';
        return {
          id: head,
          kind: 'call',
          label: head,
          brief: block?.message ?? stateCalls.get(head)?.brief ?? null,
          status,
          callIds,
          openCallIds,
          sessionId: null,
          ...resolveConversationContext(
            liveText,
            nodeReadings,
            memberId,
            callIds,
          ),
          latest: block === undefined ? null : callBlockLatest(block),
          spentTokens: usage?.tokens ?? null,
          ...spentOf(usage),
          member: conversationMember(block, callIds),
          promptCacheExpiresAt: resolveConversationCacheExpiry(
            nodeReadings,
            memberId,
            callIds,
          ),
          clocks: conversationClocks(callClocks, callIds),
        };
      });
      // After the node's own conversation, before the calls the window holds —
      // they are older than anything on screen.
      const mainAt =
        fromWindow.findIndex((thread) => thread.kind === 'main') + 1;
      return [
        ...fromWindow.slice(0, mainAt),
        ...older,
        ...fromWindow.slice(mainAt),
      ];
    };
    /**
     * WHICH reading a node's CARD states — resolved as ONE source per rank, so
     * a count from one turn is not drawn over a window from another. The count
     * and the window can still come from different PLANES within one call
     * thread (`callThreadsOf` prefers live per figure), which is safe because a
     * window is a property of the model and does not move between that call's
     * turns.
     *
     * The node's own key is a DAG-scheduled turn, and LIVE beats durable for
     * the reason the 1:1 branch above gives: a delta reports the node's context
     * as of its latest request, while `activity` can only report its last
     * COMPLETED turn.
     *
     * A CALLEE node has no DAG-scheduled turn at all — every turn it takes runs
     * under a call, so the executor publishes its readings under that CALL's
     * key and the node's own key never receives one. REPORTED as "I dont see QA
     * context", against a running cursor node whose thread row showed a figure
     * and whose card showed an empty ring. The newest thread wins because a
     * node runs one turn per call and the list is in call order, so the last
     * one carrying a reading is the turn now in flight.
     *
     * Shared by both branches below: the second one had the identical hole, and
     * two copies of this order is how a card and its own thread rows come to
     * disagree about one window.
     */
    const cardContextOf = (
      memberId: string,
      nodeActivity: AgentActivity | undefined,
      callThreads: readonly AgentThread[],
    ): {
      contextTokens?: number | null;
      contextWindowTokens?: number | null;
      contextEstimated?: boolean;
    } => {
      const own = liveText.get(memberId);
      if ((own?.contextTokens ?? null) !== null) {
        return own!;
      }
      // Asked of the live plane DIRECTLY rather than of the thread's own
      // figure, which now falls back to the durable row: without that the two
      // ranks below collapse into one, and a stale-but-newer call thread would
      // outrank the one actually streaming.
      const liveThread = [...callThreads]
        .reverse()
        .find(
          (thread) =>
            (liveText.get(partialOwnerKey(memberId, thread.id))
              ?.contextTokens ?? null) !== null,
        );
      if (liveThread !== undefined) {
        return liveThread;
      }
      // Then the newest call thread carrying a DURABLE reading — but only for a
      // node that runs nothing BUT calls. `node_state` is written on every
      // reading while `call_context` is written only under a call, so for a node
      // whose own DAG turn ran after its last call the row below holds the newer
      // figure and this rank would hand back a staler one. `threadsOf` emits a
      // `main` thread exactly when that turn happened, which is the test.
      const ownTurn = callThreads.some((thread) => thread.kind === 'main');
      const durableThread = ownTurn
        ? undefined
        : [...callThreads]
            .reverse()
            .find((thread) => (thread.contextTokens ?? null) !== null);
      if (durableThread !== undefined) {
        return durableThread;
      }
      // The daemon's own `node_state` row, which outranks the transcript for
      // the reason the run row outranks it on a chat: it moves with every
      // reading the CLI reports, while the transcript can only carry a figure
      // per SETTLED turn. This is the source that makes a reloaded window — or
      // a node parked in `await_agent`, which emits nothing for minutes — draw
      // a ring at all.
      const row = nodeReadings.get(memberId);
      if (row !== undefined && row.contextTokens !== null) {
        return row;
      }
      return nodeActivity ?? {};
    };
    const known = wfNodes.agents.map((node): AgentDisplay => {
      const nodeActivity = activity.get(node.id);
      const callThreads = callThreadsOf(node.id, nodeActivity);
      const nodeContext = cardContextOf(node.id, nodeActivity, callThreads);
      return {
        id: node.id,
        name: node.name ?? node.id,
        agent: node.agent,
        // The graph's own value is the FALLBACK, not the answer: it is what
        // this node was told to use, and a node that names none runs on the
        // CLI's current model. A node yet to take a turn has only that.
        model:
          nodeActivity?.contextModel ??
          nodeReadings.get(node.id)?.model ??
          node.model ??
          null,
        configDir: node.configDir ?? null,
        ...(node.pool?.length
          ? {
              pool: node.pool.map((member) => ({
                agent: member.agent,
                model: member.model ?? null,
                configDir: member.configDir ?? null,
              })),
              configuredModel: node.model ?? null,
            }
          : {}),
        ...ownPoolOf(nodeReadings.get(node.id)),
        // The card is per NODE (`awaitingAnswer` keys by the item's own node),
        // so the agent that is waiting is the one that says so — a run-level
        // reading would park every node in the graph at once.
        status: displayStatus(nodeActivity, awaitingAnswer.has(node.id)),
        activeTurns: nodeActivity?.activeTurns ?? 0,
        contextTokens: nodeContext?.contextTokens ?? null,
        contextEstimated: nodeContext?.contextEstimated === true,
        contextWindowTokens: nodeContext?.contextWindowTokens ?? null,
        ...nodeSpendOf(node.id, nodeActivity),
        threads: [...callThreads, ...(subagentThreads.get(node.id) ?? [])],
      };
    });
    // Items can reference nodes a since-edited team no longer has — list
    // them too (unnamed) rather than hiding work that visibly happened.
    const extras = [...activity.entries()]
      .filter(
        ([memberId]) =>
          memberId !== CHAT_AGENT_KEY && !wfNodes.allIds.has(memberId),
      )
      .map(([memberId, nodeActivity]): AgentDisplay => {
        const callThreads = callThreadsOf(memberId, nodeActivity);
        const nodeContext = cardContextOf(memberId, nodeActivity, callThreads);
        return {
          id: memberId,
          name: memberId,
          agent: null,
          // Only what its turns reported: the team no longer has this node,
          // so there is no declared value to fall back to.
          model:
            nodeActivity.contextModel ??
            nodeReadings.get(memberId)?.model ??
            null,
          // The team no longer has this node, so nothing states what it ran
          // with. Claiming a config directory here would be an invention.
          configDir: null,
          status: displayStatus(nodeActivity, awaitingAnswer.has(memberId)),
          activeTurns: nodeActivity.activeTurns,
          contextTokens: nodeContext.contextTokens ?? null,
          contextEstimated: nodeContext.contextEstimated === true,
          contextWindowTokens: nodeContext.contextWindowTokens ?? null,
          ...nodeSpendOf(memberId, nodeActivity),
          threads: [...callThreads, ...(subagentThreads.get(memberId) ?? [])],
        };
      });
    return [...known, ...extras];
    // `liveText` is READ above for the live context figure, so it belongs here:
    // without it the meter could only move when a durable item landed, which is
    // the "context never grows" complaint this panel exists to answer. There is
    // no react-hooks eslint plugin in this repo to catch the omission.
    //
    // `nodeReadings` for the same reason and a sharper case: it publishes a new
    // Map only when its own fetch resolves, and a settled team run reopened
    // — or a reconnect whose replay is empty — moves nothing else afterwards,
    // so without it the durable rings stay blank on exactly the reload they
    // exist for.
  }, [
    activeRun,
    activeRunStatus,
    activity,
    awaitingAnswer,
    callBlockIndex,
    callChains,
    callClocks,
    streaming,
    wfNodes,
    liveText,
    nodeReadings,
    runState,
    subagentThreads,
    threadTotals.costUsd,
    threadTotals.inputTokens,
    threadTotals.outputTokens,
    threadTotals.cacheTokens,
  ]);
  /** A node's agent by name, for the shelf's team-note and monitor chips — the panel has its own. */
  const goalRunId = activeRun?.id ?? null;
  const goalsArchived = activeRun?.archivedAt != null;
  const goalRun = (): string => {
    if (goalRunId === null) {
      throw new Error('No thread is open.');
    }
    return goalRunId;
  };
  const addGoal = useLatestCallback(
    (text: string) =>
      chatApi.addRunGoal({ runId: goalRun(), createRunGoalDto: { text } }),
    [chatApi, goalRunId],
  );
  const editGoal = useLatestCallback(
    (goalId: string, text: string) =>
      chatApi.editRunGoal({
        runId: goalRun(),
        goalId,
        editRunGoalDto: { text },
      }),
    [chatApi, goalRunId],
  );
  const closeGoal = useLatestCallback(
    (
      goalId: string,
      status: CloseRunGoalDtoGoalClosingStatus,
      evidence: string,
    ) =>
      chatApi.closeRunGoal({
        runId: goalRun(),
        goalId,
        closeRunGoalDto: { status, evidence },
      }),
    [chatApi, goalRunId],
  );
  const reopenGoal = useLatestCallback(
    (goalId: string) => chatApi.reopenRunGoal({ runId: goalRun(), goalId }),
    [chatApi, goalRunId],
  );
  const goalActions = useMemo(
    (): GoalsActions | undefined =>
      goalRunId === null || goalsArchived
        ? undefined
        : {
            add: addGoal,
            edit: editGoal,
            close: closeGoal,
            reopen: reopenGoal,
          },
    [goalRunId, goalsArchived, addGoal, editGoal, closeGoal, reopenGoal],
  );
  const runGoals = useMemo(
    (): RunGoals | undefined =>
      activeRun === undefined || activeRun === null
        ? undefined
        : {
            goals: activeRun.goals ?? [],
            outcome: activeRun.outcome ?? null,
            actions: goalActions,
          },
    [activeRun, goalActions],
  );

  const shelfAgentName = useLatestCallback(
    (memberId: string): string => agentNameOf(agents, memberId),
    [agents],
  );

  /**
   * What the composer's ring shows — this chat's own context, and never
   * another's.
   *
   * A team run has no single context of its own — its nodes each hold a
   * window — so the ring draws its ROOT agent's, which is the one the user
   * prompted and the one the run is about. `agents[0]` is not that node: it is
   * whichever happens to be first. A graph with no single root (none,
   * or several) leaves it withheld, as does a team whose definition has not
   * arrived yet — `runLead` is null in all three, and a run-level figure
   * invented for them would be a number about nothing.
   *
   * Three sources, freshest first. The live delta is this turn's latest
   * REQUEST, the RUN ROW is the last reading the daemon filed (one per
   * main-thread model response, so it moves inside a turn), and the transcript
   * can only offer the last SETTLED turn.
   *
   * The row is what closes the reported defect: a ring reading `2%` beside a
   * panel reading `46%`. The last settled turn had ended directly after a
   * `/compact`, so the transcript's newest figure was 16.7k of 1M, and the hour
   * of work since had regrown the window to 462k with no settled turn to record
   * it. The live plane had that figure and is EPHEMERAL — a reload, a
   * reconnect, or a chat opened for the first time this session starts without
   * one — and the transcript cannot have it at all, since it is not written
   * there until the turn ends.
   *
   * The chain is a strict recency order and nothing compares the figures: each
   * source measures a later moment than the one after it, so a plain `??` is
   * the whole rule. Reading the live delta HERE rather than through `agents[0]`
   * is what makes that true — that field already collapses the live plane onto
   * the transcript, which would have put the oldest source ahead of the row.
   *
   * {@link recallContextReading} is last and covers what none of them can: the
   * stretch during which a chat switch has cleared the transcript and its
   * refetch has not landed, where the ring used to go value → gone → value
   * under a name that had already changed.
   */
  const chatContext = useMemo(() => {
    if (activeRun === null) {
      return { tokens: null, window: null };
    }
    if (activeRun.teamId) {
      // Already resolved through `cardContextOf`'s own four-tier chain, so the
      // root's ring here and its card in the panel cannot disagree.
      const root =
        runLead === null
          ? undefined
          : agents.find((agent) => agent.id === runLead);
      return {
        tokens: root?.contextTokens ?? null,
        window: root?.contextWindowTokens ?? null,
        estimated: root?.contextEstimated === true,
      };
    }
    return chatContextFigures({
      live: liveText.get(CHAT_LIVE_KEY),
      run: activeRun,
      transcript: agents[0],
      itemsLoaded: items.length > 0,
      recall: () => recallContextReading(activeRun.id),
    });
  }, [
    activeRun,
    agents,
    items.length,
    liveText,
    recallContextReading,
    runLead,
  ]);
  /** Why the ring has no figure, when that is worth drawing — see `useContextRing`. */
  const awaitingReading = useContextRing({
    runId: activeRunId,
    figures: chatContext,
    items,
    remember: rememberContextReading,
    forget: forgetContextReading,
  });
  /**
   * The shells each agent has running right now — read by the panel's section
   * and by the header's counter, which is why the LIVENESS RULE lives here
   * rather than in either of them.
   *
   * Re-keyed to the panel's agent ids, exactly as the task lists above are and
   * for the same reason: a 1:1 chat's rows carry `nodeId: null` while its card
   * is keyed by `CHAT_AGENT_KEY`, and that mapping belongs to this screen
   * rather than to the fold.
   *
   * The gate applies to FOREGROUND commands only, and the split is the whole
   * of it. A foreground shell is read as running because its tool call has no
   * reply — a reading a cancelled or abandoned turn makes permanently false, so
   * every such row would stand for the rest of the session claiming a process
   * that died with the turn. `isSettledRunStatus` — has this agent stopped for
   * good — is the app's own answer to exactly that.
   *
   * A BACKGROUND command is not read that way and must not be gated that way.
   * Its call is answered within the second, its end is a durable row the daemon
   * writes (`shell_info`), and the daemon writes one for every shell still open
   * when the CLI process dies — so its liveness is REPORTED rather than
   * inferred, and the run settling says nothing about it. Gating it here is
   * what made the panel go blank on precisely the case it exists for: the
   * agent finishes, the turn settles, and the `pnpm dev` it started keeps
   * running with nothing on screen saying so.
   *
   * The ONE report that can go missing is the one a dying daemon cannot make:
   * announcements are suppressed during shutdown, so a command open at that
   * moment gets no row — measured, a `sleep 1200` killed with its group and
   * four transcript rows with no `shell_info` among them. That gap is closed
   * from the other end rather than by writing during a teardown: an agent's CLI
   * cannot outlive the daemon that spawned it, so a command launched before
   * THIS daemon's `startedAt` is over whatever the transcript says.
   */
  const shellsByAgent = useMemo(() => {
    const working = new Set(
      agents
        .filter((agent) => !isSettledRunStatus(agent.status))
        .map((a) => a.id),
    );
    const daemonStartedAt = Date.parse(handle.startedAt);
    const stillRunning = (shell: ShellRun): boolean => {
      const startedAt = Date.parse(shell.startedAt);
      // An unparseable stamp on either side proves nothing, so it decides
      // nothing: the row stands on whatever the transcript said.
      return (
        !Number.isFinite(daemonStartedAt) ||
        !Number.isFinite(startedAt) ||
        startedAt >= daemonStartedAt
      );
    };
    // WORKING is decided per conversation as well as per agent. A node called
    // several times holds several conversations at once, and a call that has
    // SETTLED took its foreground commands with it even while its siblings work
    // on — so the node being busy says nothing about that call's own
    // unanswered command, which would otherwise stand for the rest of the
    // session. The same rule the agent-level gate states, one level down.
    const settledCalls = new Set<string>();
    for (const agent of agents) {
      for (const thread of agent.threads) {
        if (thread.kind !== 'call') {
          continue;
        }
        // Each call of a continued conversation is asked for its OWN state:
        // two continuations of one thread can run at once, so a call is not
        // over merely for being earlier than the latest.
        for (const callId of thread.callIds) {
          if (!thread.openCallIds.includes(callId)) {
            settledCalls.add(JSON.stringify([agent.id, callId]));
          }
        }
      }
    }
    const byAgent = new Map<string, ShellRun[]>();
    // The open turns' unanswered calls the daemon read are folded in with the
    // page — a foreground command running while the reader is elsewhere in the
    // conversation — and what the daemon says has ended is dropped.
    const runs = withoutDaemonEndedShells(
      shellRuns(withAnchors(transcriptRows, runState.openToolCalls)),
      runState,
    );
    for (const [memberId, shells] of withDurableShells(
      groupRunningShells(runs),
      runs,
      runState.shells,
    )) {
      const key = memberId ?? CHAT_AGENT_KEY;
      const isWorking = (shell: ShellRun): boolean =>
        working.has(key) &&
        (shell.callId === null ||
          !settledCalls.has(JSON.stringify([key, shell.callId])));
      const live = shells.filter((shell) =>
        isWorking(shell)
          ? !shell.background || stillRunning(shell)
          : shell.background && stillRunning(shell),
      );
      if (live.length > 0) {
        byAgent.set(key, live);
      }
    }
    return byAgent;
  }, [agents, handle.startedAt, transcriptRows, runState]);
  /**
   * Worked time and tool count per agent — the pair each card draws under its
   * spend line, keyed like `shellsByAgent` above.
   *
   * DURABLE OUTRANKS THE TRANSCRIPT, and that order is the whole point. A fold
   * over `items` can only see the window this client loaded (`HISTORY_PAGE`), so
   * on a long thread it is a fraction of the answer presented as the whole of
   * it. The daemon totals both figures across every turn instead — on the NODE
   * row for a team node, and on the RUN row for a 1:1 chat, which is the
   * same split `contextTokens` already follows. The fold stays underneath as the
   * first-turn answer, before either row has been written.
   *
   * A delegate's rows are excluded, on `shell-activity.ts`'s rule — a
   * sub-agent has its own card, and folding its toolbelt into its launcher's
   * would report a fan-out's total as one agent's.
   */
  const workByAgent = useMemo(() => {
    const byAgent = new Map<string, AgentWork>();
    const entryFor = (key: string): AgentWork => {
      const found = byAgent.get(key);
      if (found !== undefined) {
        return found;
      }
      const fresh = { workedMs: null, toolCalls: null };
      byAgent.set(key, fresh);
      return fresh;
    };
    // The tools each agent's turn in flight has called so far — a durable
    // count only moves when a turn settles.
    const openSince = new Map(
      (openTurnsShown ?? []).map(
        (turn) => [turn.agentKey, turn.startedAt] as const,
      ),
    );
    const inFlightTools = new Map<string, number>();
    for (const item of transcriptRows) {
      if (subagentIdOf(item) !== null) {
        continue;
      }
      const key = item.memberId ?? CHAT_AGENT_KEY;
      const settled = turnDurations.get(item.id);
      if (settled !== undefined) {
        const entry = entryFor(key);
        entry.workedMs = (entry.workedMs ?? 0) + settled.ms;
      }
      if (item.kind === 'tool_call') {
        const entry = entryFor(key);
        entry.toolCalls = (entry.toolCalls ?? 0) + 1;
        const since = openSince.get(key);
        if (since !== undefined && Date.parse(item.createdAt) >= since) {
          inFlightTools.set(key, (inFlightTools.get(key) ?? 0) + 1);
        }
      }
    }
    // The daemon's figure ALONE wherever it has one: it counts every turn the
    // agent settled, while the fold counts the loaded window's. The turn in
    // flight is added on top — its time by each card (`openTurns`), its tools
    // here — so nothing has to stay ahead of a settle.
    const durableTools = (key: string, settled: number): number =>
      settled + (inFlightTools.get(key) ?? 0);
    for (const [memberId, reading] of nodeReadings) {
      if (reading.workedMs === null && reading.toolCalls === null) {
        continue;
      }
      const entry = entryFor(memberId);
      if (reading.workedMs !== null) {
        entry.workedMs = reading.workedMs;
      }
      if (reading.toolCalls !== null) {
        entry.toolCalls = durableTools(memberId, reading.toolCalls);
      }
    }
    // A 1:1 CHAT's durable totals are on the RUN row rather than a node row —
    // the same split `contextTokens` follows — so they arrive with the run this
    // window already holds and cost no second fetch. The row is kept current by
    // the SETTLE announce (`RunStatusEvent.workedMs` / `.toolCalls`), which had
    // to be added for this: without it the copy fetched at open never moved, and
    // since a durable total outranks the fold on any chat past `HISTORY_PAGE`
    // items, the card's clock climbed through a turn and then dropped back by
    // the whole of it the moment that turn settled.
    if (activeRun !== null && activeRun.teamId == null) {
      const entry = entryFor(CHAT_AGENT_KEY);
      if (activeRun.workedMs !== null) {
        entry.workedMs = activeRun.workedMs;
      }
      if (activeRun.toolCalls !== null) {
        entry.toolCalls = durableTools(CHAT_AGENT_KEY, activeRun.toolCalls);
      }
    }
    return byAgent;
  }, [transcriptRows, turnDurations, nodeReadings, activeRun, openTurnsShown]);
  /**
   * What the side panel is holding RIGHT NOW, as two numbers for the header
   * beside its toggle: delegates still working, and tasks still outstanding.
   *
   * The panel is where both live, and a closed panel said nothing about either
   * — so a turn that had fanned out to four sub-agents looked exactly like one
   * that had fanned out to none. Counted from the same state the panel renders
   * (`agents[].threads`, `tasksByAgent`), never re-derived, so the badge and
   * the list it points at cannot disagree.
   *
   * The DELEGATE count is the live half only: a finished delegate is history,
   * and a counter that included it would climb all turn and never come down.
   *
   * The TASK figure is a pair — done out of total — for the opposite reason. A
   * lone "still to go" is what got reported: `6` says nothing about whether
   * that is six of seven or six of sixty, and it can only shrink, so it reads
   * as a countdown out of a number the header never states. `done/total` is
   * also how the transcript cards, the panel and the sub-agent headers all say
   * it, so this is the header joining that sentence rather than inventing one.
   *
   * The SHELLS are the third — asked for beside the delegate count, and the
   * same kind of reading: how much of this machine the thread is using right
   * now. Flattened out of the very map the panel's sections render, liveness
   * rule included, so the counter and the cards below it cannot disagree about
   * what is running.
   */
  const sidePanelLive = useMemo(() => {
    // The delegates THEMSELVES, not merely how many are working: the header's
    // counter holds the list behind it now, and re-deriving that list wherever
    // it is drawn would be a second reading of the same threads.
    const subagentThreads: AgentThread[] = [];
    // Kept per agent BESIDE that flat run, off the same walk: a team's
    // popover draws one block per agent, exactly as its task chip does.
    const subagentGroups: AgentSubagentGroup[] = [];
    let subagents = 0;
    const rootAgentIds = activeRun?.teamId ? new Set(feedIds) : null;
    for (const agent of agents) {
      if (rootAgentIds !== null && !rootAgentIds.has(agent.id)) {
        continue;
      }
      const own: AgentThread[] = [];
      for (const thread of agent.threads) {
        if (thread.kind !== 'subagent') {
          continue;
        }
        own.push(thread);
        if (thread.status === 'running') {
          subagents += 1;
        }
      }
      subagentThreads.push(...own);
      if (own.length > 0) {
        subagentGroups.push({
          agentId: agent.id,
          agentName: agent.name,
          threads: own,
        });
      }
    }
    let done = 0;
    let total = 0;
    // Flattened in the panel's own agent order, so the popover's list reads
    // top-to-bottom as the cards below it do — and kept per agent BESIDE that
    // flat run, off the one walk, because a team's popover draws a block
    // per agent and re-deriving the split where it is drawn would be a second
    // reading of one set of rows.
    const taskRows: AgentTaskRow[] = [];
    const taskGroups: AgentTaskGroup[] = [];
    const seenTaskAgents = new Set<string>();
    const takeTasks = (agentId: string, agentName: string): void => {
      if (seenTaskAgents.has(agentId)) {
        return;
      }
      seenTaskAgents.add(agentId);
      const lists = (tasksByAgent.get(agentId) ?? []).filter(
        (list) => list.tasks.length > 0,
      );
      for (const list of lists) {
        const progress = taskProgress(list.tasks);
        done += progress.done;
        total += progress.total;
        taskRows.push(...list.tasks);
        // One block per CONVERSATION, named for it when the agent keeps more
        // than one — two instances' plans are two plans, the rule this popover
        // already applies between two agents.
        const several = lists.length > 1;
        taskGroups.push({
          agentId: several ? `${agentId}\u0000${list.threadId}` : agentId,
          agentName: several
            ? `${agentName} · ${list.threadId === MAIN_THREAD_ID ? 'main' : list.threadId}`
            : agentName,
          tasks: list.tasks,
        });
      }
    };
    for (const agent of agents) {
      takeTasks(agent.id, agent.name);
    }
    // Anything that announced a list without earning a card — the totals are
    // the SHELF's figure, so a set left out of this walk would be rows the
    // popover lists under a count that never counted them.
    for (const agentId of tasksByAgent.keys()) {
      takeTasks(agentId, agentId);
    }
    // In the panel's own agent order, like the task rows above — the popover
    // reads top-to-bottom as the cards below it do.
    const shells: ShellRun[] = [];
    // WHOSE each command is, built on the same walk that flattens them — a map
    // rather than a field on the row, so `ShellRun` stays what the transcript
    // fold produces and the agents panel's own bands are untouched. Whether it
    // is USED is the caller's call (see the shelf's `agentNameOf`): naming the
    // one agent of a 1:1 chat on every row would be a column of one word.
    const shellAgents = new Map<string, string>();
    // The detached commands whose call has FINISHED, keyed by shell id — still
    // running only because they outlived it, which the row must say, or a
    // command under a call that answered long ago reads as that call's live
    // work. Decided per conversation, as the label is: a continuation still
    // open keeps the commands its earlier calls started.
    const shellsLeftRunning = new Map<string, string>();
    for (const agent of agents) {
      const settledCallIds = new Set(
        agent.threads.flatMap((thread) =>
          thread.kind === 'call' && thread.openCallIds.length === 0
            ? thread.callIds
            : [],
        ),
      );
      const own = shellsByAgent.get(agent.id) ?? [];
      shells.push(...own);
      for (const shell of own) {
        // Named for its INSTANCE when a call started it — two Engineers each
        // running `pnpm test` are otherwise one name printed twice.
        // A continued conversation is one instance, named by its latest call.
        if (shell.callId === null) {
          shellAgents.set(shell.id, agent.name);
          continue;
        }
        const head = conversationHead(callChains, shell.callId);
        shellAgents.set(shell.id, `${agent.name} · ${head}`);
        if (shell.background && settledCallIds.has(shell.callId)) {
          shellsLeftRunning.set(
            shell.id,
            `Left running by ${agent.name} after ${head} finished — it keeps running until it is stopped`,
          );
        }
      }
    }
    return {
      subagents,
      subagentThreads,
      subagentGroups,
      tasks: { done, total },
      taskRows,
      taskGroups,
      shells,
      shellAgents,
      shellsLeftRunning,
    };
  }, [
    agents,
    shellsByAgent,
    tasksByAgent,
    callChains,
    activeRun?.teamId,
    feedIds,
  ]);

  /**
   * Which sub-agent's detail panel is open, by the id of the tool call that
   * launched it — an ID rather than the block itself, so the panel follows the
   * LIVE fold as the delegate keeps working instead of freezing the snapshot
   * it was opened from.
   */
  const [detailSubagentId, setDetailSubagentId] = useState<string | null>(null);
  /**
   * The command whose output is open, or null.
   *
   * The ROW rather than its id, unlike the sub-agent detail beside it: a shell
   * leaves the running list the moment it settles, so following the live fold
   * would close the dialog under the reader at exactly the moment they came to
   * see how it ended. The command, its clock and its status are a snapshot; the
   * OUTPUT is what stays live, and that is re-read from the daemon.
   */
  const [openShell, setOpenShell] = useState<ShellRun | null>(null);
  const detailSubagent = useMemo(
    (): SubagentBlockEntry | null =>
      detailSubagentId === null
        ? null
        : (collectSubagentBlocks(transcriptEntries).find(
            (block) => block.id === detailSubagentId,
          ) ?? null),
    [detailSubagentId, transcriptEntries],
  );
  const openSubagentDetail = useLatestCallback(
    (block: SubagentBlockEntry) => setDetailSubagentId(block.id),
    [],
  );
  /**
   * Open a delegate's detail from a list that names it by id — the panel's
   * cards, the shelf's chip. A delegate launched before the loaded page has no
   * block to open, so the window first moves to its launch, where the block is.
   */
  const openSubagentById = useLatestCallback(
    (id: string): void => {
      setDetailSubagentId(id);
      if (collectSubagentBlocks(durableEntries).some((b) => b.id === id)) {
        return;
      }
      const delegate = runState.delegates.find((each) => each.id === id);
      if (delegate !== undefined) {
        void jumpToSeq(delegate.launchSeq);
      }
    },
    [durableEntries, runState.delegates, jumpToSeq],
  );

  const startedAgentsWork = useMemo((): ConversationWorkSource => {
    const byCall = conversationWorkByCall({
      agents,
      shellsByAgent,
      monitors: runState.monitors,
      tasksByAgent,
      notes: teamNotes,
      actions: chatActions.actions,
    });
    return {
      of: (callIds) => conversationWorkOf(byCall, callIds),
      agentName: shelfAgentName,
      phases: chatActions.phases,
      onPressAction: chatActions.press,
      onDismissAction: chatActions.dismiss,
      onOpenNote: (seq) => setNotesView({ selected: seq }),
      onOpenShell: setOpenShell,
      onKillShell: handleKillShell,
      onStopMonitor: handleStopMonitor,
      onOpenSubagent: openSubagentById,
    };
  }, [
    agents,
    shellsByAgent,
    runState.monitors,
    tasksByAgent,
    teamNotes,
    chatActions,
    shelfAgentName,
    handleKillShell,
    handleStopMonitor,
    openSubagentById,
  ]);

  /**
   * Where this thread can be picked up by hand: the CLI invocation that reopens
   * its session, or the reason there is none. Shared by the button's action and
   * by the hint it shows on hover, so the command a user copies is exactly the
   * one the button would run.
   */
  const resolveHandoff = useLatestCallback(
    (agent: AgentDisplay, thread: AgentThread) =>
      handoffApi.resolveHandoff({
        runId: activeRunIdRef.current ?? '',
        ...(agent.id === CHAT_AGENT_KEY ? {} : { memberId: agent.id }),
        // A call thread names its OWN sub-session; a main thread lets the
        // daemon resolve the node's latest from node_state.
        ...(thread.sessionId !== null ? { sessionId: thread.sessionId } : {}),
      }),
    [handoffApi],
  );

  /** Binds this screen's error slot to the shared handoff opener. */
  const openResolvedTarget = useLatestCallback(
    (
      resolve: () => Promise<HandoffTargetDto>,
      fallback: string,
    ): Promise<void> => openResolvedHandoff(resolve, fallback, setError),
    [],
  );

  /**
   * Hand ONE thread of one agent to the user: open that agent's own CLI on the
   * thread's conversation, in the user's terminal.
   *
   * The daemon resolves the invocation, the Electron main process opens it —
   * nothing is mirrored, so nothing can fall behind.
   */
  const openThreadTerminal = useLatestCallback(
    async (agent: AgentDisplay, thread: AgentThread) => {
      if (!activeRunIdRef.current) {
        return;
      }
      await openResolvedTarget(
        () => resolveHandoff(agent, thread),
        'this conversation cannot be opened in a terminal',
      );
    },
    [resolveHandoff, openResolvedTarget],
  );

  /**
   * Open a tab of the app's own terminal panel in the folder this chat works in.
   *
   * Not built on {@link openThreadTerminal}: that one reopens the AGENT's
   * conversation in the user's own terminal app, while this is a plain shell in
   * the directory the run already carries.
   */
  const openFolderTerminal = useLatestCallback(() => {
    const cwd = activeRun?.cwd ?? null;
    if (cwd !== null) {
      onOpenTerminal?.(cwd);
    }
  }, [activeRun?.cwd, onOpenTerminal]);

  useEffect(() => {
    onFolderChange?.(activeRun?.cwd ?? null);
  }, [activeRun?.cwd, onFolderChange]);

  /** The pages this thread has published to claude.ai, newest first. */
  const artifacts = useMemo(
    () => artifactsFrom(withAnchors(transcriptRows, runState.artifactRows)),
    [transcriptRows, runState.artifactRows],
  );
  /**
   * How a published page is addressed on the daemon.
   *
   * Stable per (launch handle, run) for the reason `loadAttachment` is: it goes
   * into a context every memoized row below reads, so a fresh identity per
   * render would re-render the whole transcript at streamed-token rate.
   *
   * The KEY rides the query because an `<iframe src>` cannot carry a bearer
   * header — see the daemon's `ArtifactsController` for why that is safe.
   */
  const artifactUrl = useMemo<ArtifactUrlBuilder | null>(() => {
    if (activeRunId === null) {
      return null;
    }
    return artifactUrlBuilder(handle, activeRunId);
  }, [activeRunId, handle]);
  const artifactAnswers = useMemo<ArtifactAnswersStore | null>(
    () =>
      activeRunId === null
        ? null
        : artifactAnswersStore(apis.chats, activeRunId),
    [activeRunId, apis.chats],
  );
  /**
   * The agents panel stands beside every open chat — there is nothing to open
   * and nothing to close, so this is just "is a chat open".
   *
   * It used to be a toggle, off by default, with a header button and a close
   * control of its own; a published artifact even sprang it open, on a
   * baseline taken from the replay so a re-opened thread would not. All of
   * that was machinery for deciding when to show a panel that turned out to be
   * wanted always.
   *
   * Putting it away is the PANEL's own business now, not this flag's: it folds
   * to a rail it can be reopened from, so the column is always there and the
   * control never has to be hosted anywhere else. See `collapsed` in
   * `agents-panel.tsx`.
   *
   * This is the COLUMN, so it is withheld at phone width, where the screen
   * shows one page at a time and has no room for a second column. The panel
   * itself is NOT withheld there any more: it moves into a drawer of its own
   * ({@link showPanelDrawer}). It was withheld outright for a release, on a
   * comment claiming "nothing here is lost", and that was simply wrong —
   * the artifacts, the pull requests, the delegates, the task lists, the
   * timeline and the thread search are reachable from nowhere else, so on a
   * phone they were reachable from nowhere at all. Reported as "I don't see
   * how to open right sidebar".
   */
  const showAgentsPanel = activeRunId !== null && !narrowViewport;
  /** The same panel, in a right-edge drawer, at phone width. */
  const showPanelDrawer = activeRunId !== null && narrowViewport;
  /**
   * The chat's in-app browser: its column, globe and link handling. Never on a
   * paired device (the browser runs on the Mac) and never on a hosted screen.
   */
  const browserEnabled =
    activeRunId !== null && !isHosted && !isRemoteRuntime();
  const browserTrack = browserEnabled && !narrowViewport ? ' auto' : '';
  /**
   * The agents panel's MCP rows. The folder is the RUN's, never the composer's
   * `folder` — the panel describes the run being viewed, and those diverge the
   * moment the user picks a different folder for their next chat.
   *
   * Only asked while the panel is open: the read health-checks, which launches
   * the user's own MCP servers, and doing that for a panel nobody opened would
   * be a background cost with no reader.
   *
   * "Open" includes the phone's DRAWER. Gated on the desktop column alone, the
   * scopes would always be empty at phone width, and the MCP dialog there
   * would show a lone "MCP · Not checked" row whose Reconnect re-runs the same
   * empty read.
   */
  const mcpScopes = useMemo((): AgentMcpScope[] => {
    if (!showAgentsPanel && !(showPanelDrawer && mobilePanelOpen)) {
      return [];
    }
    // DEDUPED by (CLI, config directory): several nodes routinely share one
    // pair, and each distinct pair costs a health check — which launches the
    // user's own MCP servers — so asking once per node would multiply that by
    // the width of the graph for answers that are identical.
    const byKey = new Map<string, AgentMcpScope>();
    for (const agent of agents) {
      if (agent.agent === null) {
        continue;
      }
      // Every POOL member too: each is its own CLI under its own profile, and
      // the card's MCP dialog switches between them.
      for (const scope of [
        { agent: agent.agent, configDir: agent.configDir },
        ...(agent.pool ?? []).map((member) => ({
          agent: member.agent,
          configDir: member.configDir,
        })),
      ] satisfies AgentMcpScope[]) {
        byKey.set(mcpScopeKey(scope), scope);
      }
    }
    return [...byKey.values()];
  }, [showAgentsPanel, showPanelDrawer, mobilePanelOpen, agents]);
  /**
   * Which of the agents panel's popups is open, as the panel itself reports
   * it. Held here only to decide which reads to pay for.
   */
  const [panelPopup, setPanelPopup] = useState<AgentsPanelPopup | null>(null);
  /**
   * This run folded into money, order and timing — read only while its popup
   * is open, for `mcpScopes`' reason above: the daemon walks the run's whole
   * spine to answer. Each opening reads it afresh.
   */
  const runWaterfall = useRunWaterfall(
    apis,
    activeRun?.id ?? null,
    panelPopup === 'waterfall',
  );
  /** The thread's live processes, polled only while their popup is open. */
  const runProcesses = useRunProcesses(
    apis,
    activeRun?.id ?? null,
    panelPopup === 'processes',
  );
  // Read only while a list is actually open. The read health-checks each
  // server — it LAUNCHES the user's own MCP processes — so doing it on mount
  // meant every chat started by dialling them and showing whatever failed.
  //
  // Holds WHICH RUN's list is open rather than a bare boolean, and the gate is
  // derived. Remounting the panel per run is not enough on its own: switching
  // chats changes `cwd` in the same render the flag is still raised, so the
  // read effect fires for the NEW folder before the remount can lower it —
  // launching that folder's servers unprompted, which is the whole defect,
  // merely moved to the second chat. Derived, the gate is already false in
  // that very render.
  const [mcpOpenRunId, setMcpOpenRunId] = useState<string | null>(null);
  const mcpOpen = mcpOpenRunId !== null && mcpOpenRunId === activeRun?.id;
  const mcp = useAgentMcp(
    agentsApi,
    mcpScopes,
    activeRun?.cwd ?? null,
    mcpOpen,
  );

  /**
   * A sign-in the DAEMON is running for this chat — one of its MCP servers, or
   * the CLI's own lapsed account.
   *
   * The same controller the Settings account sign-in uses, deliberately: one
   * lifecycle, one poll, one cancel. ONE INSTANCE for both of this screen's
   * flows, for the reason the hook holds a single sign-in at all — two browser
   * challenges open at once are indistinguishable in the browser, and the second
   * reads as the first having failed.
   *
   * `onSettled` dispatches on which flow settled, because the two are answered
   * by different reads: a server's by the LISTING, an account's by the CLI's own
   * status. Neither is answered by an exit status, which only says the command
   * finished.
   */
  // Read through a ref so the controller's `onSettled` is not re-created on
  // every render of the listing hook — the poll is keyed on identity, and a
  // fresh callback each tick is how one ends up never firing.
  const mcpRefreshRef = useRef<() => void>(() => undefined);
  mcpRefreshRef.current = mcp.refresh;
  // The NARROW re-read, for the sign-in flow alone. The daemon settles a
  // server sign-in only once its own health poll has seen the server
  // connected (`verifying` → `succeeded`), so this one read is the listing
  // catching up rather than a probe of whether it landed. Behind a ref for the
  // reason its sibling is: the controller's callbacks are keyed on identity,
  // and a fresh closure per render is how a poll ends up never firing.
  const mcpRecheckRef = useRef<(server: string) => void>(() => undefined);
  const login = useCliLogin(apis, (settled) => {
    if (settled.server !== null) {
      // The ONE row, never the whole folder. Re-dialling everything to answer
      // "did that sign-in land" is what made the user wait ~30s and then press
      // Reconnect themselves.
      mcpRecheckRef.current(settled.server);
    }
    // An account sign-in re-reads nothing: what it changed lives in the CLI's
    // own credential store, and this screen shows no account state to refresh.
    // The panel's own last line is the report, and the next turn is the test.
  });
  // Assigned during render, like its sibling above. The scope is the SIGN-IN's
  // own CLI and the run's EFFECTIVE profile — `effectiveConfigDir`, never the
  // raw `configDir`, because that is the scope the listing beside it is keyed
  // by: a folder can pin a profile over the one the chat asked for, and asking
  // under the requested one describes a different account's server. Its own
  // doc block records what that mismatch cost the last time (15 servers against
  // 50), and an answer landed under the wrong key would simply never be seen.
  mcpRecheckRef.current = (server: string): void => {
    // The SIGN-IN's own scope — the CLI and the profile the flow actually ran
    // under — never the run's. They are the same thing in a 1:1 chat and
    // different in every team run, whose agents carry profiles of their
    // own while the run carries none: the answer then landed under the default
    // profile's key while the panel was watching the node's, so the row the
    // user had just signed into never moved and only a full re-dial (or the
    // Reconnect they pressed themselves) corrected it. REPORTED as "он не
    // сразу обновляется после того, как логин был завершён… мне нужно ждать
    // очень долго, пока обновится UI".
    const target = login.login ?? login.starting;
    if (target === null) {
      return;
    }
    void mcp.recheck(
      { agent: target.kind, configDir: target.configDir },
      server,
    );
  };

  /**
   * Take the panel down once the LISTING says the server is authorized.
   *
   * The panel's instruction is about work still to do — finish in the
   * browser — and the moment the row stops saying
   * `needs_auth` that work is done. Nothing was clearing it, so the sentence
   * sat under a row that had just gone green: REPORTED as "it moved to top —
   * but now i see this", with the instruction still there beside a connected
   * server. Before the wording fix it was the same defect wearing a tick.
   *
   * The LISTING is the authority, exactly as `onSettled` already treats it —
   * never the exit status, and never a timer. So this needs no new read: the
   * re-check the settle already runs is what moves the row, and this only
   * watches the answer.
   *
   * Bounded to a server sign-in that is OVER. While one is in flight the panel
   * is the only thing on screen saying so, and a row that has not moved yet is
   * exactly when the user needs it.
   */
  useEffect(() => {
    const server = login.login?.server ?? null;
    if (server === null || login.login === null) {
      return;
    }
    const settled =
      login.login.session.status === 'succeeded' ||
      login.login.session.status === 'failed' ||
      login.login.session.status === 'cancelled';
    if (!settled) {
      return;
    }
    // Any scope's listing may carry the row — the dialog shows one at a time,
    // but which one is the caller's business, not this effect's.
    const stillNeedsAuth = [...mcp.byScope.values()].some((listing) =>
      listing.servers.some(
        (row) => row.name === server && row.status === 'needs_auth',
      ),
    );
    const known = [...mcp.byScope.values()].some((listing) =>
      listing.servers.some((row) => row.name === server),
    );
    // `known` guards the window in which the refresh has replaced the listing
    // and the row has not arrived yet: absent is not the same as authorized,
    // and dismissing on it would close the panel on a reading nobody has.
    if (known && !stillNeedsAuth) {
      login.dismiss();
    }
  }, [login, mcp.byScope]);

  // A sign-in the daemon REFUSED never becomes a session, so the controller's
  // own panel — which only exists once there is one — has nowhere to show it.
  // Without this the press is silent: the button appears to do nothing, which
  // is precisely the failure the progress panel was added to end.
  useEffect(() => {
    if (login.error !== null) {
      setError(login.error);
    }
  }, [login.error]);

  /**
   * Sign one CLI in to one MCP server, WITHOUT opening a terminal window.
   *
   * The window was never the mechanism — `mcp login` refuses a piped stdin, so
   * a terminal was simply where a TTY could be found, and the daemon now
   * allocates one itself (`AgentCommandOptions.pty`). What the user gets
   * instead is the browser tab the CLI opens and a progress panel in the dialog
   * they pressed the button in, which is the reported ask: "it should take us
   * straight to the browser, not open a shell".
   *
   * The listing is re-read when the flow SETTLES rather than here — see the
   * controller's `onSettled` — because whether the server is now authenticated
   * is the listing's answer, never an exit code's, and re-dialling while the
   * consent page is still open would ask before there was anything to ask
   * about.
   */
  const signInToMcpServer = useLatestCallback(
    async (scope: AgentMcpScope, server: string) => {
      // The RUN's folder, exactly as the listing beside it was taken in — never
      // the composer's `folder`, which is where the NEXT chat would start. A
      // server name resolves against the directory the CLI runs in, so signing
      // in from the other one authenticates a different server or none.
      const cwd = activeRun?.cwd ?? null;
      if (!cwd) {
        // The route needs a folder and this one has none — a run can carry no
        // working directory at all. Said rather than swallowed: the button
        // would otherwise do nothing at all when pressed.
        //
        // Not reachable from today's panel, and deliberately kept anyway: the
        // listing that renders this button is itself gated on the run's folder
        // (`useAgentMcp`), so a folderless run has no rows to press. What the
        // spec pins is that absence, not this message — the day a caller
        // reaches the handler another way, this is the answer it gets.
        setError(
          `${server} is configured per folder, and this chat has no folder to sign in from`,
        );
        return;
      }
      await login.startMcp({
        kind: scope.agent,
        server,
        cwd,
        // The profile the LISTING was taken under — the row's own scope, not
        // the run's. A server is authorized INSIDE a config directory, so
        // signing in under a different one leaves the row exactly as
        // unauthenticated as it was.
        //
        // It was the RUN's (`effectiveConfigDir(activeRun)`), which is right
        // for a 1:1 chat and null for every TEAM run — a team carries
        // no profile of its own, its agents do. So the agents panel listed a
        // node's servers under `.claude-manifest-lab` and the press signed in
        // under the DEFAULT profile, where that server does not exist: the CLI
        // failed at once, the POST errored, and the button did nothing at all.
        // REPORTED as "я нажал на Sign In, и ничего не происходит", with the
        // same press working on the Teams page, which had always passed the
        // node's own profile. Reconstructed from the daemon's log: three
        // presses at 14:20–14:22 carried `cwd` and no `configDir` and started
        // no session, while the Teams-page presses beside them carried the
        // profile and were polled to completion.
        configDir: scope.configDir,
      });
    },
    [login, activeRun],
  );

  /**
   * Sign one CLI itself back in, WITHOUT opening a terminal window.
   *
   * The account, not one of its MCP servers — {@link signInToMcpServer} above
   * fixes a server the CLI could not authenticate, this fixes the CLI's own
   * lapsed session, and the wrong one sends the user to a command that cannot
   * fix what they hit.
   *
   * REPORTED as "after click on sign in - it will open terminal. and after
   * redirect and auth nothing will happens". It used to resolve the invocation
   * and hand it to the user's terminal, which put the only surface that knows
   * how the sign-in is going outside the app entirely: nothing in geniro was
   * watching that window, so a finished browser round-trip changed nothing on
   * screen and the failed turn sat there looking exactly as it had. The daemon
   * has run this flow itself since the Settings card stopped opening a shell
   * (`/v1/auth/login` — it allocates the pty, reads the CLI's own output, and
   * takes a pasted code); this was the last caller still going out to one.
   *
   * The run's CONFIG DIRECTORY is passed, and it is the one thing here that is
   * not machine-wide: credentials live in that folder, so a chat pointed at a
   * second profile must be signed in THERE. Without it the user signs into
   * their default account and watches the same turn fail again — which is
   * exactly the failure this control exists to end.
   */
  const signInToCli = useLatestCallback(
    async (kind: CliKind, configDir: string | null) => {
      await login.start(kind, configDir);
    },
    [login],
  );

  /**
   * The transcript's own sign-in, resolved per ROW — a team row signs in
   * the profile of the node that failed. See `signInResolverFor`.
   *
   * Keyed on the run's primitives, never on `activeRun` itself: that object is
   * replaced on every status announce, and a new resolver re-renders every row
   * reading the context.
   */
  const resolveSignIn = useMemo(
    () =>
      signInResolverFor({
        teamId: activeRun?.teamId,
        agentKind: activeRun?.agentKind,
        configDir: activeRun?.configDir,
        teamAgents: wfNodes.agents,
        signIn: (kind, configDir) => void signInToCli(kind, configDir),
      }),
    [
      activeRun?.teamId,
      activeRun?.agentKind,
      activeRun?.configDir,
      wfNodes.agents,
      signInToCli,
    ],
  );

  /**
   * Reopen the ACTIVE run's conversation after a failed turn — the transcript's
   * Retry, bound the way its sign-in neighbour is.
   *
   * Null when there is no open run, or no daemon to ask. Whether the reopen can
   * SUCCEED is deliberately not decided here (see `RetryContext`): the daemon
   * refuses a chat with no session to resume, an archived one and a busy one,
   * and it writes a real sentence for each — which is what `daemonErrorDetail`
   * puts on screen, on the same rule the approval chip follows for RUN_BUSY.
   */
  const retryActiveRun = useMemo(() => {
    const runId = activeRun?.id;
    // A TEAM run has no single conversation to reopen, and the route says
    // so with a 400 (`assertChatRun`) — so offering the button there could only
    // ever produce an error strip. The sidebar lists both kinds in one surface,
    // which is what makes this reachable.
    if (runId === undefined || !chatApi || activeRun?.teamId) {
      return null;
    }
    const worktreeRun: WorktreeRun = {
      taskId: activeRun?.taskId ?? null,
      cwd: activeRun?.cwd ?? null,
    };
    return () => {
      // Retry after a task's worktree was collected is the reported case
      // itself — the transcript's failure row offers exactly this press.
      void (async () => {
        const raised = await startHostedTurn(runId);
        try {
          await sendRestoringWorktree(
            () => chatApi.retryChat({ runId }),
            worktreeRun,
            restoreWorktree,
          );
        } catch (err) {
          if (raised) {
            refuseHostedTurn();
          }
          setError(daemonErrorDetail(err) ?? String(err));
        }
      })();
    };
  }, [
    activeRun?.id,
    activeRun?.taskId,
    activeRun?.cwd,
    chatApi,
    restoreWorktree,
    startHostedTurn,
    refuseHostedTurn,
  ]);

  /**
   * The badge a sidebar row shows for a run — the ONE reading, so a group
   * header's "something in here is working" cannot contradict the rows under
   * it.
   *
   * It is computed from facts EVERY run carries, and that is the whole rule: a
   * row must not change what it says merely because the user looked at it.
   *
   * REPORTED as "when i select thread - it became working status, but when
   * unselect - success. So it's blinking". The focused row used to answer from
   * `activeRunStatus`, which folds in `subagentRunning` and `shellsRunning` —
   * both derived from the LOADED transcript, so knowable for the open thread
   * and for no other. A settled run with a detached command still out therefore
   * read `⌛ working · waiting on background work` while selected and
   * `✓ completed · just now` the instant it was deselected, for one unchanged
   * run. Reproduced in the dev app on a `completed` turn holding one background
   * `sleep`.
   *
   * This is the same defect `heldForBackgroundWork` was ranked FIRST to fix
   * ("a held run read `running` in the header and `idle` in its own sidebar
   * row, and clicking it swapped one for the other in front of the user"), and
   * it takes the same answer: the fact has to be one the daemon publishes about
   * every run, not one a client folds out of the transcript it happens to hold.
   * So `shellsRunning` now comes from `shellsOut` — the run row's own
   * `shellsOpen`, seeded from the list and kept current by the announce — on
   * BOTH branches, and an unfocused row reads `⌛ working · waiting on
   * background work` exactly as the selected one does, which is the state the
   * report wanted to KEEP rather than lose.
   *
   * The other two focused-only readings STAY, and the difference is what each
   * one can do. `subagentRunning` is folded from the loaded transcript and no
   * row carries it, so it remains knowable for the open thread alone — dropping
   * it was tried and broke the pin that a delegate still producing rows keeps
   * the badge `running`, which is a real state the daemon's own delegate lease
   * also restores on the row. `awaitingAnswer` is read live because an open
   * card is known here before the row's own `awaiting` catches up, and
   * `needs-input` is the one state that must never be missed. Both can only
   * ever say MORE than the row, never contradict it into looking finished.
   */
  const rowRunStatus = useLatestCallback(
    (run: ChatRun, liveTurn: boolean): RunStatusKind =>
      displayRunStatus({
        status: run.status,
        streaming: liveTurn,
        awaitingAnswer: run.awaiting !== null,
        // Row-carried like the hold below, which is the whole point of it
        // being on the wire — see this callback's own doc.
        shellsRunning: shellsOut.has(run.id),
        subagentsOut: delegatesOut.has(run.id),
        monitorsRunning: run.monitorsOpen > 0,
        // Row-carried for every run, not just the focused one: seeded from the
        // run list's own `holdingFor` and then kept current by the live
        // announce, which is what makes it right for a thread the user is not
        // looking at. Its "parked on you" comes from the row for the same
        // reason — the daemon's approval registry publishes it there — which is
        // what stops a chat sitting on an unanswered question from showing a
        // spinner for as long as the user is looking elsewhere.
        heldForBackgroundWork: holding.has(run.id),
      }),
    // `delegatesOut` too: a turn that settles with sub-agents still out moves
    // only that set, and without it every thread the user was not looking at
    // kept the old reading — `completed` over a hold, `held` after it ended.
    [holding, shellsOut, delegatesOut],
  );
  /**
   * That same reading taken WITHOUT the live plane — what the row would say if
   * the user were looking somewhere else.
   *
   * Split out because the ORDER has to be computed from it (see
   * `sortRunsForSidebar`): every input to the sort must mean the same thing for
   * every run, or focusing a thread moves it.
   */
  const unfocusedRunStatus = useLatestCallback(
    (run: ChatRun): RunStatusKind => rowRunStatus(run, false),
    [rowRunStatus],
  );
  const sidebarRunStatus = useLatestCallback(
    (run: ChatRun): RunStatusKind =>
      run.id === activeRunId ? activeRunStatus : unfocusedRunStatus(run),
    [activeRunId, activeRunStatus, unfocusedRunStatus],
  );
  /**
   * "Has the agent stopped" for a thread the user is NOT looking at — the same
   * reading {@link agentRunStatus} takes for the focused one, and it leaves the
   * SHELLS out for the same reason that one does.
   *
   * REPORTED as "agent finoshed work, so i should gett notification. im not
   * sure its correctt status in case we have shells", over a thread whose agent
   * had finished with two commands still running. `agentRunStatus` already
   * omitted `shellsRunning`, so a focused thread answered this correctly — but
   * the two consumers here fell back to {@link unfocusedRunStatus}, which is the
   * BADGE reading and does count shells, so every unfocused thread answered
   * `held`. Notifications and the unseen mark are about unfocused threads by
   * definition, which is why the asymmetry was invisible until a command
   * outlived its turn: a shell that ends releases the hold and the banner
   * arrives late, while a `pnpm dev` or a tailed log holds it for good and the
   * banner never arrives at all.
   *
   * The badge is deliberately NOT changed with it. A running command IS worth
   * showing, which is the report that put `shellsRunning` into the badge in the
   * first place; what was wrong is only that "something this thread started is
   * still running" was being read as "the agent is still working". The two
   * statements are compatible, and now each has its own reading.
   */
  const unfocusedAgentStoppedStatus = useLatestCallback(
    (run: ChatRun): RunStatusKind =>
      displayRunStatus({
        status: run.status,
        streaming: false,
        awaitingAnswer: run.awaiting !== null,
        // The DELEGATE hold stays: a sub-agent still out means the agent's work
        // is genuinely unfinished, and announcing it as done is the defect this
        // whole vocabulary was built to prevent.
        heldForBackgroundWork: holding.has(run.id),
        teamLeadsDone: rootsIdle.has(run.id),
      }),
    [holding, rootsIdle],
  );
  /**
   * The same per-run reading for the two consumers that ask "has this thread
   * stopped" rather than "what is it doing" — see {@link agentRunStatus}.
   */
  const agentStoppedRunStatus = useLatestCallback(
    (run: ChatRun): RunStatusKind =>
      run.id === activeRunId
        ? agentRunStatus
        : unfocusedAgentStoppedStatus(run),
    [activeRunId, agentRunStatus, unfocusedAgentStoppedStatus],
  );

  /**
   * How many DETACHED commands this run has out — the reading that decides
   * whether a finished turn is announced by itself, for
   * {@link useRunNotifications}.
   *
   * The run row's own count, the one the Terminals chip shows and the badge's
   * `shellsOut` is derived from: the badge and the banner then disagree about
   * nothing, answering two questions off one fact — "something this thread
   * started is running" and "so this ending may not be the agent finishing".
   */
  const runShellsOpen = useLatestCallback(
    (run: ChatRun): number => run.shellsOpen,
    [],
  );

  const notificationLabel = useLatestCallback(
    (run: ChatRun): string => runLabel(run, teamNames),
    [teamNames],
  );

  /** What this run said as it settled, from the live channel — see the map. */
  const settleSummaryOf = useLatestCallback(
    (run: ChatRun): string | null => settleSummaries.get(run.id) ?? null,
    [settleSummaries],
  );

  /**
   * Whether the thread on show is the one this screen was last asked to open.
   * Another screen's request (⌘J, a board card, a link) and the switch to this
   * view land in one render, and for that render the thread on show is the one
   * being LEFT — both surfaces below must not count it as watched, or it is
   * reported read without ever being drawn.
   */
  const showsRequestedThread = openRunId === null || openRunId === activeRunId;
  /**
   * Every thread the two notification surfaces follow: the listing on show
   * AND the rows the archive filter is hiding. Whether a thread finished is not
   * a question about the scope on screen — fed `runs` alone, both hooks forgot
   * every thread a scope switch hid, so its ending was never announced and its
   * unread mark was wiped by the switch itself.
   */
  const notifiedRuns = useMemo(
    () =>
      isHosted
        ? NO_NOTIFIED_RUNS
        : offScopeRuns.length === 0
          ? runs
          : [...runs, ...offScopeRuns],
    [runs, offScopeRuns, isHosted],
  );

  const notificationSettling = useMemo(
    () =>
      rootsIdle.size === 0
        ? settleOwed
        : new Set([...settleOwed].filter((runId) => !rootsIdle.has(runId))),
    [settleOwed, rootsIdle],
  );
  /**
   * Tell the user, outside the app, when a thread stops to ask something or
   * ends — reading the SAME status the sidebar badge shows, so a banner and the
   * row it sends you to can never describe one run differently. Whether it
   * becomes a banner at all is main's call (the setting).
   */
  useRunNotifications({
    runs: notifiedRuns,
    statusOf: agentStoppedRunStatus,
    labelOf: notificationLabel,
    awaitingOf: runAwaiting,
    summaryOf: settleSummaryOf,
    quiet: quietSettles,
    // The open thread's ending lands on its terminal ITEM, ahead of the settle
    // announce that says whether it was housekeeping — so it waits for that.
    // A team run whose leads ended their turns has no settle coming while its
    // calls run, so the Manager's reply is announced as it lands.
    settling: notificationSettling,
    // A thread with a command still out may not be finished at all: the agent
    // routinely ENDS ITS TURN waiting on one and resumes the moment it reports.
    // Its ending is announced provisionally and withdrawn if the run resumes.
    // The same reading the badge uses for its own shells word — see the hook.
    shellsOpenOf: runShellsOpen,
    // What the agent said itself, with `notify_user` — posted in its words, in
    // place of the plain ending.
    notices: agentNotices,
    // Only while this screen is ON screen. `Chats` stays mounted, hidden,
    // behind Settings, Teams and the board, and the open thread stays
    // open there — so passing it regardless read a user in Settings on a
    // focused window as watching that thread, and its banners were withheld
    // from the one person not looking at it.
    activeRunId: active && showsRequestedThread ? activeRunId : null,
  });
  // An agent's share waiting on the user signing in — desktop only, like the
  // Share control that answers it.
  useShareSignInNotifications({
    client: isRemoteRuntime() || isHosted ? null : client,
    runs: notifiedRuns,
    labelOf: notificationLabel,
    activeRunId: active && showsRequestedThread ? activeRunId : null,
  });
  useLessonsFiledNotifications({
    client: isRemoteRuntime() || isHosted ? null : client,
    runs: notifiedRuns,
    labelOf: notificationLabel,
    activeRunId: active && showsRequestedThread ? activeRunId : null,
  });
  // The lasting half of the same signal. A banner is gone in seconds — and on
  // a Mac that is sharing its screen macOS drops every app's silently — so the
  // sidebar keeps the mark until the thread is opened. The mark is the DAEMON's
  // now (read off the row, cleared on every device by a look on any one), so
  // the open thread counts as looked at only while somebody can see it: this
  // screen on show and the window visible and focused. Every way into a thread
  // — a sidebar row, a clicked banner, the session picker — reports the look
  // through that one condition, and none of them has to remember to.
  //
  const windowWatched = useWindowWatched();
  const unseen = useUnseenRuns({
    runs: notifiedRuns,
    activeRunId,
    watching: active && windowWatched && showsRequestedThread,
    markSeen: markRunSeen,
  });
  // Read with the UNFOCUSED status for every run, the open one included, so
  // focusing a thread cannot change its status reading — the sidebar order's
  // rule. (Opening an unread one still sees it, which is the point.) An unread
  // team run whose leads ended their turns is read as stopped: the reply is
  // the Manager's, owed to the user while its calls work on.
  const waiting = useMemo(
    () =>
      waitReadings(
        notifiedRuns.filter((run) => run.archivedAt == null),
        {
          statusOf: (run) =>
            rootsIdle.has(run.id) && unseen.has(run.id)
              ? unfocusedAgentStoppedStatus(run)
              : unfocusedRunStatus(run),
          unseen,
        },
      ),
    [
      notifiedRuns,
      unfocusedRunStatus,
      unfocusedAgentStoppedStatus,
      rootsIdle,
      unseen,
    ],
  );
  // Reported only when a wait actually changed: the rows are rewritten on
  // every announce, and each report re-renders the whole shell. A working
  // thread's `since` is its last activity, which moves with every row it
  // writes and which nothing downstream reads, so it stays out of the key.
  const waitingKey = waiting
    .map(
      ({ runId, state, since }) =>
        `${runId}:${state}:${waitsOnUser(state) ? since : ''}`,
    )
    .join('|');
  const waitingRef = useRef(waiting);
  waitingRef.current = waiting;
  useEffect(() => {
    onWaitingChange?.(waitingRef.current);
  }, [waitingKey, onWaitingChange]);
  // This screen unmounts while no daemon answers; what it last reported must
  // not stand in the title bar, or be jumped to, meanwhile.
  useEffect(() => () => onWaitingChange?.([]), [onWaitingChange]);
  // Each finished turn's line totals, posted to the daemon for the Stats page.
  // Here rather than in the shell because a thread's folder and start commit
  // are on the run rows this screen holds — see use-line-snapshots.
  useLineSnapshots({ apis, client, runs: notifiedRuns });

  /**
   * Open the thread a clicked notification was about. Main has already raised
   * the window; this is the half that decides what it shows.
   */
  useEffect(
    () =>
      isHosted
        ? undefined
        : window.geniro.onNotificationActivated((runId) => {
            if (runId !== '') {
              handleActivateRun(runId);
            }
          }),
    [handleActivateRun, isHosted],
  );

  /**
   * Open the thread another screen asked for — the task board's "follow this
   * card's agent".
   *
   * The same activation the notification path takes, so a thread opened this
   * way joins its room and replays exactly as a clicked one does. The request
   * is acknowledged AFTER the activation, which is what stops the effect from
   * firing again on the next render with the same id still standing.
   */
  useEffect(() => {
    if (openRunId === null) {
      return;
    }
    handleActivateRun(openRunId);
    onRunOpened?.();
  }, [openRunId, handleActivateRun, onRunOpened]);

  // The outbound half, keyed on the state that actually says which thread is
  // open rather than on the request that asked for one.
  useEffect(() => {
    onActiveRunChange?.(activeRunId);
  }, [activeRunId, onActiveRunChange]);

  // Ordered BEFORE the fold, not inside it: `runGroupSections` preserves the
  // order it is given and `previewSectionRuns` decides what a folded section
  // shows from that same order, so sorting here is what puts a thread waiting
  // on an answer both at the top of its group AND above the "Show all" cut.
  const orderedRuns = useMemo(
    () => sortRunsForSidebar(runs, { statusOf: unfocusedRunStatus }),
    [runs, unfocusedRunStatus],
  );

  const sections = useMemo(
    () => runGroupSections(groups, orderedRuns),
    [groups, orderedRuns],
  );

  /** Show this section in full, or fold it back to its working set. */
  const handleToggleSectionAll = useLatestCallback((sectionKey: string) => {
    setExpandedSections((current) => {
      const next = new Set(current);
      if (!next.delete(sectionKey)) {
        next.add(sectionKey);
      }
      return next;
    });
  }, []);

  /** How many chats the group awaiting confirmation holds. */
  const deletingGroupCount = useMemo(
    () =>
      deletingGroup === null
        ? 0
        : runs.filter((run) => run.groupId === deletingGroup.id).length,
    [deletingGroup, runs],
  );

  // The chat list's width, remembered per install — the same drag-to-resize the
  // agents panel on the other edge has had all along, asked for in those words
  // ("Left sidebar with threads list should be resizible, same as right sidebar
  // with agents"). It is the SAME hook, so the clamping, the persisted-value
  // migration, the persist-at-drag-end and the ARIA splitter wiring are got
  // right once rather than twice. `CHAT_LIST_WIDTH` is now the DEFAULT rather
  // than the width.
  //
  // The bounds are the list's own, not the panel's: a thread row carries a
  // truncating title over two labels, so width buys legibility here in a way it
  // does not on a column of cards — hence a higher ceiling than the panel's
  // 420. The floor is shared, because below ~220px the list header's four
  // controls crowd the word `Chats` off the row.
  const {
    width: listWidth,
    minWidth: listMinWidth,
    maxWidth: listMaxWidth,
    startResize: startListResize,
    resizeTo: resizeListTo,
  } = usePanelWidth({
    storageKey: 'chats.listWidth',
    defaultWidth: CHAT_LIST_WIDTH,
    minWidth: 220,
    maxWidth: 520,
    handleEdge: 'right',
  });

  // minmax(0,1fr): the transcript column must be allowed to shrink below its
  // content width, or a long cwd path widens the grid past the window. The
  // third `auto` column appears only while the agents panel is open (the
  // panel's own resizable width drives it).

  /**
   * The phone's way back from a detail page to the chat list — the ‹ button
   * at the leading edge of the title bar's band, the Chats tab pressed again,
   * and the platform's own back gesture through the page's history entry.
   * From a thread it closes the thread, so the list is what is left; from the
   * composer it only leaves the page, keeping the draft for the next visit.
   */
  const phoneBack = usePhoneBackEntry(
    'chats',
    phoneDetailPage && active,
    () => {
      // The run-details drawer belongs to the thread being left; open, it
      // would cover the next thread tapped.
      setMobilePanelOpen(false);
      if (activeRunId !== null) {
        deactivateRun();
      } else {
        // `deactivateRun` clears the shared error on the thread arm; a
        // composer refusal must not follow the reader onto the list.
        dismissError();
        setMobileComposeOpen(false);
      }
    },
  );
  const homeSignalSeen = useRef(phoneHomeSignal);
  useEffect(() => {
    if (phoneHomeSignal === homeSignalSeen.current) {
      return;
    }
    homeSignalSeen.current = phoneHomeSignal;
    if (phoneDetailPage) {
      phoneBack();
    }
  }, [phoneHomeSignal, phoneDetailPage, phoneBack]);
  // A chat page's own back, the way a messenger's thread has one — asked for
  // beside the tab bar, which stays on screen under it.
  const mobileBack = phoneDetailPage ? (
    <MobileBarButton
      label="Back to chats"
      onClick={phoneBack}
      className="left-2">
      <ChevronLeft aria-hidden="true" />
    </MobileBarButton>
  ) : null;

  /**
   * The agents panel's opener, at the band's TRAILING edge — the edge its own
   * drawer slides from, and the one the back button leaves free.
   *
   * Drawn only with a thread open, because the panel is about the run: with
   * none there is nothing behind the control. It shares the band with
   * `TitleBar`'s update control, which renders nothing at all unless an update
   * is waiting (`footerUpdate` maps every other state to `none`).
   */
  const mobilePanelToggle = showPanelDrawer ? (
    <MobileBarButton
      label="Open run details"
      expanded={mobilePanelOpen}
      onClick={() => setMobilePanelOpen((open) => !open)}
      className="right-2">
      <PanelRight aria-hidden="true" />
    </MobileBarButton>
  ) : null;

  // The shelf of what this thread has produced — its own row directly above
  // the composer, or, while messages are queued, the leading half of the
  // queue's header line (see the `QueuedStrip` call below). One element for
  // both places, so the two cannot drift.
  //
  // Its own shelf rather than more chips in the composer's row: that row
  // deliberately does not wrap, and a pull-request title is user data of any
  // length — it would take width from the folder and branch chips every time.
  //
  // ONLY what this thread OPENED. The branch's own pull request used to fill
  // this space for a thread that opened none, and it was wrong twice over: the
  // shelf says "what this conversation produced", and a checkout routinely sits
  // on a branch whose pull request somebody else opened. That list keeps its
  // own captioned section in the panel, where it is named as the branch's.
  //
  // The provider, because the shelf is a SIBLING subtree of the transcript and
  // inherits none of its context — the same trap the sub-agent detail dialog
  // fell into. Without it a team whose call never returned reads `running`
  // on the chip for the life of the chat, and the chip's whole point is that it
  // goes away.
  const renderComposerShelf = (
    inQueueHeader: boolean,
    queueControl?: React.ReactNode,
  ): React.JSX.Element => (
    <ComposerShelf
      inline={inQueueHeader}
      trailing={queueControl}
      // The status counters, right-anchored, so they run VOLATILE → DURABLE:
      // a command comes and goes many times a turn, a task list outlives it.
      status={
        <>
          <RunningShellChips
            shells={sidePanelLive.shells}
            // Only a TEAM's rows are labelled. A 1:1 chat
            // has one agent, so the name would be the same word
            // down every row — and the popover is 22rem, where
            // a redundant column costs the command its width.
            agentNameOf={
              activeRun?.teamId ? sidePanelLive.shellAgents : undefined
            }
            leftRunningOf={sidePanelLive.shellsLeftRunning}
            onOpen={setOpenShell}
            onKill={handleKillShell}
          />
          <RunningMonitorChips
            monitors={runState.monitors}
            agentNameOf={activeRun?.teamId ? shelfAgentName : undefined}
            onStop={handleStopMonitor}
          />
          <RunningSubagentChips
            running={sidePanelLive.subagents}
            threads={sidePanelLive.subagentThreads}
            // Only the root agents' own delegates, so a block per
            // agent only when several roots have some.
            groups={
              sidePanelLive.subagentGroups.length > 1
                ? sidePanelLive.subagentGroups
                : undefined
            }
            // The same detail panel the agents panel's own
            // delegate rows open — the shelf is the readier
            // way to a delegate now, and a list that only
            // looked clickable would be a step back from it.
            onOpen={openSubagentById}
          />
          <WaitingMessagesChip
            messages={waitingMessages.messages}
            onRemove={waitingMessages.remove}
          />
          <TeamNotesChip
            notes={teamNotes}
            agentName={shelfAgentName}
            onOpen={(seq) => setNotesView({ selected: seq })}
          />
          <TaskListChip
            done={sidePanelLive.tasks.done}
            total={sidePanelLive.tasks.total}
            tasks={sidePanelLive.taskRows}
            // Only a TEAM's lists are split into blocks,
            // the same gate the terminals chip's labels take:
            // a 1:1 chat has one agent, so a heading over its
            // only list names nothing the reader could doubt.
            groups={activeRun?.teamId ? sidePanelLive.taskGroups : undefined}
            // The RUN's own liveness, not the list's: an
            // unfinished task on a settled thread is one
            // nothing is advancing, and a spinner there would
            // claim work that stopped.
            // `running` alone, the agents panel's own reading:
            // held or waiting on the user is not work moving
            // through the list, and the two surfaces disagreed
            // about the same task for as long as that lasted.
            live={activeRunStatus === 'running'}
          />
          {runGoals === undefined ? null : (
            <ProgressChip
              goals={runGoals}
              stages={activeRun?.stages}
              onOpen={openProgress}
            />
          )}
        </>
      }>
      {/* FIRST in the row, and the one chip here that is
            not about what the thread produced: the composer
            under it is disabled, so this is the only control
            on screen that can make it usable again. It sits
            ahead of the ordering rule below rather than
            inside it — that rule ranks READINGS by how long
            they last, and this is a control. */}
      {activeRunArchived ? (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="h-7 gap-1.5 px-2 text-xs text-muted-foreground"
          onClick={() => activeRunId && handleUnarchiveOpenRun(activeRunId)}>
          <ArchiveRestore className="size-3 shrink-0" />
          Archived — unarchive to continue
        </Button>
      ) : null}
      {/* A continue geniro has PROMISED and not made — a
            control as much as a reading (calling it off is
            behind it), so it sits with the unarchive control
            ahead of the readings, where it cannot be shifted
            by chips that come and go. */}
      <ResetWakeChip
        wakes={activeRun?.resetWakes ?? []}
        cancelling={cancellingResetWakes}
        onCancel={() => activeRunId && cancelResetWakes(activeRunId)}
      />
      <ThreadProjectChip project={activeRun?.project} />
      {/* The readings run DURABLE → VOLATILE, left to
            right, and that is the whole of the ordering
            rule: a chip that comes and goes must never shift
            one that stays. The working TREE outlives every
            pull request opened from it, so it leads; pull
            requests outlive the thread; a team ends
            within a turn. The counters live in `status`.

            Only where there is something to compare: a run
            without a folder, and one this app never stamped a
            commit for (a plain folder, a checkout with no
            commits, a chat that predates the stamp), have no
            "since" to answer about. */}
      <LeadChip name={relayLeadName} />
      {activeRun?.cwd !== null && activeRun?.startSha !== null ? (
        <FolderChangesChip
          summary={chatChanges.summary}
          truncated={chatChanges.truncated}
          onOpen={openChatChanges}
        />
      ) : null}
      <ThreadPullRequestChips
        results={openedByActiveThread}
        outcomes={activeRunOutcomes.newest}
      />
      {/* Mounted only while open and keyed by the run, so its search and
          filters start clean on every open and never carry to another thread,
          and closing it is the notes field's way out: its owed text is saved. */}
      {notesView !== null && activeRun ? (
        <NotesDialog
          key={activeRun.id}
          open
          onClose={() => setNotesView(null)}
          threadNotes={{
            runId: activeRun.id,
            value: activeRun.notes,
            onSave: (text) => handleSetRunNotes(activeRun.id, text),
          }}
          teamNotes={teamNotes}
          initialSelected={notesView.selected}
          agentName={shelfAgentName}
          onJump={jumpToSeq}
        />
      ) : null}
      {progressOpen && runGoals !== undefined ? (
        <ProgressDialog
          open
          onClose={() => setProgressOpen(false)}
          goals={runGoals}
          stages={activeRun?.stages}
          nameOf={activeRun?.teamId ? shelfAgentName : undefined}
        />
      ) : null}
      {/* An agent's buttons outlive the turn that made them,
            so they sit ahead of everything that ends within a
            turn — behind their own divider, since they are
            controls rather than readings. */}
      <ChatActionChips
        actions={chatActions.actions}
        phases={chatActions.phases}
        onPress={chatActions.press}
        onDismiss={chatActions.dismiss}
      />
      <ActiveWorkflowChips workflows={runWorkflows} onReveal={revealWorkflow} />
    </ComposerShelf>
  );

  return (
    <CardBackedRequestsContext.Provider value={cardBacked}>
      <ChatProviders
        jumpMark={mark}
        signIn={resolveSignIn}
        retry={retryActiveRun}
        callContext={resolveCallReading}
        callChannel={callChannel}
        artifactUrl={artifactUrl}
        artifactAnswers={artifactAnswers}
        artifactSharing={artifactSharing}
        // What the reader folded and opened is remembered per THREAD — see
        // `thread-ui-memory.ts`.
        threadId={activeRunId}
        runSettledAt={activeRunSettledAt}
        callConversations={callConversations}
        delegateConversations={delegateConversations}
        liveText={liveText}
        applyRecommendations={applyRecommendations}
        memberVerdicts={memberVerdicts}
        notSent={notSent}
        chatActions={chatActions}
        loadMemory={loadMemory}
        loadKnowledge={loadKnowledge}
        lessonsApi={apis.lessons}
        lessonsKnowledgeApi={apis.knowledge}
        lessonsAgentsApi={agentsApi}
        lessonsJump={jumpToSeq}>
        <AttachmentLoaderContext.Provider value={loadAttachment}>
          <ChatMetricsLoaderContext.Provider value={loadChatMetrics}>
            <LocalImageLoaderContext.Provider value={loadMarkdownImage}>
              <BrowserGrid
                runId={browserEnabled ? activeRunId : null}
                className="relative grid h-full"
                // The list's width is shared with the shell: the title bar's
                // divider is placed from it, so the band above ends exactly on
                // this column's border rather than near it.
                //
                // At phone width there is ONE column, and the list and the
                // pane beside it take turns in it as separate pages: the one
                // not on show is `hidden`, which takes it out of the grid.
                //
                // `minmax(0,1fr)`, NOT bare `1fr`, same as the desktop
                // columns below: a bare `fr` track's automatic minimum is
                // `auto` (its content's min-content size), so one long
                // unbreakable line — a user message with no spaces, a cwd
                // path — grows the TRACK past the window instead of wrapping
                // or clipping inside it, and that growth cascades up through
                // every ancestor `flex`/`grid` box (each shares the identical
                // `min-width: auto` default) until something wide enough
                // absorbs it.
                style={{
                  gridTemplateColumns: narrowViewport
                    ? 'minmax(0,1fr)'
                    : isHosted
                      ? showAgentsPanel
                        ? 'minmax(0,1fr) auto'
                        : 'minmax(0,1fr)'
                      : showAgentsPanel
                        ? `${listWidth}px minmax(0,1fr)${browserTrack} auto`
                        : `${listWidth}px minmax(0,1fr)${browserTrack}`,
                }}>
                {/* On a phone the list is a PAGE of its own: hidden (and its
                    scroll position kept) while a thread or the composer is on
                    show, the whole screen otherwise. */}
                {isHosted ? null : (
                  <aside
                    data-slot="chat-list"
                    className={cn(
                      'relative flex min-h-0 flex-col border-r border-border bg-sidebar',
                      narrowViewport &&
                        (phoneListPage ? 'border-r-0' : 'hidden'),
                    )}>
                    {/* `relative` on the aside above is what this needs: the
                      handle is absolutely positioned inside it, exactly as the
                      agents panel's is. On the RIGHT edge, because that is the
                      edge this column shares with the transcript — and the
                      hook's sign convention then makes dragging away from the
                      list grow it. Omitted at phone width, where the list is a
                      full-width page with nothing beside it to trade width
                      with. */}
                    {narrowViewport ? null : (
                      <PanelResizeHandle
                        edge="right"
                        label="Resize chat list"
                        onMouseDown={startListResize}
                        value={listWidth}
                        min={listMinWidth}
                        max={listMaxWidth}
                        onResize={resizeListTo}
                      />
                    )}
                    {/* A column heading, NOT part of the window's title bar —
                      that is one band above every column now (`title-bar.tsx`).
                      It keeps `h-11` so it still shares a baseline with the
                      transcript's header beside it. */}
                    <div className="flex h-11 items-center justify-between pr-2 pl-3">
                      <span className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
                        Chats
                      </span>
                      <span className="flex items-center gap-0.5">
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="size-7"
                          aria-label="Search all chats"
                          title="Search all chats (⌘⇧F / Ctrl+Shift+F)"
                          onClick={() => setGlobalSearchOpen(true)}>
                          <Search className="shrink-0" />
                        </Button>
                        {/* Before the add controls because it acts on the LIST
                          the row sits above, where the three after it each add
                          something to that list. */}
                        <ChatScopeFilter
                          scope={chatScope}
                          onChange={handleShowScope}
                          window={activityWindow}
                          preset={activityPreset}
                          onWindowChange={handleActivityWindow}
                        />
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="size-7"
                          aria-label="New group"
                          title="New group"
                          onClick={handleNewGroup}>
                          <FolderPlus className="shrink-0" />
                        </Button>
                        {/*
                        Beside the +, not inside it. The + is a one-click new
                        thread and has to stay one; picking up an existing
                        conversation is a different act with a question attached
                        to it, so it gets its own control.
                      */}
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="size-7"
                          aria-label="Continue a session"
                          title="Continue a session you already have"
                          onClick={() => {
                            setSessionAgent(agentKind);
                            setSessionPickerOpen(true);
                          }}>
                          <History className="shrink-0" />
                        </Button>
                        {/* The saved setups hang off the + itself: they are ways
                          of starting a new chat, so the control that starts one
                          is where the user is already aiming. A click still
                          means the plain new thread. */}
                        <NewChatButton
                          configs={runConfigs}
                          projects={projects}
                          onNewChat={() => {
                            newChat();
                            setMobileComposeOpen(true);
                          }}
                          onApply={(config) =>
                            void applyRunConfigToComposer(config)
                          }
                          onCreate={() => {
                            setRunConfigPickerMode('new');
                            setRunConfigPickerOpen(true);
                          }}
                          onManage={() => {
                            if (onOpenProject) {
                              onOpenProject(composerProject.projectId);
                              return;
                            }
                            setRunConfigPickerMode('list');
                            setRunConfigPickerOpen(true);
                          }}
                        />
                      </span>
                    </div>
                    {/* The list's own actions (listing, groups, pins) report
                      through the shared error, whose strip lives on the
                      composer and thread pages — off screen while a phone
                      shows this page, where a failed listing would otherwise
                      read as "No chats yet". */}
                    {phoneListPage && error !== null ? (
                      <ErrorBanner
                        className="mx-3 mb-2"
                        message={error}
                        onDismiss={dismissError}
                      />
                    ) : null}
                    <ul className="m-0 flex min-h-0 flex-1 list-none flex-col gap-1 overflow-y-auto p-3 pt-1">
                      {!runsLoaded && runs.length === 0 ? (
                        <li className="px-2 py-1.5 text-sm text-muted-foreground">
                          Loading chats…
                        </li>
                      ) : (
                        <>
                          {sections.map(({ group, runs: sectionRuns }) => {
                            // From the statuses the ROWS are showing, never from
                            // the daemon column: a header computed from the row
                            // would contradict its own children in exactly the
                            // cases that matter (a live turn under a stale
                            // `completed`, a parked question).
                            const summary = runGroupSummary(
                              sectionRuns.map(sidebarRunStatus),
                            );
                            const sectionId = group?.id ?? null;
                            const sectionKey = sectionId ?? 'loose';
                            const isDropTarget =
                              drag?.kind === 'run' &&
                              dropSectionId === sectionId;
                            // A long section is folded to its WORKING set — the
                            // threads that are running or waiting on the user,
                            // plus the one that is open — and the rest go behind
                            // "Show all". A group of a hundred finished chats
                            // otherwise pushed every group below it off the
                            // screen, so the next group could only be reached by
                            // scrolling past conversations nobody was returning
                            // to. The header's count stays the section's TOTAL,
                            // so what the fold holds back is never in doubt.
                            // The PINNED band leads the section and the fold is
                            // computed over what is left. Two reasons it is
                            // taken out first rather than kept and `keep`-ed
                            // through: the fold preserves the caller's order, so
                            // a pinned row would sit wherever activity had put
                            // it — pinned and third — and `Show all` could
                            // otherwise hide one, which is the one thing a pin
                            // is a promise against.
                            const { pinned, rest } =
                              splitPinnedRuns(sectionRuns);
                            const folded = previewSectionRuns(rest, {
                              keep: (run) => {
                                if (run.id === activeRunId) {
                                  return true;
                                }
                                const status = sidebarRunStatus(run);
                                return (
                                  status === 'running' ||
                                  status === 'needs-input'
                                );
                              },
                            });
                            const showingAll = expandedSections.has(sectionKey);
                            const rows = [
                              ...pinned,
                              ...(showingAll ? rest : folded.visible),
                            ].map((run) => (
                              <ChatListItem
                                key={run.id}
                                runId={run.id}
                                active={run.id === activeRunId}
                                unseen={unseen.has(run.id)}
                                naming={namingRunIds.has(run.id)}
                                label={runLabel(run, teamNames)}
                                isTeam={run.teamId != null}
                                teamName={
                                  run.teamId
                                    ? (teamNames.get(run.teamId) ?? null)
                                    : null
                                }
                                status={sidebarRunStatus(run)}
                                lastMessage={run.lastMessage}
                                lastActivityAt={lastActivityOf(run)}
                                createdAt={run.createdAt}
                                archivedAt={run.archivedAt ?? null}
                                activity={activities.get(run.id) ?? null}
                                awaiting={run.awaiting}
                                monitors={run.monitorsOpen}
                                agentKind={run.agentKind}
                                taskIdentifier={run.taskIdentifier}
                                pullRequest={
                                  rowPullRequestByRun.get(run.id) ?? null
                                }
                                dragging={
                                  drag?.kind === 'run' && drag.id === run.id
                                }
                                onActivate={handleActivateRun}
                                onRename={handleRenameRun}
                                onDelete={handleDeleteRun}
                                // Read off the ROW, never off the scope: under
                                // `Show all` both kinds of row are listed
                                // together, so a view-wide flag would offer
                                // Unarchive on a live thread and Archive on a
                                // shelved one, in the same list.
                                archived={run.archivedAt != null}
                                // Both kinds. It was chats only for a release,
                                // which left a finished team run with Delete
                                // as its one row action — the thread whose
                                // history is most worth keeping had no way off
                                // the desk but destroying it.
                                onArchive={handleArchiveRun}
                                onUnarchive={handleUnarchiveRun}
                                // An analysis is not itself analysed.
                                onAnalyze={
                                  !isAnalysisRun(run)
                                    ? handleAnalyzeRun
                                    : undefined
                                }
                                onReflect={
                                  !isAnalysisRun(run) && !isHosted
                                    ? handleReflectRun
                                    : undefined
                                }
                                readLessonsMark={readLessonsMark}
                                // Read off the ROW, like `archived` above and
                                // for its reason: under `Show all` the band and
                                // the rest are one list, so a flag derived from
                                // where the row was drawn would offer Unpin to
                                // whatever happened to come first.
                                pinned={run.pinnedPosition !== null}
                                notes={run.notes}
                                onSetPinned={handleSetRunPinned}
                                color={run.color}
                                onSetColor={handleSetRunColor}
                                onDragStartRun={handleRunDragStart}
                                onDragOverRun={handleRunDragOver}
                                onDragEndRun={handleDragEnd}
                              />
                            ));
                            // Only when the fold is actually holding something
                            // back — a short section shows every row and needs no
                            // control saying so. It rides INSIDE the row list so
                            // it sits against the group's rail, where it reads as
                            // the end of these chats rather than as a stray
                            // sidebar action.
                            const foldRow =
                              folded.hidden > 0 ? (
                                <li key="fold" className="list-none">
                                  <button
                                    type="button"
                                    data-slot="section-fold"
                                    className="w-full cursor-pointer rounded-md px-2 py-1 text-left text-xs font-medium text-muted-foreground transition-colors hover:bg-sidebar-accent hover:text-sidebar-accent-foreground"
                                    onClick={() =>
                                      handleToggleSectionAll(sectionKey)
                                    }>
                                    {showingAll
                                      ? 'Show fewer'
                                      : `Show all ${sectionRuns.length}`}
                                  </button>
                                </li>
                              ) : null;
                            return (
                              // The WHOLE section is the drop zone — its header, its
                              // rail, its rows and the space between them. Hanging
                              // the target off the header alone left the body of an
                              // expanded group inert: a chat dragged into it lit
                              // nothing up and landed nowhere, which is the reported
                              // "gets selected, but doesn't drag". `dragover`
                              // bubbles, so one handler here covers every child and
                              // the rows need none of their own.
                              <li
                                key={group?.id ?? 'loose'}
                                data-slot="group-section"
                                data-section-id={sectionId ?? 'loose'}
                                className={cn(
                                  // The bottom padding is PERMANENT, not part of
                                  // the highlight: it is what keeps the colour rail
                                  // from running flush into the edge below it, and
                                  // adding it only while a drag hovers would shift
                                  // every row down at the moment the user is aiming
                                  // at one.
                                  'list-none rounded-lg pb-1.5',
                                  // Soft and NEUTRAL: `muted` rather than `accent`,
                                  // which is the palette's warm caramel and read as
                                  // a coloured state rather than as a destination —
                                  // and a hairline rather than a 2px ring, since a
                                  // heavy outline on a block this size in a 260px
                                  // sidebar reads as an error.
                                  isDropTarget &&
                                    'bg-muted/70 ring-1 ring-border',
                                )}
                                onDragOver={(event) => {
                                  // Without preventDefault this is not a drop
                                  // target at all, and the cursor shows the
                                  // no-entry glyph over the whole list.
                                  event.preventDefault();
                                  if (dragRef.current?.kind === 'run') {
                                    event.dataTransfer.dropEffect = 'move';
                                    handleSectionDragOver(sectionId);
                                  } else if (group !== null) {
                                    handleGroupDragOver(group.id);
                                  }
                                }}
                                onDrop={(event) => {
                                  event.preventDefault();
                                  handleDropInSection(sectionId);
                                }}>
                                {group ? (
                                  <GroupHeader
                                    group={group}
                                    summary={summary}
                                    unseen={sectionRuns.some((run) =>
                                      unseen.has(run.id),
                                    )}
                                    dragging={
                                      drag?.kind === 'group' &&
                                      drag.id === group.id
                                    }
                                    autoFocusName={namingGroupId === group.id}
                                    onNameFocused={clearNamingGroup}
                                    onToggle={handleToggleGroup}
                                    onRename={handleRenameGroup}
                                    onCommand={handleGroupCommand}
                                    teams={teams}
                                    onDragStart={handleGroupDragStart}
                                    onDragEnd={handleDragEnd}
                                  />
                                ) : groups.length > 0 &&
                                  sectionRuns.length > 0 ? (
                                  // Only once a group exists: with none, this label
                                  // would restate the panel heading directly above
                                  // it. The loose runs need a name of their own the
                                  // moment anything sits above them.
                                  <p
                                    data-slot="ungrouped-label"
                                    className="m-0 px-2 pt-1 pb-0.5 text-xs font-semibold tracking-wide text-muted-foreground uppercase">
                                    Ungrouped
                                  </p>
                                ) : null}
                                {group === null ? (
                                  <ul className="m-0 flex list-none flex-col gap-1 p-0">
                                    {rows}
                                    {foldRow}
                                  </ul>
                                ) : // An EMPTY group draws no rail: the container
                                // exists to enclose rows, and with none it rendered
                                // as a 4px orphan tick under the header. The
                                // section is the drop target either way, so an
                                // empty group can still be dropped into.
                                group.collapsed || rows.length === 0 ? null : (
                                  // The group's chats are ENCLOSED: indented, and
                                  // hung off a rail in the group's own colour, so
                                  // where one group's threads end and the next
                                  // begins is visible without counting. Without it
                                  // an expanded group ran straight into the one
                                  // below and the whole list read as flat.
                                  <ul
                                    data-slot="group-runs"
                                    className={cn(
                                      'm-0 ml-3 flex list-none flex-col gap-1 border-l-2 py-1 pl-2',
                                      GROUP_RAIL_CLASS[group.color],
                                    )}>
                                    {rows}
                                    {foldRow}
                                  </ul>
                                )}
                              </li>
                            );
                          })}
                          {runs.length === 0 ? (
                            <li className="px-2 py-1.5 text-sm text-muted-foreground">
                              {chatScope === 'archived'
                                ? 'Nothing archived yet'
                                : 'No chats yet'}
                            </li>
                          ) : null}
                          {hasOlderRuns ? (
                            <li>
                              <OlderMessagesControl
                                slot="older-runs"
                                className="px-1"
                                loading={loadingOlderRuns}
                                onLoad={loadOlderRuns}
                                label="Load older chats"
                                loadingLabel="Loading older chats…"
                              />
                            </li>
                          ) : null}
                        </>
                      )}
                    </ul>
                  </aside>
                )}

                {activeRunId === null && isHosted ? (
                  <section
                    data-slot="hosted-thread-opening"
                    className="flex min-h-0 flex-col items-center justify-center gap-3 p-4 text-sm text-muted-foreground">
                    {error === null ? (
                      <span role="status" className="flex items-center gap-2">
                        <Spinner />
                        Opening the chat…
                      </span>
                    ) : (
                      <ErrorBanner
                        className="w-full max-w-xl"
                        message={error}
                        action={
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            className="h-7 shrink-0"
                            onClick={() => {
                              setError(null);
                              refreshRuns();
                            }}>
                            Try again
                          </Button>
                        }
                        onDismiss={() => setError(null)}
                      />
                    )}
                  </section>
                ) : activeRunId === null ? (
                  // The new-run composer — the landing view, one Cursor-style card: the
                  // task text on top and, inside the same card, the graph/agent it
                  // targets, the folder it runs in, and the trigger the run starts from
                  // (a run only starts by firing one), with a round send control.
                  // Every picker in this card is positioned against the
                  // WINDOW rather than against its own trigger's wrapper. The
                  // section scrolls, and a box that scrolls vertically cannot
                  // keep `overflow-x: visible` — CSS forces both axes
                  // non-visible together — so it clips a panel on BOTH edges.
                  // Reported as "окошко заходит за края аппликэйшена, оно
                  // срезается" against the branch picker, and measured at
                  // 1000×640: the panel sat at `left: 447, top: 8` inside a
                  // section whose own box starts at `left: 480, top: 41`, so
                  // every branch name lost its first characters and the search
                  // field was cut off the top. Declared HERE, on the container
                  // that does the clipping, rather than passed through each
                  // chip — the rule `Dialog` already follows for its scrolling
                  // body.
                  <MenuAnchorContext.Provider value="viewport">
                    <section
                      className={cn(
                        'flex min-h-0 flex-col overflow-y-auto',
                        phoneListPage && 'hidden',
                      )}>
                      {mobileBack}
                      {mobilePanelToggle}
                      <div
                        className="flex min-h-0 flex-1 flex-col items-center justify-center"
                        style={{ padding: START_COLUMN_PAD }}>
                        {/* Centred in the PANE it lives in — equal air either
                          side of the card. It briefly carried a margin that
                          re-centred it on the whole WINDOW instead, derived
                          from `100vw - 100%`; that reads as shifted left,
                          because the chrome it compensates for is a column the
                          eye has already stopped counting as part of the page. */}
                        <div
                          className="flex w-full flex-col gap-5"
                          style={{ maxWidth: START_COLUMN_WIDTH }}>
                          <h2 className="text-center text-xl font-semibold tracking-tight">
                            What are we building?
                          </h2>
                          <div className="relative">
                            {skillMenuOpen ? (
                              <SkillMenu
                                skills={skillMatches}
                                highlightIndex={highlightedIndex}
                                onSelect={pickSkill}
                                onHighlight={setSkillHighlight}
                              />
                            ) : null}
                            <ComposerTopRow>
                              <TargetSelect
                                value={target}
                                teams={teams}
                                cliDetections={cliDetections}
                                onChange={changeTarget}
                              />
                              <FolderSelect
                                folder={folder}
                                recentFolders={recentFolders}
                                onChoose={chooseFolder}
                                onBrowse={() => void pickFolder()}
                              />
                              <BranchSelect
                                info={git.info}
                                switching={git.switching}
                                onSwitch={(branch) => {
                                  void git.switchTo(branch);
                                }}
                              />
                              {composerProject.source === 'manual' ||
                              projects.some(
                                (project) =>
                                  project.id === composerProject.projectId,
                              ) ? (
                                <ProjectSelect
                                  variant="ghost"
                                  projects={projects}
                                  value={composerProject.projectId}
                                  noneLabel="No project"
                                  aria-label="Project for the new run"
                                  title="Its instructions go to every agent of the new run"
                                  onChange={(projectId) => {
                                    setComposerProject({
                                      projectId,
                                      source: 'manual',
                                    });
                                    const picked = projects.find(
                                      (project) => project.id === projectId,
                                    );
                                    if (picked !== undefined) {
                                      seedProjectTarget(picked);
                                    }
                                  }}
                                />
                              ) : null}
                              {!teamSlug ? (
                                // The optional config directory (account / profile)
                                // this chat's CLI runs as.
                                // Beside the folder because it is the same kind of
                                // fact — WHERE the run reads from — and above the text
                                // because, like the folder, it is fixed the moment the
                                // chat is created. A team's nodes each name their
                                // own in its YAML, so the chip is a chat's alone.
                                <ConfigDirSelect
                                  configProfiles={configProfiles.filter(
                                    (profile) => profile.agent === agentKind,
                                  )}
                                  configDir={configDir}
                                  recentConfigDirs={recentConfigDirs}
                                  unavailableReason={
                                    composerConfigDirUnavailableReason
                                  }
                                  onChange={(chosen) =>
                                    chooseConfigDir(agentKind, chosen)
                                  }
                                  onBrowse={() => void pickConfigDir()}
                                />
                              ) : null}
                              {teamSlug && triggers.length > 0 ? (
                                <Select
                                  variant="ghost"
                                  value={triggerId}
                                  aria-label="Trigger the run starts from"
                                  groups={[
                                    {
                                      items: triggers.map((entry) => ({
                                        value: entry.id,
                                        label: `${entry.name} · ${entry.trigger}`,
                                        icon: <Zap />,
                                      })),
                                    },
                                  ]}
                                  onValueChange={setTriggerId}
                                />
                              ) : null}
                            </ComposerTopRow>
                            <MessageComposer
                              attachments={attachments.attachments}
                              onRemoveAttachment={attachments.remove}
                              onAttachFiles={fileAttach.attach}
                              onPasteImages={attachments.addFromClipboard}
                              text={composerText}
                              textareaProps={{
                                ref: newChatInputRef,
                                rows: 4,
                                'aria-label': 'Task for the new run',
                                className: 'min-h-24',
                                placeholder: teamSlug
                                  ? 'Describe the task for the team…'
                                  : 'Message the agent…',
                                onKeyDown: (event) => {
                                  if (handleSkillMenuKeys(event)) {
                                    return;
                                  }
                                  if (isComposerSendKey(event)) {
                                    event.preventDefault();
                                    void send();
                                  }
                                },
                              }}
                              actions={
                                <Button
                                  type="button"
                                  size="icon"
                                  className="size-8 shrink-0 rounded-full"
                                  disabled={
                                    (!hasContent && !attachBusy) || streaming
                                  }
                                  // Held while a paste is still being read,
                                  // with the reason on hover — the follow-up
                                  // composer's rule, for its reason.
                                  aria-disabled={attachBusy}
                                  aria-label={teamSlug ? 'Start run' : 'Send'}
                                  title={
                                    attachBusy
                                      ? attachBusyTitle
                                      : teamSlug
                                        ? 'Start run'
                                        : 'Send'
                                  }
                                  onClick={() => void send()}>
                                  {attachBusy ? (
                                    <Spinner className="size-4 text-primary-foreground" />
                                  ) : teamSlug ? (
                                    <Zap className="size-4 shrink-0" />
                                  ) : (
                                    <ArrowUp className="size-4 shrink-0" />
                                  )}
                                </Button>
                              }>
                              {/* ONE control for the model and everything it
                                  can be run with — see `ModelSettingsSelect`.
                                  Only a single-agent run picks any of it here;
                                  a team's nodes each name their own in its
                                  YAML. */}
                              {!teamSlug ? (
                                <ModelSettingsSelect
                                  configProfiles={configProfiles.filter(
                                    (profile) => profile.agent === agentKind,
                                  )}
                                  agentKind={agentKind}
                                  models={agentModels}
                                  loading={agentModelsLoading}
                                  settingsLoading={modelSettingsLoading}
                                  model={models[agentKind] ?? null}
                                  onModelChange={(model) =>
                                    changeModel(agentKind, model)
                                  }
                                  efforts={agentEfforts.efforts}
                                  effort={efforts[agentKind] ?? null}
                                  onEffortChange={(effort) =>
                                    changeEffort(agentKind, effort)
                                  }
                                  // The approval posture of the NEXT chat,
                                  // moved in here from a chip of its own —
                                  // ASKED FOR as "add auto-approve option to
                                  // model settings popover instead". A mode
                                  // this CLI does not honour shows as the
                                  // "cli default" placeholder rather than a
                                  // lie: the user may have picked it while
                                  // another agent was selected.
                                  approvalCapability={
                                    composerApprovalCapability
                                  }
                                  approval={
                                    composerApprovalCapability?.modes.includes(
                                      approvalMode,
                                    )
                                      ? approvalMode
                                      : null
                                  }
                                  onApprovalChange={changeApprovalMode}
                                  windows={agentContextWindows.windows}
                                  contextWindow={
                                    contextWindows[agentKind] ?? null
                                  }
                                  onContextWindowChange={(size) =>
                                    changeContextWindow(agentKind, size)
                                  }
                                  autoCompactPercent={autoCompactPercent}
                                  onAutoCompactChange={changeAutoCompact}
                                  parameters={agentModelParameters.parameters}
                                  parameterValues={
                                    modelParameters[agentKind] ??
                                    NO_PARAMETER_VALUES
                                  }
                                  onParameterChange={(id, next) =>
                                    changeModelParameter(agentKind, id, next)
                                  }
                                />
                              ) : null}
                            </MessageComposer>
                          </div>
                          {/* The suggestion-chip row that sat here is gone. Both halves of it
                are now rows in the composer's own menus — folders in the folder
                chip, teams in the target chip, each searchable — so the
                chips only restated, below the card, choices the card already
                offered, and were capped at three besides.

                              What stands here now is not that row rebuilt: those chips
                              wrote a value the app already knew about into a chip, while a
                              fast action writes the user's OWN sentence into the message. */}
                          <FastActionBar
                            actions={fastActions}
                            onPress={insertFastAction}
                            onManage={
                              onOpenSettings
                                ? () => onOpenSettings('fast-actions')
                                : undefined
                            }
                          />
                          {/* A refused branch switch reports here — the guard says WHY
                ("uncommitted changes…"), which is the whole point of it, and
                offers the one thing the app can do about it. */}
                          {composerNotice ? (
                            <ErrorBanner
                              message={composerNotice.message}
                              tone={composerNotice.tone}
                              action={
                                noticeUseFolder !== null ? (
                                  // The way out of a branch another worktree
                                  // holds: git will never check it out twice, so
                                  // the only route to that branch is the folder
                                  // that already has it. Same clickable-string
                                  // shape as Pull below, and the same reasoning —
                                  // it is the rest of the sentence, not a second
                                  // control.
                                  <Button
                                    type="button"
                                    variant="link"
                                    size="sm"
                                    className="h-auto shrink-0 p-0 text-xs text-warning underline decoration-warning/40 underline-offset-4 hover:decoration-warning"
                                    title={`Run this chat in ${noticeUseFolder}`}
                                    onClick={() => {
                                      // Only the folder: the branch is already
                                      // checked out there, so there is nothing
                                      // left to switch, and `useGitInfo` re-reads
                                      // on its own when the directory changes.
                                      chooseFolder(noticeUseFolder);
                                      git.clearError();
                                    }}>
                                    Use that folder
                                  </Button>
                                ) : (
                                  <GitNoticeOffers
                                    notice={composerNotice}
                                    pulling={git.pulling}
                                    carrying={git.carrying}
                                    onPull={() => {
                                      void git.pull();
                                    }}
                                    onCarry={() => {
                                      void git.carry();
                                    }}
                                  />
                                )
                              }
                              onDismiss={dismissError}
                            />
                          ) : null}
                        </div>
                      </div>
                    </section>
                  </MenuAnchorContext.Provider>
                ) : (
                  <section className="flex min-h-0 flex-col">
                    {mobileBack}
                    {mobilePanelToggle}
                    {activeRun ? (
                      <ChatHeader
                        label={runLabel(activeRun, teamNames)}
                        analysisSource={analysisSourceOf(activeRun)}
                        actions={
                          hosted?.headerActions?.({
                            discard:
                              hosted.discard === undefined
                                ? null
                                : discardHosted,
                          }) ?? null
                        }
                        isTeam={activeRun.teamId != null}
                        agentKind={activeRun.agentKind}
                        // Where this conversation happens. Beside the agent
                        // because it is the same kind of fact — fixed for the
                        // run's life — and after three rejected positions in the
                        // composer below.
                        cwd={activeRun.cwd}
                        worktreeOf={taskWorktreeOf}
                        // Which profile/account this conversation belongs to, when
                        // it is not the CLI's default.
                        configDir={activeRun.configDir}
                        // And whichever profile the FOLDER pins over that one,
                        // since the CLI applies its project settings over the
                        // environment geniro hands it — so the row above is
                        // what this chat asked for, not necessarily what it got.
                        configDirPin={activeRun.configDirPin}
                        status={activeRunStatus}
                        lastActivityAt={lastActivityOf(activeRun)}
                        workedMs={threadTotalsShown.ms}
                        turnCount={threadTotalsShown.turns}
                        // The recorded total plus what the running turns
                        // have spent that no row carries yet.
                        {...headerSpendOf(
                          withLiveCost(
                            {
                              tokens: null,
                              costUsd: threadTotals.costUsd,
                              estimatedCostUsd: threadTotals.estimatedCostUsd,
                            },
                            liveRunCost(liveText),
                          ),
                        )}
                        costedTurns={threadTotals.costedTurns}
                        // Only while the run is actually live. A transcript
                        // whose last row is a user message describes an open
                        // turn whether or not one is still running — a daemon
                        // that died mid-turn leaves exactly that — and a
                        // counter reading off the rows alone would tick for
                        // days on a thread nothing is working on. The status
                        // is the authority on whether work is in flight; the
                        // rows only say what it started from.
                        openTurns={openTurnsShown}
                        // A team's agents work at once, so its clock is the
                        // UNION of their stretches — summed, it ran two seconds a
                        // second while a Manager waited on its Engineer.
                        activeSpans={
                          activeRun.teamId != null
                            ? threadTotals.activeSpans
                            : null
                        }
                        pausedSpans={threadTotals.pausedSpans ?? undefined}
                        // The delegate, task and terminal counters that used to
                        // end this row are chips on the composer shelf now.
                        // `sidePanelLive` still feeds all three from one place
                        // — see the `ComposerShelf` below.
                      />
                    ) : null}

                    {/* Stating the x axis is NOT redundant beside `overflow-y-auto`.
                  CSS resolves a `visible` axis to `auto` whenever the other
                  axis scrolls, so this box was a horizontal scroller by
                  omission — measured at 1100px wide: scrollWidth 759 against
                  clientWidth 620, and the whole conversation could be dragged
                  sideways off its own pane.

                  `hidden` and not `clip`, which was tried: CSS computes a
                  `clip` axis back to `hidden` as soon as its neighbour
                  scrolls, so the two are the same declaration here and only
                  one of them says what the browser will do.

                  Nothing reachable is lost: every genuinely wide thing in a
                  transcript (a fenced code block, a GFM table) is its OWN
                  `overflow-x-auto` box and still scrolls inside itself, and
                  the sources that overflowed as TEXT (long URLs, inline code
                  holding a path) are fixed where they render, in
                  `markdown-content.tsx`.

                  Below ~1000px `scrollWidth` still reads wider than
                  `clientWidth` — Chromium counts layout overflow those inner
                  scroll containers have already clipped. Verified in the
                  browser that it is inert: at 900px a horizontal wheel gesture
                  and a `scrollIntoView` on the widest descendant both leave
                  `scrollLeft` at 0. */}
                    {/* `overflow-anchor: none` is what keeps the tail FOLLOWING,
                  and it is the fix for a reported defect rather than a
                  precaution: "я делаю latest… он какое-то время работает, я
                  отхожу, и он перестаёт это делать", with the reporter's own
                  guess that it happens around a task list.

                  Chromium's scroll anchoring adjusts `scrollTop` on its own
                  whenever content ABOVE the viewport changes height, to keep
                  what you are looking at still. A superseded task card
                  collapsing eight rows to one is exactly that, and the
                  adjustment is indistinguishable from a scroll: it reaches
                  `nextFollowState` as `scrollTop` moving UP, which is the one
                  thing that means "the user is reading something back there" —
                  so the follow switched itself off, permanently, while nobody
                  was touching anything.

                  MEASURED in the running app on this scroller: insert a 600px
                  block above the viewport and remove it again, and the tail
                  stopped following (a later 500px growth left the viewport
                  442px short); with anchoring off, both the removal and the
                  growth left it at 0.

                  Fixed HERE rather than in `nextFollowState`, and the
                  alternative is worth recording because it looks reasonable:
                  ignoring any position change that came with a height change
                  would also silence anchoring — and would silence the USER at
                  the same time, since a streaming transcript grows on almost
                  every frame, so scrolling up mid-turn to read something would
                  no longer register at all. That is the original complaint,
                  reintroduced to fix its sequel.

                  It also de-conflicts the paging path below, which preserves
                  the reader's place itself (`scrollTop += ` the height that
                  arrived) — with anchoring on, that adjustment was applied on
                  top of the browser's own. */}
                    {/* `[&>*:first-child]:mt-auto` bottom-anchors a SHORT
                    conversation: the free space goes above the first row, so a
                    two-message thread sits just over the composer instead of
                    hanging from the top of the pane with the gap below it —
                    measured at 490px of an empty 672px transcript. Once the
                    content is taller than the pane the auto margin resolves to
                    zero and this does nothing at all, which is why it needs no
                    branch on item count.

                    An auto MARGIN on the first child, not `justify-end` on the
                    container: in a scrolling flex box, end-justification pushes
                    overflow past the scroll origin, where it cannot be reached
                    by scrolling up. The margin has no such failure mode. */}
                    <TranscriptContexts
                      runOutcomes={activeRunOutcomes}
                      runStages={activeRun?.stages ?? null}
                      openTeamNote={
                        activeRun?.teamId != null ? openTeamNote : null
                      }
                      openThread={
                        isHosted
                          ? (hosted?.onOpenThread ?? null)
                          : handleActivateRun
                      }
                      openMemory={onOpenMemory ?? null}
                      openKnowledge={onOpenKnowledge ? openKnowledge : null}
                      collapseToolSteps={collapseToolSteps}
                      runActivity={activeActivity}
                      turnDurations={turnDurations}
                      revealCallBlock={revealCallBlock}
                      revealCall={revealCall}
                      openSubagentDetail={openSubagentDetail}>
                      <div
                        data-slot="transcript"
                        className="flex min-h-0 flex-1 flex-col gap-2.5 overflow-x-hidden overflow-y-auto p-4 [overflow-anchor:none] [&>*:first-child]:mt-auto">
                        {/* A chat opens on its newest 1,000 items, so a long one
                    begins part-way through itself. SAID, rather than left as a
                    conversation that appears to start mid-sentence — and it is
                    the top row precisely because that is where a reader who has
                    scrolled this far is looking. */}
                        {/* A BUTTON as well as a caption: scrolling is the only
                    other trigger, and a transcript that does not overflow its
                    pane has no scroll to give. REPORTED as "it cannot load
                    messages" over a team whose newest page folded into ONE
                    call card — "Scroll up" above nothing to scroll. */}
                        {loadingHistory && transcriptEntries.length === 0 ? (
                          <div
                            data-slot="thread-loading"
                            role="status"
                            className="flex flex-1 items-center justify-center gap-2 text-sm text-muted-foreground">
                            <Spinner />
                            Loading conversation…
                          </div>
                        ) : null}
                        {hosted !== null &&
                        !loadingHistory &&
                        transcriptEntries.length === 0 ? (
                          <p
                            data-slot="hosted-thread-empty"
                            className="m-0 text-sm text-muted-foreground">
                            {hosted.emptyText}
                          </p>
                        ) : null}
                        {hasOlder ? (
                          <OlderMessagesControl
                            slot="older-messages"
                            className="justify-center"
                            loading={loadingOlder}
                            onLoad={() => {
                              const scroller =
                                transcriptEndRef.current?.parentElement;
                              if (scroller) {
                                void pageOlderUntilVisible(scroller);
                              }
                            }}
                          />
                        ) : null}
                        {transcriptEntries.map((entry) => {
                          const key = transcriptEntryKey(entry);
                          const startSeq = entryStartSeq(entry);
                          // The seq ANCHOR, which is what makes a search
                          // hit reachable: `revealSeq` finds the last
                          // anchor at or below the hit's seq and scrolls
                          // to it. Here rather than inside
                          // `TranscriptEntryView`, because that component
                          // returns a different root per entry kind and
                          // this is the one place they are all one list.
                          //
                          // `empty:hidden` is load-bearing twice over. An
                          // entry CAN render nothing (`TranscriptItem`
                          // answers null for ten kinds), and an empty flex
                          // child would still consume the container's
                          // `gap-2.5` — a stray 10px wherever one of those
                          // rows falls. It is also exactly the condition
                          // `revealSeq`'s `:not(:empty)` filters on, so
                          // what is skipped and what is invisible cannot
                          // drift apart.
                          const wrap = (
                            children: React.ReactNode,
                          ): React.JSX.Element => (
                            <TranscriptRow
                              key={key}
                              // `flex flex-col` is LOAD-BEARING, not
                              // decoration: `align-self` resolves only
                              // against a flex parent, and a bare
                              // `MessageBubble` relies on it — the
                              // `note` variant is `self-center`, which
                              // is how the `✓ done · 21s` row at the
                              // end of every turn is centred. As a plain
                              // block wrapper this displaced every one
                              // of them left; a one-child flex column
                              // hands the alignment back untouched.
                              // `display: contents` would too, and is
                              // wrong — it generates no box, so the mark
                              // below would not paint and `revealSeq`
                              // would have nothing to measure.
                              //
                              // The landing mark is a WASH, and it was a
                              // ring first — reported as not liked, and
                              // the reason is visible the moment a user
                              // message is the hit: this wrapper spans
                              // the transcript's whole width while a
                              // bubble is `self-end`, so an OUTLINE
                              // draws a box around the empty half and
                              // reads as a stray rectangle rather than
                              // as "this row". A fill reads as the row
                              // either way, which is also why the mark
                              // stays on the wrapper rather than moving
                              // onto the bubble: a tool group, a card
                              // and a `note` are not bubbles and have no
                              // one element to tint.
                              //
                              // The ring was chosen because it is a
                              // box-shadow and costs no layout, and that
                              // reasoning was right about padding and
                              // wrong about the conclusion: `-my-1 py-1`
                              // is net ZERO — the padding grows the
                              // painted box, the negative margin takes
                              // the same amount back off the margin box
                              // flex actually lays out — so the wash
                              // breathes without moving a single
                              // neighbouring row. Both are in the marked
                              // arm, so an unmarked row is untouched.
                              // Only the colour transitions; the
                              // geometry is instant, which is the right
                              // way round for a flash.
                              className={cn(
                                mark?.key === `entry:${startSeq}` &&
                                  JUMP_MARK_CLASS,
                              )}
                              {...jumpAnchorProps(
                                'transcript',
                                startSeq,
                                `entry:${startSeq}`,
                              )}>
                              {children}
                            </TranscriptRow>
                          );
                          if (
                            entry.type !== 'item' ||
                            entry.item.kind !== 'approval_request'
                          ) {
                            return wrap(
                              <TranscriptEntryView
                                entry={entry}
                                nodes={nodeMeta}
                                chatAgentName={activeRun?.agentKind ?? null}
                                soloAgent={soloAgent}
                                soloNodeId={
                                  wfNodes.relay ? null : wfNodes.rootId
                                }
                              />,
                            );
                          }
                          const item = entry.item;
                          // EVERY open request's card lives above the composer, so
                          // every one of them leaves a marker here. Keyed on openness
                          // rather than on the pinned id: keying on the pin gave the
                          // SECOND open question a fully live card in the scroller,
                          // which is the failure the pin exists to end. Leaving the
                          // live card here too would put two sets of buttons over one
                          // one-shot verdict channel; leaving nothing would silently
                          // drop a row out of the conversation's order.
                          if (openRequestId(item) !== null) {
                            return wrap(
                              <MessageBubble variant="note">
                                {pinnedRequest?.id === item.id
                                  ? '❓ waiting on your answer — the card is pinned below'
                                  : '❓ waiting on your answer — its card opens below once the pinned one is answered'}
                              </MessageBubble>,
                            );
                          }
                          const askerName =
                            (item.memberId
                              ? (nodeMeta.get(item.memberId)?.name ??
                                item.memberId)
                              : activeRun?.agentKind) ?? 'agent';
                          const card = (
                            <div className="w-full">
                              {approvalCardFor(item)}
                            </div>
                          );
                          // A solo agent's card needs no identity frame either.
                          return wrap(
                            soloAgent ? (
                              card
                            ) : (
                              <SenderRow
                                name={askerName}
                                colorKey={item.memberId ?? undefined}
                                time={formatClockTime(item.createdAt)}>
                                {card}
                              </SenderRow>
                            ),
                          );
                        })}
                        <div ref={transcriptEndRef} />
                      </div>
                      {activeRun === null ? null : (
                        <>
                          {hostedWorkingThreads.length === 0 ? null : (
                            <WorkingThreadsCard
                              threads={hostedWorkingThreads}
                              onOpenThread={hosted?.onOpenThread}
                              beside={startedAgents.length > 0}
                            />
                          )}
                          <WorkingAgentsCard
                            key={activeRun.id}
                            rows={startedAgents}
                            runId={activeRun.id}
                            api={chatApi}
                            client={client}
                            onShowInChat={openCall}
                            nodes={nodeMeta}
                            chatAgentName={activeRun.agentKind}
                            delegateState={runState}
                            collapseToolSteps={collapseToolSteps}
                            work={startedAgentsWork}
                          />
                        </>
                      )}
                    </TranscriptContexts>

                    {/* Between the scroller and the composer, and drawn OVER
                  the transcript from a zero-height row — see
                  `jump-to-latest.tsx` for why it cannot take part in the
                  column's sizing. */}
                    {/* Offered whenever the newest message is not what is on
                    screen, which is TWO states rather than one. `aboveTail` is
                    the scroll position; `awayFromTail` is a window fetched
                    around a search hit, whose own bottom is somewhere in the
                    middle of the conversation — there the button is the only way
                    back, and it has to FETCH rather than scroll. */}
                    <JumpToLatest
                      visible={aboveTail || awayFromTail}
                      onJump={awayFromTail ? backToTail : jumpToLatest}
                    />

                    {/* OUTSIDE the scroller, not `sticky` inside it: a sticky row
                  still belongs to the scrolled content, so it can be scrolled
                  past and it overlaps the messages it floats above. Here the
                  card is a sibling of the transcript and the composer, which
                  makes "always visible while a question is open" a layout
                  fact rather than a scroll-position accident.

                  It sits ABOVE the composer because that is where the answer
                  gets typed — the question and the reply belong on the same
                  edge of the screen. */}
                    {pinnedRequest ? (
                      <div
                        data-slot="pinned-request"
                        // Named and given a role that can CARRY a name, so a
                        // screen-reader user typing into the composer learns the
                        // turn has stopped on them. Deliberately NOT `aria-live`:
                        // the card inside is a tablist full of interactive
                        // controls, and announcing the whole region on every
                        // keystroke inside it would be worse than saying nothing.
                        role="region"
                        aria-label="Question waiting on your answer"
                        // Bounded and scrolling itself, so option previews stacked
                        // above the options cannot push them, the answer field and
                        // the composer off screen.
                        className="max-h-[60vh] min-h-0 shrink overflow-y-auto border-t border-border bg-card/60 px-4 py-3">
                        {openRequests.length > 1 ? (
                          <p className="m-0 mb-1.5 text-xs text-muted-foreground">
                            {openRequests.length} questions waiting — answering
                            this one opens the next
                          </p>
                        ) : null}
                        {/* Every open request is rendered, and all but the newest are
                      `hidden`. Rendering only the pinned one would unmount the
                      card being typed into the moment a newer question arrived,
                      resetting its picks, its text and every staged attachment
                      — with no way for the user to get any of it back. `hidden`
                      also keeps the concealed cards out of the tab order and
                      the accessibility tree, which `display:none` via a class
                      would not guarantee against a utility being overridden. */}
                        {openRequests.map((request) => (
                          <div
                            key={request.id}
                            hidden={request.id !== pinnedRequest.id}>
                            {approvalCardFor(request)}
                          </div>
                        ))}
                      </div>
                    ) : null}

                    {transcriptError ? (
                      <ErrorBanner
                        // Was a full-bleed band with its own rule, drawn that
                        // way because the strip had no surface to be seen by.
                        // It has one now, so this is an inset card and the
                        // rule would be a second separator around it.
                        className="mx-4 mb-2"
                        message={transcriptError}
                        // The run outlived the team it ran: there is nothing to
                        // retry and nothing to fix, so the only thing left to offer
                        // is removing the run. It opens the same confirm every other
                        // delete does — this is a shortcut to that action, not a
                        // second, quieter way to destroy history.
                        action={
                          missingTeam && activeRun ? (
                            <Button
                              type="button"
                              variant="outline"
                              size="sm"
                              className="h-7 shrink-0"
                              onClick={() => handleDeleteRun(activeRun.id)}>
                              <Trash2 className="size-3.5 shrink-0" />
                              Delete this run
                            </Button>
                          ) : null
                        }
                        onDismiss={dismissError}
                      />
                    ) : null}

                    {/* The ACCOUNT sign-in the transcript's error row started,
                        pinned here rather than drawn on that row. The row is
                        somewhere in a scrollback the user is free to leave, and
                        this flow needs a place they can still see when the
                        browser hands them back — including the code field claude
                        asks for, which is unusable off-screen. Above the
                        composer is where this chat already puts everything the
                        user has to act on (the queue, the failure banner).

                        The MCP half of the same controller renders in the dialog
                        it was pressed in; `server` is which one this is. */}
                    {login.login && login.login.server === null ? (
                      // `px-4` for the panel's own `-mx-4` to cancel against:
                      // it is built as a full-bleed band inside a card that
                      // pads its content, and dropped into an unpadded column
                      // the negative margin hangs it over both edges.
                      <div className="shrink-0 px-4">
                        <CliLoginProgress
                          session={login.login.session}
                          onSubmitCode={(code) => void login.submitCode(code)}
                          onCancel={() => void login.cancel()}
                          onDismiss={login.dismiss}
                          error={login.error}
                        />
                      </div>
                    ) : null}

                    {/* No rule above the composer. The card below already has
                        its own border and its own shadow, so the hairline was
                        a second edge a few pixels above the first — it read as
                        a stray line across the pane rather than as the
                        boundary of anything. The transcript's own scroll and
                        the card's elevation are what separate the two. */}
                    <div className="flex flex-col gap-2 p-3">
                      <WaitingMessagesStrip
                        messages={waitingMessages.messages}
                        onDeliver={waitingMessages.deliver}
                        onRemove={waitingMessages.remove}
                      />
                      {/* The queue and the shelf share ONE reserved line. The
                          shelf keeps its row's height even when it holds no
                          chip (so a chip coming or going never moves the
                          transcript), and a queue under it used to leave that
                          row standing EMPTY between the two — REPORTED as a
                          permanent gap. So while anything is queued, the chips
                          ride in the queue's own header line, which is held at
                          the same height: the reservation is always filled by
                          something, and a chip still cannot resize it. */}
                      <QueuedStrip
                        messages={queued}
                        paused={
                          activeRun ? pausedQueues.has(activeRun.id) : false
                        }
                        turnInFlight={streaming}
                        // Only a running turn's ending releases the head; with
                        // none — after Stop, or a send that failed — nothing
                        // will until the user does.
                        advancing={streaming}
                        postingIds={postingIds}
                        steerUnavailableReason={steerUnavailableReason}
                        steerInterrupts={steerInterrupts}
                        steerStatus={steerStatus}
                        onEdit={messageQueue.edit}
                        onRemove={messageQueue.remove}
                        onReorder={messageQueue.reorder}
                        onSteer={(id) => void messageQueue.steer(id)}
                        onTogglePause={messageQueue.togglePause}
                        leading={(control) =>
                          renderComposerShelf(true, control)
                        }
                      />
                      {queued.length === 0 ? renderComposerShelf(false) : null}

                      {/* The SAME composer card as the new-run screen, with the run's
                fixed choices (agent/graph, folder, trigger) as inactive
                chips — a run's identity can't change after creation. */}
                      <div className="relative">
                        {skillMenuOpen ? (
                          <SkillMenu
                            skills={skillMatches}
                            highlightIndex={highlightedIndex}
                            onSelect={pickSkill}
                            onHighlight={setSkillHighlight}
                          />
                        ) : null}
                        {/* There is NO top row on an open run any more, and the
                    last chip to leave it was the team's trigger — it is
                    inside the card now, in the slot the model chip holds on a
                    chat (see `ComposerBottomRow` below). REPORTED as "i see
                    request - manual trigger here. We should not have it there.
                    It should be in textarea, in same place where model suppose
                    to be": one lone chip on a band of its own, between the
                    shelf's chips and the card, read as a third row of chrome
                    over a composer a team run cannot even type into.

                    Every chip that used to live here went the same way and for
                    the same reason. This row states what is still to be DECIDED
                    about the run, and a run's identity is decided at creation:
                    approval, model and effort are live per-turn controls and sit
                    inside the card; the FOLDER, the agent and the profile are
                    fixed for the run's life and belong to the header's identity
                    line (see `chat-header.tsx`'s `cwd` prop for the three
                    positions tried in this composer first, and why a fact that
                    changes nothing kept looking wrong on a band of its own). The
                    branch chip is gone outright: it was read-only anyway, and
                    naming live repo state under a transcript whose turns all run
                    against the tree the run STARTED on only invited a switch the
                    control could not perform. */}
                        <MessageComposer
                          attachments={attachments.attachments}
                          onRemoveAttachment={attachments.remove}
                          onAttachFiles={fileAttach.attach}
                          onPasteImages={attachments.addFromClipboard}
                          // Only between turns of a live chat: a running turn is
                          // re-warming the cache as it goes, and an archived
                          // chat takes no next message to warn about.
                          notice={
                            activeRun &&
                            !streaming &&
                            !activeRunArchived &&
                            !activeRun.teamId ? (
                              <PromptCacheNotice
                                expiresAt={activeRun.promptCacheExpiresAt}
                                ttlMs={activeRun.promptCacheTtlMs}
                                ttlReason={activeRun.promptCacheTtlReason}
                                contextTokens={activeRun.contextTokens}
                              />
                            ) : null
                          }
                          text={composerText}
                          textareaProps={{
                            rows: 2,
                            'aria-label':
                              hosted?.composerLabel ?? 'Message the agent',
                            disabled: activeRunArchived,
                            placeholder:
                              hosted !== null && !streaming
                                ? hosted.composerPlaceholder
                                : followUpPlaceholder({
                                    archived: activeRunArchived,
                                    working: streaming && !activeRunHeld,
                                    team: Boolean(activeRun?.teamId),
                                    narrow: narrowViewport,
                                    lead: relayLeadName,
                                  }),
                            onKeyDown: (event) => {
                              if (handleSkillMenuKeys(event)) {
                                return;
                              }
                              if (isComposerSendKey(event)) {
                                event.preventDefault();
                                void sendFollowUp();
                              }
                            },
                          }}
                          actions={
                            <>
                              {/* The run's FOLDER is not here any more — it is
                          INSIDE the card, at its top right (see that chip for
                          the two positions it held before this one). It led the
                          actions for a while, on the reading that a cwd fixed
                          at creation is a caption on the button that dispatches
                          the work rather than a picker among live ones; it is a
                          caption on the MESSAGE now, which answers the same
                          observation without putting the one user-data label on
                          a line that may never wrap.

                          The run's config directory is NOT repeated here.
                          It is in the header, beside the agent, because it is
                          the same kind of fact — fixed for the run's life, and
                          about what the conversation IS rather than where this
                          message goes. Two chips for one fact only invited them
                          to disagree. */}
                              {/* Drawn while idle always (disabled when
                                    empty), and while a turn runs only once
                                    there is something to send — beside Stop. */}
                              {!streaming || hasContent || attachBusy ? (
                                <Button
                                  type="button"
                                  size="icon"
                                  className="size-8 rounded-full"
                                  // It QUEUES while a turn is running, and the
                                  // label says so: a message sent into the
                                  // turn in flight leaves no moment at which
                                  // the user can still edit or withdraw it.
                                  // Mid-turn delivery is the strip's own
                                  // "send now", one click away.
                                  //
                                  // …EXCEPT while the turn is merely held for
                                  // background work, where there is no turn in
                                  // flight to redirect — and it QUEUES with no
                                  // turn at all when earlier messages are still
                                  // waiting. `composerButton` is the one reading
                                  // of all of it, the send path's own.
                                  aria-label={composerButton?.label ?? 'Send'}
                                  // A paste still being read: `aria-disabled`
                                  // rather than `disabled`, because the reason
                                  // is the hover sentence and a disabled button
                                  // never shows one.
                                  aria-disabled={attachBusy}
                                  disabled={!hasContent && !attachBusy}
                                  title={
                                    attachBusy
                                      ? attachBusyTitle
                                      : (composerButton?.title ?? 'Send')
                                  }
                                  onClick={() => void sendFollowUp()}>
                                  {/* NOT the ArrowUp that Send uses when it
                                      queues. The one thing the user has to
                                      understand before clicking is that this
                                      does not reach the agent, and an identical
                                      glyph left that to the hover title. Clock
                                      is what the strip above already marks a
                                      waiting message with, so the button and its
                                      result read as the same thing. */}
                                  {attachBusy ? (
                                    <Spinner className="size-4 text-primary-foreground" />
                                  ) : composerButton?.label === 'Queue' ? (
                                    <Clock className="size-4 shrink-0" />
                                  ) : (
                                    <ArrowUp className="size-4 shrink-0" />
                                  )}
                                </Button>
                              ) : null}
                              {streaming ? (
                                <Button
                                  type="button"
                                  // Red, not outline: Stop ABORTS the turn the user
                                  // is watching, and the one control in the composer
                                  // that destroys work should not read the same as
                                  // the pickers beside it.
                                  variant="destructive"
                                  size="icon"
                                  className="size-8 rounded-full"
                                  aria-label="Stop"
                                  title="Stop the current turn"
                                  onClick={() => void cancel()}>
                                  <Square className="size-3.5 shrink-0" />
                                </Button>
                              ) : null}
                            </>
                          }>
                          {activeRun &&
                          activeRun.teamId === null &&
                          activeRun.agentKind ? (
                            /* How THIS turn thinks — the two settings that sit
                        below the text, beside the actions, rather than above
                        with the run's identity.

                        A running turn's argv is fixed at spawn and no adapter
                        can mutate it in flight, so a change made now takes
                        effect on the NEXT turn — which both chips say while a
                        turn streams, because a control that silently did
                        nothing for the thing you are watching would be worse
                        than one that announces the delay. */
                            <>
                              <ModelSettingsSelect
                                configProfiles={configProfiles.filter(
                                  (profile) =>
                                    profile.agent === activeRun.agentKind,
                                )}
                                agentKind={activeRun.agentKind}
                                models={agentModels}
                                loading={agentModelsLoading}
                                settingsLoading={modelSettingsLoading}
                                model={activeRun.model}
                                nextTurnOnly={streaming}
                                onModelChange={(model) =>
                                  void changeRunSettings({ model })
                                }
                                efforts={agentEfforts.efforts}
                                effort={activeRun.effort}
                                onEffortChange={(effort) =>
                                  void changeRunSettings({ effort })
                                }
                                // Approval rides the same popover as the rest
                                // now. Unlike model and effort it does NOT
                                // wait for the next turn — the CLI accepts a
                                // mode change on a turn already in flight —
                                // which is why the trigger's `nextTurnOnly`
                                // wording stays about the model settings and
                                // this row is simply always live.
                                approvalCapability={approvalCapabilityFor(
                                  activeRun.agentKind,
                                )}
                                approval={activeRun.approval}
                                onApprovalChange={(approval) =>
                                  void changeRunSettings({ approval })
                                }
                                windows={agentContextWindows.windows}
                                contextWindow={activeRun.contextWindow}
                                // The window the AGENT reported for this
                                // thread — the ring's own denominator, so the
                                // panel and the meter beside it cannot state
                                // two different windows for one model.
                                windowTokens={chatContext.window}
                                onContextWindowChange={(contextWindow) =>
                                  void changeRunSettings({ contextWindow })
                                }
                                autoCompactPercent={
                                  activeRun.autoCompactPercent
                                }
                                onAutoCompactChange={(percent) =>
                                  void changeRunSettings({
                                    autoCompactPercent: percent,
                                  })
                                }
                                parameters={agentModelParameters.parameters}
                                parameterValues={activeRun.modelParameters}
                                onParameterChange={(id, next) =>
                                  void changeRunSettings({
                                    modelParameters: withModelParameter(
                                      activeRun.modelParameters,
                                      id,
                                      next,
                                    ),
                                  })
                                }
                                // WHICH ACCOUNT the next turns run as — a row
                                // of this panel now rather than a chip beside
                                // it, ASKED FOR as "давай еще Default profile
                                // тоже засунем в Opus Submenu". It is here at
                                // all, rather than stated in the header,
                                // because it CHANGES something: the report
                                // that made it live was "I wanna have ability
                                // to dynamically change config directory for
                                // current claude threads to have an ability
                                // continue thread with other account".
                                //
                                // It carries no `nextTurnOnly`: the daemon
                                // REFUSES the change mid-turn rather than
                                // deferring it, because switching profiles
                                // moves the CLI's own conversation and retires
                                // the run's process — neither safe underneath
                                // a turn writing into the profile being left.
                                // The refusal arrives as the daemon's own
                                // sentence through `changeRunSettings`.
                                //
                                // This chat's OWN profile, which is what the
                                // turn runs as. Two releases said otherwise on
                                // the strength of an override MEASUREMENT says
                                // does not exist — a folder's
                                // `.claude/settings.local.json`
                                // `env.CLAUDE_CONFIG_DIR` neither outranks
                                // what geniro sets nor applies when it sets
                                // nothing (the three readings are in the
                                // `Profile` row of `chat-header.tsx`). The
                                // report behind that ("Its again showing
                                // different account plan", `Plan limits ·
                                // TEAM` under a chip reading `-personal`) had
                                // no override in it either: a directory
                                // decides which credentials, settings, MCP
                                // servers and history a turn uses, while the
                                // PLAN comes from whatever account those
                                // credentials are. Probing both of the
                                // reporter's profiles returned
                                // `subscription_type: "team"` with the same
                                // five-hour bucket at the same 65%. A
                                // directory is not a subscription.
                                configDir={activeRun.configDir}
                                recentConfigDirs={
                                  recentConfigDirsByAgent[
                                    activeRun.agentKind
                                  ] ?? EMPTY_RECENT_CONFIG_DIRS
                                }
                                configDirUnavailableReason={configDirReasonFor(
                                  activeRun.agentKind,
                                )}
                                onConfigDirChange={changeRunConfigDir}
                                onBrowseConfigDir={() =>
                                  void pickRunConfigDir()
                                }
                              />
                              {/* The context readout, DIRECTLY after the effort
                          chip rather than over beside Send.

                          It reads as one of this turn's settings, because that
                          is what it is about: model, effort and how much room
                          is left are the three facts describing the request
                          you are composing. Pinned to the actions it sat
                          against the one control that destroys work (Stop),
                          separated from everything it belongs with, and its
                          readout panel opened against the send button. Here it
                          also wraps with the chips instead of squeezing the
                          actions. */}
                              <ContextMeter
                                // The row's `gap-x-0.5` is 2px because every
                                // OTHER child of it is a chip carrying `px-2`
                                // inside its own box — so two chips read as
                                // 18px apart while their fills sit 2px apart.
                                // The ring carries no padding at all, so that
                                // same gap put it 2px from the model chip's
                                // edge and it read as stuck to it. `ml-1.5`
                                // makes 8px in total: the ring stands off the
                                // chip by exactly the chip's own inner
                                // padding, so it is as far from that box as
                                // the word inside it is. A margin here rather
                                // than a wider row gap, which would space the
                                // chips from each other as well and undo the
                                // one-line rule above.
                                className="ml-1.5"
                                // The expanded readout is about ONE agent's
                                // window, so it is offered for a chat and not
                                // for a team run, whose nodes each hold one
                                // of their own.
                                runId={activeRun.teamId ? null : activeRun.id}
                                contextTokens={chatContext.tokens}
                                contextWindowTokens={chatContext.window}
                                contextEstimated={chatContext.estimated}
                                awaitingReading={awaitingReading}
                                // Whether the readout has to keep itself
                                // current. The BADGE reading, not the run
                                // row — the same authority the header and
                                // the sidebar use, so a panel that keeps
                                // re-reading and a chat that says it is
                                // running cannot disagree about whether
                                // anything is happening.
                                live={isWorkingRunStatus(activeRunStatus)}
                                runningCost={liveRunCost(liveText)}
                                // Opens UPWARD. This row sits at the bottom of the
                                // composer, inside the app shell's
                                // `overflow-hidden` main — roughly 20px below a
                                // panel that is 50-68px tall — so a downward
                                // readout is clipped, and the ring shows no figures
                                // of its own to fall back on.
                                side="top"
                              />
                            </>
                          ) : activeRun?.teamId &&
                            wfNodes.triggers.length > 0 ? (
                            /* A team run's one fact of this kind, in the
                        slot the model chip holds on a chat. It is a STATIC
                        chip, not a picker: a run's trigger is decided when the
                        run is created and there is nothing here to change —
                        which is exactly why it had no business on the row above,
                        where every other chip was a decision still open.

                        This slot is otherwise empty for a team run (its
                        nodes each carry their own model, effort and approval in
                        the graph), so the chip costs the row nothing and the
                        band above the card goes away entirely. */
                            <>
                              <Chip>
                                <Zap />
                                <span className="max-w-52 truncate">
                                  {`${wfNodes.triggers[0]!.name} · ${wfNodes.triggers[0]!.trigger}`}
                                </span>
                              </Chip>
                              {/* The run-level ring, drawn from the ROOT
                          agent — the node the user prompted. `chatContext`
                          resolves it and answers nulls where the graph names no
                          single root, so this draws nothing rather than a
                          figure about no particular node.

                          Its full breakdown is the ROOT node's, asked by node:
                          a team run holds one process per node, so the run
                          alone names no agent. REPORTED as "i cant see full
                          context info for team" while this was withheld. */}
                              {chatContext.tokens === null ? null : (
                                <ContextMeter
                                  className="ml-1.5"
                                  runId={runLead === null ? null : activeRun.id}
                                  memberId={runLead}
                                  contextTokens={chatContext.tokens}
                                  contextWindowTokens={chatContext.window}
                                  contextEstimated={chatContext.estimated}
                                  live={isWorkingRunStatus(activeRunStatus)}
                                  runningCost={
                                    runLead === null
                                      ? null
                                      : liveNodeCost(liveText, runLead)
                                  }
                                  side="top"
                                />
                              )}
                            </>
                          ) : null}
                        </MessageComposer>
                      </div>
                    </div>
                  </section>
                )}

                {browserEnabled ? (
                  <BrowserColumn
                    key={activeRunId}
                    narrow={narrowViewport}
                    chatTitle={
                      activeRun ? runLabel(activeRun, teamNames) : 'Chat'
                    }
                  />
                ) : null}

                {showAgentsPanel || showPanelDrawer ? (
                  /* ONE panel, two hosts — a grid column at `sm` and wider,
                     a right-edge drawer below it. A second call site would
                     mean this prop list twice, which is how one host comes
                     to be handed a reading the other has. */
                  <PanelHost
                    drawer={showPanelDrawer}
                    open={mobilePanelOpen}
                    onClose={() => setMobilePanelOpen(false)}>
                    <AgentsPanel
                      // Remounted per run ON PURPOSE. The panel keys its open-MCP set by
                      // agent id, and every single-agent chat's agent carries the same
                      // sentinel — so without this the list stayed open across a chat
                      // switch and the gate stayed raised, dialling the NEW folder's MCP
                      // servers unprompted. That is the very defect the disclosure exists
                      // to prevent, merely moved to the second chat.
                      key={activeRun?.id ?? 'no-run'}
                      agents={agents}
                      nodes={nodeMeta}
                      // Both act on the WHOLE conversation, which is what the
                      // panel's own control row is already for — and being on
                      // its rail is what keeps them reachable with the column
                      // folded.
                      onSearch={openChatSearch}
                      timeline={timelinePanel}
                      artifacts={artifacts}
                      publishedArtifacts={publishedArtifacts}
                      threadPullRequests={openedByActiveThread}
                      pullRequestOutcomes={pullRequestOutcomes}
                      workflows={runWorkflows}
                      onRevealWorkflow={revealWorkflow}
                      goals={runGoals}
                      onOpenProgress={openProgress}
                      stages={
                        activeRun?.stages
                          ? {
                              progress: activeRun.stages,
                              definitions: runStageDefinitions,
                              archived: activeRun.archivedAt !== null,
                              onMove: (moveTeamRunStageDto) =>
                                teamApi.moveTeamRunStage({
                                  runId: activeRun.id,
                                  moveTeamRunStageDto,
                                }),
                            }
                          : undefined
                      }
                      tasksByAgent={tasksByAgent}
                      shellsByAgent={shellsByAgent}
                      workByAgent={workByAgent}
                      // The SAME guarded list the header counts — keyed per
                      // agent by `scanTurns`, so each card adds the turn in
                      // flight that belongs to it.
                      openTurns={openTurnsShown}
                      browserRunId={
                        browserEnabled && activeRun ? activeRun.id : null
                      }
                      onOpenShell={setOpenShell}
                      onKillShell={handleKillShell}
                      leftRunningOf={sidePanelLive.shellsLeftRunning}
                      // Withheld for a run with no working directory, and where
                      // no terminal panel hosts it — the panel itself never
                      // sees the path.
                      onOpenFolderTerminal={
                        activeRun?.cwd && onOpenTerminal
                          ? openFolderTerminal
                          : undefined
                      }
                      // The panel is per-OPEN-run, so the control is only ever
                      // about the thread on screen — which is also why the handler
                      // is bound to that run's id here rather than the panel being
                      // handed one to look up.
                      onExportChat={
                        activeRun
                          ? () => handleExportRun(activeRun.id)
                          : undefined
                      }
                      onAnalyzeThread={
                        activeRun && !isAnalysisRun(activeRun) && !isHosted
                          ? () => handleAnalyzeRun(activeRun.id)
                          : undefined
                      }
                      analysisMark={analysisMark}
                      onReflectLessons={
                        activeRun && !isAnalysisRun(activeRun) && !isHosted
                          ? () => handleReflectRun(activeRun.id)
                          : undefined
                      }
                      lessonsMark={lessonsMark}
                      terminalReasons={terminalReasons}
                      // In the drawer the panel owns no column, so it drops
                      // the stored width, the resize handle and the fold —
                      // see `fill` in `agents-panel.tsx`.
                      fill={showPanelDrawer}
                      // A team run's readouts are asked per NODE, each
                      // holding its own process; a chat's is its one agent's.
                      metricsRunId={activeRun?.id ?? null}
                      metricsByNode={Boolean(activeRun?.teamId)}
                      waterfall={activeRun ? runWaterfall : undefined}
                      processes={activeRun ? runProcesses : undefined}
                      onPopupChange={setPanelPopup}
                      popupRequest={
                        processesRequest !== null &&
                        processesRequest === activeRun?.id
                          ? 'processes'
                          : null
                      }
                      onPopupRequestHandled={onProcessesOpened}
                      notes={
                        activeRun
                          ? {
                              written:
                                hasThreadNotes(activeRun.notes) ||
                                teamNotes.length > 0,
                              onOpen: () => setNotesView({ selected: null }),
                            }
                          : undefined
                      }
                      // The HOVER half of the same resolution the button acts on.
                      // Never passed until now, so the hint it feeds — the invocation,
                      // selectable, with a copy control — could not open on this
                      // screen at all: `OpenInCliButton` treats a missing resolver as
                      // "nothing to show" and stays silent. That copyable line is the
                      // documented way out for anyone whose terminal geniro cannot
                      // launch (a remote host, an open tmux pane), and it was
                      // unreachable.
                      onResolveHandoff={resolveHandoff}
                      onSetPoolMember={
                        activeRun?.teamId ? setOwnPoolMember : undefined
                      }
                      // The HOVER half of the same resolution the button acts on.
                      // Never passed until now, so the hint it feeds — the invocation,
                      // selectable, with a copy control — could not open on this
                      // screen at all: `OpenInCliButton` treats a missing resolver as
                      // "nothing to show" and stays silent. That copyable line is the
                      // documented way out for anyone whose terminal geniro cannot
                      // launch (a remote host, an open tmux pane), and it was
                      // unreachable.
                      mcpByScope={mcp.byScope}
                      mcpLoading={mcp.loading}
                      onRefreshMcp={mcp.refresh}
                      onSetMcpEnabled={mcp.setEnabled}
                      onAddMcpPluginServer={mcp.addPluginServer}
                      // The profile the dialog's rows came from, written at
                      // USER scope — so the builder's node dialog, a pool
                      // member's and this one all add to the same file.
                      mcpConfigActionsFor={(scope) =>
                        mcpConfigActions(agentsApi, scope)
                      }
                      onSignInMcp={signInToMcpServer}
                      // Busy for the WHOLE flow, which is two windows end to end.
                      // The first is before the panel below can exist: the daemon
                      // holds its first reply until the CLI prints a URL —
                      // measured at 4001ms in the running app — and until then
                      // there is no session to render, which is the reported
                      // "I press Sign In and there is no loader, nothing".
                      //
                      // The second is longer and was not covered: `mcp login`
                      // EXITS as soon as it has handed the browser the challenge,
                      // so `starting` clears while the user is still authorizing
                      // — measured at 15–20s on a real connector, during which
                      // the row offered a live Sign in button. Pressing it again
                      // there opens a second challenge and invalidates the first,
                      // which is the one thing this control must not invite. The
                      // panel is on screen for exactly that stretch, so its own
                      // server is what marks the row busy; it comes down when the
                      // listing says the server is authorized.
                      mcpSigningIn={
                        login.starting?.server ?? login.login?.server ?? null
                      }
                      mcpLoginServer={
                        login.login?.server ??
                        // A refusal never becomes a session, so without this
                        // the dialog has nothing to place and the press reads
                        // as doing nothing. The row it was pressed on is
                        // where the sentence belongs.
                        (login.error !== null
                          ? (login.errorTarget?.server ?? null)
                          : null)
                      }
                      mcpLoginPanel={
                        // The SERVER half of the one controller. An account
                        // sign-in shares its lifecycle but not its home: it is
                        // started from a failed turn in the transcript and shown
                        // there (see the band above the composer), so routing it
                        // here would put the progress inside a dialog the user
                        // never opened.
                        login.login && login.login.server !== null ? (
                          <CliLoginProgress
                            session={login.login.session}
                            onSubmitCode={(code) => void login.submitCode(code)}
                            onCancel={() => void login.cancel()}
                            onDismiss={login.dismiss}
                            error={login.error}
                            // Among rows rather than across the foot of a card,
                            // so it does not cancel padding it is not inside —
                            // the negative margin took the pasted-code field off
                            // the dialog's edge, which is the second half of the
                            // reported "broken UI".
                            variant="inline"
                            // The one SERVER sign-in in the app — this branch is
                            // already gated on `server !== null`. It is what
                            // stops a clean exit reading as "Sign-in finished"
                            // over a row that still says needs sign-in.
                            scope="server"
                          />
                        ) : login.error !== null &&
                          login.errorTarget?.server != null ? (
                          // The refusal itself, on the row it was pressed
                          // on. `CliLoginProgress` needs a session and there
                          // is none, so the sentence is the whole panel.
                          <ErrorBanner
                            message={login.error}
                            onDismiss={login.dismiss}
                          />
                        ) : null
                      }
                      mcpToggleError={mcp.toggleError}
                      onDismissMcpToggleError={mcp.dismissToggleError}
                      onMcpOpenChange={(open) =>
                        setMcpOpenRunId(open ? (activeRun?.id ?? null) : null)
                      }
                      onOpenThread={(agent, thread) =>
                        void openThreadTerminal(agent, thread)
                      }
                      onOpenSubagent={openSubagentById}
                    />
                  </PanelHost>
                ) : null}

                <Dialog
                  open={detailSubagent !== null}
                  onClose={() => setDetailSubagentId(null)}
                  title={
                    // The category prefix is dropped for a delegate that has no
                    // name of its own, because the fallback title already opens
                    // with it — reported as the title reading
                    // `Sub-agent · sub-agent`, which names nothing twice.
                    detailSubagent
                      ? subagentNamed(detailSubagent)
                        ? `Sub-agent · ${subagentTitle(detailSubagent)}`
                        : subagentTitle(detailSubagent)
                      : 'Sub-agent'
                  }
                  className="max-w-2xl">
                  {detailSubagent ? (
                    // The dialog is a SIBLING subtree of the transcript, so it
                    // inherits none of the transcript's providers. Without this it
                    // read the context default (`false`) and drew a pulsing "is
                    // working…" for a delegate the block behind it correctly
                    // showed as stopped — the original bug, surviving on the new
                    // surface.
                    <SubagentDetail
                      block={detailSubagent}
                      nodes={nodeMeta}
                      chatAgentName={activeRun?.agentKind ?? null}
                    />
                  ) : null}
                </Dialog>

                <ShellOutputDialog
                  shell={openShell}
                  onClose={() => setOpenShell(null)}
                  load={loadShellOutput}
                />

                <ConfirmDialog
                  open={subagentCancelAsk !== null}
                  title="Send now and stop the sub-agents?"
                  confirmLabel="Stop them and send"
                  busyLabel="Sending…"
                  onCancel={() => answerCancelAsk(false)}
                  onConfirm={() => answerCancelAsk(true)}>
                  {subagentCancelAsk?.detail ??
                    'Sending this now cancels the sub-agents still running, and whatever they have not finished is lost.'}{' '}
                  Keep it queued and it goes out when this turn ends.
                </ConfirmDialog>

                {archiveLessons === null ? null : (
                  <div className="pointer-events-none fixed inset-x-0 bottom-4 z-40 flex justify-center px-4">
                    <ActionNotice
                      key={archiveLessons.segment.id}
                      className="pointer-events-auto w-full max-w-[420px]"
                      icon="💡"
                      title={`Learning from “${segmentTitle(archiveLessons.segment)}”`}
                      detail={archiveLessonDetail?.detail}
                      detailHint={archiveLessonDetail?.hint}
                      action={{
                        label: 'Skip',
                        onAction: () =>
                          skipArchivedLessons(archiveLessons.segment),
                      }}
                      onDismiss={() => setArchiveLessons(null)}
                    />
                  </div>
                )}

                {/* One dialog for both archives; the COPY is what separates
                    them. A settled chat is only being filed away, so it is
                    told what it costs (the row) and what it does not (the
                    conversation). A chat with a turn in flight has that turn
                    cancelled on the way, and cancelled work does not come
                    back with the thread — the one part of archiving that
                    destroys something, and the only one drawn destructive. */}
                <ConfirmDialog
                  open={archiving !== null}
                  busy={archiveBusy}
                  error={archiveError}
                  title={archiveDialogCopy(archiving).title}
                  confirmLabel={archiveDialogCopy(archiving).confirmLabel}
                  confirmVariant={
                    archiving?.status === 'running' ? 'destructive' : 'default'
                  }
                  busyLabel="Archiving…"
                  onCancel={() => setArchiving(null)}
                  onConfirm={() => void confirmArchive()}>
                  {archiving?.status === 'running' ? (
                    <>
                      <strong>
                        {archiving ? runLabel(archiving, teamNames) : ''}
                      </strong>{' '}
                      is still working. Archiving it{' '}
                      {archiving.teamId != null
                        ? 'stops the run and every agent still working in it first — whatever they are part-way through is lost'
                        : 'stops the turn and closes its agent session first — whatever it is part-way through is lost'}
                      . The transcript itself is kept, and you can unarchive it
                      at any time.
                    </>
                  ) : (
                    <>
                      Archive{' '}
                      <strong>
                        {archiving ? runLabel(archiving, teamNames) : ''}
                      </strong>
                      ? It leaves the list and nothing is deleted — the
                      transcript is kept, and you can unarchive it at any time.
                    </>
                  )}
                </ConfirmDialog>

                <ConfirmDialog
                  open={deleting !== null}
                  busy={deleteBusy}
                  error={deleteError}
                  title={deleting?.teamId ? 'Delete run' : 'Delete chat'}
                  confirmLabel="Delete"
                  busyLabel="Deleting…"
                  onCancel={() => setDeleting(null)}
                  onConfirm={() => void confirmDelete()}>
                  <>
                    Delete{' '}
                    <strong>
                      {deleting ? runLabel(deleting, teamNames) : ''}
                    </strong>
                    ? Its transcript, attachments and any live terminal go with
                    it, and so does the agent’s own saved copy of the
                    conversation — except one you imported from your terminal,
                    which stays there. This cannot be undone — unlike archiving,
                    nothing is kept. Its token and cost totals stay on the Stats
                    page.
                    {deleting?.teamId
                      ? ' The team itself stays in your library.'
                      : ''}
                    {deleteLessons === null ||
                    deleteLessons.signals === 0 ? null : (
                      <label className="mt-3 flex items-start gap-2 text-foreground">
                        <input
                          type="checkbox"
                          className="mt-0.5 size-4 accent-primary"
                          checked={extractLessonsOnDelete}
                          onChange={(event) =>
                            setExtractLessonsOnDelete(event.target.checked)
                          }
                        />
                        <span>
                          {`Extract lessons first · ${lessonCostLabel(deleteLessons.estimate, deleteLessons.check, deleteLessonModel)}`}
                        </span>
                      </label>
                    )}
                  </>
                </ConfirmDialog>

                <ConfirmDialog
                  open={deletingGroup !== null}
                  busy={deleteGroupBusy}
                  error={deleteGroupError}
                  title="Delete group"
                  confirmLabel="Delete group"
                  busyLabel="Deleting…"
                  onCancel={() => setDeletingGroup(null)}
                  onConfirm={() => void confirmDeleteGroup()}>
                  <>
                    Delete the group <strong>{deletingGroup?.name}</strong>?
                    {/* What is NOT deleted is the whole point, and it is said
                      first: "delete" reads as final, and the chats are the
                      thing a user would be afraid of losing. */}
                    <span className="mt-2 block">
                      {deletingGroupCount === 0
                        ? 'It holds no chats.'
                        : `Its ${deletingGroupCount} ${deletingGroupCount === 1 ? 'chat is' : 'chats are'} kept — they move to Ungrouped with all their history.`}{' '}
                      Only the group itself is removed.
                    </span>
                  </>
                </ConfirmDialog>
                <RunConfigPicker
                  open={runConfigPickerOpen}
                  openTo={runConfigPickerMode}
                  configs={runConfigs}
                  agentsApi={agentsApi}
                  teams={teams}
                  projects={projects}
                  cliDetections={cliDetections}
                  recentFolders={recentFolders}
                  // Asked about the CONFIGURATION's own agent, not the
                  // composer's — a saved setup routinely names a different CLI.
                  recentConfigDirsFor={(kind) =>
                    recentConfigDirsByAgent[kind] ?? []
                  }
                  configProfilesFor={(kind) =>
                    configProfiles.filter((profile) => profile.agent === kind)
                  }
                  approvalCapabilityFor={approvalCapabilityFor}
                  configDirReasonFor={configDirReasonFor}
                  captureCurrent={captureCurrentRunConfig}
                  onApply={(config) => void applyRunConfigToComposer(config)}
                  onSave={saveRunConfig}
                  onDelete={deleteRunConfig}
                  onReorder={reorderRunConfigs}
                  onClose={() => setRunConfigPickerOpen(false)}
                />
                <AnalysisDialog
                  key={`${analysisOf?.id ?? ''}:${analysisGeneration}`}
                  subject={
                    analysisOf ? { kind: 'thread', run: analysisOf } : null
                  }
                  sourceLabel={
                    analysisOf ? runLabel(analysisOf, teamNames) : ''
                  }
                  apis={apis}
                  renderThread={(thread) => (
                    <Chats client={client} handle={handle} hosted={thread} />
                  )}
                  onNewAnalysis={() => setAnalyzingRun(analysisOf)}
                  onClose={() => {
                    setAnalysisOf(null);
                    setAnalysisGeneration((n) => n + 1);
                  }}
                />
                <AnalyzeThreadDialog
                  subject={
                    analyzingRun ? { kind: 'thread', run: analyzingRun } : null
                  }
                  replaces={
                    analyzingRun !== null && analysisOf?.id === analyzingRun.id
                  }
                  sourceLabel={
                    analyzingRun ? runLabel(analyzingRun, teamNames) : ''
                  }
                  chatApi={chatApi}
                  agentsApi={agentsApi}
                  cliDetections={cliDetections}
                  composerSetup={{
                    agent: agentKind,
                    configDir: configDirs[agentKind] ?? null,
                    model: models[agentKind] ?? null,
                    effort: efforts[agentKind] ?? null,
                    contextWindow: contextWindows[agentKind] ?? null,
                    autoCompactPercent,
                    modelParameters: modelParameters[agentKind] ?? {},
                    // Never the composer's mode: an analysis starts on auto.
                    approval: null,
                  }}
                  recentConfigDirsFor={(kind) =>
                    recentConfigDirsByAgent[kind] ?? []
                  }
                  configProfilesFor={(kind) =>
                    configProfiles.filter((profile) => profile.agent === kind)
                  }
                  configDirReasonFor={configDirReasonFor}
                  approvalCapabilityFor={approvalCapabilityFor}
                  runSettings={currentRunSettings}
                  onClose={() => setAnalyzingRun(null)}
                  onStarted={() => {
                    // Opened in its popup over the thread, never as a sidebar
                    // chat; the bump makes it a new conversation there.
                    setAnalysisOf(analyzingRun);
                    setAnalyzingRun(null);
                    setAnalysisGeneration((n) => n + 1);
                  }}
                />
                <GlobalChatSearchDialog
                  open={globalSearchOpen}
                  chatApi={chatApi}
                  onClose={() => setGlobalSearchOpen(false)}
                  onJump={openGlobalSearchHit}
                />
                <SessionPicker
                  open={sessionPickerOpen}
                  agent={sessionAgent}
                  onAgentChange={setSessionAgent}
                  profiles={sessionProfileDirs}
                  query={sessionQuery}
                  onQueryChange={setSessionQuery}
                  listing={sessionListing}
                  loading={sessionsLoading}
                  error={sessionsError}
                  busyId={resumingSessionId}
                  onClose={() => setSessionPickerOpen(false)}
                  onResume={(row) => void resumeSession(row)}
                />
                {/* Beside the session picker because they are the same kind of
                    surface — a search whose answer is a place to go — and the
                    two must not grow different ideas of what one looks like.
                    Rendered only with a thread open: without one there is no
                    conversation to search. */}
                {activeRunId === null ? null : (
                  <ChatSearchDialog
                    open={searchOpen}
                    search={chatSearch}
                    onClose={closeChatSearch}
                    onJump={jumpToHit}
                  />
                )}
                {/* Mounted only while OPEN — but it no longer READS: the header
                    chip states the same figures, so one `useChatChanges` feeds
                    both and the two cannot disagree about a folder they are
                    describing at the same instant. Opening still asks for a
                    fresh read (`refresh(true)`, past the freshness floor), which
                    is the behaviour the dialog documented for itself. */}
                {changesOpen && activeRun ? (
                  <ChatChangesDialog
                    open
                    startSha={activeRun.startSha}
                    changes={chatChanges.changes}
                    elsewhere={chatChanges.elsewhere}
                    truncated={chatChanges.truncated}
                    unavailableReason={chatChanges.unavailableReason}
                    movedOffStart={chatChanges.movedOffStart}
                    upstreamBase={chatChanges.upstreamBase}
                    error={chatChanges.error}
                    loading={chatChanges.loading}
                    onRefresh={readChangesNow}
                    onClose={closeChatChanges}
                  />
                ) : null}
              </BrowserGrid>
            </LocalImageLoaderContext.Provider>
          </ChatMetricsLoaderContext.Provider>
        </AttachmentLoaderContext.Provider>
      </ChatProviders>
    </CardBackedRequestsContext.Provider>
  );
}
